const FILES = {"fastapi/basic": {"01_crud.py": {"content": "# ══════════════════════════════════════════════════════════════════\n#  FastAPI CRUD — Raw Dict Patterns (No Pydantic)\n#  Run: uvicorn 01_crud:app --reload   (from fastapi/basic)\n# ══════════════════════════════════════════════════════════════════\nfrom fastapi import Body, Cookie, FastAPI, File, Form, Header, HTTPException, Path, Query, UploadFile, status\nfrom fastapi.responses import JSONResponse\nfrom typing import List, Optional\n\napp = FastAPI()\nshipment_data = {\n    1: {\"id\": 1, \"content\": \"Shipment 1 content\", \"weight\": 10, \"status\": \"In Transit\"},\n    2: {\"id\": 2, \"content\": \"Shipment 2 content\", \"weight\": 20, \"status\": \"Delivered\"},\n    3: {\"id\": 3, \"content\": \"Shipment 3 content\", \"weight\": 15, \"status\": \"Pending\"},\n}\n\n# ╔══════════════════════════════════════════════════╗\n# ║              BEGINNER                            ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. Path Parameter ──────────────────────────────\n@app.get(\"/shipment/{id}\")\ndef get_by_path(id: int):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    return shipment_data[id]\n# curl http://localhost:8000/shipment/1\n\n# ── 2. Query Parameter ──────────────────────────────\n@app.get(\"/shipment\")\ndef get_by_query(id: int):  # auto-read from ?id=1\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    return shipment_data[id]\n# curl http://localhost:8000/shipment?id=1\n\n# ── 3. Request Body (raw dict) — CREATE ──────────────────────────────\n@app.post(\"/shipment\", status_code=status.HTTP_201_CREATED)\ndef create_shipment(data: dict = Body()):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\n        \"id\": new_id, \"content\": data[\"content\"],\n        \"weight\": data[\"weight\"], \"status\": data.get(\"status\", \"Pending\"),\n    }\n    return shipment_data[new_id]\n# curl -X POST http://localhost:8000/shipment -H \"Content-Type: application/json\" -d '{\"content\":\"New\",\"weight\":30}'\n\n# ── 4. CREATE via Query Params ──────────────────────────────\n@app.post(\"/shipment/query\", status_code=status.HTTP_201_CREATED)\ndef create_via_query(\n    content: str = Query(...), weight: float = Query(...),\n    shipment_status: str = Query(\"Pending\"),\n):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\"id\": new_id, \"content\": content, \"weight\": weight, \"status\": shipment_status}\n    return shipment_data[new_id]\n# curl -X POST \"http://localhost:8000/shipment/query?content=New&weight=30\"\n\n# ── 5. UPDATE (PUT) — path + body ──────────────────────────────\n@app.put(\"/shipment/{id}\")\ndef update_shipment(id: int, data: dict = Body()):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    for key in (\"content\", \"weight\", \"status\"):\n        if key in data:\n            shipment_data[id][key] = data[key]\n    return shipment_data[id]\n# curl -X PUT http://localhost:8000/shipment/1 -H \"Content-Type: application/json\" -d '{\"status\":\"Delivered\"}'\n\n# ── 6. DELETE — path parameter ──────────────────────────────\n@app.delete(\"/shipment/{id}\")\ndef delete_by_path(id: int):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    return {\"message\": \"Deleted\", \"shipment\": shipment_data.pop(id)}\n# curl -X DELETE http://localhost:8000/shipment/1\n\n# ── 7. DELETE — query parameter ──────────────────────────────\n@app.delete(\"/shipment\")\ndef delete_by_query(id: int = Query(...)):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    return {\"message\": \"Deleted\", \"shipment\": shipment_data.pop(id)}\n# curl -X DELETE \"http://localhost:8000/shipment?id=2\"\n\n# ── 8. Multiple Path Parameters ──────────────────────────────\n@app.get(\"/warehouse/{warehouse_id}/shipment/{shipment_id}\")\ndef get_by_multiple_path(warehouse_id: str, shipment_id: int):\n    return {\"warehouse\": warehouse_id, \"shipment\": shipment_data.get(shipment_id, \"Not found\")}\n# curl http://localhost:8000/warehouse/NYC/shipment/1\n\n# ╔══════════════════════════════════════════════════╗\n# ║            INTERMEDIATE                          ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 9. Path with Validation (Path()) ──────────────────────────────\n@app.get(\"/shipment/validated/{id}\")\ndef get_by_path_validated(id: int = Path(gt=0, description=\"Must be > 0\")):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    return shipment_data[id]\n# curl http://localhost:8000/shipment/validated/0  -> 422\n\n# ── 10. Query with Validation (Query()) ──────────────────────────────\n@app.get(\"/shipments\")\ndef get_filtered(\n    status: Optional[str] = Query(None), limit: int = Query(10, ge=1, le=100),\n    offset: int = Query(0, ge=0),\n):\n    results = list(shipment_data.values())\n    if status:\n        results = [s for s in results if s[\"status\"] == status]\n    return results[offset:offset + limit]\n# curl \"http://localhost:8000/shipments?status=Pending&limit=5\"\n\n# ── 11. PATCH — path + query + body combined ──────────────────────────────\n@app.patch(\"/shipment/{id}\")\ndef patch_shipment(id: int, notify: bool = Query(False), data: dict = Body()):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    for key in (\"content\", \"weight\", \"status\"):\n        if key in data:\n            shipment_data[id][key] = data[key]\n    return {\"shipment\": shipment_data[id], \"notified\": notify}\n# curl -X PATCH \"http://localhost:8000/shipment/1?notify=true\" -H \"Content-Type: application/json\" -d '{\"status\":\"Delivered\"}'\n\n# ── 12. Path + Query — field selection ──────────────────────────────\n@app.get(\"/shipment/{id}/details\")\ndef get_with_field_filter(id: int, fields: List[str] = Query(None)):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    shipment = shipment_data[id]\n    return {k: v for k, v in shipment.items() if k in fields} if fields else shipment\n# curl \"http://localhost:8000/shipment/1/details?fields=content&fields=status\"\n\n# ── 13. Required vs Optional vs Default query params ──────────────────────────────\n@app.get(\"/shipments/search\")\ndef search_shipments(\n    q: str = Query(..., min_length=1),                     # required\n    status_filter: Optional[str] = Query(None),            # optional (None)\n    sort_by: str = Query(\"id\"),                            # default value\n):\n    results = [s for s in shipment_data.values() if q.lower() in s[\"content\"].lower()]\n    if status_filter:\n        results = [s for s in results if s[\"status\"] == status_filter]\n    return {\"query\": q, \"sort\": sort_by, \"results\": results}\n# curl \"http://localhost:8000/shipments/search?q=Shipment&status_filter=Pending\"\n\n# ── 14. Header Parameter ──────────────────────────────\n@app.get(\"/shipment/auth/{id}\")\ndef get_with_header(\n    id: int, x_token: str = Header(...),\n    x_request_id: Optional[str] = Header(None),\n):\n    if x_token != \"secret-token\":\n        raise HTTPException(status_code=401, detail=\"Invalid token\")\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    return {\"shipment\": shipment_data[id], \"request_id\": x_request_id}\n# curl http://localhost:8000/shipment/auth/1 -H \"X-Token: secret-token\"\n\n# ── 15. Cookie Parameter ──────────────────────────────\n@app.get(\"/shipment/session/{id}\")\ndef get_with_cookie(id: int, session_id: Optional[str] = Cookie(None)):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    return {\"shipment\": shipment_data[id], \"session\": session_id}\n# curl http://localhost:8000/shipment/session/1 -b \"session_id=abc123\"\n\n# ── 16. Form Data ──────────────────────────────\n@app.post(\"/shipment/form\", status_code=status.HTTP_201_CREATED)\ndef create_via_form(content: str = Form(...), weight: float = Form(...), shipment_status: str = Form(\"Pending\")):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\"id\": new_id, \"content\": content, \"weight\": weight, \"status\": shipment_status}\n    return shipment_data[new_id]\n# curl -X POST http://localhost:8000/shipment/form -d \"content=FormShipment&weight=25\"\n\n# ── 17. File Upload ──────────────────────────────\n@app.post(\"/shipment/upload\")\nasync def upload_shipment_doc(shipment_id: int = Query(...), file: UploadFile = File(...)):\n    if shipment_id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    contents = await file.read()\n    return {\"shipment_id\": shipment_id, \"filename\": file.filename, \"size_bytes\": len(contents)}\n# curl -X POST \"http://localhost:8000/shipment/upload?shipment_id=1\" -F \"file=@doc.pdf\"\n\n# ── 18. File + Form Data ──────────────────────────────\n@app.post(\"/shipment/upload-with-data\")\nasync def upload_with_form(content: str = Form(...), weight: float = Form(...), file: UploadFile = File(...)):\n    file_contents = await file.read()\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\"id\": new_id, \"content\": content, \"weight\": weight, \"status\": \"Pending\", \"attachment\": file.filename}\n    return {\"shipment\": shipment_data[new_id], \"file_size\": len(file_contents)}\n# curl -X POST http://localhost:8000/shipment/upload-with-data -F \"content=New\" -F \"weight=30\" -F \"file=@doc.pdf\"\n\n# ── 19. Multiple File Upload ──────────────────────────────\n@app.post(\"/shipment/upload-multiple\")\nasync def upload_multiple(shipment_id: int = Query(...), files: List[UploadFile] = File(...)):\n    if shipment_id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    file_info = [{\"filename\": f.filename, \"size\": len(await f.read())} for f in files]\n    return {\"shipment_id\": shipment_id, \"files\": file_info}\n# curl -X POST \"http://localhost:8000/shipment/upload-multiple?shipment_id=1\" -F \"files=@a.pdf\" -F \"files=@b.pdf\"\n\n# ╔══════════════════════════════════════════════════╗\n# ║              ADVANCED                            ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 20. Body with embed=True ──────────────────────────────\n# Without embed: {\"content\":\"...\", \"weight\":30}\n# With embed:    {\"data\": {\"content\":\"...\", \"weight\":30}}\n@app.post(\"/shipment/embedded\", status_code=status.HTTP_201_CREATED)\ndef create_embedded(data: dict = Body(embed=True)):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\"id\": new_id, \"content\": data[\"content\"], \"weight\": data[\"weight\"], \"status\": data.get(\"status\", \"Pending\")}\n    return shipment_data[new_id]\n# curl -X POST http://localhost:8000/shipment/embedded -H \"Content-Type: application/json\" -d '{\"data\":{\"content\":\"Embedded\",\"weight\":40}}'\n\n# ── 21. Multiple Body Parameters ──────────────────────────────\n# Body: {\"shipment\": {...}, \"metadata\": {...}} — auto-embedded by param name\n@app.post(\"/shipment/with-metadata\", status_code=status.HTTP_201_CREATED)\ndef create_with_metadata(shipment: dict = Body(...), metadata: dict = Body(...)):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\n        \"id\": new_id, \"content\": shipment[\"content\"], \"weight\": shipment[\"weight\"],\n        \"status\": shipment.get(\"status\", \"Pending\"), \"metadata\": metadata,\n    }\n    return shipment_data[new_id]\n# curl -X POST http://localhost:8000/shipment/with-metadata -H \"Content-Type: application/json\" -d '{\"shipment\":{\"content\":\"New\",\"weight\":30},\"metadata\":{\"source\":\"API\"}}'\n\n# ── 22. Custom Response — headers, cookies, status ──────────────────────────────\n@app.post(\"/shipment/custom-response\", status_code=status.HTTP_201_CREATED)\ndef create_with_custom_response(data: dict = Body()):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\"id\": new_id, \"content\": data[\"content\"], \"weight\": data[\"weight\"], \"status\": data.get(\"status\", \"Pending\")}\n    response = JSONResponse(content={\"shipment\": shipment_data[new_id]}, status_code=201)\n    response.set_cookie(key=\"last_shipment_id\", value=str(new_id))\n    response.headers[\"X-Shipment-ID\"] = str(new_id)\n    return response\n# curl -v -X POST http://localhost:8000/shipment/custom-response -H \"Content-Type: application/json\" -d '{\"content\":\"Custom\",\"weight\":20}'\n\n# ── 23. Enum-like Path Parameter ──────────────────────────────\n@app.get(\"/shipment/status/{status_value}\")\ndef get_by_status_path(status_value: str):\n    results = [s for s in shipment_data.values() if s[\"status\"].lower() == status_value.lower()]\n    if not results:\n        raise HTTPException(status_code=404, detail=f\"No shipments with status '{status_value}'\")\n    return results\n# curl http://localhost:8000/shipment/status/pending\n\n# ── 24. List Query Parameter — batch GET ──────────────────────────────\n@app.get(\"/shipments/batch\")\ndef get_batch(ids: List[int] = Query(...)):\n    return [shipment_data[id] for id in ids if id in shipment_data]\n# curl \"http://localhost:8000/shipments/batch?ids=1&ids=2&ids=3\"\n\n# ── 25. Bulk DELETE with body ──────────────────────────────\n@app.delete(\"/shipments/bulk\")\ndef delete_bulk(data: dict = Body()):\n    ids = data.get(\"ids\", [])\n    deleted, not_found = [], []\n    for id in ids:\n        (deleted if id in shipment_data else not_found).append(shipment_data.pop(id) if id in shipment_data else id)\n    return {\"deleted\": deleted, \"not_found\": not_found}\n# curl -X DELETE http://localhost:8000/shipments/bulk -H \"Content-Type: application/json\" -d '{\"ids\":[1,2,99]}'", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n#  CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\n# SOURCE        | SYNTAX                          | EXAMPLE\n# --------------|--------------------------------|----------------------------\n# Path param    | def f(id: int)                 | /shipment/{id}\n# Path valid.   | id: int = Path(gt=0)           | /shipment/validated/{id}\n# Query param   | def f(id: int)                 | /shipment?id=1\n# Query valid.  | limit: int = Query(10, ge=1)   | ?limit=5\n# Query list    | ids: List[int] = Query(...)    | ?ids=1&ids=2\n# Body (dict)   | data: dict = Body()            | JSON body\n# Body embed    | data: dict = Body(embed=True)  | {\"data\": {...}}\n# Multi body    | a: dict = Body(), b: dict = Body() | {\"a\":{...},\"b\":{...}}\n# Header        | x_token: str = Header(...)     | -H \"X-Token: val\"\n# Cookie        | sid: str = Cookie(None)        | -b \"sid=abc\"\n# Form          | name: str = Form(...)          | -d \"name=val\"\n# File          | file: UploadFile = File(...)    | -F \"file=@f.pdf\"\n# Custom resp   | return JSONResponse(...)       | set cookies/headers\n# ══════════════════════════════════════════════════════════════════\n#", "reference": "# ══════════════════════════════════════════════════════════════════\n#  PARAMETER DECLARATIONS — DETAILED REFERENCE\n# ══════════════════════════════════════════════════════════════════\n#\n# ── Body() — Reads from JSON request body ────────────────────────\n#   data: dict = Body()             → optional, reads entire JSON body as dict\n#   data: dict = Body(...)          → required (... = Ellipsis = no default allowed)\n#   data: dict = Body(embed=True)   → expects {\"data\": {...}} — wraps value under param name\n#   a: dict = Body(), b: dict = Body()  → multiple body params: {\"a\":{...},\"b\":{...}}\n#   Note: Body() is needed to tell FastAPI \"read from body\" explicitly.\n#         Without it, simple types (str, int) would be treated as query params.\n#\n#   BEGINNER EXAMPLE — Why Body() matters:\n#\n#     # ── CASE 1: WITHOUT Body() ─────────────────────────────────────\n#     @app.post(\"/test\")\n#     def test(name: str, data: dict):\n#         ...\n#     # name: str   → simple type, no Body()  → FastAPI reads from QUERY string\n#     # data: dict  → complex type            → FastAPI reads from JSON BODY\n#     #\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/test?name=abc\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\"key\": \"val\"}'\n#     #\n#     #   URL:  /test?name=abc          ← name comes from here (query)\n#     #   Body: {\"key\": \"val\"}          ← data comes from here (entire body = data)\n#     #\n#     #   Inside function:\n#     #     name → \"abc\"                ← from query string\n#     #     data → {\"key\": \"val\"}       ← from JSON body\n#\n#     # ── CASE 2: WITH Body() on all params ──────────────────────────\n#     @app.post(\"/test\")\n#     def test(name: str = Body(), data: dict = Body()):\n#         ...\n#     # name: str = Body()  → Body() overrides → reads from JSON BODY\n#     # data: dict = Body() → Body() explicit  → reads from JSON BODY\n#     #\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/test\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\"name\": \"abc\", \"data\": {\"key\": \"val\"}}'\n#     #\n#     #   URL:  /test                   ← no query params needed\n#     #   Body: {                       ← BOTH params come from body\n#     #           \"name\": \"abc\",            ← name comes from here\n#     #           \"data\": {\"key\": \"val\"}    ← data comes from here\n#     #         }\n#     #\n#     #   Inside function:\n#     #     name → \"abc\"                ← from body[\"name\"]\n#     #     data → {\"key\": \"val\"}       ← from body[\"data\"]\n#\n#     # ── CASE 3: Single Body param (no Body()) ──────────────────────\n#     @app.post(\"/shipment\")\n#     def create(data: dict = Body()):\n#         ...\n#     # Only ONE body param → body IS the value directly (no wrapping)\n#     #\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/shipment\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\"content\": \"Table\", \"weight\": 10}'\n#     #\n#     #   Body: {\"content\": \"Table\", \"weight\": 10}   ← entire body = data\n#     #\n#     #   Inside function:\n#     #     data → {\"content\": \"Table\", \"weight\": 10}  ← body itself\n#\n#     # ── CASE 4: Single Body param WITH embed=True ──────────────────\n#     @app.post(\"/shipment\")\n#     def create(data: dict = Body(embed=True)):\n#         ...\n#     # embed=True → wraps under param name, even for single param\n#     #\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/shipment\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\"data\": {\"content\": \"Table\", \"weight\": 10}}'\n#     #\n#     #   Body: {                                     ← wrapped under \"data\" key\n#     #           \"data\": {\"content\": \"Table\", \"weight\": 10}\n#     #         }\n#     #\n#     #   Inside function:\n#     #     data → {\"content\": \"Table\", \"weight\": 10}  ← extracted from body[\"data\"]\n#\n#   RULES FastAPI uses (when you DON'T add Body/Query/Path/etc.):\n#     simple type (str, int, float, bool) → Query param   (?key=val)\n#     complex type (dict, list, Pydantic) → Body param    (JSON)\n#     name matches {name} in URL path    → Path param     (/items/{name})\n#\n#   Body() OVERRIDES the default → forces any type to be read from JSON body.\n#   Body(...) = required  |  Body() = optional  |  Body(\"default\") = has default\n#\n# ── Query() — Reads from URL query string (?key=value) ───────────\n#   q: str = Query(...)                   → required, no default\n#   q: str = Query(..., min_length=1)     → required + string length validation\n#   status: str = Query(\"Pending\")        → optional, defaults to \"Pending\"\n#   status: Optional[str] = Query(None)   → optional, defaults to None\n#   limit: int = Query(10, ge=1, le=100)  → default 10, must be between 1-100\n#   ids: List[int] = Query(...)           → list param: ?ids=1&ids=2&ids=3\n#   Validators: ge (>=), le (<=), gt (>), lt (<), min_length, max_length\n#\n#   BEGINNER EXAMPLE — Query():\n#\n#     @app.get(\"/search\")\n#     def search(q: str = Query(..., min_length=1), limit: int = Query(10, ge=1, le=100)):\n#         ...\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/search?q=table&limit=5\"\n#     #\n#     #   URL:  /search?q=table&limit=5\n#     #                  │        │\n#     #                  ▼        ▼\n#     #   Inside function:\n#     #     q     → \"table\"     ← from ?q=table (required — omit → 422)\n#     #     limit → 5           ← from ?limit=5 (optional — omit → default 10)\n#     #\n#     #   curl \"http://localhost:8000/search\"            → 422! q is required (...)\n#     #   curl \"http://localhost:8000/search?q=&limit=5\" → 422! min_length=1 fails\n#     #   curl \"http://localhost:8000/search?q=x&limit=200\" → 422! le=100 fails\n#\n#     # List query param:\n#     @app.get(\"/filter\")\n#     def filter_items(ids: List[int] = Query(...)):\n#         ...\n#     #   curl \"http://localhost:8000/filter?ids=1&ids=2&ids=3\"\n#     #     ids → [1, 2, 3]     ← repeated key = list\n#\n# ── Path() — Reads from URL path (/items/{id}) ───────────────────\n#   id: int = Path(gt=0, description=\"Must be > 0\")\n#   Path params are always required (they're part of the URL).\n#   Use Path() to add validation (gt, ge, lt, le) and OpenAPI docs metadata.\n#\n#   BEGINNER EXAMPLE — Path():\n#\n#     @app.get(\"/shipment/{id}\")\n#     def get_shipment(id: int = Path(gt=0, le=10000)):\n#         ...\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/shipment/42\"\n#     #\n#     #   URL:  /shipment/42\n#     #                   │\n#     #                   ▼\n#     #   Inside function:\n#     #     id → 42              ← from URL path segment (always required)\n#     #\n#     #   curl \"http://localhost:8000/shipment/0\"     → 422! gt=0 fails (must be > 0)\n#     #   curl \"http://localhost:8000/shipment/abc\"   → 422! not a valid int\n#     #   curl \"http://localhost:8000/shipment/\"      → 404! path segment missing\n#\n# ── Header() — Reads from HTTP headers ───────────────────────────\n#   x_token: str = Header(...)              → required header\n#   x_request_id: Optional[str] = Header(None)  → optional header\n#   FastAPI auto-converts: x_token → \"X-Token\" (underscores → hyphens)\n#\n#   BEGINNER EXAMPLE — Header():\n#\n#     @app.get(\"/secure\")\n#     def secure(x_token: str = Header(...), x_request_id: Optional[str] = Header(None)):\n#         ...\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/secure\" \\\n#     #        -H \"X-Token: my-secret-123\" \\\n#     #        -H \"X-Request-Id: req-456\"\n#     #\n#     #   Headers:\n#     #     X-Token: my-secret-123       ← x_token reads this (underscore → hyphen)\n#     #     X-Request-Id: req-456        ← x_request_id reads this\n#     #            │                │\n#     #            ▼                ▼\n#     #   Inside function:\n#     #     x_token      → \"my-secret-123\"  ← required — omit → 422\n#     #     x_request_id → \"req-456\"        ← optional — omit → None\n#     #\n#     #   curl \"http://localhost:8000/secure\"  → 422! X-Token header missing\n#     #   NOTE: Python uses _ but HTTP headers use - (auto-converted by FastAPI)\n#\n# ── Cookie() — Reads from cookies ────────────────────────────────\n#   session_id: Optional[str] = Cookie(None)  → optional cookie\n#   Reads from the Cookie header, matches by parameter name.\n#\n#   BEGINNER EXAMPLE — Cookie():\n#\n#     @app.get(\"/profile\")\n#     def profile(session_id: Optional[str] = Cookie(None)):\n#         ...\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/profile\" -b \"session_id=abc123\"\n#     #\n#     #   Cookie header: session_id=abc123\n#     #                            │\n#     #                            ▼\n#     #   Inside function:\n#     #     session_id → \"abc123\"   ← from cookie (optional — no cookie → None)\n#     #\n#     #   curl \"http://localhost:8000/profile\"  → session_id = None (optional)\n#     #   -b flag = --cookie = send cookie header\n#\n# ── Form() — Reads from form-encoded body (application/x-www-form-urlencoded) ──\n#   content: str = Form(...)          → required form field\n#   status: str = Form(\"Pending\")     → optional with default\n#   Used for HTML form submissions or curl -d. Cannot mix with Body().\n#\n#   BEGINNER EXAMPLE — Form():\n#\n#     @app.post(\"/login\")\n#     def login(username: str = Form(...), password: str = Form(...)):\n#         ...\n#\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/login\" \\\n#     #        -d \"username=john&password=secret123\"\n#     #\n#     #   Form body: username=john&password=secret123\n#     #              │              │\n#     #              ▼              ▼\n#     #   Inside function:\n#     #     username → \"john\"         ← from form field\n#     #     password → \"secret123\"    ← from form field\n#     #\n#     #   Content-Type: application/x-www-form-urlencoded  (auto-set by curl -d)\n#     #   This is what HTML <form> sends by default\n#     #   CANNOT mix Form() with Body() in same endpoint!\n#\n# ── File() — Reads uploaded files (multipart/form-data) ──────────\n#   file: UploadFile = File(...)              → single file upload\n#   files: List[UploadFile] = File(...)       → multiple file upload\n#   UploadFile provides: .filename, .content_type, .read(), .size\n#   Can mix with Form() but NOT with Body().\n#\n#   BEGINNER EXAMPLE — File():\n#\n#     @app.post(\"/upload\")\n#     def upload(file: UploadFile = File(...), description: str = Form(\"none\")):\n#         ...\n#\n#     # How to call (single file):\n#     #   curl -X POST \"http://localhost:8000/upload\" \\\n#     #        -F \"file=@report.pdf\" \\\n#     #        -F \"description=Q1 Report\"\n#     #\n#     #   Multipart body:\n#     #     file=@report.pdf            ← file upload\n#     #     description=Q1 Report       ← form field alongside file\n#     #        │             │\n#     #        ▼             ▼\n#     #   Inside function:\n#     #     file.filename     → \"report.pdf\"\n#     #     file.content_type → \"application/pdf\"\n#     #     file.size         → 102400 (bytes)\n#     #     await file.read() → b\"...\" (file bytes)\n#     #     description       → \"Q1 Report\"\n#     #\n#     #   Multiple files:\n#     #   curl -X POST \"/upload-multi\" -F \"files=@a.pdf\" -F \"files=@b.pdf\"\n#     #     files → [UploadFile(\"a.pdf\"), UploadFile(\"b.pdf\")]\n#     #   -F flag = --form = multipart/form-data\n#     #   CAN mix File() + Form()  |  CANNOT mix File() + Body()\n#\n# ── Depends() — Dependency injection (see session.py) ────────────\n#   user: dict = Depends(get_current_user)    → runs function, injects result\n#   db: Session = Depends(get_db)             → DB session injection\n#   Runs BEFORE the route handler. If dependency raises, route is skipped.\n#   Can chain: dependencies can have their own Depends().\n#   Can also go on decorator: @app.get(\"/x\", dependencies=[Depends(verify)])\n#\n#   BEGINNER EXAMPLE — Depends():\n#\n#     # Step 1: Define a dependency function\n#     def pagination_params(page: int = Query(1, ge=1), size: int = Query(10, ge=1, le=100)):\n#         return {\"page\": page, \"size\": size, \"skip\": (page - 1) * size}\n#\n#     # Step 2: Use it in a route\n#     @app.get(\"/items\")\n#     def list_items(pagination: dict = Depends(pagination_params)):\n#         ...\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/items?page=2&size=20\"\n#     #\n#     #   URL:  /items?page=2&size=20\n#     #                │        │\n#     #                ▼        ▼\n#     #   Depends() runs pagination_params(page=2, size=20) FIRST\n#     #     returns → {\"page\": 2, \"size\": 20, \"skip\": 20}\n#     #                              │\n#     #                              ▼\n#     #   Inside route function:\n#     #     pagination → {\"page\": 2, \"size\": 20, \"skip\": 20}  ← injected result\n#     #\n#     #   curl \"http://localhost:8000/items\"  → page=1, size=10 (defaults)\n#     #   The route itself has NO query params — Depends() handles them!\n#\n#     # Auth dependency (chain):\n#     #   @app.get(\"/profile\")\n#     #   def profile(user: dict = Depends(get_current_user)):\n#     #\n#     #   curl \"http://localhost:8000/profile\" -H \"Authorization: Bearer <token>\"\n#     #     Depends(get_current_user) → extracts token → verifies → returns user dict\n#     #     If token invalid → raises HTTPException(401) → route NEVER runs\n#\n# ── ... (Ellipsis) vs None vs value ──────────────────────────────\n#   = Query(...)          → REQUIRED — request fails 422 without it\n#   = Query(None)         → OPTIONAL — defaults to None\n#   = Query(\"default\")    → OPTIONAL — defaults to \"default\"\n#   = Query()             → OPTIONAL — same as Query(None) for most types\n#\n#   BEGINNER EXAMPLE — Ellipsis (...) vs None vs default:\n#\n#     @app.get(\"/demo\")\n#     def demo(\n#         a: str = Query(...),           # required\n#         b: str = Query(None),          # optional, default None\n#         c: str = Query(\"hello\"),       # optional, default \"hello\"\n#     ):\n#         ...\n#\n#     # curl \"http://localhost:8000/demo?a=foo\"\n#     #   a → \"foo\"     ← provided\n#     #   b → None      ← not provided → default None\n#     #   c → \"hello\"   ← not provided → default \"hello\"\n#     #\n#     # curl \"http://localhost:8000/demo?a=foo&b=bar&c=world\"\n#     #   a → \"foo\"     ← provided\n#     #   b → \"bar\"     ← provided (overrides None)\n#     #   c → \"world\"   ← provided (overrides \"hello\")\n#     #\n#     # curl \"http://localhost:8000/demo\"\n#     #   → 422 ERROR! \"a\" is required (...) and not provided\n#     #\n#     # COMPARISON:\n#     #   ...       → \"MUST send this\"    → 422 if missing\n#     #   None      → \"send if you want\"  → None if missing\n#     #   \"default\" → \"send if you want\"  → \"default\" if missing\n#     #   ()        → same as None        → None if missing\n#\n# ── Annotated[] style (modern, see routes.py) ────────────────────\n#   Old: id: int = Path(gt=0)\n#   New: id: Annotated[int, Path(gt=0)]\n#   Both are equivalent. Annotated separates type hint from FastAPI metadata,\n#   making it reusable and cleaner with type checkers. Recommended approach.\n#\n#   BEGINNER EXAMPLE — Annotated[] vs old style:\n#\n#     from typing import Annotated\n#\n#     # Old style (still works):\n#     @app.get(\"/old/{id}\")\n#     def old_style(id: int = Path(gt=0), q: str = Query(\"default\")):\n#         ...\n#\n#     # New style (recommended):\n#     @app.get(\"/new/{id}\")\n#     def new_style(id: Annotated[int, Path(gt=0)], q: Annotated[str, Query()] = \"default\"):\n#         ...\n#\n#     # Both called EXACTLY the same way:\n#     #   curl \"http://localhost:8000/old/42?q=test\"\n#     #   curl \"http://localhost:8000/new/42?q=test\"\n#     #     id → 42, q → \"test\"\n#     #\n#     # Reusable type aliases:\n#     #   PositiveInt = Annotated[int, Path(gt=0)]\n#     #   @app.get(\"/a/{id}\")\n#     #   def route_a(id: PositiveInt): ...    ← reuse same validation\n#     #   @app.get(\"/b/{id}\")\n#     #   def route_b(id: PositiveInt): ...    ← no duplication\n#\n# ══════════════════════════════════════════════════════════════════"}, "02_pydantic.py": {"content": "# ══════════════════════════════════════════════════════════════════\n#  FastAPI + Pydantic — Typed Models, Validation, Nested Data\n#  Run: uvicorn 02_pydantic:app --reload   (from fastapi/basic)\n#\n#  NOTE: See 01_crud.py for raw dict CRUD patterns (path/query/body/\n#  header/cookie/form/file). This file covers Pydantic-only features.\n#\n#  dict = Body()        vs   BaseModel (Pydantic)\n#  ──────────────────        ────────────────────\n#  No validation             Auto-validates all fields\n#  KeyError at runtime       422 error with clear message\n#  No docs in Swagger        Full schema in Swagger UI\n#  data[\"key\"]               data.key (dot access)\n# ══════════════════════════════════════════════════════════════════\nfrom enum import Enum\nfrom fastapi import Body, Depends, FastAPI, HTTPException, Path, Query, status\nfrom pydantic import BaseModel, Field, field_validator, model_validator\nfrom typing import List, Optional\n\napp = FastAPI()\nshipment_data = {\n    1: {\"id\": 1, \"content\": \"Shipment 1 content\", \"weight\": 10, \"status\": \"In Transit\"},\n    2: {\"id\": 2, \"content\": \"Shipment 2 content\", \"weight\": 20, \"status\": \"Delivered\"},\n    3: {\"id\": 3, \"content\": \"Shipment 3 content\", \"weight\": 15, \"status\": \"Pending\"},\n}\n\n# ╔══════════════════════════════════════════════════╗\n# ║              BEGINNER                            ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. Basic BaseModel — auto validation + Swagger docs ──────────────────────────────\nclass ShipmentCreate(BaseModel):\n    content: str                       # required — no default\n    weight: float                      # required — no default\n    status: str = \"Pending\"            # optional — has default\n\n@app.post(\"/shipment/pydantic\", status_code=status.HTTP_201_CREATED)\ndef create_with_pydantic(data: ShipmentCreate):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\"id\": new_id, \"content\": data.content, \"weight\": data.weight, \"status\": data.status}\n    return shipment_data[new_id]\n# curl -X POST http://localhost:8000/shipment/pydantic -H \"Content-Type: application/json\" -d '{\"content\":\"New\",\"weight\":30}'\n# Missing field -> 422: {\"detail\":[{\"loc\":[\"body\",\"weight\"],\"msg\":\"Field required\"}]}\n# Wrong type   -> 422: {\"detail\":[{\"loc\":[\"body\",\"weight\"],\"msg\":\"Input should be a valid number\"}]}\n\n# ── 2. Field() Constraints — like Query()/Path() but for body ──────────────────────────────\nclass ShipmentCreateValidated(BaseModel):\n    content: str = Field(min_length=3, max_length=200, description=\"3-200 chars\", examples=[\"Electronics from warehouse A\"])\n    weight: float = Field(gt=0, le=10000, description=\"Weight in kg (>0, max 10000)\", examples=[25.5])\n    status: str = Field(default=\"Pending\", examples=[\"Pending\", \"In Transit\", \"Delivered\"])\n\n@app.post(\"/shipment/pydantic-validated\", status_code=status.HTTP_201_CREATED)\ndef create_with_field_validation(data: ShipmentCreateValidated):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\"id\": new_id, \"content\": data.content, \"weight\": data.weight, \"status\": data.status}\n    return shipment_data[new_id]\n# curl -X POST http://localhost:8000/shipment/pydantic-validated -H \"Content-Type: application/json\" -d '{\"content\":\"Electronics\",\"weight\":25.5}'\n# content=\"AB\" -> 422: \"String should have at least 3 characters\"\n# weight=-5    -> 422: \"Input should be greater than 0\"\n\n# ╔══════════════════════════════════════════════════╗\n# ║            INTERMEDIATE                          ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 3. Optional Fields — for PATCH/partial update ──────────────────────────────\nclass ShipmentUpdate(BaseModel):\n    content: Optional[str] = None      # can be missing\n    weight: Optional[float] = None\n    status: Optional[str] = None\n\n@app.put(\"/shipment/pydantic/{id}\")\ndef update_with_pydantic(id: int, data: ShipmentUpdate):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    if data.content is not None:\n        shipment_data[id][\"content\"] = data.content\n    if data.weight is not None:\n        shipment_data[id][\"weight\"] = data.weight\n    if data.status is not None:\n        shipment_data[id][\"status\"] = data.status\n    return shipment_data[id]\n# curl -X PUT http://localhost:8000/shipment/pydantic/1 -H \"Content-Type: application/json\" -d '{\"status\":\"Delivered\"}'\n# Empty body {} -> nothing changes, returns current state\n\n# ── 4. Enum Validation — restrict to allowed values ──────────────────────────────\nclass ShipmentStatus(str, Enum):\n    PENDING = \"Pending\"\n    IN_TRANSIT = \"In Transit\"\n    DELIVERED = \"Delivered\"\n    CANCELLED = \"Cancelled\"\n\nclass ShipmentCreateWithEnum(BaseModel):\n    content: str\n    weight: float = Field(gt=0)\n    status: ShipmentStatus = ShipmentStatus.PENDING  # only 4 values allowed\n\n@app.post(\"/shipment/pydantic-enum\", status_code=status.HTTP_201_CREATED)\ndef create_with_enum(data: ShipmentCreateWithEnum):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\"id\": new_id, \"content\": data.content, \"weight\": data.weight, \"status\": data.status.value}\n    return shipment_data[new_id]\n# curl -X POST http://localhost:8000/shipment/pydantic-enum -H \"Content-Type: application/json\" -d '{\"content\":\"Test\",\"weight\":10,\"status\":\"In Transit\"}'\n# status=\"Lost\" -> 422: \"Input should be 'Pending', 'In Transit', 'Delivered' or 'Cancelled'\"\n\n# ── 5. field_validator — custom validation logic ──────────────────────────────\nclass ShipmentCreateCustomValidation(BaseModel):\n    content: str\n    weight: float\n    status: str = \"Pending\"\n\n    @field_validator(\"content\")\n    @classmethod\n    def content_not_empty(cls, v: str) -> str:\n        if v.strip() == \"\":\n            raise ValueError(\"Content cannot be empty or whitespace\")\n        return v.strip()  # auto-trim\n\n    @field_validator(\"weight\")\n    @classmethod\n    def weight_positive(cls, v: float) -> float:\n        if v <= 0:\n            raise ValueError(\"Weight must be > 0\")\n        if v > 50000:\n            raise ValueError(\"Weight cannot exceed 50000 kg\")\n        return round(v, 2)  # auto-round\n\n    @field_validator(\"status\")\n    @classmethod\n    def status_valid(cls, v: str) -> str:\n        allowed = [\"Pending\", \"In Transit\", \"Delivered\", \"Cancelled\"]\n        if v not in allowed:\n            raise ValueError(f\"Status must be one of: {allowed}\")\n        return v\n\n@app.post(\"/shipment/pydantic-custom\", status_code=status.HTTP_201_CREATED)\ndef create_with_custom_validation(data: ShipmentCreateCustomValidation):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\"id\": new_id, \"content\": data.content, \"weight\": data.weight, \"status\": data.status}\n    return shipment_data[new_id]\n# curl -X POST http://localhost:8000/shipment/pydantic-custom -H \"Content-Type: application/json\" -d '{\"content\":\"  Electronics  \",\"weight\":25.666}'\n# -> content=\"Electronics\" (trimmed), weight=25.67 (rounded)\n# content=\"   \" -> 422: \"Content cannot be empty or whitespace\"\n\n# ── 6. model_validator — cross-field validation ──────────────────────────────\nclass ShipmentCreateCrossField(BaseModel):\n    content: str\n    weight: float = Field(gt=0)\n    max_weight: float = Field(gt=0)\n    status: str = \"Pending\"\n\n    @model_validator(mode=\"after\")\n    def weight_must_not_exceed_max(self):\n        if self.weight > self.max_weight:\n            raise ValueError(f\"weight ({self.weight}) cannot exceed max_weight ({self.max_weight})\")\n        return self\n\n@app.post(\"/shipment/pydantic-cross\", status_code=status.HTTP_201_CREATED)\ndef create_with_cross_validation(data: ShipmentCreateCrossField):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\n        \"id\": new_id, \"content\": data.content, \"weight\": data.weight,\n        \"max_weight\": data.max_weight, \"status\": data.status,\n    }\n    return shipment_data[new_id]\n# curl -X POST http://localhost:8000/shipment/pydantic-cross -H \"Content-Type: application/json\" -d '{\"content\":\"Test\",\"weight\":20,\"max_weight\":50}'\n# weight=100, max_weight=50 -> 422: \"weight (100.0) cannot exceed max_weight (50.0)\"\n\n# ╔══════════════════════════════════════════════════╗\n# ║              ADVANCED                            ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 7. Nested Models — structured data ──────────────────────────────\nclass Address(BaseModel):\n    street: str\n    city: str\n    country: str = \"US\"\n    zip_code: Optional[str] = None\n\nclass Dimensions(BaseModel):\n    length: float = Field(gt=0)\n    width: float = Field(gt=0)\n    height: float = Field(gt=0)\n\nclass ShipmentCreateNested(BaseModel):\n    content: str\n    weight: float = Field(gt=0)\n    origin: Address                           # required nested\n    destination: Address                      # required nested\n    dimensions: Optional[Dimensions] = None   # optional nested\n\n@app.post(\"/shipment/pydantic-nested\", status_code=status.HTTP_201_CREATED)\ndef create_with_nested(data: ShipmentCreateNested):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\n        \"id\": new_id, \"content\": data.content, \"weight\": data.weight,\n        \"origin\": data.origin.model_dump(),\n        \"destination\": data.destination.model_dump(),\n        \"dimensions\": data.dimensions.model_dump() if data.dimensions else None,\n        \"status\": \"Pending\",\n    }\n    return shipment_data[new_id]\n# curl -X POST http://localhost:8000/shipment/pydantic-nested -H \"Content-Type: application/json\" -d '{\"content\":\"Electronics\",\"weight\":25,\"origin\":{\"street\":\"123 Main\",\"city\":\"NYC\"},\"destination\":{\"street\":\"456 Oak\",\"city\":\"London\",\"country\":\"UK\"}}'\n# Missing nested field -> 422: origin.city \"Field required\"\n\n# ── 8. List[Model] — batch create ──────────────────────────────\nclass ShipmentItem(BaseModel):\n    content: str\n    weight: float = Field(gt=0)\n    status: str = \"Pending\"\n\n@app.post(\"/shipment/pydantic-batch\", status_code=status.HTTP_201_CREATED)\ndef create_batch(items: List[ShipmentItem]):\n    created = []\n    for item in items:\n        new_id = max(shipment_data.keys()) + 1\n        shipment_data[new_id] = {\"id\": new_id, \"content\": item.content, \"weight\": item.weight, \"status\": item.status}\n        created.append(shipment_data[new_id])\n    return {\"created\": len(created), \"shipments\": created}\n# curl -X POST http://localhost:8000/shipment/pydantic-batch -H \"Content-Type: application/json\" -d '[{\"content\":\"A\",\"weight\":10},{\"content\":\"B\",\"weight\":20}]'\n# One bad item fails entire batch: weight=-5 -> 422\n\n# ── 9. response_model — control output shape ──────────────────────────────\nclass ShipmentResponse(BaseModel):\n    id: int\n    content: str\n    weight: float\n    status: str\n\n@app.get(\"/shipment/pydantic-response/{id}\", response_model=ShipmentResponse)\ndef get_with_response_model(id: int):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    return shipment_data[id]  # extra fields stripped by response_model\n# curl http://localhost:8000/shipment/pydantic-response/1\n\n# ── 10. PATH + QUERY + BODY all together ──────────────────────────────\nclass ShipmentPatch(BaseModel):\n    content: Optional[str] = None\n    weight: Optional[float] = Field(None, gt=0)\n    status: Optional[str] = None\n\n@app.patch(\"/shipment/pydantic/{id}\")\ndef patch_with_pydantic(\n    id: int,                                                          # path\n    dry_run: bool = Query(False, description=\"Preview without saving\"),  # query\n    data: ShipmentPatch = Body(),                                     # body\n):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    changes = {}\n    if data.content is not None:\n        changes[\"content\"] = data.content\n    if data.weight is not None:\n        changes[\"weight\"] = data.weight\n    if data.status is not None:\n        changes[\"status\"] = data.status\n    if not dry_run:\n        shipment_data[id].update(changes)\n    return {\"shipment\": shipment_data[id], \"changes_applied\": not dry_run, \"changes\": changes}\n# curl -X PATCH \"http://localhost:8000/shipment/pydantic/1\" -H \"Content-Type: application/json\" -d '{\"status\":\"Delivered\",\"weight\":50}'\n# curl -X PATCH \"http://localhost:8000/shipment/pydantic/1?dry_run=true\" -H \"Content-Type: application/json\" -d '{\"status\":\"Cancelled\"}'\n\n# ── 11. Pydantic Settings — env/config management ──────────────────────────────\n# pip install pydantic-settings\nfrom functools import lru_cache\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\n\nclass Settings(BaseSettings):\n    model_config = SettingsConfigDict(env_file=\".env\", env_file_encoding=\"utf-8\")\n\n    app_name: str = \"Shipment API\"\n    debug: bool = False\n    database_url: str = \"sqlite:///./default.db\"   # overridden by DATABASE_URL env var\n\n@lru_cache  # cache so Settings() (which reads the env/file) only runs ONCE\ndef get_settings() -> Settings:\n    return Settings()\n\n@app.get(\"/config-info\")\ndef config_info(settings: Settings = Depends(get_settings)):\n    return {\"app_name\": settings.app_name, \"debug\": settings.debug}\n# curl http://localhost:8000/config-info\n# Env vars are matched case-insensitively to field names by default:\n# DATABASE_URL=postgres://... uvicorn 02_pydantic:app --reload\n# GOTCHA: @lru_cache means settings are read once and cached for the process\n# lifetime — restart the app (not just re-request) to pick up changed env vars.\n# In tests, override with: app.dependency_overrides[get_settings] = lambda: Settings(debug=True)", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n#  CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\n# FEATURE              | SYNTAX                                  | EFFECT\n# ---------------------|----------------------------------------|---------------------------\n# BaseModel            | class M(BaseModel): name: str          | Auto-validate + Swagger\n# Field() constraints  | Field(gt=0, max_length=200)            | Range/length checks\n# Optional field       | name: Optional[str] = None             | Can be missing (PATCH)\n# Default value        | status: str = \"Pending\"                | Fallback if omitted\n# Enum validation      | class S(str, Enum): A=\"a\"              | Restrict allowed values\n# field_validator      | @field_validator(\"name\")                | Custom per-field logic\n# model_validator      | @model_validator(mode=\"after\")          | Cross-field checks\n# Nested model         | address: Address                       | Deep validation\n# List[Model]          | items: List[Item]                      | Batch with per-item checks\n# response_model       | @app.get(..., response_model=M)        | Filter output fields\n# model_dump()         | data.model_dump()                      | Model -> dict\n# BaseSettings          | class S(BaseSettings): debug: bool     | Env-var/.env config, cached\n# ══════════════════════════════════════════════════════════════════\n#", "reference": "# ══════════════════════════════════════════════════════════════════\n#  PYDANTIC & FASTAPI DECLARATIONS — DETAILED REFERENCE\n# ══════════════════════════════════════════════════════════════════\n#\n# ── BaseModel — The core Pydantic model ──────────────────────────\n#   class ShipmentCreate(BaseModel):\n#       content: str                   → required, no default — request fails 422 without it\n#       weight: float                  → required, auto-validates type (string \"abc\" → 422)\n#       status: str = \"Pending\"        → optional, uses default if omitted\n#   Usage: def create(data: ShipmentCreate)  → FastAPI auto-reads from JSON body\n#   vs dict = Body(): BaseModel gives validation, dot access (data.content), Swagger schema\n#\n#   BEGINNER EXAMPLE — BaseModel:\n#\n#     class ShipmentCreate(BaseModel):\n#         content: str                     # required\n#         weight: float                    # required\n#         status: str = \"Pending\"          # optional, default \"Pending\"\n#\n#     @app.post(\"/shipment\")\n#     def create(data: ShipmentCreate):\n#         ...\n#\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/shipment\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\"content\": \"Table\", \"weight\": 25.5}'\n#     #\n#     #   Body: {\"content\": \"Table\", \"weight\": 25.5}\n#     #          │                    │\n#     #          ▼                    ▼\n#     #   Inside function:\n#     #     data.content → \"Table\"       ← from body (required)\n#     #     data.weight  → 25.5          ← from body (required)\n#     #     data.status  → \"Pending\"     ← NOT sent → uses default\n#     #\n#     #   curl ... -d '{\"content\": \"Table\"}'           → 422! weight is required\n#     #   curl ... -d '{\"content\": \"Table\", \"weight\": \"abc\"}'  → 422! float expected\n#     #\n#     # vs dict = Body():\n#     #   BaseModel: data.content (dot access), auto-validation, Swagger schema\n#     #   dict:      data[\"content\"] (bracket access), no validation, no schema\n#\n# ── Field() — Validation constraints for model fields ────────────\n#   content: str = Field(min_length=3, max_length=200)   → string length limits\n#   weight: float = Field(gt=0, le=10000)                → numeric range (gt/ge/lt/le)\n#   status: str = Field(default=\"Pending\")               → default value\n#   Field(description=\"...\", examples=[\"...\"])            → OpenAPI docs metadata\n#   Field() is to BaseModel what Query()/Path() is to route parameters\n#\n#   BEGINNER EXAMPLE — Field():\n#\n#     class Item(BaseModel):\n#         content: str = Field(min_length=3, max_length=200)\n#         weight: float = Field(gt=0, le=10000)\n#\n#     @app.post(\"/item\")\n#     def create(data: Item):\n#         ...\n#\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/item\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\"content\": \"Wooden Table\", \"weight\": 25.0}'\n#     #\n#     #   Body: {\"content\": \"Wooden Table\", \"weight\": 25.0}\n#     #          │                           │\n#     #          ▼                           ▼\n#     #   Inside function:\n#     #     data.content → \"Wooden Table\"   ← valid (3-200 chars)\n#     #     data.weight  → 25.0             ← valid (0 < 25 <= 10000)\n#     #\n#     #   curl ... -d '{\"content\": \"AB\", \"weight\": 5}'   → 422! min_length=3 fails\n#     #   curl ... -d '{\"content\": \"OK\", \"weight\": -1}'  → 422! gt=0 fails\n#     #   curl ... -d '{\"content\": \"OK\", \"weight\": 99999}' → 422! le=10000 fails\n#\n# ── Optional fields — For PATCH/partial updates ──────────────────\n#   content: Optional[str] = None     → field can be missing from request body\n#   Check with: if data.content is not None → only update fields that were sent\n#   Use model_dump(exclude_unset=True) to get only fields explicitly provided\n#\n#   BEGINNER EXAMPLE — Optional fields (PATCH):\n#\n#     class ShipmentPatch(BaseModel):\n#         content: Optional[str] = None\n#         weight: Optional[float] = None\n#         status: Optional[str] = None\n#\n#     @app.patch(\"/shipment/{id}\")\n#     def update(id: int, data: ShipmentPatch):\n#         ...\n#\n#     # How to call (send only what changed):\n#     #   curl -X PATCH \"http://localhost:8000/shipment/1\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\"status\": \"Delivered\"}'\n#     #\n#     #   Body: {\"status\": \"Delivered\"}     ← only status sent\n#     #          │\n#     #          ▼\n#     #   Inside function:\n#     #     data.content → None          ← not sent → None (skip update)\n#     #     data.weight  → None          ← not sent → None (skip update)\n#     #     data.status  → \"Delivered\"   ← sent → update this field\n#     #\n#     #   curl ... -d '{}'    → all fields None → no changes (valid request)\n#     #   curl ... -d '{\"weight\": 50, \"content\": \"New\"}' → updates 2 fields\n#\n# ── Enum — Restrict to allowed values ────────────────────────────\n#   class Status(str, Enum):          → must inherit BOTH str and Enum\n#       PENDING = \"Pending\"\n#   Invalid value → 422: \"Input should be 'Pending', 'In Transit', ...\"\n#   Access: data.status.value → \"Pending\" (string), data.status → Status.PENDING (enum)\n#\n#   BEGINNER EXAMPLE — Enum validation:\n#\n#     class Status(str, Enum):\n#         PENDING = \"Pending\"\n#         TRANSIT = \"In Transit\"\n#         DELIVERED = \"Delivered\"\n#\n#     class Shipment(BaseModel):\n#         content: str\n#         status: Status = Status.PENDING\n#\n#     @app.post(\"/shipment\")\n#     def create(data: Shipment):\n#         ...\n#\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/shipment\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\"content\": \"Table\", \"status\": \"Delivered\"}'\n#     #\n#     #   Inside function:\n#     #     data.status       → Status.DELIVERED   ← enum member\n#     #     data.status.value → \"Delivered\"         ← string value\n#     #\n#     #   curl ... -d '{\"content\": \"Table\", \"status\": \"Lost\"}'\n#     #     → 422! \"Input should be 'Pending', 'In Transit' or 'Delivered'\"\n#\n# ── @field_validator — Custom per-field logic ────────────────────\n#   @field_validator(\"content\")\n#   @classmethod\n#   def validate_content(cls, v: str) -> str:\n#       if not v.strip(): raise ValueError(\"Cannot be empty\")\n#       return v.strip()              → can transform the value (trim, round, etc.)\n#   Runs after type validation. Raise ValueError for custom error messages.\n#\n#   BEGINNER EXAMPLE — @field_validator:\n#\n#     class Item(BaseModel):\n#         content: str\n#         weight: float\n#\n#         @field_validator(\"content\")\n#         @classmethod\n#         def validate_content(cls, v):\n#             if not v.strip(): raise ValueError(\"Cannot be empty/whitespace\")\n#             return v.strip().title()       # transforms: \"  wooden table  \" → \"Wooden Table\"\n#\n#     # How to call:\n#     #   curl ... -d '{\"content\": \"  wooden table  \", \"weight\": 10}'\n#     #     data.content → \"Wooden Table\"    ← stripped + title-cased by validator\n#     #\n#     #   curl ... -d '{\"content\": \"   \", \"weight\": 10}'\n#     #     → 422! \"Cannot be empty/whitespace\" (custom error message)\n#\n# ── @model_validator — Cross-field validation ────────────────────\n#   @model_validator(mode=\"after\")    → runs after all field validators\n#   def check_fields(self):           → has access to all fields via self.field_name\n#       if self.weight > self.max_weight: raise ValueError(...)\n#       return self                   → must return self\n#   mode=\"before\" runs on raw dict before field parsing\n#\n#   BEGINNER EXAMPLE — @model_validator:\n#\n#     class DateRange(BaseModel):\n#         start_date: str\n#         end_date: str\n#\n#         @model_validator(mode=\"after\")\n#         def check_dates(self):\n#             if self.end_date < self.start_date:\n#                 raise ValueError(\"end_date must be after start_date\")\n#             return self\n#\n#     # How to call:\n#     #   curl ... -d '{\"start_date\": \"2024-01-01\", \"end_date\": \"2024-06-01\"}'\n#     #     → valid (end > start)\n#     #\n#     #   curl ... -d '{\"start_date\": \"2024-06-01\", \"end_date\": \"2024-01-01\"}'\n#     #     → 422! \"end_date must be after start_date\"\n#     #     (cross-field check — needs BOTH fields, so model_validator not field_validator)\n#\n# ── Nested models — Deep structured validation ───────────────────\n#   class Address(BaseModel):\n#       street: str; city: str\n#   class Shipment(BaseModel):\n#       origin: Address               → required nested object\n#       dims: Optional[Dims] = None   → optional nested object\n#   Validates recursively: missing origin.city → 422 with path [\"body\",\"origin\",\"city\"]\n#   Convert to dict: data.origin.model_dump()\n#\n#   BEGINNER EXAMPLE — Nested models:\n#\n#     class Address(BaseModel):\n#         street: str\n#         city: str\n#         country: str = \"US\"\n#\n#     class Shipment(BaseModel):\n#         content: str\n#         origin: Address                  # required nested\n#         destination: Optional[Address] = None  # optional nested\n#\n#     @app.post(\"/shipment\")\n#     def create(data: Shipment):\n#         ...\n#\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/shipment\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\n#     #              \"content\": \"Electronics\",\n#     #              \"origin\": {\"street\": \"123 Main\", \"city\": \"NYC\"},\n#     #              \"destination\": {\"street\": \"456 Oak\", \"city\": \"London\", \"country\": \"UK\"}\n#     #            }'\n#     #\n#     #   Body structure:\n#     #     {\n#     #       \"content\": \"Electronics\",      ← data.content\n#     #       \"origin\": {                    ← data.origin (Address model)\n#     #         \"street\": \"123 Main\",            ← data.origin.street\n#     #         \"city\": \"NYC\"                    ← data.origin.city\n#     #                                          ← data.origin.country → \"US\" (default)\n#     #       },\n#     #       \"destination\": {               ← data.destination (optional Address)\n#     #         \"street\": \"456 Oak\",\n#     #         \"city\": \"London\",\n#     #         \"country\": \"UK\"                  ← overrides default \"US\"\n#     #       }\n#     #     }\n#     #\n#     #   curl ... -d '{\"content\": \"X\", \"origin\": {\"street\": \"A\"}}'\n#     #     → 422! origin.city is required — error path: [\"body\",\"origin\",\"city\"]\n#\n# ── List[Model] — Batch operations ──────────────────────────────\n#   def create_batch(items: List[ShipmentItem]):\n#   Request body: [{\"content\":\"A\",\"weight\":10}, {\"content\":\"B\",\"weight\":20}]\n#   Each item validated individually. One bad item → entire batch fails 422.\n#\n#   BEGINNER EXAMPLE — List[Model]:\n#\n#     class Item(BaseModel):\n#         content: str\n#         weight: float = Field(gt=0)\n#\n#     @app.post(\"/batch\")\n#     def create_batch(items: List[Item]):\n#         ...\n#\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/batch\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '[\n#     #              {\"content\": \"Table\", \"weight\": 25},\n#     #              {\"content\": \"Chair\", \"weight\": 10}\n#     #            ]'\n#     #\n#     #   Body: [ {...}, {...} ]       ← JSON array (NOT object!)\n#     #          │        │\n#     #          ▼        ▼\n#     #   Inside function:\n#     #     items[0].content → \"Table\"     ← first item\n#     #     items[0].weight  → 25\n#     #     items[1].content → \"Chair\"     ← second item\n#     #     items[1].weight  → 10\n#     #     len(items)       → 2\n#     #\n#     #   curl ... -d '[{\"content\": \"A\", \"weight\": 5}, {\"content\": \"B\", \"weight\": -1}]'\n#     #     → 422! items[1].weight must be > 0 — ONE bad item fails ENTIRE batch\n#\n# ── response_model — Control output shape ────────────────────────\n#   @app.get(\"/item/{id}\", response_model=ItemResponse)\n#   Strips fields not in ItemResponse from the response (e.g., hides internal fields)\n#   Also generates response schema in Swagger docs\n#\n#   BEGINNER EXAMPLE — response_model:\n#\n#     class ShipmentResponse(BaseModel):\n#         id: int\n#         content: str\n#         status: str\n#         # NOTE: \"weight\" and \"internal_notes\" are NOT here — hidden from response\n#\n#     @app.get(\"/shipment/{id}\", response_model=ShipmentResponse)\n#     def get_shipment(id: int):\n#         return {\"id\": 1, \"content\": \"Table\", \"status\": \"Delivered\",\n#                 \"weight\": 25, \"internal_notes\": \"fragile\"}\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/shipment/1\"\n#     #\n#     #   What function returns (internal):\n#     #     {\"id\": 1, \"content\": \"Table\", \"status\": \"Delivered\",\n#     #      \"weight\": 25, \"internal_notes\": \"fragile\"}\n#     #\n#     #   What client receives (filtered by response_model):\n#     #     {\"id\": 1, \"content\": \"Table\", \"status\": \"Delivered\"}\n#     #      ↑         ↑                  ↑\n#     #      in model   in model           in model\n#     #                     weight → STRIPPED (not in ShipmentResponse)\n#     #                     internal_notes → STRIPPED (not in ShipmentResponse)\n#\n# ── model_dump() — Convert model to dict ─────────────────────────\n#   data.model_dump()                 → all fields as dict\n#   data.model_dump(exclude_unset=True)  → only fields explicitly set (for PATCH)\n#   data.model_dump(exclude={\"password\"}) → exclude specific fields\n#\n#   BEGINNER EXAMPLE — model_dump():\n#\n#     class Item(BaseModel):\n#         content: str\n#         weight: float\n#         status: str = \"Pending\"\n#\n#     data = Item(content=\"Table\", weight=25)\n#\n#     # data.model_dump()\n#     #   → {\"content\": \"Table\", \"weight\": 25.0, \"status\": \"Pending\"}\n#     #      ← ALL fields including defaults\n#     #\n#     # data.model_dump(exclude_unset=True)\n#     #   → {\"content\": \"Table\", \"weight\": 25.0}\n#     #      ← only fields EXPLICITLY SET (status was default, so excluded)\n#     #      ← useful for PATCH: only update what user actually sent\n#     #\n#     # data.model_dump(exclude={\"weight\"})\n#     #   → {\"content\": \"Table\", \"status\": \"Pending\"}\n#     #      ← weight explicitly excluded\n#\n# ── Body() + Query() + Path() with Pydantic ─────────────────────\n#   def patch(id: int, dry_run: bool = Query(False), data: Model = Body()):\n#   id → from URL path (auto-detected)\n#   dry_run → from query string (?dry_run=true)\n#   data → from JSON body (Pydantic model)\n#   FastAPI can combine all three in one endpoint\n#\n#   BEGINNER EXAMPLE — Path + Query + Body combined:\n#\n#     @app.patch(\"/shipment/{id}\")\n#     def update(id: int, dry_run: bool = Query(False), data: ShipmentPatch = Body()):\n#         ...\n#\n#     # How to call:\n#     #   curl -X PATCH \"http://localhost:8000/shipment/42?dry_run=true\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\"status\": \"Delivered\", \"weight\": 50}'\n#     #\n#     #   URL:  /shipment/42?dry_run=true\n#     #                   │         │\n#     #                   ▼         ▼\n#     #     id      → 42        ← from URL path (auto: matches {id})\n#     #     dry_run → True      ← from query string (?dry_run=true)\n#     #\n#     #   Body: {\"status\": \"Delivered\", \"weight\": 50}\n#     #          │                      │\n#     #          ▼                      ▼\n#     #     data.status → \"Delivered\"   ← from JSON body\n#     #     data.weight → 50            ← from JSON body\n#     #\n#     #   3 sources in 1 endpoint:\n#     #     Path  → /shipment/{id}          → id\n#     #     Query → ?dry_run=true           → dry_run\n#     #     Body  → {\"status\": \"Delivered\"} → data (Pydantic model)\n#\n# ══════════════════════════════════════════════════════════════════"}, "03_routes.py": {"content": "# ══════════════════════════════════════════════════════════════════\n# FastAPI Routes — Condensed Reference\n# ══════════════════════════════════════════════════════════════════\n# Run:  uv run uvicorn 03_routes:app --reload   (from fastapi/basic)\n# Docs: http://localhost:8000/docs\n# ══════════════════════════════════════════════════════════════════\nfrom enum import Enum\nfrom typing import Annotated\nfrom fastapi import (\n    FastAPI, APIRouter, HTTPException, Query, Path, Body,\n    Header, Cookie, Form, File, UploadFile, Request, Response, Depends, status,\n    BackgroundTasks,\n)\nfrom fastapi.responses import (\n    JSONResponse, HTMLResponse, PlainTextResponse, RedirectResponse, StreamingResponse,\n)\nfrom pydantic import BaseModel, Field\n\napp = FastAPI(title=\"FastAPI Routes — All Approaches\")\n\n# ╔══════════════════════════════════════════════════╗\n# ║                   BEGINNER                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. HTTP Methods ──────────────────────────────\n# GET=read  POST=create  PUT=replace  PATCH=partial-update  DELETE=remove\n# HEAD/OPTIONS also exist — rarely hand-written (FastAPI auto-generates OPTIONS)\n@app.get(\"/items\")\nasync def get_items():\n    return [{\"id\": 1, \"name\": \"Laptop\"}, {\"id\": 2, \"name\": \"Phone\"}]\n\n@app.post(\"/items\", status_code=status.HTTP_201_CREATED)  # 201 for creation\nasync def create_item():\n    return {\"id\": 3, \"name\": \"Tablet\", \"created\": True}\n\n@app.put(\"/items/{item_id}\")  # replace entire resource\nasync def replace_item(item_id: int):\n    return {\"id\": item_id, \"replaced\": True}\n\n@app.patch(\"/items/{item_id}\")  # partial update\nasync def update_item(item_id: int):\n    return {\"id\": item_id, \"updated\": True}\n\n@app.delete(\"/items/{item_id}\", status_code=status.HTTP_204_NO_CONTENT)  # no body\nasync def delete_item(item_id: int):\n    return None\n\n# ── 2. Path Parameters ──────────────────────────────\n# Values from URL path. Type hint = auto-validation. /users/abc -> 422 error\n@app.get(\"/users/{user_id}\")  # simple — /users/42 -> user_id=42\nasync def get_user(user_id: int):\n    return {\"user_id\": user_id}\n\n@app.get(\"/orgs/{org_name}/teams/{team_name}\")  # multiple params\nasync def get_team(org_name: str, team_name: str):\n    return {\"org\": org_name, \"team\": team_name}\n\n@app.get(\"/products/{product_id}\")  # Path() — validation + docs\nasync def get_product(\n    product_id: Annotated[int, Path(title=\"Product ID\", ge=1, le=10000)],\n):\n    return {\"product_id\": product_id}\n\nclass ModelName(str, Enum):  # Enum — fixed choices (/models/random -> 422)\n    GPT4O = \"gpt-4o\"; CLAUDE = \"claude-sonnet\"; GEMINI = \"gemini-pro\"\n\n@app.get(\"/models/{model_name}\")\nasync def get_model(model_name: ModelName):\n    return {\"model\": model_name, \"value\": model_name.value}\n\n@app.get(\"/files/{file_path:path}\")  # catch-all — captures slashes\nasync def get_file(file_path: str):  # /files/docs/reports/q1.pdf -> \"docs/reports/q1.pdf\"\n    return {\"file_path\": file_path}\n\n# ── 3. Query Parameters ──────────────────────────────\n# From ?key=value. Any param NOT in path -> query param automatically.\n@app.get(\"/search\")  # default = optional, no default = required. /search -> 422 (q required)\nasync def search(q: str, page: int = 1, limit: int = 10):\n    return {\"query\": q, \"page\": page, \"limit\": limit}\n\n@app.get(\"/articles\")  # None default = truly optional\nasync def list_articles(tag: str | None = None):\n    return {\"articles\": f\"filtered by {tag}\" if tag else \"all\"}\n\n@app.get(\"/events\")  # Query() — validation, description, alias for hyphenated names\nasync def list_events(\n    start: Annotated[str, Query(description=\"Start date YYYY-MM-DD\")],\n    end: Annotated[str, Query(description=\"End date YYYY-MM-DD\")],\n    max_results: Annotated[int, Query(alias=\"max-results\", ge=1, le=100)] = 10,\n):\n    return {\"start\": start, \"end\": end, \"max_results\": max_results}\n\n@app.get(\"/filter\")  # list param — /filter?status=active&status=pending\nasync def filter_items(status: Annotated[list[str], Query()] = [\"active\"]):\n    return {\"statuses\": status}\n\n# ── 4. Request Body (Pydantic) ──────────────────────────────\n# POST/PUT/PATCH send JSON body. Pydantic model = auto-validate + docs.\nclass OrderCreate(BaseModel):\n    product: str = Field(min_length=1, max_length=100)\n    quantity: int = Field(ge=1, le=1000)\n    price: float = Field(gt=0)\n    notes: str | None = None\n\nclass OrderResponse(BaseModel):\n    id: int\n    product: str\n    quantity: int\n    price: float\n    total: float\n\n@app.post(\"/orders\", response_model=OrderResponse, status_code=201)\nasync def create_order(order: OrderCreate):  # body model; add path param for PUT /orders/{id}\n    return OrderResponse(id=1, **order.model_dump(exclude={\"notes\"}),\n                         total=order.quantity * order.price)\n\nclass OrderUpdate(BaseModel):  # partial update — all fields optional\n    product: str | None = None\n    quantity: int | None = Field(default=None, ge=1)\n    price: float | None = Field(default=None, gt=0)\n\n@app.patch(\"/orders/{order_id}\")\nasync def partial_update_order(order_id: int, updates: OrderUpdate):\n    return {\"id\": order_id, \"updated_fields\": updates.model_dump(exclude_unset=True)}\n\n@app.post(\"/shipping\")  # multiple body params — Body(embed=True) nests under keys\nasync def create_shipping(  # body: {\"order\": {...}, \"address\": \"123 Main\", \"priority\": true}\n    order: OrderCreate,\n    address: Annotated[str, Body(embed=True)],\n    priority: Annotated[bool, Body(embed=True)] = False,\n):\n    return {\"order\": order.product, \"address\": address, \"priority\": priority}\n\n# ╔══════════════════════════════════════════════════╗\n# ║                 INTERMEDIATE                     ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 5. Headers / Cookies / Form / File ──────────────────────────────\n@app.get(\"/headers\")  # header names auto-convert: \"X-Request-ID\" -> x_request_id\nasync def read_headers(\n    user_agent: Annotated[str, Header()],\n    x_request_id: Annotated[str | None, Header()] = None,\n):\n    return {\"user_agent\": user_agent, \"request_id\": x_request_id}\n\n@app.get(\"/cookies\")\nasync def read_cookies(session_token: Annotated[str | None, Cookie()] = None):\n    return {\"session_token\": session_token}\n\n@app.post(\"/login\")  # Form data (not JSON) — curl -d \"username=john&password=secret\"\nasync def login_form(username: Annotated[str, Form()], password: Annotated[str, Form()]):\n    return {\"username\": username, \"logged_in\": True}\n\n@app.post(\"/upload\")  # file upload — curl -F \"file=@photo.jpg\"\nasync def upload_file(file: UploadFile = File(...)):\n    contents = await file.read()\n    return {\"filename\": file.filename, \"size_bytes\": len(contents)}\n\n@app.post(\"/upload-many\")  # multiple files\nasync def upload_files(files: list[UploadFile] = File(...)):\n    return [{\"filename\": f.filename, \"size\": f.size} for f in files]\n\n# ── 6. Response Types ──────────────────────────────\n# Default=JSON | HTMLResponse | PlainTextResponse | RedirectResponse | StreamingResponse\n@app.get(\"/response/json\")  # default — just return dict or Pydantic model\nasync def json_response():\n    return {\"format\": \"json\", \"auto\": True}  # JSONResponse(...) for custom status/headers\n\n@app.get(\"/response/html\", response_class=HTMLResponse)  # or PlainTextResponse for plain text\nasync def html_response():\n    return \"<h1>Hello from FastAPI</h1>\"\n\n@app.get(\"/response/text\", response_class=PlainTextResponse)\nasync def text_response():\n    return \"Just plain text, no JSON\"\n\n@app.get(\"/response/redirect\")  # 302 redirect\nasync def redirect_response():\n    return RedirectResponse(url=\"/items\", status_code=302)\n\n@app.get(\"/response/stream\")  # streaming for large data / SSE\nasync def streaming_response():\n    async def generate():\n        for i in range(5): yield f\"chunk {i}\\n\"\n    return StreamingResponse(generate(), media_type=\"text/plain\")\n\n@app.get(\"/response/set-cookie\")  # set cookie + custom headers via Response param\nasync def set_cookie_response(response: Response):\n    response.set_cookie(key=\"theme\", value=\"dark\", max_age=3600, httponly=True)\n    response.headers[\"X-Process-Time\"] = \"0.5s\"\n    return {\"message\": \"Cookie + header set\"}\n\n# ── 7. Dependency Injection ──────────────────────────────\n# Depends() injects reusable logic. Runs BEFORE route; exception = route skipped.\n\nasync def pagination_params(page: int = 1, limit: int = Query(default=10, le=100)):  # 7a. function dep\n    return {\"page\": page, \"limit\": limit, \"offset\": (page - 1) * limit}\n\n@app.get(\"/posts\")  # reuse same dep across many routes (/posts, /comments, etc.)\nasync def list_posts(pagination: dict = Depends(pagination_params)):\n    return {\"posts\": [], **pagination}\n\nasync def verify_api_key(x_api_key: Annotated[str, Header()]):  # 7b. auth dep\n    if x_api_key != \"secret-key-123\":\n        raise HTTPException(status_code=403, detail=\"Invalid API key\")\n    return x_api_key\n\n@app.get(\"/admin/dashboard\")\nasync def admin_dashboard(api_key: str = Depends(verify_api_key)):\n    return {\"dashboard\": \"admin data\", \"authenticated_with\": api_key}\n\nclass DBSession:  # 7c. yield dep — setup + cleanup\n    def __init__(self): self.connected = True\n    def query(self, table: str): return [{\"id\": 1, \"table\": table}]\n\nasync def get_db():\n    db = DBSession()\n    try: yield db                  # route uses db\n    finally: db.connected = False  # cleanup after route\n\n@app.get(\"/db-demo\")\nasync def db_demo(db: DBSession = Depends(get_db)):\n    return db.query(\"shipments\")\n\n# ╔══════════════════════════════════════════════════╗\n# ║                   ADVANCED                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 8. APIRouter — Organize Routes ──────────────────────────────\n# Like Flask blueprints. Production: routers/users.py, routers/orders.py, main.py includes them.\ncustomer_router = APIRouter(prefix=\"/api/v1/customers\", tags=[\"Customers\"])\n\n@customer_router.get(\"/\")\nasync def list_customers():\n    return [{\"id\": 1, \"name\": \"Acme Corp\"}]\n\n@customer_router.get(\"/{customer_id}\")\nasync def get_customer(customer_id: int):\n    return {\"id\": customer_id, \"name\": \"Acme Corp\"}\n\n@customer_router.post(\"/\", status_code=201)\nasync def create_customer(name: str = Body(embed=True)):\n    return {\"id\": 3, \"name\": name}\n\nprotected_router = APIRouter(  # shared deps — every route requires API key\n    prefix=\"/api/v1/reports\", tags=[\"Reports\"],\n    dependencies=[Depends(verify_api_key)],\n)\n\n@protected_router.get(\"/sales\")\nasync def sales_report():\n    return {\"report\": \"sales\", \"total\": 50000}\n\napp.include_router(customer_router)\napp.include_router(protected_router)\n\n# ── 9. Raw Request Access ──────────────────────────────\n@app.get(\"/raw-request\")\nasync def raw_request(request: Request):\n    return {\"method\": request.method, \"url\": str(request.url),\n            \"query_params\": dict(request.query_params), \"headers\": dict(request.headers),\n            \"client_ip\": request.client.host if request.client else None}\n\n# ── 10. Error Handling ──────────────────────────────\n@app.get(\"/fail/{error_code}\")  # HTTPException — standard errors\nasync def fail(error_code: int):\n    if error_code == 404:\n        raise HTTPException(status_code=404, detail=\"Resource not found\")\n    if error_code == 403:\n        raise HTTPException(status_code=403, detail=\"Forbidden\", headers={\"X-Error\": \"No\"})\n    return {\"status\": \"ok\"}\n\nclass ShipmentNotFoundError(Exception):  # custom exception + handler\n    def __init__(self, shipment_id: int): self.shipment_id = shipment_id\n\n@app.exception_handler(ShipmentNotFoundError)\nasync def shipment_not_found_handler(request: Request, exc: ShipmentNotFoundError):\n    return JSONResponse(status_code=404,\n                        content={\"error\": \"shipment_not_found\", \"id\": exc.shipment_id})\n\n@app.get(\"/shipments-demo/{shipment_id}\")\nasync def get_shipment_demo(shipment_id: int):\n    if shipment_id > 100: raise ShipmentNotFoundError(shipment_id)\n    return {\"id\": shipment_id, \"status\": \"delivered\"}\n\n# ── 11. Async vs Sync ──────────────────────────────\n# async def = I/O-bound (await db/http) on event loop | def = CPU-bound, auto-threadpool\n@app.get(\"/async-demo\")\nasync def async_route(): return {\"type\": \"async\", \"blocks_event_loop\": False}  # use await inside\n\n@app.get(\"/sync-demo\")\ndef sync_route(): return {\"type\": \"sync\", \"runs_in\": \"threadpool\"}  # no await needed\n\n# ── 12. api_route — Multiple Methods ──────────────────────────────\n@app.api_route(\"/multi\", methods=[\"GET\", \"POST\"])\nasync def multi_method(request: Request):\n    return {\"action\": \"reading\" if request.method == \"GET\" else \"creating\"}\n\n# ── 13. BackgroundTasks — run AFTER the response is sent ──────────────────────────────\n# Unlike asyncio.create_task() (see ../intermediate/05_async_await.py), BackgroundTasks is a\n# FastAPI-native way to schedule work that runs once the response has already\n# gone back to the client — the caller never waits for it.\ndef send_confirmation_email(email: str, shipment_id: int):\n    print(f\"[background] emailing {email} about shipment {shipment_id}\")  # simulate I/O\n\n@app.post(\"/shipments-demo/{shipment_id}/notify\")\nasync def notify_shipment(shipment_id: int, email: str, background_tasks: BackgroundTasks):\n    background_tasks.add_task(send_confirmation_email, email, shipment_id)\n    return {\"status\": \"accepted\", \"id\": shipment_id}  # client gets this immediately\n# curl -X POST \"http://localhost:8000/shipments-demo/1/notify?email=a@b.com\"\n# GOTCHA: BackgroundTasks still run in the SAME process/request lifecycle —\n# they delay the server from being fully \"free\" and are lost if the process\n# crashes before running. For durable/critical work, use a real task queue\n# (Celery, arq, RQ) instead — BackgroundTasks is for cheap, best-effort work\n# (sending a notification, writing a log) that shouldn't block the response.", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n# CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\n# SOURCE      | DETECTION               | EXAMPLE\n# ------------|-------------------------|------------------------------------\n# Path param  | {name} in URL           | /users/{id} -> id: int\n# Query param | not in path, simple type| ?page=2 -> page: int = 1\n# Body        | Pydantic model hint     | order: OrderCreate\n# Header      | Header()                | x_tok: Annotated[str, Header()]\n# Cookie      | Cookie()                | sess: Annotated[str, Cookie()]\n# Form        | Form()                  | user: Annotated[str, Form()]\n# File        | File() / UploadFile     | f: UploadFile = File(...)\n# Dependency  | Depends()               | db = Depends(get_db)\n# Raw request | Request type hint       | request: Request\n#\n# RESPONSE    | HOW                     | DEPS: async def()->no cleanup\n# JSON default| return dict/model       |        yield->cleanup in finally\n# Custom JSON | JSONResponse(...)       |        class->via yield wrapper\n# HTML        | response_class=HTML...  |\n# Redirect    | RedirectResponse(url=)  | ASYNC vs SYNC\n# Streaming   | StreamingResponse(gen)  | async def = I/O (await), event loop\n# Plain text  | response_class=Plain... | def = CPU-bound, auto-threadpool\n#\n# Background  | BackgroundTasks         | tasks.add_task(fn, *args) — runs\n#              |                          | AFTER response is sent to client\n# ══════════════════════════════════════════════════════════════════\n#", "reference": "# ══════════════════════════════════════════════════════════════════\n#  ROUTES & ANNOTATED STYLE — DETAILED REFERENCE\n# ══════════════════════════════════════════════════════════════════\n#\n# ── Annotated[] — Modern parameter declaration style ─────────────\n#   Old style:  id: int = Path(gt=0)\n#   New style:  id: Annotated[int, Path(gt=0)]\n#   Both are equivalent. Annotated separates type hint from metadata.\n#   Benefits: reusable (UserId = Annotated[int, Path(ge=1)]), cleaner with type checkers\n#   Requires: from typing import Annotated\n#\n#   BEGINNER EXAMPLE — Annotated[]:\n#\n#     # Old style:\n#     @app.get(\"/old/{id}\")\n#     def old(id: int = Path(gt=0), q: str = Query(\"default\")):\n#         ...\n#     # New style (same behavior):\n#     @app.get(\"/new/{id}\")\n#     def new(id: Annotated[int, Path(gt=0)], q: Annotated[str, Query()] = \"default\"):\n#         ...\n#\n#     # Both called the same way:\n#     #   curl \"http://localhost:8000/new/42?q=test\"\n#     #     id → 42, q → \"test\"\n#     #\n#     # Reusable alias:\n#     #   PositiveInt = Annotated[int, Path(gt=0)]\n#     #   def route_a(id: PositiveInt): ...   ← reuse across routes\n#\n# ── Path() with Annotated ────────────────────────────────────────\n#   product_id: Annotated[int, Path(title=\"Product ID\", ge=1, le=10000)]\n#   title/description → shown in Swagger docs\n#   ge/le/gt/lt → numeric validation (ge=1 means >= 1)\n#\n#   BEGINNER EXAMPLE — Path() with Annotated:\n#\n#     @app.get(\"/product/{product_id}\")\n#     def get_product(product_id: Annotated[int, Path(title=\"Product ID\", ge=1, le=10000)]):\n#         ...\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/product/42\"\n#     #\n#     #   URL:  /product/42\n#     #                  │\n#     #                  ▼\n#     #   Inside function:\n#     #     product_id → 42          ← from URL path, validated ge=1, le=10000\n#     #\n#     #   curl \"http://localhost:8000/product/0\"     → 422! ge=1 fails\n#     #   curl \"http://localhost:8000/product/99999\" → 422! le=10000 fails\n#\n# ── Query() with Annotated ───────────────────────────────────────\n#   start: Annotated[str, Query(description=\"Start date YYYY-MM-DD\")]  → required\n#   max_results: Annotated[int, Query(alias=\"max-results\", ge=1)] = 10 → optional + alias\n#   status: Annotated[list[str], Query()] = [\"active\"]                 → list query param\n#   alias=\"max-results\" → accept hyphenated query param names (?max-results=5)\n#\n#   BEGINNER EXAMPLE — Query() with Annotated + alias:\n#\n#     @app.get(\"/search\")\n#     def search(\n#         q: Annotated[str, Query(description=\"Search term\")],\n#         max_results: Annotated[int, Query(alias=\"max-results\", ge=1)] = 10,\n#         status: Annotated[list[str], Query()] = [\"active\"],\n#     ):\n#         ...\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/search?q=table&max-results=5&status=active&status=pending\"\n#     #\n#     #   URL:  /search?q=table&max-results=5&status=active&status=pending\n#     #                 │        │               │             │\n#     #                 ▼        ▼               └──────┬──────┘\n#     #   Inside function:                              ▼\n#     #     q           → \"table\"          ← required\n#     #     max_results → 5                ← alias \"max-results\" → Python name max_results\n#     #     status      → [\"active\", \"pending\"]  ← repeated key = list\n#     #\n#     #   curl \"http://localhost:8000/search?q=table\"\n#     #     max_results → 10 (default)\n#     #     status → [\"active\"] (default list)\n#     #   NOTE: alias lets you use hyphens in URLs (?max-results) while Python uses underscores\n#\n# ── Body() with Annotated ────────────────────────────────────────\n#   address: Annotated[str, Body(embed=True)]\n#   priority: Annotated[bool, Body(embed=True)] = False\n#   embed=True → wraps each param under its name: {\"address\":\"...\", \"priority\":true}\n#   Without embed, multiple Body params auto-embed by default\n#\n#   BEGINNER EXAMPLE — Body() with Annotated + embed:\n#\n#     @app.post(\"/order\")\n#     def create(\n#         address: Annotated[str, Body(embed=True)],\n#         priority: Annotated[bool, Body(embed=True)] = False,\n#     ):\n#         ...\n#\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/order\" \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\"address\": \"123 Main St\", \"priority\": true}'\n#     #\n#     #   Body: {\"address\": \"123 Main St\", \"priority\": true}\n#     #          │                          │\n#     #          ▼                          ▼\n#     #   Inside function:\n#     #     address  → \"123 Main St\"    ← from body[\"address\"]\n#     #     priority → True             ← from body[\"priority\"]\n#     #\n#     #   curl ... -d '{\"address\": \"123 Main St\"}'\n#     #     priority → False (default)\n#\n# ── Header() with Annotated ──────────────────────────────────────\n#   user_agent: Annotated[str, Header()]        → reads \"User-Agent\" header (auto-converts _ to -)\n#   x_request_id: Annotated[str | None, Header()] = None  → optional header\n#\n#   BEGINNER EXAMPLE — Header() with Annotated:\n#\n#     @app.get(\"/info\")\n#     def info(\n#         user_agent: Annotated[str, Header()],\n#         x_request_id: Annotated[str | None, Header()] = None,\n#     ):\n#         ...\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/info\" \\\n#     #        -H \"User-Agent: MyApp/1.0\" \\\n#     #        -H \"X-Request-Id: req-789\"\n#     #\n#     #   Headers:\n#     #     User-Agent: MyApp/1.0        ← user_agent (underscore → hyphen auto-convert)\n#     #     X-Request-Id: req-789        ← x_request_id\n#     #          │              │\n#     #          ▼              ▼\n#     #   Inside function:\n#     #     user_agent   → \"MyApp/1.0\"   ← from User-Agent header\n#     #     x_request_id → \"req-789\"     ← from X-Request-Id header (optional)\n#\n# ── Cookie() with Annotated ──────────────────────────────────────\n#   session_token: Annotated[str | None, Cookie()] = None  → optional cookie\n#\n#   BEGINNER EXAMPLE — Cookie() with Annotated:\n#\n#     @app.get(\"/dashboard\")\n#     def dashboard(session_token: Annotated[str | None, Cookie()] = None):\n#         ...\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/dashboard\" -b \"session_token=tok_abc123\"\n#     #\n#     #   Cookie: session_token=tok_abc123\n#     #                         │\n#     #                         ▼\n#     #   Inside function:\n#     #     session_token → \"tok_abc123\"   ← from cookie (optional — None if absent)\n#\n# ── Form() with Annotated ───────────────────────────────────────\n#   username: Annotated[str, Form()]    → reads from form-encoded body\n#   Used for HTML form submissions. Cannot mix with Body() in same endpoint.\n#\n#   BEGINNER EXAMPLE — Form() with Annotated:\n#\n#     @app.post(\"/login\")\n#     def login(\n#         username: Annotated[str, Form()],\n#         password: Annotated[str, Form()],\n#     ):\n#         ...\n#\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/login\" \\\n#     #        -d \"username=john&password=secret\"\n#     #\n#     #   Form body: username=john&password=secret\n#     #              │             │\n#     #              ▼             ▼\n#     #   Inside function:\n#     #     username → \"john\"       ← from form field\n#     #     password → \"secret\"     ← from form field\n#     #   Content-Type: application/x-www-form-urlencoded (auto-set)\n#\n# ── File() / UploadFile ──────────────────────────────────────────\n#   file: UploadFile = File(...)        → single file upload (multipart/form-data)\n#   files: list[UploadFile] = File(...) → multiple files\n#   UploadFile attrs: .filename, .content_type, .size, .read(), .seek()\n#\n#   BEGINNER EXAMPLE — File() upload:\n#\n#     @app.post(\"/upload\")\n#     def upload(file: UploadFile = File(...)):\n#         ...\n#\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/upload\" -F \"file=@photo.jpg\"\n#     #\n#     #   Multipart: file=@photo.jpg\n#     #                    │\n#     #                    ▼\n#     #   Inside function:\n#     #     file.filename     → \"photo.jpg\"\n#     #     file.content_type → \"image/jpeg\"\n#     #     await file.read() → b\"\\xff\\xd8...\" (raw bytes)\n#     #\n#     #   Multiple files:\n#     #   curl -F \"files=@a.jpg\" -F \"files=@b.png\" \"http://localhost:8000/upload-multi\"\n#     #     files → [UploadFile(\"a.jpg\"), UploadFile(\"b.png\")]\n#\n# ── Depends() — Dependency injection ─────────────────────────────\n#   pagination: dict = Depends(pagination_params)     → function dependency (reusable params)\n#   api_key: str = Depends(verify_api_key)            → auth guard (raises 403 if invalid)\n#   db: DBSession = Depends(get_db)                   → yield dependency (setup + cleanup)\n#   dependencies=[Depends(verify_api_key)]            → route-level deps (no return value needed)\n#   Yield deps: try: yield resource / finally: cleanup — runs cleanup after route finishes\n#\n#   BEGINNER EXAMPLE — Depends():\n#\n#     # Function dep (reusable params):\n#     def pagination(page: int = Query(1), size: int = Query(10)):\n#         return {\"page\": page, \"size\": size, \"skip\": (page-1)*size}\n#\n#     @app.get(\"/items\")\n#     def list_items(p: dict = Depends(pagination)):\n#         ...\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/items?page=2&size=20\"\n#     #\n#     #   Depends() runs pagination(page=2, size=20) FIRST\n#     #     → returns {\"page\": 2, \"size\": 20, \"skip\": 20}\n#     #                              │\n#     #                              ▼\n#     #     p → {\"page\": 2, \"size\": 20, \"skip\": 20}\n#\n#     # Yield dep (setup + cleanup):\n#     async def get_db():\n#         db = DBSession()\n#         try: yield db            # ← route uses db\n#         finally: db.close()      # ← cleanup AFTER route finishes\n#\n#     # Auth guard:\n#     #   curl \"http://localhost:8000/admin\" -H \"X-Api-Key: secret-key-123\"\n#     #     → Depends(verify_api_key) checks header → valid → route runs\n#     #   curl \"http://localhost:8000/admin\" -H \"X-Api-Key: wrong\"\n#     #     → Depends raises HTTPException(403) → route NEVER runs\n#\n# ── APIRouter — Organize routes into modules ─────────────────────\n#   router = APIRouter(prefix=\"/api/v1/users\", tags=[\"Users\"])\n#   @router.get(\"/\") → becomes /api/v1/users/\n#   app.include_router(router)         → register with main app\n#   Like Flask blueprints. Use for: routers/users.py, routers/orders.py, etc.\n#   dependencies=[Depends(...)] on router → applies to ALL routes in that router\n#\n#   BEGINNER EXAMPLE — APIRouter:\n#\n#     customer_router = APIRouter(prefix=\"/api/v1/customers\", tags=[\"Customers\"])\n#\n#     @customer_router.get(\"/\")\n#     def list_customers(): ...\n#\n#     @customer_router.get(\"/{id}\")\n#     def get_customer(id: int): ...\n#\n#     app.include_router(customer_router)\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/api/v1/customers/\"\n#     #     → hits list_customers()    (prefix + \"/\" = /api/v1/customers/)\n#     #\n#     #   curl \"http://localhost:8000/api/v1/customers/42\"\n#     #     → hits get_customer(id=42) (prefix + \"/{id}\" = /api/v1/customers/42)\n#     #\n#     #   Router with shared auth:\n#     #   protected = APIRouter(prefix=\"/admin\", dependencies=[Depends(verify_api_key)])\n#     #     → EVERY route in this router requires API key — no need to add Depends per route\n#\n# ── Response types ───────────────────────────────────────────────\n#   return dict/model                  → auto-JSONResponse (default)\n#   JSONResponse(content={}, status_code=201)  → custom status/headers\n#   HTMLResponse(\"<h1>Hi</h1>\")        → HTML content\n#   PlainTextResponse(\"text\")          → plain text\n#   RedirectResponse(url=\"/other\", status_code=302) → redirect\n#   StreamingResponse(generator, media_type=\"text/plain\") → streaming/SSE\n#   response.set_cookie(key, value, httponly=True) → set cookie via Response param\n#\n#   BEGINNER EXAMPLE — Response types:\n#\n#     # Default JSON:\n#     @app.get(\"/json\")\n#     def get_json(): return {\"msg\": \"hello\"}\n#     #   curl \"http://localhost:8000/json\"\n#     #     → {\"msg\": \"hello\"}  (Content-Type: application/json — auto)\n#\n#     # Custom status:\n#     @app.post(\"/create\")\n#     def create(): return JSONResponse(content={\"id\": 1}, status_code=201)\n#     #   curl -X POST \"http://localhost:8000/create\"\n#     #     → 201 Created, {\"id\": 1}\n#\n#     # HTML:\n#     @app.get(\"/page\", response_class=HTMLResponse)\n#     def page(): return \"<h1>Hello</h1>\"\n#     #   curl \"http://localhost:8000/page\"\n#     #     → <h1>Hello</h1>  (Content-Type: text/html)\n#\n#     # Redirect:\n#     @app.get(\"/old\")\n#     def old(): return RedirectResponse(url=\"/new\", status_code=301)\n#     #   curl -L \"http://localhost:8000/old\"\n#     #     → follows redirect to /new\n#\n# ── Error handling ───────────────────────────────────────────────\n#   raise HTTPException(status_code=404, detail=\"Not found\")  → standard error\n#   raise HTTPException(status_code=403, headers={\"X-Error\": \"No\"}) → with custom headers\n#   @app.exception_handler(CustomError)   → custom exception → custom JSON response\n#   Custom exception class + handler → clean API error format\n#\n#   BEGINNER EXAMPLE — Error handling:\n#\n#     # Standard HTTPException:\n#     @app.get(\"/item/{id}\")\n#     def get_item(id: int):\n#         if id > 100: raise HTTPException(status_code=404, detail=\"Not found\")\n#         return {\"id\": id}\n#\n#     #   curl \"http://localhost:8000/item/1\"    → {\"id\": 1}\n#     #   curl \"http://localhost:8000/item/999\"  → 404: {\"detail\": \"Not found\"}\n#\n#     # Custom exception + handler:\n#     class ItemNotFound(Exception):\n#         def __init__(self, item_id): self.item_id = item_id\n#\n#     @app.exception_handler(ItemNotFound)\n#     def handle(request, exc):\n#         return JSONResponse(status_code=404, content={\"error\": \"item_not_found\", \"id\": exc.item_id})\n#\n#     #   raise ItemNotFound(42) → {\"error\": \"item_not_found\", \"id\": 42}\n#\n# ── Enum path parameters ────────────────────────────────────────\n#   class ModelName(str, Enum):\n#       GPT4O = \"gpt-4o\"\n#   def route(model: ModelName):       → invalid value → 422 auto-error\n#\n#   BEGINNER EXAMPLE — Enum path:\n#\n#     class ModelName(str, Enum):\n#         GPT4O = \"gpt-4o\"\n#         CLAUDE = \"claude-3.5\"\n#\n#     @app.get(\"/models/{model}\")\n#     def get_model(model: ModelName):\n#         ...\n#\n#     #   curl \"http://localhost:8000/models/gpt-4o\"     → model → ModelName.GPT4O\n#     #   curl \"http://localhost:8000/models/invalid\"    → 422! not a valid enum value\n#\n# ── Catch-all path ──────────────────────────────────────────────\n#   @app.get(\"/files/{file_path:path}\")\n#   → captures slashes: /files/docs/reports/q1.pdf → file_path=\"docs/reports/q1.pdf\"\n#\n#   BEGINNER EXAMPLE — Catch-all :path:\n#\n#     @app.get(\"/files/{file_path:path}\")\n#     def get_file(file_path: str):\n#         ...\n#\n#     #   curl \"http://localhost:8000/files/docs/reports/q1.pdf\"\n#     #\n#     #   URL:  /files/docs/reports/q1.pdf\n#     #                │\n#     #                ▼\n#     #     file_path → \"docs/reports/q1.pdf\"  ← captures everything including slashes\n#     #   Normal {param} would stop at first / — :path captures the full nested path\n#\n# ── api_route — Multiple HTTP methods on same path ──────────────\n#   @app.api_route(\"/multi\", methods=[\"GET\", \"POST\"])\n#   → request.method to distinguish: \"GET\" vs \"POST\"\n#\n#   BEGINNER EXAMPLE — api_route:\n#\n#     @app.api_route(\"/resource\", methods=[\"GET\", \"POST\"])\n#     async def resource(request: Request):\n#         if request.method == \"GET\": return {\"action\": \"reading\"}\n#         else: return {\"action\": \"creating\"}\n#\n#     #   curl \"http://localhost:8000/resource\"            → {\"action\": \"reading\"}\n#     #   curl -X POST \"http://localhost:8000/resource\"    → {\"action\": \"creating\"}\n#     #   Same path, different behavior based on HTTP method\n#\n# ── Raw Request access ──────────────────────────────────────────\n#   request: Request                   → full access to method, url, headers, cookies, client IP\n#   dict(request.query_params)         → all query params as dict\n#   dict(request.headers)              → all headers as dict\n#   request.client.host                → client IP address\n#\n#   BEGINNER EXAMPLE — Raw Request:\n#\n#     @app.get(\"/debug\")\n#     async def debug(request: Request):\n#         return {\n#             \"method\": request.method,\n#             \"url\": str(request.url),\n#             \"headers\": dict(request.headers),\n#             \"client_ip\": request.client.host,\n#         }\n#\n#     #   curl \"http://localhost:8000/debug?foo=bar\" -H \"X-Custom: hello\"\n#     #\n#     #   Inside function:\n#     #     request.method           → \"GET\"\n#     #     request.url              → \"http://localhost:8000/debug?foo=bar\"\n#     #     request.query_params     → {\"foo\": \"bar\"}\n#     #     request.headers[\"x-custom\"] → \"hello\"\n#     #     request.client.host      → \"127.0.0.1\"\n#\n# ══════════════════════════════════════════════════════════════════"}, "04_headers_auth_request_anatomy.py": {"content": "# ══════════════════════════════════════════════════════════════════\n# HTTP Headers, Auth & Request Anatomy — Condensed Reference\n# ══════════════════════════════════════════════════════════════════\n# Run:  uv run uvicorn 04_headers_auth_request_anatomy:app --reload   (from fastapi/basic)\n# Docs: http://localhost:8000/docs\n# ══════════════════════════════════════════════════════════════════\n# This file covers the TERMINOLOGY and CONCEPTS behind what you\n# send when making an HTTP request — headers, auth schemes,\n# API keys, tokens, custom headers, content negotiation, etc.\n# ══════════════════════════════════════════════════════════════════\nfrom typing import Annotated\nfrom fastapi import (\n    FastAPI, Header, Cookie, Depends, HTTPException, Request, Response, Query, status,\n)\nfrom fastapi.security import (\n    HTTPBasic, HTTPBasicCredentials, HTTPBearer, HTTPAuthorizationCredentials,\n    APIKeyHeader, APIKeyQuery, APIKeyCookie, OAuth2PasswordBearer, OAuth2PasswordRequestForm,\n)\nfrom fastapi.responses import JSONResponse\nfrom pydantic import BaseModel\n\napp = FastAPI(title=\"HTTP Headers, Auth & Request Anatomy\")\n\n\n# ╔══════════════════════════════════════════════════════════════════╗\n# ║  WHAT IS AN HTTP REQUEST? — THE FULL ANATOMY                    ║\n# ╠══════════════════════════════════════════════════════════════════╣\n# ║                                                                  ║\n# ║  When you call an API (curl, fetch, axios, httpx), you send:     ║\n# ║                                                                  ║\n# ║  ┌──────────────────────────────────────────────────────────┐    ║\n# ║  │  REQUEST LINE                                            │    ║\n# ║  │  POST /api/v1/orders?page=2 HTTP/1.1                    │    ║\n# ║  │  ───── ─────────────────── ────────                      │    ║\n# ║  │  method   URL path+query   protocol                      │    ║\n# ║  ├──────────────────────────────────────────────────────────┤    ║\n# ║  │  HEADERS (key: value metadata — NOT the data itself)     │    ║\n# ║  │  Host: api.example.com                                   │    ║\n# ║  │  Authorization: Bearer eyJhbGci...                       │    ║\n# ║  │  Content-Type: application/json                          │    ║\n# ║  │  Accept: application/json                                │    ║\n# ║  │  X-Request-ID: req-abc-123                               │    ║\n# ║  │  User-Agent: MyApp/1.0                                   │    ║\n# ║  ├──────────────────────────────────────────────────────────┤    ║\n# ║  │  BODY (the actual data — only for POST/PUT/PATCH)        │    ║\n# ║  │  {\"product\": \"Laptop\", \"quantity\": 2}                    │    ║\n# ║  └──────────────────────────────────────────────────────────┘    ║\n# ║                                                                  ║\n# ║  HEADERS vs BODY vs QUERY PARAMS — When to use which:           ║\n# ║  ┌──────────────┬──────────────────────────────────────────┐    ║\n# ║  │ Query params │ Filtering/pagination: ?page=2&sort=name  │    ║\n# ║  │ Headers      │ Metadata: auth, content type, tracing    │    ║\n# ║  │ Body         │ Actual data: the resource you're sending │    ║\n# ║  └──────────────┴──────────────────────────────────────────┘    ║\n# ╚══════════════════════════════════════════════════════════════════╝\n\n\n# ╔══════════════════════════════════════════════════════════════════╗\n# ║                        BEGINNER                                  ║\n# ╚══════════════════════════════════════════════════════════════════╝\n\n# ── 1. WHAT ARE HTTP HEADERS? ────────────────────────────────────\n# Headers = key-value pairs sent WITH every request and response.\n# They carry METADATA (info about the request), not the data itself.\n# Think of them as the \"envelope\" — the body is the \"letter inside\".\n#\n# REQUEST headers  = client tells server about itself and what it wants\n# RESPONSE headers = server tells client about the response\n#\n# Headers are CASE-INSENSITIVE: \"Content-Type\" = \"content-type\" = \"CONTENT-TYPE\"\n\n@app.get(\"/headers/inspect\")\nasync def inspect_all_headers(request: Request):\n    return {\n        \"all_headers\": dict(request.headers),\n        \"explanation\": {\n            \"host\": \"Domain the request was sent to\",\n            \"user-agent\": \"What client/browser sent the request\",\n            \"accept\": \"What response format the client wants\",\n            \"accept-encoding\": \"What compression the client supports\",\n            \"connection\": \"Keep TCP connection open or close after response\",\n        },\n    }\n# curl -v http://localhost:8000/headers/inspect\n# You'll see headers like: Host, User-Agent, Accept — sent automatically!\n\n\n# ── 2. STANDARD REQUEST HEADERS (sent by client) ────────────────\n# These are headers the CLIENT sends TO the server.\n# You don't invent these — they're defined by HTTP standards (RFCs).\n\n@app.get(\"/headers/standard\")\nasync def standard_headers(\n    host: Annotated[str, Header()],                                 # always sent — the domain\n    user_agent: Annotated[str, Header()],                           # browser/client identifier\n    accept: Annotated[str, Header()] = \"application/json\",          # what format client wants back\n    accept_language: Annotated[str | None, Header()] = None,        # preferred language\n    accept_encoding: Annotated[str | None, Header()] = None,        # gzip, br, deflate\n    connection: Annotated[str | None, Header()] = None,             # keep-alive or close\n    cache_control: Annotated[str | None, Header()] = None,          # caching directives\n    referer: Annotated[str | None, Header()] = None,                # page that linked here\n):\n    return {\n        \"host\": {\"value\": host, \"meaning\": \"Domain name of the server\"},\n        \"user_agent\": {\"value\": user_agent, \"meaning\": \"Client software identifier\"},\n        \"accept\": {\"value\": accept, \"meaning\": \"Response format client prefers\"},\n        \"accept_language\": {\"value\": accept_language, \"meaning\": \"Preferred human language (en-US)\"},\n        \"accept_encoding\": {\"value\": accept_encoding, \"meaning\": \"Compression methods supported\"},\n        \"connection\": {\"value\": connection, \"meaning\": \"Keep TCP alive or close after response\"},\n        \"cache_control\": {\"value\": cache_control, \"meaning\": \"Caching behavior instructions\"},\n        \"referer\": {\"value\": referer, \"meaning\": \"URL of the page that linked to this one\"},\n    }\n# curl http://localhost:8000/headers/standard -H \"Accept-Language: en-US\"\n\n\n# ── 3. STANDARD RESPONSE HEADERS (sent by server) ───────────────\n# These are headers the SERVER sends BACK to the client.\n\n@app.get(\"/headers/response-demo\")\nasync def response_headers_demo(response: Response):\n    response.headers[\"Content-Type\"] = \"application/json\"           # what format the body is\n    response.headers[\"X-Process-Time\"] = \"0.042s\"                   # custom: how long it took\n    response.headers[\"Cache-Control\"] = \"public, max-age=60\"        # caching instruction\n    response.headers[\"ETag\"] = '\"abc123\"'                           # content fingerprint\n    response.headers[\"X-RateLimit-Remaining\"] = \"98\"                # custom: API quota remaining\n    return {\n        \"common_response_headers\": {\n            \"Content-Type\": \"Format of the response body (application/json, text/html)\",\n            \"Content-Length\": \"Size of response body in bytes\",\n            \"Cache-Control\": \"How long client/CDN can cache this response\",\n            \"ETag\": \"Content fingerprint — used for conditional caching (304)\",\n            \"Set-Cookie\": \"Tells browser to store a cookie\",\n            \"Location\": \"Where to redirect (used with 301/302 status codes)\",\n            \"Access-Control-Allow-Origin\": \"CORS — which origins can access this\",\n        },\n    }\n\n\n# ── 4. CONTENT-TYPE — What Format Is the Data? ──────────────────\n# Tells the receiver what format the body is in.\n# REQUEST Content-Type  = \"I'm sending you JSON/form-data/XML\"\n# RESPONSE Content-Type = \"I'm giving you back JSON/HTML/plain text\"\n#\n# Common Content-Type values:\n#   application/json                     → JSON (most APIs)\n#   application/x-www-form-urlencoded    → HTML form data (key=val&key2=val2)\n#   multipart/form-data                  → file uploads\n#   text/html                            → HTML page\n#   text/plain                           → plain text\n#   application/xml                      → XML\n#   application/octet-stream             → raw binary\n\n@app.post(\"/headers/content-type-demo\")\nasync def content_type_demo(request: Request):\n    content_type = request.headers.get(\"content-type\", \"not set\")\n    return {\n        \"you_sent_content_type\": content_type,\n        \"note\": \"FastAPI auto-reads JSON body when Content-Type is application/json\",\n    }\n# curl -X POST http://localhost:8000/headers/content-type-demo \\\n#      -H \"Content-Type: application/json\" -d '{\"key\": \"value\"}'\n# curl -X POST http://localhost:8000/headers/content-type-demo \\\n#      -d \"username=john\"   # → Content-Type: application/x-www-form-urlencoded (auto)\n\n\n# ── 5. ACCEPT — What Format Do You Want Back? ───────────────────\n# Client tells server: \"Give me the response in THIS format\"\n# Server checks Accept header and returns appropriate Content-Type.\n# Most APIs ignore this and always return JSON — but it's the standard.\n\n@app.get(\"/headers/accept-demo\")\nasync def accept_demo(accept: Annotated[str, Header()] = \"application/json\"):\n    if \"text/html\" in accept:\n        return Response(\"<h1>HTML response</h1>\", media_type=\"text/html\")\n    if \"text/plain\" in accept:\n        return Response(\"Plain text response\", media_type=\"text/plain\")\n    return {\"format\": \"json\", \"message\": \"Default JSON response\"}\n# curl http://localhost:8000/headers/accept-demo -H \"Accept: text/html\"\n# curl http://localhost:8000/headers/accept-demo -H \"Accept: text/plain\"\n# curl http://localhost:8000/headers/accept-demo  # → JSON (default)\n\n\n# ╔══════════════════════════════════════════════════════════════════╗\n# ║                      INTERMEDIATE                                ║\n# ╚══════════════════════════════════════════════════════════════════╝\n\n# ── 6. AUTHORIZATION HEADER — The Standard Way to Authenticate ──\n# Authorization: <scheme> <credentials>\n#\n# THE MOST IMPORTANT HEADER. Almost every API requires it.\n# The value has two parts: the SCHEME (how) and the CREDENTIALS (what).\n#\n# Common Authorization schemes:\n# ┌─────────────────┬────────────────────────────────────────────────┐\n# │ Scheme          │ Example                                        │\n# ├─────────────────┼────────────────────────────────────────────────┤\n# │ Bearer          │ Authorization: Bearer eyJhbGciOi...            │\n# │                 │ (JWT or OAuth2 token — most common in APIs)    │\n# ├─────────────────┼────────────────────────────────────────────────┤\n# │ Basic           │ Authorization: Basic dXNlcjpwYXNz             │\n# │                 │ (base64 of \"username:password\" — simple auth)  │\n# ├─────────────────┼────────────────────────────────────────────────┤\n# │ ApiKey          │ Authorization: ApiKey sk-abc123...              │\n# │                 │ (some APIs use this — not a standard scheme)    │\n# ├─────────────────┼────────────────────────────────────────────────┤\n# │ Digest          │ Authorization: Digest username=\"...\",nonce=... │\n# │                 │ (challenge-response — rare, more secure basic) │\n# ├─────────────────┼────────────────────────────────────────────────┤\n# │ AWS4-HMAC-SHA256│ Authorization: AWS4-HMAC-SHA256 Credential=...│\n# │                 │ (AWS SigV4 — for AWS service calls)            │\n# └─────────────────┴────────────────────────────────────────────────┘\n\n# 6a. Bearer Token (JWT / OAuth2) — most common modern API auth\nbearer_scheme = HTTPBearer()\n\n@app.get(\"/auth/bearer\")\nasync def bearer_auth(credentials: HTTPAuthorizationCredentials = Depends(bearer_scheme)):\n    return {\n        \"scheme\": credentials.scheme,          # \"Bearer\"\n        \"token\": credentials.credentials,       # the actual token string\n        \"note\": \"In production, decode and validate the JWT here\",\n    }\n# curl http://localhost:8000/auth/bearer -H \"Authorization: Bearer my-jwt-token-here\"\n# Without the header → 403 Forbidden (HTTPBearer auto-rejects)\n\n# 6b. Basic Auth — username:password base64-encoded\nbasic_scheme = HTTPBasic()\n\n@app.get(\"/auth/basic\")\nasync def basic_auth(credentials: HTTPBasicCredentials = Depends(basic_scheme)):\n    if credentials.username != \"admin\" or credentials.password != \"secret\":\n        raise HTTPException(status_code=401, detail=\"Invalid credentials\",\n                            headers={\"WWW-Authenticate\": \"Basic\"})\n    return {\"username\": credentials.username, \"authenticated\": True}\n# curl http://localhost:8000/auth/basic -u admin:secret\n# curl automatically base64-encodes \"admin:secret\" → \"YWRtaW46c2VjcmV0\"\n# and sends: Authorization: Basic YWRtaW46c2VjcmV0\n\n\n# ── 7. API KEYS — Alternative to Authorization Header ───────────\n# Not all APIs use the Authorization header. API keys can travel in:\n#   1. Header:  X-API-Key: sk-abc123        (most common)\n#   2. Query:   ?api_key=sk-abc123          (easy but visible in logs/URLs)\n#   3. Cookie:  api_key=sk-abc123           (rare for APIs)\n#\n# API keys vs Tokens:\n# ┌─────────────┬────────────────────────────────────────────────┐\n# │ API Key     │ Static string, identifies the APPLICATION      │\n# │             │ \"Which app is calling me?\" — billing, rate limit│\n# ├─────────────┼────────────────────────────────────────────────┤\n# │ Bearer Token│ Dynamic string (JWT), identifies the USER      │\n# │ (JWT)       │ \"Who is this person?\" — permissions, identity  │\n# ├─────────────┼────────────────────────────────────────────────┤\n# │ Both        │ Some APIs need both: API key (which app) +     │\n# │             │ Bearer token (which user)                      │\n# └─────────────┴────────────────────────────────────────────────┘\n\n# 7a. API Key in Header\napi_key_header = APIKeyHeader(name=\"X-API-Key\")\n\n@app.get(\"/auth/api-key-header\")\nasync def api_key_in_header(api_key: str = Depends(api_key_header)):\n    if api_key != \"sk-live-abc123\":\n        raise HTTPException(status_code=403, detail=\"Invalid API key\")\n    return {\"api_key_source\": \"header\", \"key\": api_key[:10] + \"...\"}\n# curl http://localhost:8000/auth/api-key-header -H \"X-API-Key: sk-live-abc123\"\n\n# 7b. API Key in Query Parameter\napi_key_query = APIKeyQuery(name=\"api_key\")\n\n@app.get(\"/auth/api-key-query\")\nasync def api_key_in_query(api_key: str = Depends(api_key_query)):\n    if api_key != \"sk-live-abc123\":\n        raise HTTPException(status_code=403, detail=\"Invalid API key\")\n    return {\"api_key_source\": \"query\", \"key\": api_key[:10] + \"...\"}\n# curl \"http://localhost:8000/auth/api-key-query?api_key=sk-live-abc123\"\n# WARNING: query params show up in browser history, server logs, referer headers!\n\n# 7c. API Key in Cookie\napi_key_cookie = APIKeyCookie(name=\"api_key\")\n\n@app.get(\"/auth/api-key-cookie\")\nasync def api_key_in_cookie(api_key: str = Depends(api_key_cookie)):\n    if api_key != \"sk-live-abc123\":\n        raise HTTPException(status_code=403, detail=\"Invalid API key\")\n    return {\"api_key_source\": \"cookie\", \"key\": api_key[:10] + \"...\"}\n# curl http://localhost:8000/auth/api-key-cookie -b \"api_key=sk-live-abc123\"\n\n\n# ── 8. X-<NAME> CUSTOM HEADERS — Application-Specific Metadata ──\n# X- prefix = custom/non-standard header. Your app defines these.\n# Common patterns in production APIs:\n#\n# ┌──────────────────────┬───────────────────────────────────────────┐\n# │ Header               │ Purpose                                   │\n# ├──────────────────────┼───────────────────────────────────────────┤\n# │ X-Request-ID         │ Unique ID for tracing a request across    │\n# │                      │ services (debugging distributed systems)  │\n# ├──────────────────────┼───────────────────────────────────────────┤\n# │ X-Correlation-ID     │ Same as X-Request-ID (different name)     │\n# ├──────────────────────┼───────────────────────────────────────────┤\n# │ X-Tenant-ID          │ Multi-tenant apps: which tenant/org       │\n# ├──────────────────────┼───────────────────────────────────────────┤\n# │ X-API-Key            │ API key (alternative to Authorization)    │\n# ├──────────────────────┼───────────────────────────────────────────┤\n# │ X-RateLimit-Limit    │ Max requests allowed in window            │\n# │ X-RateLimit-Remaining│ Requests left in current window           │\n# │ X-RateLimit-Reset    │ When the window resets (Unix timestamp)   │\n# ├──────────────────────┼───────────────────────────────────────────┤\n# │ X-Forwarded-For      │ Original client IP when behind a proxy    │\n# │ X-Forwarded-Proto    │ Original protocol (http/https) behind LB  │\n# │ X-Forwarded-Host     │ Original Host header behind proxy         │\n# ├──────────────────────┼───────────────────────────────────────────┤\n# │ X-Application-Name   │ Which app is calling (for logging)        │\n# │ X-User-ID            │ User identifier (when not in JWT)         │\n# │ X-Session-ID         │ Session tracking across requests          │\n# └──────────────────────┴───────────────────────────────────────────┘\n#\n# NOTE: The X- prefix was officially deprecated in RFC 6648 (2012).\n# New custom headers don't NEED the prefix, but most APIs still use it\n# by convention. Both \"X-Request-ID\" and \"Request-ID\" are valid.\n\n@app.get(\"/headers/custom\")\nasync def custom_headers(\n    x_request_id: Annotated[str | None, Header()] = None,\n    x_tenant_id: Annotated[str | None, Header()] = None,\n    x_correlation_id: Annotated[str | None, Header()] = None,\n    x_application_name: Annotated[str | None, Header()] = None,\n    x_user_id: Annotated[str | None, Header()] = None,\n):\n    return {\n        \"received_custom_headers\": {\n            \"X-Request-ID\": x_request_id,\n            \"X-Tenant-ID\": x_tenant_id,\n            \"X-Correlation-ID\": x_correlation_id,\n            \"X-Application-Name\": x_application_name,\n            \"X-User-ID\": x_user_id,\n        },\n        \"note\": \"FastAPI auto-converts header names: X-Request-ID -> x_request_id\",\n    }\n# curl http://localhost:8000/headers/custom \\\n#      -H \"X-Request-ID: req-abc-123\" \\\n#      -H \"X-Tenant-ID: tenant-42\" \\\n#      -H \"X-Application-Name: LEON\"\n\n\n# ── 9. REAL-WORLD MULTI-HEADER AUTH PATTERN ──────────────────────\n# Many production APIs require MULTIPLE headers together.\n# Example: Our Reuters AI Assistant backend expects:\n#   Authorization: Bearer <jwt>       ← who is the user\n#   X-Tenant-ID: leon-shubham         ← which tenant/organization\n#   X-Application-Name: LEON          ← which frontend app\n#   X-User-ID: user@reuters.com       ← user identifier\n#   X-Request-ID: req-123             ← request tracing\n\nasync def verify_full_auth(\n    authorization: Annotated[str, Header()],\n    x_tenant_id: Annotated[str, Header()],\n    x_application_name: Annotated[str | None, Header()] = None,\n    x_user_id: Annotated[str | None, Header()] = None,\n    x_request_id: Annotated[str | None, Header()] = None,\n):\n    if not authorization.startswith(\"Bearer \"):\n        raise HTTPException(status_code=401, detail=\"Invalid Authorization header\")\n    token = authorization.removeprefix(\"Bearer \")\n    return {\n        \"token\": token,\n        \"tenant\": x_tenant_id,\n        \"app\": x_application_name,\n        \"user\": x_user_id,\n        \"request_id\": x_request_id,\n    }\n\n@app.get(\"/auth/multi-header\")\nasync def multi_header_auth(auth_context: dict = Depends(verify_full_auth)):\n    return {\"authenticated\": True, \"context\": auth_context}\n# curl http://localhost:8000/auth/multi-header \\\n#      -H \"Authorization: Bearer eyJhbGciOiJIUzI1NiJ9.test\" \\\n#      -H \"X-Tenant-ID: leon-shubham\" \\\n#      -H \"X-Application-Name: LEON\" \\\n#      -H \"X-User-ID: john@example.com\" \\\n#      -H \"X-Request-ID: req-abc-123\"\n\n\n# ╔══════════════════════════════════════════════════════════════════╗\n# ║                        ADVANCED                                  ║\n# ╚══════════════════════════════════════════════════════════════════╝\n\n# ── 10. OAuth2 PASSWORD FLOW (FastAPI built-in) ──────────────────\n# OAuth2 = standard protocol for token-based auth. Many flows exist:\n#   Password flow  = send username+password, get token back (simple)\n#   Auth code flow = redirect to login page, get code, exchange for token (Google/GitHub login)\n#   Client creds   = machine-to-machine auth (no user involved)\n#\n# FastAPI has built-in OAuth2 support that auto-generates a login form in /docs.\n\noauth2_scheme = OAuth2PasswordBearer(tokenUrl=\"/auth/token\")\n\nFAKE_USERS_DB = {\n    \"admin\": {\"username\": \"admin\", \"password\": \"secret\", \"role\": \"admin\"},\n    \"reader\": {\"username\": \"reader\", \"password\": \"pass123\", \"role\": \"reader\"},\n}\n\n@app.post(\"/auth/token\")\nasync def login_for_token(form_data: OAuth2PasswordRequestForm = Depends()):\n    user = FAKE_USERS_DB.get(form_data.username)\n    if not user or user[\"password\"] != form_data.password:\n        raise HTTPException(status_code=401, detail=\"Invalid credentials\")\n    return {\"access_token\": f\"fake-jwt-for-{form_data.username}\", \"token_type\": \"bearer\"}\n# curl -X POST http://localhost:8000/auth/token -d \"username=admin&password=secret\"\n# → {\"access_token\": \"fake-jwt-for-admin\", \"token_type\": \"bearer\"}\n\n@app.get(\"/auth/protected\")\nasync def protected_route(token: str = Depends(oauth2_scheme)):\n    return {\"message\": \"You have access\", \"token_received\": token}\n# curl http://localhost:8000/auth/protected -H \"Authorization: Bearer fake-jwt-for-admin\"\n\n\n# ── 11. CONTENT NEGOTIATION — Full Pattern ───────────────────────\n# Client says what it wants (Accept), server responds accordingly.\n# Professional APIs support multiple formats from the same endpoint.\n\n@app.get(\"/data/{item_id}\")\nasync def get_data_negotiated(item_id: int, request: Request):\n    data = {\"id\": item_id, \"name\": \"Widget\", \"price\": 29.99}\n    accept = request.headers.get(\"accept\", \"application/json\")\n\n    if \"text/csv\" in accept:\n        csv = \"id,name,price\\n\" + f\"{data['id']},{data['name']},{data['price']}\"\n        return Response(content=csv, media_type=\"text/csv\",\n                        headers={\"Content-Disposition\": f\"attachment; filename=item_{item_id}.csv\"})\n\n    if \"text/plain\" in accept:\n        return Response(content=f\"Item {item_id}: {data['name']} - ${data['price']}\")\n\n    return data  # default JSON\n# curl http://localhost:8000/data/1                          → JSON\n# curl http://localhost:8000/data/1 -H \"Accept: text/csv\"   → CSV download\n# curl http://localhost:8000/data/1 -H \"Accept: text/plain\" → plain text\n\n\n# ── 12. SECURITY HEADERS (Response) ─────────────────────────────\n# Headers the server sends to protect the client (browser security).\n# Usually set in middleware or reverse proxy (nginx), not per-route.\n\n@app.middleware(\"http\")\nasync def add_security_headers(request: Request, call_next):\n    response = await call_next(request)\n    response.headers[\"X-Content-Type-Options\"] = \"nosniff\"               # don't guess MIME type\n    response.headers[\"X-Frame-Options\"] = \"DENY\"                         # prevent iframe embedding\n    response.headers[\"Strict-Transport-Security\"] = \"max-age=31536000\"   # force HTTPS for 1 year\n    response.headers[\"X-XSS-Protection\"] = \"1; mode=block\"               # legacy XSS filter\n    response.headers[\"Referrer-Policy\"] = \"strict-origin-when-cross-origin\"\n    return response\n\n\n# ── 13. FORWARDING / PROXY HEADERS ──────────────────────────────\n# When your API is behind a load balancer (ALB, nginx, Cloudflare),\n# the client IP and protocol get replaced by the proxy's.\n# Proxy sets X-Forwarded-* headers with the ORIGINAL values.\n\n@app.get(\"/headers/proxy-info\")\nasync def proxy_info(request: Request):\n    return {\n        \"direct_client_ip\": request.client.host if request.client else None,\n        \"x_forwarded_for\": request.headers.get(\"x-forwarded-for\"),\n        \"x_forwarded_proto\": request.headers.get(\"x-forwarded-proto\"),\n        \"x_forwarded_host\": request.headers.get(\"x-forwarded-host\"),\n        \"x_real_ip\": request.headers.get(\"x-real-ip\"),\n        \"explanation\": {\n            \"X-Forwarded-For\": \"Original client IP (can be chain: client, proxy1, proxy2)\",\n            \"X-Forwarded-Proto\": \"Original protocol (https even if proxy→app is http)\",\n            \"X-Forwarded-Host\": \"Original Host header before proxy rewrote it\",\n            \"X-Real-IP\": \"Nginx-specific: single original client IP\",\n        },\n    }\n# Behind ALB: client (1.2.3.4) → ALB (10.0.0.1) → your app\n#   request.client.host = \"10.0.0.1\" (ALB's IP — NOT the user!)\n#   X-Forwarded-For = \"1.2.3.4\" (the real user IP)", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n# CHEAT SHEET — HEADER CATEGORIES\n# ══════════════════════════════════════════════════════════════════\n# CATEGORY          │ HEADER                │ PURPOSE\n# ──────────────────┼───────────────────────┼──────────────────────────────\n# IDENTITY          │ Host                  │ Target server domain\n#                   │ User-Agent            │ Client software identifier\n#                   │ Referer               │ Page that linked here\n# ──────────────────┼───────────────────────┼──────────────────────────────\n# AUTH              │ Authorization         │ Bearer <token> or Basic <b64>\n#                   │ X-API-Key             │ API key (custom header)\n#                   │ Cookie                │ Session/auth cookie\n#                   │ WWW-Authenticate      │ Server tells client how to auth\n# ──────────────────┼───────────────────────┼──────────────────────────────\n# CONTENT           │ Content-Type          │ Body format (application/json)\n#                   │ Content-Length         │ Body size in bytes\n#                   │ Accept                │ Desired response format\n#                   │ Accept-Encoding       │ Compression support (gzip, br)\n#                   │ Accept-Language       │ Preferred language (en-US)\n#                   │ Content-Disposition   │ Download filename hint\n# ──────────────────┼───────────────────────┼──────────────────────────────\n# CACHING           │ Cache-Control         │ Caching rules (max-age, no-store)\n#                   │ ETag                  │ Content fingerprint\n#                   │ If-None-Match         │ Conditional request (use ETag)\n#                   │ Last-Modified         │ When resource last changed\n#                   │ If-Modified-Since     │ Conditional request (use date)\n# ──────────────────┼───────────────────────┼──────────────────────────────\n# SECURITY          │ Strict-Transport-Security │ Force HTTPS\n#                   │ X-Content-Type-Options│ Prevent MIME sniffing\n#                   │ X-Frame-Options       │ Prevent iframe embedding\n#                   │ X-XSS-Protection      │ Legacy XSS filter\n#                   │ Referrer-Policy       │ Control referer leakage\n# ──────────────────┼───────────────────────┼──────────────────────────────\n# CORS              │ Origin                │ Where the request came from\n#                   │ Access-Control-Allow-Origin    │ Allowed origins\n#                   │ Access-Control-Allow-Methods   │ Allowed HTTP methods\n#                   │ Access-Control-Allow-Headers   │ Allowed request headers\n# ──────────────────┼───────────────────────┼──────────────────────────────\n# PROXY/LB          │ X-Forwarded-For       │ Original client IP\n#                   │ X-Forwarded-Proto     │ Original protocol (http/https)\n#                   │ X-Forwarded-Host      │ Original host header\n#                   │ X-Real-IP             │ Nginx: single client IP\n# ──────────────────┼───────────────────────┼──────────────────────────────\n# CUSTOM (X-)       │ X-Request-ID          │ Request tracing/correlation\n#                   │ X-Tenant-ID           │ Multi-tenant: which org\n#                   │ X-Application-Name    │ Which app is calling\n#                   │ X-User-ID             │ User identifier\n#                   │ X-RateLimit-*         │ Rate limit info\n# ──────────────────┼───────────────────────┼──────────────────────────────\n# CONNECTION        │ Connection            │ keep-alive or close\n#                   │ Transfer-Encoding     │ chunked (streaming)\n#                   │ Upgrade               │ Protocol upgrade (WebSocket)\n# ══════════════════════════════════════════════════════════════════\n\n# ══════════════════════════════════════════════════════════════════\n# AUTH COMPARISON — When to Use What\n# ══════════════════════════════════════════════════════════════════\n# METHOD            │ WHERE                 │ WHEN TO USE\n# ──────────────────┼───────────────────────┼──────────────────────────\n# Bearer Token (JWT)│ Authorization header  │ User auth, modern APIs\n#                   │                       │ Contains user info inside token\n# ──────────────────┼───────────────────────┼──────────────────────────\n# Basic Auth        │ Authorization header  │ Simple server-to-server\n#                   │                       │ Username:password base64\n# ──────────────────┼───────────────────────┼──────────────────────────\n# API Key (header)  │ X-API-Key header      │ App identification, billing\n#                   │                       │ Static, doesn't expire\n# ──────────────────┼───────────────────────┼──────────────────────────\n# API Key (query)   │ ?api_key=xxx          │ Quick testing, webhooks\n#                   │                       │ AVOID in prod (leaks in logs)\n# ──────────────────┼───────────────────────┼──────────────────────────\n# Cookie            │ Cookie header         │ Browser sessions, SSR apps\n#                   │                       │ Auto-sent by browser\n# ──────────────────┼───────────────────────┼──────────────────────────\n# OAuth2 Code Flow  │ Authorization header  │ \"Login with Google/GitHub\"\n#                   │                       │ User redirected → code → token\n# ══════════════════════════════════════════════════════════════════", "reference": "# ══════════════════════════════════════════════════════════════════\n#  HEADERS, AUTH & REQUEST ANATOMY — DETAILED REFERENCE\n# ══════════════════════════════════════════════════════════════════\n#\n# ── What is an HTTP Header? ──────────────────────────────────────\n#   A key-value pair sent alongside every HTTP request and response.\n#   Headers are METADATA — they describe the request, not the data.\n#   Case-insensitive: Content-Type = content-type = CONTENT-TYPE\n#   Format: \"Header-Name: header-value\" (colon + space separator)\n#\n#   BEGINNER EXAMPLE — What headers look like in raw HTTP:\n#\n#     # When you run: curl -v http://localhost:8000/items\n#     # You see the FULL HTTP request:\n#     #\n#     #   > GET /items HTTP/1.1              ← request line (method + path)\n#     #   > Host: localhost:8000             ← HEADER: which server\n#     #   > User-Agent: curl/7.88.1         ← HEADER: what client\n#     #   > Accept: */*                     ← HEADER: any format is fine\n#     #   >                                 ← empty line = end of headers\n#     #                                        (body would go here for POST)\n#     #\n#     #   < HTTP/1.1 200 OK                 ← response status\n#     #   < content-type: application/json  ← RESPONSE HEADER: it's JSON\n#     #   < content-length: 42              ← RESPONSE HEADER: 42 bytes\n#     #   <                                 ← empty line = end of headers\n#     #   < [{\"id\":1,\"name\":\"Laptop\"}]      ← RESPONSE BODY\n#     #\n#     #   > means REQUEST (sent by you)\n#     #   < means RESPONSE (sent by server)\n#\n# ── Authorization header — Bearer token ──────────────────────────\n#   Authorization: Bearer eyJhbGciOiJIUzI1NiJ9...\n#   \"Bearer\" = scheme name (tells server how to interpret the token)\n#   The token after \"Bearer \" is typically a JWT (JSON Web Token).\n#   JWT contains encoded user info: {user_id, role, exp} signed by server.\n#   Server VALIDATES the JWT signature — if tampered, auth fails.\n#\n#   BEGINNER EXAMPLE — Bearer token flow:\n#\n#     # Step 1: Login — POST username/password, get token back\n#     #   curl -X POST http://localhost:8000/auth/token \\\n#     #        -d \"username=admin&password=secret\"\n#     #     → {\"access_token\": \"eyJhbG...\", \"token_type\": \"bearer\"}\n#     #\n#     # Step 2: Use token — include in every subsequent request\n#     #   curl http://localhost:8000/auth/protected \\\n#     #        -H \"Authorization: Bearer eyJhbG...\"\n#     #     → {\"message\": \"You have access\"}\n#     #\n#     # What happens inside the server:\n#     #   1. Extract token from \"Authorization: Bearer <token>\"\n#     #   2. Decode JWT → {\"user_id\": 42, \"role\": \"admin\", \"exp\": 1700000000}\n#     #   3. Verify signature (was it signed by our server's secret key?)\n#     #   4. Check expiry (is exp > now?)\n#     #   5. If valid → allow request; if invalid → 401 Unauthorized\n#     #\n#     # Why \"Bearer\"?\n#     #   \"Bearer\" means \"whoever BEARS (carries) this token gets access\"\n#     #   It's like a concert ticket — anyone holding it can enter\n#     #   That's why tokens must be kept secret and sent over HTTPS only\n#\n# ── Authorization header — Basic auth ────────────────────────────\n#   Authorization: Basic dXNlcjpwYXNz\n#   \"Basic\" = scheme name\n#   \"dXNlcjpwYXNz\" = base64(\"user:pass\")\n#   base64 is NOT encryption — anyone can decode it!\n#   Only safe over HTTPS.\n#\n#   BEGINNER EXAMPLE — Basic auth:\n#\n#     # curl -u admin:secret http://localhost:8000/auth/basic\n#     #\n#     # What curl does behind the scenes:\n#     #   1. Takes \"admin:secret\"\n#     #   2. base64 encodes it → \"YWRtaW46c2VjcmV0\"\n#     #   3. Sends: Authorization: Basic YWRtaW46c2VjcmV0\n#     #\n#     # Server decodes:\n#     #   base64(\"YWRtaW46c2VjcmV0\") → \"admin:secret\"\n#     #   Split on \":\" → username=\"admin\", password=\"secret\"\n#     #   Check against database → valid → 200\n#     #\n#     # DANGER: base64 is reversible — NOT secure without HTTPS\n#     #   echo \"YWRtaW46c2VjcmV0\" | base64 -d   → \"admin:secret\"\n#\n# ── API Keys — Header vs Query vs Cookie ─────────────────────────\n#   HEADER:  curl -H \"X-API-Key: sk-abc123\" http://api.example.com/data\n#   QUERY:   curl \"http://api.example.com/data?api_key=sk-abc123\"\n#   COOKIE:  curl -b \"api_key=sk-abc123\" http://api.example.com/data\n#\n#   BEGINNER EXAMPLE — API key flow:\n#\n#     # API keys are like a building pass — identifies WHICH APP, not which user.\n#     #\n#     # Header (RECOMMENDED):\n#     #   curl http://localhost:8000/data -H \"X-API-Key: sk-live-abc123\"\n#     #   Pros: doesn't show in URL, not in browser history\n#     #   Cons: can't send from <a href> or <img src> tags\n#     #\n#     # Query param (easy but risky):\n#     #   curl \"http://localhost:8000/data?api_key=sk-live-abc123\"\n#     #   Pros: works everywhere (even in <img src=\"...?api_key=xxx\">)\n#     #   Cons: shows in server logs, browser history, Referer header!\n#     #         If you share the URL, you share your key\n#     #\n#     # Real-world examples:\n#     #   OpenAI:   Authorization: Bearer sk-...     (Bearer token style)\n#     #   Stripe:   Authorization: Bearer sk_live_...\n#     #   Google:   ?key=AIzaSy...                   (query param)\n#     #   GitHub:   Authorization: token ghp_...     (custom scheme)\n#     #   AWS:      Authorization: AWS4-HMAC-SHA256  (SigV4 signature)\n#\n# ── X-<Name> Custom Headers ──────────────────────────────────────\n#   \"X-\" prefix = custom header defined by YOUR application.\n#   FastAPI auto-converts: \"X-Request-ID\" → Python param x_request_id\n#   (underscores replace hyphens, everything lowercase)\n#\n#   BEGINNER EXAMPLE — Custom headers:\n#\n#     @app.get(\"/api/data\")\n#     async def get_data(\n#         x_request_id: Annotated[str | None, Header()] = None,\n#         x_tenant_id: Annotated[str | None, Header()] = None,\n#     ):\n#         ...\n#\n#     # curl http://localhost:8000/api/data \\\n#     #      -H \"X-Request-ID: req-abc-123\" \\\n#     #      -H \"X-Tenant-ID: acme-corp\"\n#     #\n#     #   Header names sent:        Python parameter names:\n#     #   X-Request-ID    ────────→  x_request_id\n#     #   X-Tenant-ID     ────────→  x_tenant_id\n#     #   Content-Type    ────────→  content_type\n#     #   User-Agent      ────────→  user_agent\n#     #\n#     #   Rule: hyphens → underscores, all lowercase\n#     #   \"X-My-Custom-Header\" → x_my_custom_header\n#\n# ── Content-Type — Common Values ─────────────────────────────────\n#   application/json                    → JSON body (most APIs)\n#   application/x-www-form-urlencoded   → HTML form: key=val&key2=val2\n#   multipart/form-data                 → File uploads\n#   text/html                           → HTML page\n#   text/plain                          → Plain text\n#   text/csv                            → CSV data\n#   application/xml                     → XML\n#   application/pdf                     → PDF file\n#   application/octet-stream            → Raw binary (downloads)\n#   image/png, image/jpeg               → Images\n#\n#   BEGINNER EXAMPLE — Content-Type matters:\n#\n#     # Sending JSON (most common for APIs):\n#     #   curl -X POST http://localhost:8000/orders \\\n#     #        -H \"Content-Type: application/json\" \\\n#     #        -d '{\"product\": \"Laptop\", \"qty\": 2}'\n#     #   FastAPI sees Content-Type: application/json → parses body as JSON\n#     #\n#     # Sending form data (HTML forms, login):\n#     #   curl -X POST http://localhost:8000/login \\\n#     #        -d \"username=admin&password=secret\"\n#     #   curl auto-sets Content-Type: application/x-www-form-urlencoded\n#     #   FastAPI uses Form() to read these fields\n#     #\n#     # Uploading a file:\n#     #   curl -X POST http://localhost:8000/upload -F \"file=@photo.jpg\"\n#     #   curl auto-sets Content-Type: multipart/form-data\n#     #   FastAPI uses File() / UploadFile to read the file\n#     #\n#     # KEY INSIGHT: Content-Type tells the server HOW to parse the body.\n#     # Wrong Content-Type = server can't read your data!\n#\n# ── Cookies vs Headers — When to Use Which ───────────────────────\n#   Cookies: auto-sent by browser on every request to that domain\n#            great for web apps (session tokens, preferences)\n#            set by server via Set-Cookie response header\n#   Headers: manually added by client code (fetch, axios, curl)\n#            great for APIs (tokens, API keys, metadata)\n#            not auto-sent — you control exactly what's included\n#\n#   BEGINNER EXAMPLE — Cookies vs Headers:\n#\n#     # COOKIE flow (browser web app):\n#     #   1. Login: POST /login → server responds with Set-Cookie: session=abc123\n#     #   2. Browser AUTOMATICALLY sends Cookie: session=abc123 on every request\n#     #   3. No client code needed — browser handles it\n#     #\n#     # HEADER flow (API / mobile app):\n#     #   1. Login: POST /auth/token → server responds with {\"token\": \"eyJ...\"}\n#     #   2. Client manually stores token (localStorage, keychain)\n#     #   3. Client manually adds: Authorization: Bearer eyJ... to every request\n#     #   4. Full control — but more work for the developer\n#     #\n#     # Why APIs prefer headers over cookies:\n#     #   - Cookies are domain-bound (can't use cross-domain easily)\n#     #   - Cookies are vulnerable to CSRF attacks\n#     #   - Headers work identically from any client (browser, mobile, CLI)\n#     #   - Headers are explicit — no \"magic\" auto-sending\n#\n# ── FastAPI Header() — Conversion Rules ──────────────────────────\n#   FastAPI automatically converts between HTTP header names and Python:\n#     HTTP header name    →  Python parameter name\n#     Content-Type        →  content_type\n#     X-Request-ID        →  x_request_id\n#     User-Agent          →  user_agent\n#     Authorization       →  authorization\n#     Accept-Language     →  accept_language\n#\n#   Rules:\n#     1. Hyphens (-) become underscores (_)\n#     2. Everything becomes lowercase\n#     3. This is automatic — you don't need to configure it\n#\n#   To disable conversion (rare):\n#     x_weird: Annotated[str, Header(convert_underscores=False)]\n#     → reads header named literally \"x_weird\" (with underscore)\n#\n# ── WWW-Authenticate — Server Tells Client How to Auth ───────────\n#   When server returns 401, it SHOULD include WWW-Authenticate header\n#   telling the client WHICH auth method to use.\n#\n#     HTTP/1.1 401 Unauthorized\n#     WWW-Authenticate: Bearer realm=\"api\"\n#     → Client should retry with: Authorization: Bearer <token>\n#\n#     HTTP/1.1 401 Unauthorized\n#     WWW-Authenticate: Basic realm=\"admin area\"\n#     → Browser auto-pops up username/password dialog!\n#\n# ══════════════════════════════════════════════════════════════════"}}, "fastapi/intermediate": {"05_async_await.py": {"content": "# ══════════════════════════════════════════════════════════════════\n# Python Async/Await Guide with FastAPI  (~25 patterns, condensed)\n# ══════════════════════════════════════════════════════════════════\nimport asyncio, httpx\nfrom fastapi import FastAPI, HTTPException\nfrom typing import Optional\napp = FastAPI()\nshipment_data = {\n    1: {\"id\": 1, \"content\": \"Shipment 1\", \"weight\": 10, \"status\": \"In Transit\"},\n    2: {\"id\": 2, \"content\": \"Shipment 2\", \"weight\": 20, \"status\": \"Delivered\"},\n    3: {\"id\": 3, \"content\": \"Shipment 3\", \"weight\": 15, \"status\": \"Pending\"},\n}\n\n# ╔══════════════════════════════════════════════════╗\n# ║               BEGINNER                           ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. Sync vs Async Endpoints ─────────────────────\n#  def        → thread pool (CPU work)  |  async def → event loop (I/O)\n#  KEY RULE: inside async def, \"await\" before any async op\n@app.get(\"/sync/shipment/{id}\")\ndef get_shipment_sync(id: int):                       # sync — thread pool\n    if id not in shipment_data: raise HTTPException(404, \"Not found\")\n    return shipment_data[id]\n@app.get(\"/async/shipment/{id}\")\nasync def get_shipment_async(id: int):                # async — event loop\n    if id not in shipment_data: raise HTTPException(404, \"Not found\")\n    return shipment_data[id]\n\n# ── 2. Await a Sleep ───────────────────────────────\n#  asyncio.sleep() = non-blocking  |  time.sleep() = BLOCKING (freezes server!)\n@app.get(\"/async/slow-shipment/{id}\")\nasync def get_shipment_slow(id: int):\n    await asyncio.sleep(2)  # server handles other requests during wait\n    if id not in shipment_data: raise HTTPException(404, \"Not found\")\n    return {\"shipment\": shipment_data[id]}\n\n# ── 3. Await HTTP Call (httpx) ─────────────────────\n#  httpx.AsyncClient = async  |  requests.get() = BLOCKING (never in async def!)\n@app.get(\"/async/external-api\")\nasync def call_external_api():\n    async with httpx.AsyncClient() as client:\n        resp = await client.get(\"https://jsonplaceholder.typicode.com/todos/1\")\n    return {\"external_data\": resp.json()}\n\n# ── 4. Sequential Awaits ──────────────────────────\n#  Each await waits for previous → total = sum of all waits\n@app.get(\"/async/sequential\")\nasync def sequential_calls():\n    async with httpx.AsyncClient() as client:\n        r1 = await client.get(\"https://jsonplaceholder.typicode.com/todos/1\")\n        r2 = await client.get(\"https://jsonplaceholder.typicode.com/todos/2\")\n        r3 = await client.get(\"https://jsonplaceholder.typicode.com/todos/3\")\n    return {\"t1\": r1.json()[\"title\"], \"t2\": r2.json()[\"title\"], \"t3\": r3.json()[\"title\"]}\n\n# ╔══════════════════════════════════════════════════╗\n# ║             INTERMEDIATE                         ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 5. asyncio.gather() — Parallel ────────────────\n#  gather(*coros) → all at once, results IN ORDER, total = max wait\n@app.get(\"/async/parallel\")\nasync def parallel_calls():\n    async with httpx.AsyncClient() as client:\n        r1, r2, r3 = await asyncio.gather(\n            client.get(\"https://jsonplaceholder.typicode.com/todos/1\"),\n            client.get(\"https://jsonplaceholder.typicode.com/todos/2\"),\n            client.get(\"https://jsonplaceholder.typicode.com/todos/3\"),\n        )  # ~1s total instead of ~3s\n    return {\"t1\": r1.json()[\"title\"], \"t2\": r2.json()[\"title\"], \"t3\": r3.json()[\"title\"]}\n\n# ── 6. Gather — Dynamic List ─────────────────────\n@app.get(\"/async/parallel-dynamic\")\nasync def parallel_dynamic(ids: str = \"1,2,3,4,5\"):\n    todo_ids = [int(i) for i in ids.split(\",\")]\n    async with httpx.AsyncClient() as client:\n        responses = await asyncio.gather(\n            *[client.get(f\"https://jsonplaceholder.typicode.com/todos/{t}\") for t in todo_ids])\n    return {\"results\": [r.json()[\"title\"] for r in responses]}\n\n# ── 7. Gather — Error Handling ────────────────────\n#  return_exceptions=True → failed tasks return Exception, others still complete\n@app.get(\"/async/parallel-safe\")\nasync def parallel_with_error_handling():\n    async with httpx.AsyncClient() as client:\n        results = await asyncio.gather(\n            client.get(\"https://jsonplaceholder.typicode.com/todos/1\"),\n            client.get(\"https://invalid-url.com/data\"),\n            client.get(\"https://jsonplaceholder.typicode.com/todos/3\"),\n            return_exceptions=True)\n    return [{\"task\": i+1, \"error\": str(r)} if isinstance(r, Exception)\n            else {\"task\": i+1, \"data\": r.json()[\"title\"]} for i, r in enumerate(results)]\n\n# ── 8-9. Async Helpers (Sequential & Parallel) ────\nasync def fetch_from_db(id: int) -> dict:\n    await asyncio.sleep(0.5); return shipment_data.get(id)\nasync def enrich(shipment: dict) -> dict:\n    await asyncio.sleep(0.3); shipment[\"tracking\"] = f\"https://track.example.com/{shipment['id']}\"; return shipment\nasync def get_weight(id: int): await asyncio.sleep(0.5); return shipment_data.get(id, {}).get(\"weight\", 0)\nasync def get_status(id: int): await asyncio.sleep(0.5); return shipment_data.get(id, {}).get(\"status\", \"?\")\n\n@app.get(\"/async/helper/{id}\")\nasync def get_with_helpers(id: int):                  # sequential: 0.5 + 0.3 = 0.8s\n    s = await fetch_from_db(id)\n    if not s: raise HTTPException(404, \"Not found\")\n    return await enrich(s.copy())\n\n@app.get(\"/async/parallel-helpers/{id}\")\nasync def get_with_parallel_helpers(id: int):         # parallel: max(0.5, 0.5) = 0.5s\n    if id not in shipment_data: raise HTTPException(404, \"Not found\")\n    weight, status = await asyncio.gather(get_weight(id), get_status(id))\n    return {\"id\": id, \"weight\": weight, \"status\": status}\n\n# ── 10. create_task() — Fire and Forget ───────────\n#  Starts background work; endpoint returns immediately. Task lost on shutdown.\nasync def send_notification(sid: int, msg: str):\n    await asyncio.sleep(2); print(f\"NOTIFICATION: Shipment {sid} - {msg}\")\n\n@app.post(\"/async/fire-and-forget/{id}\")\nasync def update_and_notify(id: int):\n    if id not in shipment_data: raise HTTPException(404, \"Not found\")\n    shipment_data[id][\"status\"] = \"Delivered\"\n    asyncio.create_task(send_notification(id, \"Status changed\"))\n    return {\"shipment\": shipment_data[id]}\n\n# ── 11. wait_for() — Timeout ─────────────────────\nasync def slow_db_query(id: int): await asyncio.sleep(5); return shipment_data.get(id)\n\n@app.get(\"/async/timeout/{id}\")\nasync def get_with_timeout(id: int):\n    try: return await asyncio.wait_for(slow_db_query(id), timeout=2.0)\n    except asyncio.TimeoutError: raise HTTPException(504, \"Timed out after 2s\")\n\n# ── 12. Semaphore — Limit Concurrency ────────────\n#  Semaphore(N) = max N concurrent; others wait for a slot\nsem = asyncio.Semaphore(3)\nasync def rate_limited_fetch(client: httpx.AsyncClient, tid: int):\n    async with sem:\n        return (await client.get(f\"https://jsonplaceholder.typicode.com/todos/{tid}\")).json()\n\n@app.get(\"/async/semaphore\")\nasync def get_with_semaphore():\n    async with httpx.AsyncClient() as client:\n        results = await asyncio.gather(*[rate_limited_fetch(client, i) for i in range(1, 11)])\n    return {\"count\": len(results), \"titles\": [r[\"title\"] for r in results]}\n\n# ── 13. Lock — Prevent Race Conditions ────────────\n#  Lock = only ONE task at a time  (vs Semaphore = N at a time)\ncounter = {\"value\": 0}\nlock = asyncio.Lock()\nasync def inc_safe():\n    async with lock: c = counter[\"value\"]; await asyncio.sleep(0.01); counter[\"value\"] = c + 1\nasync def inc_unsafe():\n    c = counter[\"value\"]; await asyncio.sleep(0.01); counter[\"value\"] = c + 1\n\n@app.get(\"/async/lock-demo\")\nasync def lock_demo():\n    counter[\"value\"] = 0; await asyncio.gather(*[inc_safe() for _ in range(10)])\n    safe = counter[\"value\"]  # always 10\n    counter[\"value\"] = 0; await asyncio.gather(*[inc_unsafe() for _ in range(10)])\n    return {\"with_lock\": safe, \"without_lock\": counter[\"value\"]}  # unsafe might be < 10\n\n# ── 14. Event — Coordinate Tasks ─────────────────\n#  set() = signal  |  wait() = block until set  |  clear() = reset\n@app.get(\"/async/event-demo\")\nasync def event_demo():\n    ready, steps = asyncio.Event(), []\n    async def setup():\n        steps.append(\"DB starting\"); await asyncio.sleep(1); steps.append(\"DB ready\"); ready.set()\n    async def query():\n        steps.append(\"Query waiting\"); await ready.wait(); steps.append(\"Query running\")\n    await asyncio.gather(setup(), query())\n    return {\"steps\": steps}\n\n# ── 15. Queue — Producer/Consumer ─────────────────\n@app.post(\"/async/queue-demo\")\nasync def queue_demo():\n    q, results = asyncio.Queue(), []\n    async def producer():\n        for id in shipment_data: await q.put(id); await asyncio.sleep(0.1)\n        await q.put(None)\n    async def consumer():\n        while (id := await q.get()) is not None:\n            await asyncio.sleep(0.2); results.append({\"id\": id, \"ok\": True}); q.task_done()\n    await asyncio.gather(producer(), consumer())\n    return {\"processed\": results}\n\n# ╔══════════════════════════════════════════════════╗\n# ║               ADVANCED                           ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 16. async for — Async Generators ─────────────\nasync def fetch_pages(page_size: int = 2):\n    ids = list(shipment_data.keys())\n    for i in range(0, len(ids), page_size):\n        await asyncio.sleep(0.3)\n        yield [shipment_data[sid] for sid in ids[i:i+page_size]]\n\n@app.get(\"/async/async-for\")\nasync def get_with_async_for():\n    items, pages = [], 0\n    async for page in fetch_pages():\n        pages += 1; items.extend(page)\n    return {\"pages\": pages, \"total\": len(items), \"data\": items}\n\n# ── 17. async with — Async Context Manager ───────\nclass AsyncDBConn:\n    async def __aenter__(self):\n        await asyncio.sleep(0.2); self.connected = True; return self\n    async def __aexit__(self, *exc):\n        await asyncio.sleep(0.1); self.connected = False; return False\n    async def query(self, id: int) -> Optional[dict]:\n        await asyncio.sleep(0.1); return shipment_data.get(id)\n\n@app.get(\"/async/context-manager/{id}\")\nasync def get_with_ctx(id: int):\n    async with AsyncDBConn() as db:\n        result = await db.query(id)\n        if not result: raise HTTPException(404, \"Not found\")\n        return {\"shipment\": result, \"connected\": db.connected}\n\n# ── 18. shield() — Protect from Cancellation ─────\n#  Inner task survives even if outer is cancelled. Use for payments, saves.\nasync def critical_save(id: int):\n    await asyncio.sleep(1); shipment_data[id][\"status\"] = \"Saved\"; return shipment_data[id]\n\n@app.post(\"/async/shield/{id}\")\nasync def save_with_shield(id: int):\n    if id not in shipment_data: raise HTTPException(404, \"Not found\")\n    try: return await asyncio.wait_for(asyncio.shield(critical_save(id)), timeout=0.5)\n    except asyncio.TimeoutError: return {\"note\": \"Timed out, but save still running\"}\n\n# ── 19. to_thread() — Sync in Async ─────────────\ndef heavy_cpu_work(id: int): return {\"id\": id, \"sum\": sum(range(1_000_000))}\n\n@app.get(\"/async/sync-in-async/{id}\")\nasync def call_sync_from_async(id: int):\n    return await asyncio.to_thread(heavy_cpu_work, id)\n\n# ── 20. as_completed() — Fastest First ───────────\n#  gather = input order  |  as_completed = finish order\nasync def fetch_delayed(id: int, delay: float):\n    await asyncio.sleep(delay); return {\"id\": id, \"delay\": delay}\n\n@app.get(\"/async/as-completed\")\nasync def process_as_completed():\n    tasks = [asyncio.create_task(fetch_delayed(1, 2.0)),\n             asyncio.create_task(fetch_delayed(2, 0.5)),\n             asyncio.create_task(fetch_delayed(3, 1.0))]\n    results, n = [], 1\n    for done in asyncio.as_completed(tasks):\n        r = await done; r[\"order\"] = n; results.append(r); n += 1\n    return {\"results\": results}  # id=2 first, id=3 second, id=1 last\n\n# ── 21. Retry Pattern ────────────────────────────\n_attempts = {\"n\": 0}\nasync def unreliable():\n    _attempts[\"n\"] += 1\n    if _attempts[\"n\"] < 3: raise Exception(f\"Fail #{_attempts['n']}\")\n    return {\"data\": \"ok\", \"attempts\": _attempts[\"n\"]}\n\nasync def retry_async(func, retries=3, delay=0.5):\n    for i in range(1, retries + 1):\n        try: return await func()\n        except Exception as e:\n            if i == retries: raise\n            await asyncio.sleep(delay * i)\n\n@app.get(\"/async/retry\")\nasync def get_with_retry():\n    _attempts[\"n\"] = 0\n    try: return await retry_async(unreliable, retries=5, delay=0.3)\n    except Exception as e: raise HTTPException(503, str(e))\n\n# ── 22. Async Comprehension ──────────────────────\nasync def process_one(id: int):\n    await asyncio.sleep(0.1); s = shipment_data.get(id)\n    return {**s, \"processed\": True} if s else {\"id\": id, \"processed\": False}\n\n@app.get(\"/async/comprehension\")\nasync def async_comprehension():\n    # WRONG: [await process_one(id) for id in ids]  ← sequential!\n    # RIGHT: gather for parallel\n    return {\"results\": list(await asyncio.gather(*[process_one(id) for id in shipment_data]))}\n\n# ── 23. Chaining — fetch -> transform -> validate\nasync def s_fetch(id: int): await asyncio.sleep(0.2); return shipment_data.get(id, {})\nasync def s_transform(d: dict): await asyncio.sleep(0.2); d[\"weight_lbs\"] = round(d.get(\"weight\", 0) * 2.205, 2); return d\nasync def s_validate(d: dict): await asyncio.sleep(0.1); d[\"valid\"] = d.get(\"weight_lbs\", 0) > 0; return d\n\n@app.get(\"/async/chain/{id}\")\nasync def chained_pipeline(id: int):\n    if id not in shipment_data: raise HTTPException(404, \"Not found\")\n    return await s_validate(await s_transform((await s_fetch(id)).copy()))\n\n# ── 24. Fan-Out / Fan-In ─────────────────────────\n#  Fan-out: 1 input -> N parallel tasks  |  Fan-in: N results -> 1 output\nasync def check_warehouse(wh: str, id: int):\n    await asyncio.sleep(0.3); return {\"wh\": wh, \"avail\": (id + hash(wh)) % 2 == 0}\n\n@app.get(\"/async/fan-out/{id}\")\nasync def fan_out_fan_in(id: int):\n    whs = [\"NYC\", \"LON\", \"TYO\", \"SYD\", \"BER\"]\n    results = await asyncio.gather(*[check_warehouse(w, id) for w in whs])\n    return {\"id\": id, \"available\": [r[\"wh\"] for r in results if r[\"avail\"]], \"checked\": len(results)}", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n# CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\n#  CONCEPT              │ TOOL                        │ USE WHEN\n# ──────────────────────┼─────────────────────────────┼─────────────────────────────\n#  Non-blocking wait    │ await asyncio.sleep(n)      │ Simulate delay, yield control\n#  Async HTTP           │ httpx.AsyncClient           │ External API calls\n#  Run in parallel      │ asyncio.gather(*coros)      │ Multiple independent I/O ops\n#  Safe parallel        │ gather(return_exceptions=T) │ Some tasks may fail\n#  Background task      │ asyncio.create_task(coro)   │ Fire-and-forget (logs, notifs)\n#  Timeout              │ asyncio.wait_for(c, t)      │ Cancel if too slow\n#  Limit concurrency    │ asyncio.Semaphore(N)        │ Rate-limit API/DB calls\n#  Mutual exclusion     │ asyncio.Lock()              │ Prevent race conditions\n#  Signal readiness     │ asyncio.Event()             │ \"Wait until X is ready\"\n#  Producer/consumer    │ asyncio.Queue()             │ Job processing pipelines\n#  Protect from cancel  │ asyncio.shield(coro)        │ Critical ops (payments, saves)\n#  Sync in async        │ asyncio.to_thread(fn)       │ CPU work / blocking libraries\n#  Fastest first        │ asyncio.as_completed(tasks) │ Process results as they arrive\n#  Retry on failure     │ retry_async(fn, n, delay)   │ Unreliable external services\n#  Async iteration      │ async for x in gen()        │ Paginated/streaming data\n#  Async context mgr    │ async with Resource() as r  │ Setup/teardown needing await\n#  Async comprehension  │ gather(*[coro for ...])     │ Parallel list processing\n#  Chaining             │ await g(await f(x))         │ Pipeline: fetch->transform->save\n#  Fan-out/fan-in       │ gather → filter/combine     │ Split work, merge results\n#\n#  COMPARISON           │ A                           │ B\n# ──────────────────────┼─────────────────────────────┼─────────────────────────────\n#  Blocking vs async    │ time.sleep() — blocks       │ asyncio.sleep() — yields\n#  HTTP client          │ requests.get() — sync       │ httpx.AsyncClient — async\n#  Endpoint             │ def f() — thread pool       │ async def f() — event loop\n#  gather vs create_task│ gather: await all results   │ create_task: fire-and-forget\n#  gather vs as_compl.  │ gather: input order         │ as_completed: finish order\n#  Semaphore vs Lock    │ Semaphore(N): N concurrent  │ Lock: exactly 1 at a time\n#  Sequential vs ||     │ await a; await b — sum time │ gather(a,b) — max time\n# ══════════════════════════════════════════════════════════════════\n#", "reference": "# ══════════════════════════════════════════════════════════════════\n#  ASYNC/AWAIT — DETAILED REFERENCE\n# ══════════════════════════════════════════════════════════════════\n#\n# ── async def vs def — When to use which ─────────────────────────\n#   async def route():     → runs on event loop, use for I/O (HTTP, DB, files)\n#   def route():           → runs in thread pool, use for CPU work (calculations)\n#   KEY RULE: inside async def, you MUST \"await\" any async operation\n#   NEVER use time.sleep() or requests.get() in async def — they BLOCK the event loop\n#\n#   BEGINNER EXAMPLE — async vs sync endpoints:\n#\n#     # Async — for I/O (HTTP calls, DB queries, file reads):\n#     @app.get(\"/async\")\n#     async def async_route():\n#         data = await fetch_from_db()    # ← yields control, doesn't block\n#         return data\n#\n#     # Sync — for CPU work (calculations, image processing):\n#     @app.get(\"/sync\")\n#     def sync_route():\n#         result = heavy_calculation()     # ← runs in thread pool automatically\n#         return result\n#\n#     # Both called the same way:\n#     #   curl \"http://localhost:8000/async\"\n#     #   curl \"http://localhost:8000/sync\"\n#     #\n#     # Difference is INTERNAL — async yields to event loop, sync gets a thread\n#\n# ── await — Pause and yield control ──────────────────────────────\n#   result = await some_async_function()\n#   Pauses THIS function, lets event loop handle other requests.\n#   Only works inside async def. The awaited function must be a coroutine.\n#\n# ── asyncio.gather() — Run tasks in parallel ─────────────────────\n#   r1, r2, r3 = await asyncio.gather(coro1(), coro2(), coro3())\n#   All run concurrently. Results returned IN INPUT ORDER.\n#   Total time = max(individual times), not sum.\n#   return_exceptions=True → failed tasks return Exception object instead of crashing all.\n#   Dynamic: await asyncio.gather(*[fetch(id) for id in ids])\n#\n#   BEGINNER EXAMPLE — gather():\n#\n#     async def fetch_user(id): await asyncio.sleep(1); return {\"id\": id}\n#     async def fetch_orders(id): await asyncio.sleep(1); return [{\"order\": 1}]\n#     async def fetch_prefs(id): await asyncio.sleep(1); return {\"theme\": \"dark\"}\n#\n#     @app.get(\"/user/{id}\")\n#     async def get_user_full(id: int):\n#         user, orders, prefs = await asyncio.gather(\n#             fetch_user(id), fetch_orders(id), fetch_prefs(id)\n#         )\n#         return {\"user\": user, \"orders\": orders, \"prefs\": prefs}\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/user/1\"\n#     #\n#     #   WITHOUT gather (sequential):\n#     #     fetch_user   ──1s──▶\n#     #     fetch_orders        ──1s──▶\n#     #     fetch_prefs                ──1s──▶\n#     #     Total: 3 seconds\n#     #\n#     #   WITH gather (parallel):\n#     #     fetch_user   ──1s──▶\n#     #     fetch_orders ──1s──▶  ← all start at same time\n#     #     fetch_prefs  ──1s──▶\n#     #     Total: 1 second (max of individual times)\n#     #\n#     #   Results returned in INPUT order (not finish order):\n#     #     user → {\"id\": 1}, orders → [{\"order\": 1}], prefs → {\"theme\": \"dark\"}\n#\n# ── asyncio.create_task() — Fire and forget ──────────────────────\n#   asyncio.create_task(send_email(user))\n#   Starts background work. Endpoint returns immediately.\n#   Task runs in background. WARNING: lost on server shutdown.\n#   Use for: logging, notifications, non-critical side effects.\n#\n#   BEGINNER EXAMPLE — create_task():\n#\n#     async def send_notification(user_id: int, msg: str):\n#         await asyncio.sleep(2)       # simulate slow email\n#         print(f\"Notified user {user_id}: {msg}\")\n#\n#     @app.post(\"/order\")\n#     async def create_order():\n#         order = {\"id\": 99, \"status\": \"created\"}\n#         asyncio.create_task(send_notification(1, \"Order created\"))\n#         return order                  # ← returns IMMEDIATELY, email sends in background\n#\n#     # How to call:\n#     #   curl -X POST \"http://localhost:8000/order\"\n#     #     → {\"id\": 99, \"status\": \"created\"}  (instant response)\n#     #     → 2 seconds later: \"Notified user 1: Order created\" (in server logs)\n#     #\n#     #   Timeline:\n#     #     create_order() ──returns──▶ client gets response\n#     #     send_notification() ──────────2s──────────▶ prints in background\n#\n# ── asyncio.wait_for() — Timeout ────────────────────────────────\n#   result = await asyncio.wait_for(slow_query(), timeout=2.0)\n#   Raises asyncio.TimeoutError if not done in time. Cancels the task.\n#\n#   BEGINNER EXAMPLE — wait_for() timeout:\n#\n#     async def slow_query():\n#         await asyncio.sleep(5)       # takes 5 seconds\n#         return {\"data\": \"result\"}\n#\n#     @app.get(\"/query\")\n#     async def get_query():\n#         try:\n#             result = await asyncio.wait_for(slow_query(), timeout=2.0)\n#             return result\n#         except asyncio.TimeoutError:\n#             raise HTTPException(504, \"Query took too long\")\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/query\"\n#     #\n#     #   Timeline:\n#     #     slow_query() starts ──2s──▶ TIMEOUT! → 504 \"Query took too long\"\n#     #                                 (cancelled at 2s, never reaches 5s)\n#     #\n#     #   If query finishes in < 2s → normal response\n#     #   If query takes > 2s → TimeoutError → task cancelled\n#\n# ── asyncio.Semaphore(N) — Limit concurrency ────────────────────\n#   sem = asyncio.Semaphore(3)        → max 3 concurrent\n#   async with sem:                   → acquire slot (blocks if all N taken)\n#       await do_work()               → work runs with slot held\n#   Use for: rate-limiting API calls, DB connection limits.\n#\n#   BEGINNER EXAMPLE — Semaphore:\n#\n#     sem = asyncio.Semaphore(3)   # max 3 concurrent API calls\n#\n#     async def call_api(id):\n#         async with sem:            # ← waits if 3 already running\n#             await asyncio.sleep(1) # simulate API call\n#             return {\"id\": id}\n#\n#     @app.get(\"/batch\")\n#     async def batch():\n#         results = await asyncio.gather(*[call_api(i) for i in range(10)])\n#         return results\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/batch\"\n#     #\n#     #   10 tasks but Semaphore(3) → only 3 run at a time:\n#     #     Time 0s: tasks 0,1,2 start  │ tasks 3-9 wait\n#     #     Time 1s: tasks 0,1,2 done   │ tasks 3,4,5 start\n#     #     Time 2s: tasks 3,4,5 done   │ tasks 6,7,8 start\n#     #     Time 3s: tasks 6,7,8 done   │ task 9 starts\n#     #     Time 4s: task 9 done        │ total ~4s (not 10s, not 1s)\n#\n# ── asyncio.Lock() — Mutual exclusion ───────────────────────────\n#   lock = asyncio.Lock()\n#   async with lock:                  → only ONE task at a time\n#       counter += 1                  → safe from race conditions\n#   Semaphore(1) == Lock(). Use Lock when exactly-one is the intent.\n#\n#   BEGINNER EXAMPLE — Lock:\n#\n#     counter = {\"value\": 0}\n#     lock = asyncio.Lock()\n#\n#     @app.post(\"/increment\")\n#     async def increment():\n#         async with lock:                 # ← only ONE request at a time\n#             counter[\"value\"] += 1        # safe — no race condition\n#         return counter\n#\n#     # Without lock: 2 requests at same time could both read 0, both write 1\n#     # With lock: request A holds lock → B waits → A writes 1 → B reads 1, writes 2\n#\n# ── asyncio.Event() — Signal between tasks ──────────────────────\n#   event = asyncio.Event()\n#   await event.wait()                → blocks until event.set() is called\n#   event.set()                       → unblocks all waiters\n#   event.clear()                     → reset to unset state\n#   Use for: \"wait until database is ready\", \"wait until config loaded\"\n#\n#   BEGINNER EXAMPLE — Event:\n#\n#     db_ready = asyncio.Event()\n#\n#     async def init_db():\n#         await asyncio.sleep(2)       # simulate slow DB connect\n#         db_ready.set()               # ← signal \"ready!\"\n#\n#     @app.get(\"/data\")\n#     async def get_data():\n#         await db_ready.wait()        # ← blocks until db_ready.set() is called\n#         return {\"status\": \"db is ready\"}\n#\n#     # Flow:\n#     #   Server starts → init_db() begins (2s)\n#     #   curl /data at 0s → waits... waits...\n#     #   At 2s: db_ready.set() → all waiters unblocked → response returned\n#\n# ── asyncio.Queue() — Producer/consumer ─────────────────────────\n#   q = asyncio.Queue()\n#   await q.put(item)                 → producer adds work\n#   item = await q.get()              → consumer takes work (blocks if empty)\n#   q.task_done()                     → mark item as processed\n#   Use for: job processing, work distribution, buffering.\n#\n#   BEGINNER EXAMPLE — Queue:\n#\n#     job_queue = asyncio.Queue()\n#\n#     @app.post(\"/job\")\n#     async def submit_job():\n#         await job_queue.put({\"task\": \"process\", \"id\": 1})  # producer\n#         return {\"queued\": True, \"pending\": job_queue.qsize()}\n#\n#     async def worker():\n#         while True:\n#             job = await job_queue.get()    # blocks until job available\n#             print(f\"Processing: {job}\")\n#             job_queue.task_done()\n#\n#     # curl -X POST \"http://localhost:8000/job\"\n#     #   → {\"queued\": true, \"pending\": 1}\n#     #   → worker picks up job from queue and processes it\n#\n# ── asyncio.shield() — Protect from cancellation ────────────────\n#   await asyncio.shield(critical_save(data))\n#   Even if outer task is cancelled, shielded task keeps running.\n#   Use for: payments, database commits, anything that MUST finish.\n#\n#   BEGINNER EXAMPLE — shield:\n#\n#     async def save_payment(id):\n#         await asyncio.sleep(3)        # slow but MUST complete\n#         return {\"id\": id, \"saved\": True}\n#\n#     @app.post(\"/pay/{id}\")\n#     async def pay(id: int):\n#         try:\n#             return await asyncio.wait_for(asyncio.shield(save_payment(id)), timeout=1)\n#         except asyncio.TimeoutError:\n#             return {\"msg\": \"Timed out, but payment still processing\"}\n#\n#     # curl -X POST \"http://localhost:8000/pay/1\"\n#     #   → timeout after 1s → {\"msg\": \"Timed out, but payment still processing\"}\n#     #   → BUT save_payment keeps running in background (shield protects it)\n#     #   Without shield: timeout would CANCEL save_payment → payment lost!\n#\n# ── asyncio.to_thread() — Run sync code in async context ────────\n#   result = await asyncio.to_thread(heavy_cpu_function, arg1, arg2)\n#   Runs sync function in thread pool, doesn't block event loop.\n#   Use for: CPU-heavy work, libraries that don't support async.\n#\n#   BEGINNER EXAMPLE — to_thread:\n#\n#     def heavy_cpu_work(n):           # sync function — can't use await\n#         return sum(range(n))         # CPU-intensive calculation\n#\n#     @app.get(\"/compute/{n}\")\n#     async def compute(n: int):\n#         result = await asyncio.to_thread(heavy_cpu_work, n)\n#         return {\"sum\": result}\n#\n#     # curl \"http://localhost:8000/compute/1000000\"\n#     #   → {\"sum\": 499999500000}\n#     #\n#     #   Without to_thread: heavy_cpu_work BLOCKS event loop → other requests wait\n#     #   With to_thread: runs in thread pool → event loop stays free for other requests\n#\n# ── asyncio.as_completed() — Process fastest first ──────────────\n#   for done in asyncio.as_completed(tasks):\n#       result = await done            → get result in FINISH ORDER (not input order)\n#   vs gather: returns in input order. as_completed: returns as each finishes.\n#\n#   BEGINNER EXAMPLE — as_completed:\n#\n#     async def fetch(id, delay):\n#         await asyncio.sleep(delay)\n#         return {\"id\": id, \"delay\": delay}\n#\n#     @app.get(\"/race\")\n#     async def race():\n#         tasks = [fetch(1, 2.0), fetch(2, 0.5), fetch(3, 1.0)]\n#         results = []\n#         for done in asyncio.as_completed(tasks):\n#             r = await done\n#             results.append(r)\n#         return results\n#\n#     # curl \"http://localhost:8000/race\"\n#     #\n#     #   gather would return: [id=1, id=2, id=3]  ← input order\n#     #   as_completed returns: [id=2, id=3, id=1]  ← finish order (fastest first)\n#     #\n#     #   Timeline:\n#     #     0.5s: id=2 finishes first  → results[0]\n#     #     1.0s: id=3 finishes second → results[1]\n#     #     2.0s: id=1 finishes last   → results[2]\n#\n# ── async for — Async iteration ─────────────────────────────────\n#   async def fetch_pages():\n#       yield page                     → async generator (yields data over time)\n#   async for page in fetch_pages():\n#       process(page)                  → processes each page as it arrives\n#   Use for: paginated APIs, streaming data, chunked file reads.\n#\n#   BEGINNER EXAMPLE — async for:\n#\n#     async def fetch_pages():\n#         for page_num in range(1, 4):\n#             await asyncio.sleep(0.5)     # simulate API delay\n#             yield [f\"item_{page_num}_1\", f\"item_{page_num}_2\"]\n#\n#     @app.get(\"/pages\")\n#     async def get_all_pages():\n#         all_items = []\n#         async for page in fetch_pages():  # ← processes each page as it arrives\n#             all_items.extend(page)\n#         return {\"items\": all_items}\n#\n#     # curl \"http://localhost:8000/pages\"\n#     #   → page 1 arrives at 0.5s → page 2 at 1.0s → page 3 at 1.5s\n#     #   → {\"items\": [\"item_1_1\",\"item_1_2\",\"item_2_1\",...]}\n#\n# ── async with — Async context manager ──────────────────────────\n#   async with httpx.AsyncClient() as client:\n#       response = await client.get(url)\n#   __aenter__ = async setup, __aexit__ = async cleanup\n#   Use for: connections, sessions, resources needing async open/close.\n#\n#   BEGINNER EXAMPLE — async with:\n#\n#     @app.get(\"/external\")\n#     async def call_external():\n#         async with httpx.AsyncClient() as client:    # ← opens connection\n#             resp = await client.get(\"https://api.example.com/data\")\n#             return resp.json()\n#         # ← connection auto-closed here (even if error occurs)\n#\n#     # curl \"http://localhost:8000/external\"\n#     #   async with opens client → makes request → returns data → closes client\n#     #   Same as try/finally but cleaner — cleanup guaranteed\n#\n# ── Retry pattern ───────────────────────────────────────────────\n#   for i in range(retries):\n#       try: return await func()\n#       except: await asyncio.sleep(delay * i)  → exponential backoff\n#   Use for: unreliable external APIs, transient network errors.\n#\n#   BEGINNER EXAMPLE — Retry:\n#\n#     async def retry_async(func, retries=3, delay=0.5):\n#         for i in range(1, retries + 1):\n#             try:\n#                 return await func()\n#             except Exception as e:\n#                 if i == retries: raise      # last attempt — give up\n#                 await asyncio.sleep(delay * i)  # wait longer each time\n#\n#     @app.get(\"/api-call\")\n#     async def get_api():\n#         return await retry_async(unreliable_api, retries=3, delay=0.5)\n#\n#     # curl \"http://localhost:8000/api-call\"\n#     #\n#     #   Attempt 1: fails → wait 0.5s\n#     #   Attempt 2: fails → wait 1.0s (exponential backoff)\n#     #   Attempt 3: succeeds → return result\n#     #   OR Attempt 3: fails → raise exception (503)\n#\n# ── httpx.AsyncClient — Async HTTP client ───────────────────────\n#   async with httpx.AsyncClient() as client:\n#       resp = await client.get(url)\n#   NEVER use requests.get() in async def — it blocks the event loop.\n#   httpx is the async-native replacement for requests.\n#\n#   BEGINNER EXAMPLE — httpx:\n#\n#     # BAD — blocks event loop:\n#     #   import requests\n#     #   resp = requests.get(\"https://api.com/data\")  ← BLOCKS all other requests!\n#     #\n#     # GOOD — non-blocking:\n#     #   async with httpx.AsyncClient() as client:\n#     #       resp = await client.get(\"https://api.com/data\")  ← yields control\n#     #\n#     # curl \"http://localhost:8000/external\"\n#     #   → httpx makes async HTTP call → event loop handles other requests meanwhile\n#\n# ══════════════════════════════════════════════════════════════════"}, "06_middleware_cors_caching.py": {"content": "# ══════════════════════════════════════════════════════════════════\n# 4. MIDDLEWARE, CORS & CACHING\n#\n# Middleware = code that runs BEFORE and AFTER every request\n# Request -> MW1 -> MW2 -> Endpoint -> MW2 -> MW1 -> Response (onion model)\n# CORS = which websites can call your API from a browser\n# Caching = store responses to avoid recomputing\n# NOTE: Middleware functions MUST be async def; endpoints can be sync\n# ══════════════════════════════════════════════════════════════════\nimport time, hashlib, json\nfrom fastapi import FastAPI, HTTPException, Request, Response\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom fastapi.middleware.trustedhost import TrustedHostMiddleware\nfrom fastapi.middleware.gzip import GZipMiddleware\nfrom fastapi.responses import JSONResponse\n\napp = FastAPI()\nshipment_data = {\n    1: {\"id\": 1, \"content\": \"Shipment 1\", \"weight\": 10, \"status\": \"In Transit\"},\n    2: {\"id\": 2, \"content\": \"Shipment 2\", \"weight\": 20, \"status\": \"Delivered\"},\n    3: {\"id\": 3, \"content\": \"Shipment 3\", \"weight\": 15, \"status\": \"Pending\"},\n}\n\n# ╔══════════════════════════════════════════════════╗\n# ║              BEGINNER                            ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. CORS — Allow Frontend to Call Your API ─────────────────────\n# Without CORS: browser blocks requests from different origins\n# allow_origins = which sites | allow_methods = which HTTP verbs\n# allow_headers = which headers | allow_credentials = cookies/auth\n\n# OPTION A: Specific origins (RECOMMENDED for prod)\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=[\"http://localhost:3000\", \"http://localhost:5173\", \"https://myapp.example.com\"],\n    allow_credentials=True,                                        # allow cookies/JWT\n    allow_methods=[\"GET\", \"POST\", \"PUT\", \"DELETE\", \"PATCH\"],\n    allow_headers=[\"*\"],\n)\n# OPTION B: allow_origins=[\"*\"], allow_credentials=False           — any site, dev/public APIs only\n# OPTION C: allow_origin_regex=r\"https://.*\\.example\\.com\"         — regex pattern matching\n\n@app.get(\"/cors/test\")\ndef cors_test():\n    return {\"message\": \"If CORS is set up, your frontend can call this\"}\n\n# ── 2. GZip — Compress Responses ──────────────────────────────────\n# Compresses responses > minimum_size bytes (60-90% smaller for JSON)\napp.add_middleware(GZipMiddleware, minimum_size=500)\n\n@app.get(\"/middleware/gzip-test\")\ndef gzip_test():\n    return {\"data\": [shipment_data[k] for k in shipment_data] * 50}\n# curl -H \"Accept-Encoding: gzip\" http://localhost:8000/middleware/gzip-test\n\n# ── 3. TrustedHost — Block Unknown Hosts ──────────────────────────\n# Prevents Host header attacks; non-matching Host -> 400\napp.add_middleware(\n    TrustedHostMiddleware,\n    allowed_hosts=[\"localhost\", \"127.0.0.1\", \"myapp.example.com\", \"*.example.com\"],\n)\n\n# ╔══════════════════════════════════════════════════╗\n# ║            INTERMEDIATE                          ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 4. Custom Middleware — Process Time Header ────────────────────\n# request = incoming | call_next = calls next middleware/endpoint | response = result\n@app.middleware(\"http\")\nasync def add_process_time_header(request: Request, call_next):\n    start = time.time()\n    response = await call_next(request)\n    response.headers[\"X-Process-Time\"] = str(round(time.time() - start, 4))\n    return response  # curl -v ... -> X-Process-Time: 0.0012\n\n# ── 5. Custom Middleware — Request Logging ────────────────────────\n@app.middleware(\"http\")\nasync def log_requests(request: Request, call_next):\n    print(f\"-> {request.method} {request.url.path}\")\n    response = await call_next(request)\n    print(f\"<- {request.method} {request.url.path} -> {response.status_code}\")\n    return response\n\n# ── 6. Custom Middleware — Block Paths ────────────────────────────\n# Deny access to /admin/* without correct token\n@app.middleware(\"http\")\nasync def block_admin_routes(request: Request, call_next):\n    if request.url.path.startswith(\"/admin\"):\n        if request.headers.get(\"Authorization\", \"\") != \"Bearer admin-secret-token\":\n            return JSONResponse(status_code=403, content={\"detail\": \"Admin access denied\"})\n    return await call_next(request)\n\n@app.get(\"/admin/dashboard\")\ndef admin_dashboard():\n    return {\"message\": \"Welcome to admin dashboard\"}\n\n# ── 7. Custom Middleware — Rate Limiting ──────────────────────────\n# Track requests per IP, block if too many in window\nrequest_counts: dict[str, list[float]] = {}\nRATE_LIMIT = 10    # max requests\nRATE_WINDOW = 60.0 # per N seconds\n\n@app.middleware(\"http\")\nasync def rate_limiter(request: Request, call_next):\n    client_ip = request.client.host if request.client else \"unknown\"\n    now = time.time()\n    if client_ip not in request_counts:\n        request_counts[client_ip] = []\n    request_counts[client_ip] = [t for t in request_counts[client_ip] if now - t < RATE_WINDOW]\n    if len(request_counts[client_ip]) >= RATE_LIMIT:\n        return JSONResponse(status_code=429, content={\"detail\": \"Too many requests\"})\n    request_counts[client_ip].append(now)\n    response = await call_next(request)\n    response.headers[\"X-RateLimit-Remaining\"] = str(RATE_LIMIT - len(request_counts[client_ip]))\n    return response\n\n# ── 8. Custom Middleware — Exception Handler ──────────────────────\n# Catch ALL unhandled exceptions -> clean JSON instead of ugly 500 HTML\n@app.middleware(\"http\")\nasync def catch_exceptions(request: Request, call_next):\n    try:\n        return await call_next(request)\n    except Exception as e:\n        return JSONResponse(status_code=500, content={\"detail\": \"Internal server error\", \"error\": str(e)})\n\n# ╔══════════════════════════════════════════════════╗\n# ║              ADVANCED                            ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 9. Middleware Execution Order ─────────────────────────────────\n# Middleware runs in REVERSE order of registration!\n# Added: A, B, C  ->  Execution: C -> B -> A -> endpoint -> A -> B -> C\n# Last added = outermost layer (runs first)\n\n@app.get(\"/middleware/order-test\")\ndef middleware_order_test():\n    return {\"message\": \"Check server logs to see middleware execution order\"}\n\n# ── 10. In-Memory Cache (Server-Side) ────────────────────────────\n# Dict cache with TTL — fastest, but lost on restart\ncache_store: dict[str, dict] = {}\nCACHE_TTL = 30  # seconds\n\n@app.get(\"/cache/simple/{id}\")\ndef get_with_simple_cache(id: int):\n    cache_key, now = f\"shipment:{id}\", time.time()\n    if cache_key in cache_store:                                   # check cache\n        cached = cache_store[cache_key]\n        if now - cached[\"timestamp\"] < CACHE_TTL:\n            return {**cached[\"data\"], \"_cache\": \"HIT\", \"_age\": round(now - cached[\"timestamp\"], 1)}\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    result = shipment_data[id]\n    cache_store[cache_key] = {\"data\": result, \"timestamp\": now}    # store in cache\n    return {**result, \"_cache\": \"MISS\"}\n\n# ── 11. Cache Invalidation ───────────────────────────────────────\n# Delete cache when data changes (PUT/DELETE) to prevent stale data\n@app.put(\"/cache/shipment/{id}\")\ndef update_shipment_and_invalidate(id: int, status: str = \"Updated\"):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    shipment_data[id][\"status\"] = status\n    cache_store.pop(f\"shipment:{id}\", None)                        # invalidate\n    return {\"updated\": shipment_data[id], \"cache_invalidated\": True}\n\n@app.delete(\"/cache/clear\")\ndef clear_all_cache():\n    cache_store.clear()\n    return {\"message\": \"All cache cleared\"}\n\n# ── 12. HTTP Cache Headers (Client-Side) ─────────────────────────\n# Cache-Control tells browsers/CDNs to cache; ETag = data fingerprint\n# Client-side caching (browser stores it) vs server-side (dict cache above)\n@app.get(\"/cache/headers/{id}\")\ndef get_with_cache_headers(id: int):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    data = shipment_data[id]\n    content = json.dumps(data, sort_keys=True)\n    etag = hashlib.md5(content.encode()).hexdigest()\n    return Response(\n        content=content, media_type=\"application/json\",\n        headers={\"Cache-Control\": \"public, max-age=60\", \"ETag\": f'\"{etag}\"'},\n    )\n\n# Cache-Control variants:\n# no-store                             -> never cache (real-time data, auth tokens)\n# private, max-age=300                 -> only browser caches, NOT CDN (user-specific)\n# public, max-age=60                   -> browser AND CDN can cache (public data)\n# public, max-age=31536000, immutable  -> content NEVER changes at this URL (versioned assets)\n\n# ── 13. Conditional Caching — ETag + If-None-Match ────────────────\n# Client sends ETag back -> server checks if data changed\n# Unchanged -> 304 Not Modified (no body, saves bandwidth)\n# Changed -> 200 with new data + new ETag\n@app.get(\"/cache/conditional/{id}\")\ndef conditional_cache(id: int, request: Request):\n    if id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    data = shipment_data[id]\n    content = json.dumps(data, sort_keys=True)\n    etag = hashlib.md5(content.encode()).hexdigest()\n    if request.headers.get(\"If-None-Match\", \"\") == f'\"{etag}\"':    # client already has this version\n        return Response(status_code=304)\n    return Response(\n        content=content, media_type=\"application/json\",\n        headers={\"ETag\": f'\"{etag}\"', \"Cache-Control\": \"public, max-age=60\"},\n    )\n# 1st call: curl -v /cache/conditional/1                          -> 200 + ETag\n# 2nd call: curl -v -H 'If-None-Match: \"<etag>\"' /cache/cond/1   -> 304 (no body)", "cheatSheet": "# ── CHEAT SHEET ───────────────────────────────────────────────────\n# CORS:\n#   Specific origins (prod)   | allow_origins=[\"https://app.com\"]\n#   All origins (dev only)    | allow_origins=[\"*\"], allow_credentials=False\n#   Regex pattern             | allow_origin_regex=r\"https://.*\\.example\\.com\"\n#\n# BUILT-IN MIDDLEWARE:\n#   GZipMiddleware            | Compress responses > N bytes\n#   TrustedHostMiddleware     | Block unknown Host headers\n#\n# CUSTOM MIDDLEWARE PATTERN:\n#   @app.middleware(\"http\")\n#   async def mw(request: Request, call_next):\n#       response = await call_next(request)    # call next layer\n#       return response\n#\n# EXECUTION ORDER:\n#   Added A, B, C -> runs C -> B -> A -> endpoint -> A -> B -> C\n#\n# CACHING COMPARISON:\n#   In-memory dict            | Server-side, fast, lost on restart\n#   Cache-Control header      | Client-side, browser/CDN stores it\n#   ETag + If-None-Match      | Conditional: 304 if unchanged, saves bandwidth\n#\n# CACHE-CONTROL VALUES:\n#   no-store                  | Never cache (real-time, auth)\n#   private, max-age=N        | Browser only, no CDN (user data)\n#   public, max-age=N         | Browser + CDN (public data)\n#   immutable                 | Content never changes (versioned assets)\n#\n# RATE LIMITING:             Track timestamps per IP, prune old, reject if >= limit\n# EXCEPTION MIDDLEWARE:      try/except around call_next -> clean JSON 500\n#", "reference": "# ══════════════════════════════════════════════════════════════════\n#  MIDDLEWARE, CORS & CACHING — DETAILED REFERENCE\n# ══════════════════════════════════════════════════════════════════\n#\n# ── CORSMiddleware — Cross-Origin Resource Sharing ───────────────\n#   app.add_middleware(CORSMiddleware, allow_origins=[...], ...)\n#   allow_origins=[\"http://localhost:3000\"]   → specific origins (RECOMMENDED for prod)\n#   allow_origins=[\"*\"]                       → any site (dev/public APIs only)\n#   allow_origin_regex=r\"https://.*\\.example\\.com\"  → regex pattern\n#   allow_credentials=True                    → allow cookies/JWT in cross-origin requests\n#   allow_methods=[\"GET\",\"POST\",...]          → which HTTP verbs are allowed\n#   allow_headers=[\"*\"]                       → which request headers are allowed\n#   Without CORS: browser blocks requests from different origins (same-origin policy)\n#\n#   BEGINNER EXAMPLE — CORSMiddleware:\n#\n#     from fastapi.middleware.cors import CORSMiddleware\n#     app.add_middleware(\n#         CORSMiddleware,\n#         allow_origins=[\"http://localhost:3000\"],  # ← React dev server\n#         allow_credentials=True,\n#         allow_methods=[\"*\"],\n#         allow_headers=[\"*\"],\n#     )\n#\n#     # Problem CORS solves:\n#     #   React app at http://localhost:3000 calls API at http://localhost:8000\n#     #   Browser sees DIFFERENT origins (different ports) → blocks the request!\n#     #\n#     #   With CORSMiddleware:\n#     #   Browser → OPTIONS /api/items (preflight check)\n#     #         ← Access-Control-Allow-Origin: http://localhost:3000  ✓\n#     #   Browser → GET /api/items (actual request, now allowed)\n#     #         ← data + CORS headers\n#     #\n#     #   allow_origins=[\"*\"]  → any website can call your API (ok for public APIs)\n#     #   allow_origins=[\"http://localhost:3000\"] → only React app can call (safer)\n#\n# ── GZipMiddleware — Response compression ────────────────────────\n#   app.add_middleware(GZipMiddleware, minimum_size=500)\n#   Compresses responses > minimum_size bytes. 60-90% smaller for JSON.\n#   Client must send Accept-Encoding: gzip header.\n#\n#   BEGINNER EXAMPLE — GZipMiddleware:\n#\n#     from starlette.middleware.gzip import GZipMiddleware\n#     app.add_middleware(GZipMiddleware, minimum_size=500)\n#\n#     # curl -H \"Accept-Encoding: gzip\" \"http://localhost:8000/big-data\"\n#     #\n#     #   Without GZip:\n#     #     Server → 10,000 bytes JSON → Client\n#     #\n#     #   With GZip:\n#     #     Server → compress → 2,000 bytes → Client → decompress → 10,000 bytes\n#     #     (60-90% smaller, faster over slow networks)\n#     #\n#     #   minimum_size=500 → only compress responses > 500 bytes\n#     #   (small responses: compression overhead > savings)\n#\n# ── TrustedHostMiddleware — Host header protection ───────────────\n#   app.add_middleware(TrustedHostMiddleware, allowed_hosts=[\"myapp.com\", \"*.example.com\"])\n#   Requests with non-matching Host header → 400 Bad Request.\n#   Prevents Host header injection attacks.\n#\n#   BEGINNER EXAMPLE — TrustedHostMiddleware:\n#\n#     from starlette.middleware.trustedhost import TrustedHostMiddleware\n#     app.add_middleware(TrustedHostMiddleware, allowed_hosts=[\"myapp.com\", \"*.myapp.com\"])\n#\n#     # curl -H \"Host: myapp.com\" \"http://localhost:8000/\"    → ✓ 200 OK\n#     # curl -H \"Host: evil.com\"  \"http://localhost:8000/\"    → ✗ 400 Bad Request\n#     #\n#     # Prevents: attacker sends fake Host header to trick server\n#     # into generating links/redirects to evil.com\n#\n# ── Custom middleware pattern ────────────────────────────────────\n#   @app.middleware(\"http\")\n#   async def my_middleware(request: Request, call_next):\n#       # BEFORE: runs before endpoint\n#       response = await call_next(request)  → calls next middleware/endpoint\n#       # AFTER: runs after endpoint\n#       return response\n#   Must be async def. Can modify request before, response after.\n#   Can short-circuit: return JSONResponse(...) without calling call_next.\n#\n#   BEGINNER EXAMPLE — Custom middleware:\n#\n#     import time\n#\n#     @app.middleware(\"http\")\n#     async def add_timing(request: Request, call_next):\n#         start = time.time()                    # BEFORE endpoint\n#         response = await call_next(request)    # run endpoint\n#         elapsed = time.time() - start          # AFTER endpoint\n#         response.headers[\"X-Process-Time\"] = str(elapsed)\n#         return response\n#\n#     # curl -v \"http://localhost:8000/any-route\"\n#     #\n#     #   Request arrives\n#     #     │\n#     #     ▼ BEFORE: start = time.time()\n#     #     │\n#     #     ▼ call_next(request) → endpoint runs → returns response\n#     #     │\n#     #     ▼ AFTER: calculate elapsed, add header\n#     #     │\n#     #   Response sent with X-Process-Time: 0.0023\n#     #\n#     #   Short-circuit (skip endpoint):\n#     #     if \"Authorization\" not in request.headers:\n#     #         return JSONResponse({\"error\": \"No auth\"}, status_code=401)\n#\n# ── Middleware execution order ───────────────────────────────────\n#   Registered: A, B, C → Runs: C → B → A → endpoint → A → B → C\n#   Last added = outermost layer (runs first). Like an onion — wraps around.\n#\n#   BEGINNER EXAMPLE — Execution order:\n#\n#     # Register order:\n#     app.add_middleware(A)   # added first\n#     app.add_middleware(B)   # added second\n#     app.add_middleware(C)   # added last\n#\n#     # Execution order (REVERSED — like wrapping an onion):\n#     #   Request comes in:\n#     #     C (before) → B (before) → A (before) → ENDPOINT\n#     #   Response goes out:\n#     #     A (after)  → B (after)  → C (after)  → CLIENT\n#     #\n#     #   Visual:\n#     #     ┌─── C ────────────────────────────────┐\n#     #     │ ┌─── B ──────────────────────────┐   │\n#     #     │ │ ┌─── A ────────────────────┐   │   │\n#     #     │ │ │       ENDPOINT           │   │   │\n#     #     │ │ └──────────────────────────┘   │   │\n#     #     │ └────────────────────────────────┘   │\n#     #     └──────────────────────────────────────┘\n#     #   Last added (C) wraps outermost → runs FIRST on request, LAST on response\n#\n# ── request: Request — Available in middleware & routes ──────────\n#   request.url.path          → \"/api/items\"\n#   request.method            → \"GET\", \"POST\", etc.\n#   request.headers           → all HTTP headers\n#   request.client.host       → client IP address\n#   request.cookies           → all cookies\n#   request.query_params      → URL query parameters\n#\n#   BEGINNER EXAMPLE — Request object:\n#\n#     from fastapi import Request\n#\n#     @app.get(\"/debug\")\n#     async def debug(request: Request):\n#         return {\n#             \"path\": request.url.path,            # → \"/debug\"\n#             \"method\": request.method,             # → \"GET\"\n#             \"user_agent\": request.headers.get(\"user-agent\"),\n#             \"client_ip\": request.client.host,     # → \"127.0.0.1\"\n#             \"cookies\": dict(request.cookies),     # → {\"session_id\": \"abc\"}\n#             \"query\": dict(request.query_params),  # → {\"page\": \"1\"}\n#         }\n#\n#     # curl \"http://localhost:8000/debug?page=1\" -b \"session_id=abc\"\n#     #   → {\"path\":\"/debug\",\"method\":\"GET\",\"client_ip\":\"127.0.0.1\",\n#     #      \"cookies\":{\"session_id\":\"abc\"},\"query\":{\"page\":\"1\"}}\n#\n# ── In-memory cache (server-side) ────────────────────────────────\n#   cache_store[key] = {\"data\": result, \"timestamp\": time.time()}\n#   Check: if now - cached[\"timestamp\"] < TTL → return cached (HIT)\n#   Invalidate: cache_store.pop(key, None) on PUT/DELETE (prevent stale data)\n#   Pros: fastest. Cons: lost on restart, per-process (not shared across workers).\n#\n#   BEGINNER EXAMPLE — In-memory cache:\n#\n#     import time\n#     cache = {}\n#     TTL = 60  # seconds\n#\n#     @app.get(\"/items\")\n#     async def get_items():\n#         now = time.time()\n#         if \"items\" in cache and now - cache[\"items\"][\"ts\"] < TTL:\n#             return {\"data\": cache[\"items\"][\"data\"], \"source\": \"cache\"}  # HIT\n#         data = await fetch_items_from_db()          # MISS — query DB\n#         cache[\"items\"] = {\"data\": data, \"ts\": now}  # store in cache\n#         return {\"data\": data, \"source\": \"db\"}\n#\n#     @app.delete(\"/items/{id}\")\n#     async def delete_item(id: int):\n#         await db_delete(id)\n#         cache.pop(\"items\", None)   # ← invalidate cache (prevent stale data)\n#         return {\"deleted\": id}\n#\n#     # Flow:\n#     #   curl GET /items      → MISS → query DB → cache result → return\n#     #   curl GET /items      → HIT  → return from cache (fast!)\n#     #   ... 60 seconds pass ...\n#     #   curl GET /items      → MISS → cache expired → query DB again\n#     #   curl DELETE /items/1 → delete + invalidate cache → next GET re-fetches\n#\n# ── Cache-Control header (client-side) ───────────────────────────\n#   \"no-store\"                           → never cache (real-time data, auth tokens)\n#   \"private, max-age=300\"               → browser only, NOT CDN (user-specific data)\n#   \"public, max-age=60\"                 → browser + CDN can cache (public data)\n#   \"public, max-age=31536000, immutable\"→ never changes at this URL (versioned assets)\n#   Tells browser/CDN to store the response — server not contacted until expiry.\n#\n#   BEGINNER EXAMPLE — Cache-Control:\n#\n#     from fastapi.responses import JSONResponse\n#\n#     @app.get(\"/public-data\")\n#     async def public():\n#         data = get_public_data()\n#         return JSONResponse(data, headers={\"Cache-Control\": \"public, max-age=60\"})\n#\n#     @app.get(\"/user-profile\")\n#     async def profile():\n#         data = get_user_data()\n#         return JSONResponse(data, headers={\"Cache-Control\": \"private, max-age=300\"})\n#\n#     @app.get(\"/stock-price\")\n#     async def stock():\n#         data = get_live_price()\n#         return JSONResponse(data, headers={\"Cache-Control\": \"no-store\"})\n#\n#     # curl -v \"http://localhost:8000/public-data\"\n#     #   ← Cache-Control: public, max-age=60\n#     #\n#     #   What happens:\n#     #     \"no-store\"         → browser NEVER caches (stock prices, auth tokens)\n#     #     \"private, 300\"     → browser caches 5min, CDN does NOT (user-specific)\n#     #     \"public, 60\"       → browser AND CDN cache 60s (shared public data)\n#     #     \"immutable\"        → never changes at this URL (app.abc123.js)\n#     #\n#     #   Flow with \"public, max-age=60\":\n#     #     Request 1: Browser → Server → 200 + data (stored in browser cache)\n#     #     Request 2 (within 60s): Browser → cache HIT → no server contact!\n#     #     Request 3 (after 60s): Browser → Server → fresh 200\n#\n# ── ETag + If-None-Match (conditional caching) ──────────────────\n#   Server: response with ETag: \"abc123\" (content fingerprint, usually MD5 hash)\n#   Client: next request with If-None-Match: \"abc123\"\n#   Server: data unchanged → 304 Not Modified (no body, saves bandwidth)\n#   Server: data changed → 200 with new data + new ETag\n#   Combines with Cache-Control for optimal caching strategy.\n#\n#   BEGINNER EXAMPLE — ETag:\n#\n#     import hashlib, json\n#     from fastapi import Response\n#\n#     @app.get(\"/article/{id}\")\n#     async def get_article(id: int, request: Request):\n#         article = get_article_from_db(id)\n#         etag = hashlib.md5(json.dumps(article).encode()).hexdigest()\n#\n#         if request.headers.get(\"if-none-match\") == etag:\n#             return Response(status_code=304)       # not modified — no body\n#\n#         return JSONResponse(article, headers={\"ETag\": etag})\n#\n#     # Flow:\n#     #   1st request:\n#     #     curl \"http://localhost:8000/article/1\"\n#     #       ← 200 + {\"title\":\"...\"} + ETag: \"abc123\"\n#     #       (browser stores response + ETag)\n#     #\n#     #   2nd request (data UNCHANGED):\n#     #     curl -H \"If-None-Match: abc123\" \"http://localhost:8000/article/1\"\n#     #       ← 304 Not Modified (NO BODY — saves bandwidth!)\n#     #       (browser uses stored version)\n#     #\n#     #   3rd request (data CHANGED — article was edited):\n#     #     curl -H \"If-None-Match: abc123\" \"http://localhost:8000/article/1\"\n#     #       ← 200 + {\"title\":\"new...\"} + ETag: \"xyz789\"\n#     #       (browser replaces stored version)\n#\n# ── Rate limiting pattern ────────────────────────────────────────\n#   Track request timestamps per client IP in a dict.\n#   Prune timestamps older than RATE_WINDOW seconds.\n#   If count >= RATE_LIMIT → return 429 Too Many Requests.\n#   Add X-RateLimit-Remaining header for client awareness.\n#\n#   BEGINNER EXAMPLE — Rate limiting:\n#\n#     import time\n#     from collections import defaultdict\n#\n#     RATE_LIMIT = 5       # max requests\n#     RATE_WINDOW = 60     # per 60 seconds\n#     request_log = defaultdict(list)\n#\n#     @app.middleware(\"http\")\n#     async def rate_limit(request: Request, call_next):\n#         ip = request.client.host\n#         now = time.time()\n#         request_log[ip] = [t for t in request_log[ip] if now - t < RATE_WINDOW]\n#\n#         if len(request_log[ip]) >= RATE_LIMIT:\n#             return JSONResponse(\n#                 {\"error\": \"Too many requests\"}, status_code=429,\n#                 headers={\"X-RateLimit-Remaining\": \"0\"}\n#             )\n#\n#         request_log[ip].append(now)\n#         remaining = RATE_LIMIT - len(request_log[ip])\n#         response = await call_next(request)\n#         response.headers[\"X-RateLimit-Remaining\"] = str(remaining)\n#         return response\n#\n#     # curl \"http://localhost:8000/anything\"  → 200 (X-RateLimit-Remaining: 4)\n#     # curl \"http://localhost:8000/anything\"  → 200 (X-RateLimit-Remaining: 3)\n#     # ... 3 more ...\n#     # curl \"http://localhost:8000/anything\"  → 429 \"Too many requests\"\n#     #\n#     # After 60 seconds: old timestamps pruned → can make requests again\n#\n# ══════════════════════════════════════════════════════════════════"}, "07_lifespan.py": {"content": "# ══════════════════════════════════════════════════════════════════\n# FastAPI Lifespan — Startup, Shutdown & Resource Management\n# ══════════════════════════════════════════════════════════════════\n# Deps:  pip install fastapi uvicorn httpx\n# Run:   uvicorn 07_lifespan:app --reload   (from fastapi/intermediate)\n# Docs:  http://127.0.0.1:8000/docs\n#\n# Lifespan = the async context manager that wraps your entire app.\n# Code BEFORE yield runs once at startup (open connections, load data).\n# Code AFTER  yield runs once at shutdown (close connections, flush).\n#\n#   startup code\n#       |\n#       v\n#     yield  <-- app serves requests while yielded\n#       |\n#       v\n#   shutdown code\n\nimport asyncio\nimport logging\nimport os\nfrom contextlib import asynccontextmanager\nfrom typing import Any, AsyncGenerator\n\nimport httpx\nfrom fastapi import Depends, FastAPI, Request\nfrom fastapi.responses import JSONResponse\n\n\n# ── What is @asynccontextmanager? ────────────────────\n#\n# A decorator from `contextlib` that converts an async generator\n# (a function with `yield`) into an `async with`-compatible\n# context manager — no class needed.\n#\n#   WITHOUT it (full class):\n#\n#     class DBManager:\n#         async def __aenter__(self):\n#             self.conn = await connect()\n#             return self.conn\n#         async def __aexit__(self, *exc):\n#             await self.conn.close()\n#\n#   WITH it (shortcut — same behavior):\n#\n#     @asynccontextmanager\n#     async def db_manager():\n#         conn = await connect()    # __aenter__ (setup)\n#         yield conn                # value for `async with ... as X`\n#         await conn.close()        # __aexit__ (cleanup)\n#\n#   Both used the same way:\n#     async with db_manager() as conn:\n#         await conn.execute(\"SELECT 1\")\n#\n#   KEY RULE:\n#     before yield = setup    (runs once at start)\n#     yield        = hand off (caller runs while yielded)\n#     after yield  = cleanup  (runs once at end)\n#\n#   HOW IT'S CONSUMED (what happens under the hood):\n#\n#     async with db_manager() as conn:   # calls __aenter__ → runs code before yield\n#         await conn.execute(\"SELECT 1\") # your code runs here (yield pauses db_manager)\n#     # exiting `async with` calls __aexit__ → runs code after yield\n#\n#     # Step by step:\n#     # 1. Python sees `async with db_manager()`\n#     # 2. Calls __aenter__  → runs `conn = await connect()` (before yield)\n#     # 3. yield conn        → `conn` becomes the `as conn` variable\n#     # 4. YOUR code runs    → `await conn.execute(\"SELECT 1\")`\n#     # 5. Block exits       → __aexit__ runs `await conn.close()` (after yield)\n#\n#     # FastAPI does the same with lifespan:\n#     # async with lifespan(app):  ← FastAPI calls this internally\n#     #     # app serves requests here (between yield)\n#\n#   HOW FASTAPI CONSUMES LIFESPAN:\n#\n#     # Step 1: You define the lifespan\n#     @asynccontextmanager\n#     async def lifespan(app: FastAPI):\n#         db = await connect()       # startup\n#         app.state.db = db\n#         yield                      # app serves requests\n#         await db.close()           # shutdown\n#\n#     # Step 2: You pass it to FastAPI (just a reference, NOT called yet)\n#     app = FastAPI(lifespan=lifespan)\n#\n#     # Step 3: Uvicorn starts → FastAPI internally does:\n#     async with lifespan(app):     # ← FastAPI calls it for you\n#         await serve_requests()    # handles all HTTP traffic\n#     # exiting async with → shutdown code runs\n#\n#     # You NEVER call lifespan() yourself — FastAPI is the consumer.\n#\n#   If setup raises before yield, cleanup code after yield\n#   NEVER executes — this is why FastAPI chose it for lifespan.\n#\n#   Sync equivalent: @contextmanager (regular def + yield, no async)\n\n\n# ╔══════════════════════════════════════════════════╗\n# ║               BEGINNER                           ║\n# ╚══════════════════════════════════════════════════╝\n\n\n# ── 1. Minimal lifespan ─────────────────────────────\n# The simplest possible lifespan — just proves the\n# startup/shutdown hooks fire.\n\n@asynccontextmanager\nasync def minimal_lifespan(app: FastAPI) -> AsyncGenerator[None, None]:\n    print(\">>> APP STARTING\")\n    yield\n    print(\">>> APP SHUTTING DOWN\")\n\n# Usage: FastAPI(lifespan=minimal_lifespan)\n\n\n# ── 2. Old vs new (why lifespan replaced on_event) ──\n# BEFORE (deprecated since FastAPI 0.93):\n#\n#   @app.on_event(\"startup\")\n#   async def startup():\n#       app.state.db = await connect_db()\n#\n#   @app.on_event(\"shutdown\")\n#   async def shutdown():\n#       await app.state.db.close()\n#\n# PROBLEMS with on_event:\n#   - startup and shutdown are separate functions with no shared scope\n#   - if startup fails halfway, shutdown still runs for resources\n#     that were never created -> crashes or silent bugs\n#   - no way to guarantee cleanup order\n#\n# AFTER (lifespan context manager):\n#\n#   @asynccontextmanager\n#   async def lifespan(app):\n#       db = await connect_db()      # startup\n#       app.state.db = db\n#       yield                         # app runs\n#       await db.close()              # shutdown (only runs if startup succeeded)\n#\n# The context manager guarantees: if startup raises before yield,\n# the shutdown code after yield never executes.\n\n\n# ── 3. Sharing resources via app.state ──────────────\n# Create expensive resources once, share across all requests.\n\n@asynccontextmanager\nasync def basic_lifespan(app: FastAPI) -> AsyncGenerator[None, None]:\n    # Startup — create an HTTP client with connection pooling\n    app.state.http_client = httpx.AsyncClient(\n        timeout=httpx.Timeout(30.0),\n        limits=httpx.Limits(max_connections=20),\n    )\n    print(f\"[startup] HTTP client ready (pool=20)\")\n\n    yield  # app serves requests here\n\n    # Shutdown — close the client, release all connections\n    await app.state.http_client.aclose()\n    print(\"[shutdown] HTTP client closed\")\n\n\n# ╔══════════════════════════════════════════════════╗\n# ║             INTERMEDIATE                         ║\n# ╚══════════════════════════════════════════════════╝\n\n\n# ── 4. Multiple resources in one lifespan ────────────\n# Real apps need several resources. Initialise them in order,\n# tear them down in reverse order (like a stack).\n\n_cache: dict[str, Any] = {}\n\n@asynccontextmanager\nasync def multi_resource_lifespan(app: FastAPI) -> AsyncGenerator[None, None]:\n    # 1) HTTP client\n    app.state.http_client = httpx.AsyncClient(\n        timeout=httpx.Timeout(30.0),\n        limits=httpx.Limits(max_connections=20),\n    )\n\n    # 2) In-memory cache (stands in for Redis/Memcached)\n    _cache.clear()\n    _cache[\"app_version\"] = \"1.0.0\"\n    app.state.cache = _cache\n\n    # 3) Simulated DB pool (replace with asyncpg/sqlalchemy in real code)\n    app.state.db_pool = {\"status\": \"connected\", \"max_size\": 10}\n\n    print(\"[startup] All resources initialised\")\n    yield\n    # Teardown in reverse order\n    app.state.db_pool = None\n    _cache.clear()\n    await app.state.http_client.aclose()\n    print(\"[shutdown] All resources released\")\n\n\n# ── 5. Error handling in lifespan ────────────────────\n# If one resource fails to init, clean up anything already created.\n\n@asynccontextmanager\nasync def safe_lifespan(app: FastAPI) -> AsyncGenerator[None, None]:\n    http_client = None\n    try:\n        # Resource 1 — might succeed\n        http_client = httpx.AsyncClient(timeout=httpx.Timeout(30.0))\n        app.state.http_client = http_client\n\n        # Resource 2 — might fail (simulated)\n        db_url = os.getenv(\"DATABASE_URL\")\n        if not db_url:\n            # Non-critical: warn but continue\n            print(\"[startup] WARNING: DATABASE_URL not set, DB features disabled\")\n            app.state.db_pool = None\n        else:\n            app.state.db_pool = {\"url\": db_url, \"status\": \"connected\"}\n\n        print(\"[startup] Ready\")\n        yield\n\n    finally:\n        # Always clean up whatever was created\n        if http_client:\n            await http_client.aclose()\n            print(\"[shutdown] HTTP client closed\")\n\n\n# ── 6. Background tasks in lifespan ──────────────────\n# Start a periodic background job at startup, cancel on shutdown.\n\nasync def _periodic_cleanup(interval_seconds: int = 60):\n    \"\"\"Run cleanup every N seconds until cancelled.\"\"\"\n    while True:\n        await asyncio.sleep(interval_seconds)\n        print(f\"[cleanup] Running periodic cleanup...\")\n        # Real work: expire cache entries, delete stale sessions, etc.\n\n@asynccontextmanager\nasync def bg_task_lifespan(app: FastAPI) -> AsyncGenerator[None, None]:\n    # Start background task\n    cleanup_task = asyncio.create_task(\n        _periodic_cleanup(interval_seconds=60),\n        name=\"periodic-cleanup\",\n    )\n    print(\"[startup] Background cleanup task started\")\n\n    yield\n\n    # Cancel and await the task so it exits cleanly\n    cleanup_task.cancel()\n    try:\n        await cleanup_task\n    except asyncio.CancelledError:\n        pass\n    print(\"[shutdown] Background cleanup task stopped\")\n\n\n# ── 7. Dependency injection (cleaner than app.state) ─\n# Instead of reaching into request.app.state everywhere, create\n# a Depends() function that returns the resource. Routes declare\n# what they need; FastAPI wires it up.\n\ndef get_http_client(request: Request) -> httpx.AsyncClient:\n    \"\"\"Dependency that provides the shared HTTP client.\"\"\"\n    return request.app.state.http_client\n\ndef get_cache(request: Request) -> dict[str, Any]:\n    \"\"\"Dependency that provides the shared cache.\"\"\"\n    return request.app.state.cache\n\n# Usage in route:\n#   @app.get(\"/proxy\")\n#   async def proxy(client: httpx.AsyncClient = Depends(get_http_client)):\n#       resp = await client.get(\"https://httpbin.org/get\")\n#       return resp.json()\n\n\n# ╔══════════════════════════════════════════════════╗\n# ║               ADVANCED                           ║\n# ╚══════════════════════════════════════════════════╝\n\n\n# ── 8. Startup config validation (production pattern) ─\n# Validate configuration at startup and log redacted credentials.\n# Fail fast if critical config is missing.\n# Pattern from: reuters-assistant_backend/src/app.py\n\nlogger = logging.getLogger(__name__)\n\ndef _validate_config() -> dict[str, str]:\n    \"\"\"Check required env vars at startup. Raise if critical ones are missing.\"\"\"\n    config = {\n        \"API_KEY\": os.getenv(\"API_KEY\", \"\"),\n        \"DATABASE_URL\": os.getenv(\"DATABASE_URL\", \"\"),\n        \"ENVIRONMENT\": os.getenv(\"ENVIRONMENT\", \"development\"),\n    }\n\n    # Log redacted values so ops can verify secrets resolved\n    for key, val in config.items():\n        if val:\n            redacted = val[:4] + \"...\" if len(val) > 4 else \"***\"\n            logger.info(f\"Config {key}: {redacted}\")\n        else:\n            logger.warning(f\"Config {key}: <not set>\")\n\n    # Fail fast on critical missing config (only in production)\n    if config[\"ENVIRONMENT\"] == \"production\" and not config[\"API_KEY\"]:\n        raise RuntimeError(\"API_KEY is required in production\")\n\n    return config\n\n@asynccontextmanager\nasync def production_lifespan(app: FastAPI) -> AsyncGenerator[None, None]:\n    logger.info(\"=== STARTUP CONFIG CHECK ===\")\n    config = _validate_config()\n    app.state.config = config\n    logger.info(f\"Environment: {config['ENVIRONMENT']}\")\n    logger.info(\"============================\")\n\n    # Init resources\n    app.state.http_client = httpx.AsyncClient(\n        timeout=httpx.Timeout(30.0),\n        limits=httpx.Limits(max_connections=20),\n    )\n\n    # Background cleanup\n    cleanup_task = asyncio.create_task(\n        _periodic_cleanup(interval_seconds=300),\n        name=\"session-cleanup\",\n    )\n\n    logger.info(\"App started successfully\")\n    yield\n\n    # Graceful shutdown\n    logger.info(\"Shutting down...\")\n    cleanup_task.cancel()\n    try:\n        await cleanup_task\n    except asyncio.CancelledError:\n        pass\n\n    await app.state.http_client.aclose()\n    logger.info(\"Shutdown complete\")\n\n\n# ── 9. Graceful shutdown with timeout ────────────────\n# In production, shutdown must complete within a deadline\n# (e.g., ECS sends SIGTERM and kills after 30s).\n# Use asyncio.wait_for to enforce a time limit.\n\nasync def _shutdown_with_timeout(app: FastAPI, timeout: float = 10.0):\n    \"\"\"Close resources with a hard timeout.\"\"\"\n    try:\n        await asyncio.wait_for(\n            _do_cleanup(app),\n            timeout=timeout,\n        )\n    except asyncio.TimeoutError:\n        logger.error(f\"Shutdown timed out after {timeout}s - forcing exit\")\n    except Exception as e:\n        logger.error(f\"Shutdown error: {e}\")\n\nasync def _do_cleanup(app: FastAPI):\n    \"\"\"Actual cleanup work — may take a while.\"\"\"\n    if hasattr(app.state, \"http_client\"):\n        await app.state.http_client.aclose()\n    if hasattr(app.state, \"cleanup_task\"):\n        app.state.cleanup_task.cancel()\n        try:\n            await app.state.cleanup_task\n        except asyncio.CancelledError:\n            pass\n    logger.info(\"All resources cleaned up\")\n\n@asynccontextmanager\nasync def timeout_lifespan(app: FastAPI) -> AsyncGenerator[None, None]:\n    app.state.http_client = httpx.AsyncClient(timeout=httpx.Timeout(30.0))\n    app.state.cleanup_task = asyncio.create_task(\n        _periodic_cleanup(300), name=\"cleanup\"\n    )\n    yield\n    await _shutdown_with_timeout(app, timeout=10.0)\n\n\n# ── 10. Testing lifespan ─────────────────────────────\n# TestClient automatically triggers lifespan events.\n# For async tests, use httpx + ASGITransport.\n#\n# SYNC test (pytest):\n#\n#   from fastapi.testclient import TestClient\n#\n#   def test_startup_creates_client():\n#       with TestClient(app) as client:    # triggers lifespan\n#           resp = client.get(\"/status\")\n#           assert resp.status_code == 200\n#           assert resp.json()[\"http_client\"] == \"ready\"\n#       # exiting `with` triggers shutdown\n#\n#\n# ASYNC test (pytest-asyncio):\n#\n#   import pytest\n#   from httpx import ASGITransport, AsyncClient\n#\n#   @pytest.mark.asyncio\n#   async def test_startup_async():\n#       transport = ASGITransport(app=app)\n#       async with AsyncClient(transport=transport, base_url=\"http://test\") as c:\n#           resp = await c.get(\"/status\")\n#           assert resp.status_code == 200\n#\n#\n# KEY POINT: TestClient triggers lifespan by default. If you want\n# to test WITHOUT lifespan (e.g., unit-testing a single route),\n# pass raise_server_exceptions=False or mock app.state directly.\n\n\n# ═══════════════════════════════════════════════════════\n# RUNNABLE APP — uses production_lifespan from section 8\n# ═══════════════════════════════════════════════════════\n\nlogging.basicConfig(level=logging.INFO)\napp = FastAPI(title=\"Lifespan Demo\", lifespan=production_lifespan)\n\n\n@app.get(\"/\")\nasync def root():\n    return {\"message\": \"App is running\", \"environment\": app.state.config[\"ENVIRONMENT\"]}\n\n\n@app.get(\"/status\")\nasync def status(client: httpx.AsyncClient = Depends(get_http_client)):\n    \"\"\"Check that lifespan-created resources are available.\"\"\"\n    return {\n        \"http_client\": \"ready\" if client else \"missing\",\n        \"config\": app.state.config,\n    }\n\n\n@app.get(\"/proxy\")\nasync def proxy_example(client: httpx.AsyncClient = Depends(get_http_client)):\n    \"\"\"Use the shared HTTP client to call an external API.\"\"\"\n    resp = await client.get(\"https://httpbin.org/get\")\n    return resp.json()", "cheatSheet": "", "reference": ""}}, "fastapi/advanced": {"08_session.py": {"content": "# ══════════════════════════════════════════════════════════════════\n# FastAPI Sessions & Lifespan — Cookie, Redis, JWT\n# ══════════════════════════════════════════════════════════════════\n# Deps: fastapi, uvicorn, httpx, PyJWT, redis, itsdangerous\n#\n# Run: uvicorn 08_session:app --reload   (from fastapi/advanced)\n\nimport uuid, json\nfrom datetime import datetime, timedelta, timezone\nfrom contextlib import asynccontextmanager\nimport httpx, jwt, redis.asyncio as redis\nfrom fastapi import FastAPI, HTTPException, Request, Response, Depends\nfrom fastapi.security import HTTPBearer, HTTPAuthorizationCredentials\nfrom starlette.middleware.sessions import SessionMiddleware\n\n# ╔══════════════════════════════════════════════════╗\n# ║               BEGINNER                           ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. Lifespan — Startup & Shutdown ───────────────\n# @asynccontextmanager turns an async generator into a context manager:\n#   before yield = startup, after yield = shutdown.\n# Replaces the old @app.on_event(\"startup\") / @app.on_event(\"shutdown\").\n# Equivalent to writing __aenter__ / __aexit__ on a class.\n@asynccontextmanager\nasync def lifespan(app: FastAPI):\n    # STARTUP: create shared resources once\n    print(\"Starting up...\")\n    app.state.http_client = httpx.AsyncClient(timeout=30)  # connection-pooled client\n    app.state.redis = redis.Redis(host=\"localhost\", port=6379, decode_responses=True)\n    app.state.shipments = {\n        1: {\"id\": 1, \"content\": \"Wooden Table\", \"weight\": 10, \"status\": \"In Transit\"},\n        2: {\"id\": 2, \"content\": \"Steel Chair\", \"weight\": 20, \"status\": \"Delivered\"},\n        3: {\"id\": 3, \"content\": \"Glass Vase\", \"weight\": 5, \"status\": \"Pending\"},\n    }\n    print(f\"Loaded {len(app.state.shipments)} shipments\")\n    yield  # server is live, handling requests\n    # SHUTDOWN: clean up resources\n    print(\"Shutting down...\")\n    await app.state.http_client.aclose()\n    await app.state.redis.aclose()\n    print(\"All connections closed\")\n\napp = FastAPI(title=\"Shipment Tracker API\", lifespan=lifespan)\napp.add_middleware(SessionMiddleware, secret_key=\"super-secret-key-change-in-prod\")\nJWT_SECRET = \"jwt-secret-key-change-in-prod\"\nsecurity = HTTPBearer()\nSESSION_TTL = 3600  # 1 hour\n\n# ── 2. Shared State via app.state ──────────────────\n# app.state persists across requests for the app's lifetime.\n# Set in lifespan, accessed in routes via app.state.X or request.app.state.X.\n@app.get(\"/shipments\")\nasync def list_shipments():\n    return list(app.state.shipments.values())  # reads from lifespan-loaded data\n\n@app.get(\"/shipments/{shipment_id}\")\nasync def get_shipment(shipment_id: int):\n    shipment = app.state.shipments.get(shipment_id)\n    if not shipment:\n        raise HTTPException(status_code=404, detail=\"Shipment not found\")\n    return shipment\n\n@app.get(\"/external\")\nasync def call_external():\n    resp = await app.state.http_client.get(\"https://jsonplaceholder.typicode.com/todos/1\")\n    return resp.json()  # uses shared httpx client from lifespan\n\n# ╔══════════════════════════════════════════════════╗\n# ║             INTERMEDIATE                         ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 3. Cookie-Based Sessions (SessionMiddleware) ──\n# Starlette stores session data in a signed cookie (client-side).\n# Needs: app.add_middleware(SessionMiddleware, secret_key=...)\n# Data lives in request.session dict. Auto-set on response.\n@app.get(\"/cookie/login\")\nasync def cookie_login(request: Request):\n    request.session[\"user\"] = \"john@reuters.com\"  # stored in signed cookie\n    request.session[\"role\"] = \"editor\"\n    return {\"message\": \"Logged in via cookie session\"}\n\n@app.get(\"/cookie/profile\")\nasync def cookie_profile(request: Request):\n    user = request.session.get(\"user\")\n    if not user:\n        return {\"message\": \"Not logged in\"}\n    return {\"user\": user, \"role\": request.session.get(\"role\")}\n\n@app.get(\"/cookie/logout\")\nasync def cookie_logout(request: Request):\n    request.session.clear()  # removes all session data\n    return {\"message\": \"Logged out\"}\n\n# ── 4. Redis Server-Side Sessions ─────────────────\n# Session ID in cookie, actual data in Redis. Server-controlled expiry.\n# Uses app.state.redis from lifespan.\n@app.get(\"/redis/login\")\nasync def redis_login(request: Request, response: Response):\n    session_id = str(uuid.uuid4())\n    session_data = {\"user\": \"john@reuters.com\", \"role\": \"editor\"}\n    await request.app.state.redis.setex(  # SET with EXpiry\n        f\"session:{session_id}\", SESSION_TTL, json.dumps(session_data),\n    )\n    response.set_cookie(key=\"session_id\", value=session_id, httponly=True)\n    return {\"message\": \"Logged in via Redis session\", \"session_id\": session_id}\n\n@app.get(\"/redis/profile\")\nasync def redis_profile(request: Request):\n    session_id = request.cookies.get(\"session_id\")\n    if not session_id:\n        return {\"message\": \"Not logged in\"}\n    data = await request.app.state.redis.get(f\"session:{session_id}\")\n    if not data:\n        return {\"message\": \"Session expired\"}\n    return json.loads(data)\n\n@app.get(\"/redis/logout\")\nasync def redis_logout(request: Request, response: Response):\n    session_id = request.cookies.get(\"session_id\")\n    if session_id:\n        await request.app.state.redis.delete(f\"session:{session_id}\")\n    response.delete_cookie(\"session_id\")\n    return {\"message\": \"Logged out\"}\n\n# ╔══════════════════════════════════════════════════╗\n# ║               ADVANCED                           ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 5. JWT Token-Based Sessions ────────────────────\n# Stateless: token carries all session data, signed with secret.\n# No server storage needed. Client sends token in Authorization header.\n@app.post(\"/jwt/login\")\nasync def jwt_login():\n    payload = {\n        \"user\": \"john@reuters.com\", \"role\": \"editor\",\n        \"exp\": datetime.now(timezone.utc) + timedelta(hours=1),\n    }\n    token = jwt.encode(payload, JWT_SECRET, algorithm=\"HS256\")\n    return {\"message\": \"Logged in via JWT\", \"token\": token}\n\nasync def get_current_user(credentials: HTTPAuthorizationCredentials = Depends(security)):\n    try:\n        return jwt.decode(credentials.credentials, JWT_SECRET, algorithms=[\"HS256\"])\n    except jwt.ExpiredSignatureError:\n        raise HTTPException(status_code=401, detail=\"Token expired\")\n    except jwt.InvalidTokenError:\n        raise HTTPException(status_code=401, detail=\"Invalid token\")\n\n@app.get(\"/jwt/profile\")\nasync def jwt_profile(user: dict = Depends(get_current_user)):\n    return {\"user\": user[\"user\"], \"role\": user[\"role\"]}\n\n# ── 6. Comparison: Cookie vs Redis vs JWT ──────────\n#\n# ┌─────────────┬──────────────────┬──────────────────┬──────────────────┐\n# | Aspect       | Cookie           | Redis            | JWT              |\n# ├─────────────┼──────────────────┼──────────────────┼──────────────────┤\n# | Storage      | Client (cookie)  | Server (Redis)   | Client (token)   |\n# | Size limit   | ~4KB per cookie  | Unlimited        | ~8KB practical   |\n# | Scalability  | Stateless        | Needs shared DB  | Stateless        |\n# | Revocation   | Clear cookie     | Delete key       | Can't revoke*    |\n# | Security     | Signed, not enc  | Server-only data | Signed, not enc  |\n# | Server load  | None             | Redis lookup/req | None (decode)    |\n# | Best for     | Simple apps      | Production apps  | APIs / SPAs      |\n# └─────────────┴──────────────────┴──────────────────┴──────────────────┘\n# * JWT revocation requires a blocklist (adds server state)\n#\n# Pick cookie for prototypes, Redis for production web apps,\n# JWT for stateless APIs and microservices.", "cheatSheet": "# ── CHEAT SHEET ────────────────────────────────────\n# LIFESPAN\n#   @asynccontextmanager + yield       startup/shutdown lifecycle\n#   app.state.X = resource             share across requests\n#   FastAPI(lifespan=lifespan)          attach to app\n#\n# COOKIE SESSION\n#   SessionMiddleware(secret_key=...)   enable cookie sessions\n#   request.session[\"key\"] = val        write session\n#   request.session.get(\"key\")          read session\n#   request.session.clear()             destroy session\n#\n# REDIS SESSION\n#   redis.setex(key, ttl, data)         store with expiry\n#   redis.get(key)                      retrieve\n#   redis.delete(key)                   remove\n#   response.set_cookie(httponly=True)   secure session cookie\n#\n# JWT SESSION\n#   jwt.encode(payload, secret, alg)    create token\n#   jwt.decode(token, secret, algs)     verify + decode\n#   Depends(HTTPBearer())               extract from header\n#   \"exp\" claim                         auto-expiry\n#", "reference": "# ══════════════════════════════════════════════════════════════════\n#  SESSIONS & AUTH DECLARATIONS — DETAILED REFERENCE\n# ══════════════════════════════════════════════════════════════════\n#\n# ── Lifespan — App startup/shutdown lifecycle ────────────────────\n#   @asynccontextmanager\n#   async def lifespan(app: FastAPI):\n#       app.state.db = connect()       → before yield = STARTUP (create resources)\n#       yield                          → server is live, handling requests\n#       app.state.db.close()           → after yield = SHUTDOWN (cleanup)\n#   FastAPI(lifespan=lifespan)         → attach to app\n#   Replaces old @app.on_event(\"startup\") / @app.on_event(\"shutdown\")\n#\n#   BEGINNER EXAMPLE — Lifespan:\n#\n#     @asynccontextmanager\n#     async def lifespan(app: FastAPI):\n#         # STARTUP — runs once before first request\n#         app.state.http_client = httpx.AsyncClient(timeout=30)\n#         app.state.db = await connect_db()\n#         print(\"Ready!\")\n#         yield                              # ← server is live here\n#         # SHUTDOWN — runs when server stops (Ctrl+C)\n#         await app.state.http_client.aclose()\n#         await app.state.db.close()\n#\n#     app = FastAPI(lifespan=lifespan)       # ← attach to app\n#\n#     # Flow:\n#     #   uvicorn 08_session:app --reload\n#     #     │\n#     #     ▼\n#     #   STARTUP: create http_client, connect DB\n#     #     │\n#     #     ▼\n#     #   yield → server handles requests (uses app.state.http_client, app.state.db)\n#     #     │\n#     #     ▼  (Ctrl+C or server stops)\n#     #   SHUTDOWN: close http_client, close DB\n#\n# ── app.state — Share resources across requests ──────────────────\n#   app.state.http_client = httpx.AsyncClient()   → set in lifespan startup\n#   Access in routes: app.state.X or request.app.state.X\n#   Persists for app's entire lifetime. Use for: DB pools, HTTP clients, caches.\n#\n#   BEGINNER EXAMPLE — app.state:\n#\n#     # Set in lifespan startup:\n#     app.state.shipments = {1: {\"id\": 1, \"content\": \"Table\"}}\n#\n#     # Access in any route:\n#     @app.get(\"/shipments\")\n#     async def list_shipments():\n#         return list(app.state.shipments.values())\n#\n#     # How to call:\n#     #   curl \"http://localhost:8000/shipments\"\n#     #     → [{\"id\": 1, \"content\": \"Table\"}]\n#     #\n#     #   app.state is shared across ALL requests for the app's lifetime\n#     #   Set once in startup → use everywhere → cleanup in shutdown\n#\n# ── SessionMiddleware — Cookie-based sessions ────────────────────\n#   app.add_middleware(SessionMiddleware, secret_key=\"...\")\n#   request.session[\"user\"] = \"john\"   → WRITE — stored in signed cookie (client-side)\n#   request.session.get(\"user\")        → READ — auto-parsed from cookie\n#   request.session.clear()            → DESTROY — removes all session data\n#   Data limit: ~4KB (cookie size limit). Signed but NOT encrypted.\n#\n#   BEGINNER EXAMPLE — Cookie sessions:\n#\n#     app.add_middleware(SessionMiddleware, secret_key=\"my-secret\")\n#\n#     @app.get(\"/cookie/login\")\n#     async def login(request: Request):\n#         request.session[\"user\"] = \"john@reuters.com\"\n#         return {\"message\": \"Logged in\"}\n#\n#     @app.get(\"/cookie/profile\")\n#     async def profile(request: Request):\n#         user = request.session.get(\"user\")\n#         return {\"user\": user}   # None if not logged in\n#\n#     # How to call:\n#     #   Step 1 — Login (sets cookie):\n#     #   curl -c cookies.txt \"http://localhost:8000/cookie/login\"\n#     #     → response sets Set-Cookie header with signed session data\n#     #     → cookies.txt stores: session=eyJhb...  (signed, base64-encoded)\n#     #\n#     #   Step 2 — Access profile (sends cookie back):\n#     #   curl -b cookies.txt \"http://localhost:8000/cookie/profile\"\n#     #     → browser/curl sends cookie → FastAPI decodes → request.session populated\n#     #     → {\"user\": \"john@reuters.com\"}\n#     #\n#     #   Without cookie:\n#     #   curl \"http://localhost:8000/cookie/profile\"\n#     #     → {\"user\": null}   (no session cookie = empty session)\n#     #\n#     #   -c cookies.txt = save cookies to file\n#     #   -b cookies.txt = send cookies from file\n#\n# ── Redis sessions — Server-side storage ─────────────────────────\n#   Session ID in cookie, actual data in Redis (server-controlled).\n#   redis.setex(key, ttl, data)        → store with expiry (auto-delete after TTL)\n#   redis.get(key)                     → retrieve (returns None if expired)\n#   redis.delete(key)                  → explicit removal (logout)\n#   response.set_cookie(httponly=True)  → httponly prevents JS access (XSS protection)\n#\n#   BEGINNER EXAMPLE — Redis sessions:\n#\n#     @app.get(\"/redis/login\")\n#     async def login(request: Request, response: Response):\n#         session_id = str(uuid.uuid4())        # generate unique ID\n#         data = {\"user\": \"john@reuters.com\"}\n#         await redis.setex(f\"session:{session_id}\", 3600, json.dumps(data))\n#         response.set_cookie(key=\"session_id\", value=session_id, httponly=True)\n#         return {\"message\": \"Logged in\"}\n#\n#     @app.get(\"/redis/profile\")\n#     async def profile(request: Request):\n#         session_id = request.cookies.get(\"session_id\")\n#         data = await redis.get(f\"session:{session_id}\")\n#         return json.loads(data) if data else {\"message\": \"Not logged in\"}\n#\n#     # How to call:\n#     #   Step 1 — Login:\n#     #   curl -c cookies.txt \"http://localhost:8000/redis/login\"\n#     #     → generates session_id (e.g., \"a1b2c3d4-...\")\n#     #     → stores {\"user\": \"john\"} in Redis with key \"session:a1b2c3d4-...\"\n#     #     → sets cookie: session_id=a1b2c3d4-... (httponly — JS can't read it)\n#     #\n#     #   Step 2 — Profile:\n#     #   curl -b cookies.txt \"http://localhost:8000/redis/profile\"\n#     #     Cookie: session_id=a1b2c3d4-...\n#     #                        │\n#     #                        ▼\n#     #     Redis lookup: GET \"session:a1b2c3d4-...\"\n#     #                        │\n#     #                        ▼\n#     #     → {\"user\": \"john@reuters.com\"}\n#     #\n#     #   vs Cookie session:\n#     #     Cookie: data IN the cookie (client-side, ~4KB limit)\n#     #     Redis:  only session_id in cookie, data in Redis (unlimited, server-controlled)\n#\n# ── JWT — Stateless token-based auth ─────────────────────────────\n#   jwt.encode(payload, secret, algorithm=\"HS256\")  → create token (includes \"exp\" for expiry)\n#   jwt.decode(token, secret, algorithms=[\"HS256\"]) → verify signature + decode payload\n#   Raises: jwt.ExpiredSignatureError (token too old), jwt.InvalidTokenError (tampered/invalid)\n#   Stateless: no server storage needed. Client sends in Authorization: Bearer <token> header.\n#\n#   BEGINNER EXAMPLE — JWT auth:\n#\n#     @app.post(\"/jwt/login\")\n#     async def login():\n#         payload = {\"user\": \"john\", \"role\": \"editor\",\n#                    \"exp\": datetime.now(timezone.utc) + timedelta(hours=1)}\n#         token = jwt.encode(payload, \"secret\", algorithm=\"HS256\")\n#         return {\"token\": token}\n#\n#     @app.get(\"/jwt/profile\")\n#     async def profile(user: dict = Depends(get_current_user)):\n#         return {\"user\": user[\"user\"]}\n#\n#     # How to call:\n#     #   Step 1 — Login (get token):\n#     #   curl -X POST \"http://localhost:8000/jwt/login\"\n#     #     → {\"token\": \"eyJhbGciOiJIUzI1NiJ9.eyJ1c2VyIjoiam9obi...\"}\n#     #\n#     #   Step 2 — Access protected route (send token):\n#     #   curl \"http://localhost:8000/jwt/profile\" \\\n#     #        -H \"Authorization: Bearer eyJhbGciOiJIUzI1NiJ9...\"\n#     #\n#     #   Header: Authorization: Bearer eyJhbGci...\n#     #                                 │\n#     #                                 ▼\n#     #   Depends(get_current_user):\n#     #     HTTPBearer() extracts token from header\n#     #       → jwt.decode(token, secret) → {\"user\": \"john\", \"role\": \"editor\"}\n#     #                                       │\n#     #                                       ▼\n#     #     user → {\"user\": \"john\", \"role\": \"editor\"}\n#     #\n#     #   Bad token:  curl ... -H \"Authorization: Bearer invalid\"\n#     #     → 401! jwt.InvalidTokenError\n#     #   Expired:    → 401! jwt.ExpiredSignatureError\n#     #   No header:  → 403! HTTPBearer finds no Authorization header\n#\n# ── Depends() — Dependency injection for auth ────────────────────\n#   security = HTTPBearer()\n#   async def get_current_user(credentials: HTTPAuthorizationCredentials = Depends(security)):\n#       → HTTPBearer() extracts token from \"Authorization: Bearer <token>\" header\n#       → credentials.credentials = the raw token string\n#       → Depends(security) runs HTTPBearer BEFORE your function\n#   @app.get(\"/protected\")\n#   async def route(user: dict = Depends(get_current_user)):\n#       → Depends(get_current_user) runs auth check BEFORE route\n#       → If it raises HTTPException, route is skipped (401/403 returned)\n#       → Chaining: route depends on get_current_user, which depends on HTTPBearer()\n#\n#   BEGINNER EXAMPLE — Depends() chain for auth:\n#\n#     security = HTTPBearer()\n#\n#     # Dependency 1: extract token from header\n#     # Dependency 2: decode and verify token\n#     async def get_current_user(cred: HTTPAuthorizationCredentials = Depends(security)):\n#         return jwt.decode(cred.credentials, \"secret\", algorithms=[\"HS256\"])\n#\n#     @app.get(\"/profile\")\n#     async def profile(user: dict = Depends(get_current_user)):\n#         return user\n#\n#     # How the chain works:\n#     #   curl \"http://localhost:8000/profile\" -H \"Authorization: Bearer <token>\"\n#     #\n#     #   Request arrives\n#     #     │\n#     #     ▼\n#     #   Depends(get_current_user) runs FIRST\n#     #     │\n#     #     ├── Depends(security) runs FIRST (inside get_current_user)\n#     #     │     → HTTPBearer() extracts \"Bearer <token>\" from header\n#     #     │     → cred.credentials = \"<token>\" (raw token string)\n#     #     │\n#     #     ├── jwt.decode(token) → {\"user\": \"john\", \"role\": \"editor\"}\n#     #     │\n#     #     ▼\n#     #   profile() runs with user = {\"user\": \"john\", \"role\": \"editor\"}\n#     #\n#     #   If ANY dependency fails → HTTPException → route NEVER runs\n#\n# ── Request & Response objects ───────────────────────────────────\n#   request: Request                   → access to headers, cookies, session, URL, client IP\n#   request.cookies.get(\"session_id\")  → read a specific cookie\n#   request.headers.get(\"Authorization\") → read a header\n#   response: Response                 → set cookies, headers on outgoing response\n#   response.set_cookie(key, value, httponly=True, max_age=3600)\n#   response.delete_cookie(\"session_id\") → remove a cookie\n#\n#   BEGINNER EXAMPLE — Request & Response:\n#\n#     @app.get(\"/demo\")\n#     async def demo(request: Request, response: Response):\n#         # READ from request:\n#         session = request.cookies.get(\"session_id\")     # read cookie\n#         auth = request.headers.get(\"Authorization\")     # read header\n#         ip = request.client.host                        # client IP\n#\n#         # WRITE to response:\n#         response.set_cookie(\"visited\", \"true\", max_age=3600)   # set cookie\n#         response.headers[\"X-Custom\"] = \"hello\"                 # set header\n#         return {\"session\": session, \"ip\": ip}\n#\n#     # How to call:\n#     #   curl -v \"http://localhost:8000/demo\" \\\n#     #        -b \"session_id=abc\" \\\n#     #        -H \"Authorization: Bearer tok123\"\n#     #\n#     #   Request (what server reads):\n#     #     Cookie: session_id=abc          → request.cookies.get(\"session_id\") → \"abc\"\n#     #     Authorization: Bearer tok123    → request.headers.get(\"Authorization\")\n#     #     Client IP: 127.0.0.1           → request.client.host\n#     #\n#     #   Response (what client receives):\n#     #     Set-Cookie: visited=true; Max-Age=3600  ← response.set_cookie()\n#     #     X-Custom: hello                         ← response.headers[]\n#     #     Body: {\"session\": \"abc\", \"ip\": \"127.0.0.1\"}\n#\n# ══════════════════════════════════════════════════════════════════"}, "09_testing_with_pytest.py": {"content": "# ══════════════════════════════════════════════════════════════════\n# Testing FastAPI Apps — TestClient & pytest\n# ══════════════════════════════════════════════════════════════════\n# Deps:  pip install fastapi httpx pytest pytest-asyncio\n# Run:   pytest 09_testing_with_pytest.py -v   (from fastapi/advanced)\n#\n# NOTE: For testing lifespan (startup/shutdown) specifically, see\n# ../intermediate/07_lifespan.py section 10 — this file covers testing ORDINARY routes:\n# CRUD assertions, mocking dependencies, async clients, validation errors.\n# ══════════════════════════════════════════════════════════════════\nimport pytest\nfrom fastapi import Depends, FastAPI, HTTPException\nfrom fastapi.testclient import TestClient\nfrom httpx import ASGITransport, AsyncClient\nfrom pydantic import BaseModel\n\napp = FastAPI()\nshipment_data = {1: {\"id\": 1, \"content\": \"Books\", \"weight\": 5.0, \"status\": \"Pending\"}}\n\n\nclass ShipmentCreate(BaseModel):\n    content: str\n    weight: float\n\n\nclass ShipmentOut(BaseModel):\n    id: int\n    content: str\n    weight: float\n    status: str\n\n\ndef get_current_user():\n    # In real code: decode a JWT/session (see 08_session.py). Kept trivial\n    # here so the DEPENDENCY OVERRIDE example below has something to swap.\n    return {\"username\": \"real-user\"}\n\n\n@app.get(\"/shipments/{shipment_id}\", response_model=ShipmentOut)\ndef get_shipment(shipment_id: int):\n    if shipment_id not in shipment_data:\n        raise HTTPException(status_code=404, detail=\"Not found\")\n    return shipment_data[shipment_id]\n\n\n@app.post(\"/shipments\", response_model=ShipmentOut, status_code=201)\ndef create_shipment(data: ShipmentCreate, user: dict = Depends(get_current_user)):\n    new_id = max(shipment_data.keys()) + 1\n    shipment_data[new_id] = {\"id\": new_id, \"content\": data.content, \"weight\": data.weight, \"status\": \"Pending\"}\n    return shipment_data[new_id]\n\n\n# ╔══════════════════════════════════════════════════╗\n# ║                   BEGINNER                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. TestClient basics — GET ──────────────────────────────\n# TestClient wraps the app and lets you call routes directly, in-process,\n# with NO real network socket or running server needed.\nclient = TestClient(app)\n\n\ndef test_get_existing_shipment():\n    response = client.get(\"/shipments/1\")\n    assert response.status_code == 200\n    assert response.json()[\"content\"] == \"Books\"\n\n\ndef test_get_missing_shipment_returns_404():\n    response = client.get(\"/shipments/999\")\n    assert response.status_code == 404\n    assert response.json() == {\"detail\": \"Not found\"}\n\n\n# ── 2. POST / body payloads ──────────────────────────────\ndef test_create_shipment():\n    response = client.post(\"/shipments\", json={\"content\": \"Laptops\", \"weight\": 12.5})\n    assert response.status_code == 201\n    body = response.json()\n    assert body[\"content\"] == \"Laptops\"\n    assert body[\"status\"] == \"Pending\"  # server-assigned default\n\n\n# ── 3. Validation errors (422) ──────────────────────────────\ndef test_create_shipment_missing_field_returns_422():\n    response = client.post(\"/shipments\", json={\"content\": \"Laptops\"})  # weight missing\n    assert response.status_code == 422\n    errors = response.json()[\"detail\"]\n    assert any(e[\"loc\"][-1] == \"weight\" for e in errors)\n\n\n# ╔══════════════════════════════════════════════════╗\n# ║               INTERMEDIATE                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 4. Dependency overrides — mock auth/DB without touching real code ──────\n# app.dependency_overrides is a dict: {original_dependency: replacement_fn}.\n# This is THE standard way to swap a real auth/DB dependency for a fake one\n# in tests — no monkeypatching, no changing the endpoint code at all.\ndef fake_current_user():\n    return {\"username\": \"test-user\"}\n\n\ndef test_create_shipment_with_overridden_dependency():\n    app.dependency_overrides[get_current_user] = fake_current_user\n    try:\n        response = client.post(\"/shipments\", json={\"content\": \"Books\", \"weight\": 1.0})\n        assert response.status_code == 201\n    finally:\n        app.dependency_overrides.clear()  # GOTCHA: always clear — overrides leak across tests otherwise\n\n\n# ── 5. Async endpoint testing — httpx.AsyncClient + ASGITransport ──────\n# TestClient is sync and fine for most cases. For genuinely async test code\n# (e.g. awaiting other async fixtures), use AsyncClient wired directly to\n# the app via ASGITransport — no real network, same in-process call.\n@pytest.mark.asyncio\nasync def test_get_shipment_async():\n    transport = ASGITransport(app=app)\n    async with AsyncClient(transport=transport, base_url=\"http://test\") as ac:\n        response = await ac.get(\"/shipments/1\")\n    assert response.status_code == 200", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n# CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\n# NEED                          | HOW\n# ------------------------------|----------------------------------------\n# Call a route in a test         | TestClient(app).get/post/put/delete(...)\n# Assert JSON body               | response.json() == {...}\n# Assert validation error        | response.status_code == 422\n# Mock a dependency               | app.dependency_overrides[dep] = fake_dep\n# Undo a mock                     | app.dependency_overrides.clear()\n# Test an async endpoint          | httpx.AsyncClient(transport=ASGITransport(app=app))\n# Test startup/shutdown           | see ../intermediate/07_lifespan.py §10 (TestClient triggers lifespan)\n# ══════════════════════════════════════════════════════════════════\n#", "reference": "# ══════════════════════════════════════════════════════════════════\n#  TESTING FASTAPI APPS — DETAILED REFERENCE\n# ══════════════════════════════════════════════════════════════════\n#\n# ── Why TestClient needs no running server ─────────────────────\n#   TestClient is built on httpx and talks to your `app` object directly\n#   through its ASGI interface — the same interface uvicorn uses to call\n#   your app, just without a real socket/port. That's why tests are fast\n#   and don't need `uvicorn` running in the background.\n#\n# ── dependency_overrides gotchas ─────────────────────\n#   1. Keys are the ORIGINAL function object, not a string name:\n#        app.dependency_overrides[get_current_user] = fake_current_user\n#   2. Overrides are GLOBAL and MUTABLE on the `app` instance — if one test\n#      forgets to clear them, later tests silently inherit the mock. Prefer\n#      a pytest fixture with a `yield` + cleanup, or a try/finally as above.\n#   3. You can override a dependency with another dependency that itself\n#      has sub-dependencies — FastAPI resolves the whole replaced chain.\n#\n# ── A typical pytest fixture version of the override pattern ───\n#   import pytest\n#\n#   @pytest.fixture\n#   def client_as_test_user():\n#       app.dependency_overrides[get_current_user] = fake_current_user\n#       yield TestClient(app)\n#       app.dependency_overrides.clear()\n#\n#   def test_something(client_as_test_user):\n#       response = client_as_test_user.post(\"/shipments\", json={...})\n#       assert response.status_code == 201\n#\n# ── Testing raised HTTPException vs uncaught exceptions ───\n#   TestClient re-raises unhandled server errors by default so tests fail\n#   loudly instead of silently returning a 500. To assert on a 500 response\n#   itself (rare), pass `raise_server_exceptions=False` to TestClient(...).\n#\n# ── conftest.py pattern for a real project ───\n#   Put the `client` fixture (and any dependency-override fixtures) in a\n#   conftest.py at your test root so every test file can use them without\n#   re-importing TestClient/the app in each file.\n# ══════════════════════════════════════════════════════════════════"}}, "python": {"01-data-types.py": {"content": "# ══════════════════════════════════════════════════════════════════\n# PYTHON DATA TYPES — CONDENSED REFERENCE\n# ══════════════════════════════════════════════════════════════════\nimport math, copy, re, weakref\nfrom enum import Enum, IntEnum, Flag, auto\nfrom typing import (List, Dict, Tuple, Set, Optional, Union,\n                    Any, Callable, Final, Literal, NamedTuple, TypedDict)\nfrom collections import namedtuple, OrderedDict, defaultdict, Counter, deque, ChainMap\nfrom dataclasses import dataclass, field\nfrom datetime import date, time, datetime, timedelta, timezone\nfrom decimal import Decimal, getcontext\nfrom fractions import Fraction\nfrom pathlib import Path\nfrom queue import Queue, LifoQueue, PriorityQueue\nfrom contextlib import contextmanager\nfrom functools import partial\n\n# ╔══════════════════════════════════════════════════╗\n# ║                   BEGINNER                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# THINK: Python has two families of types:\n#   IMMUTABLE (int, float, str, tuple, frozenset, bytes) — safe to share, can be dict keys\n#   MUTABLE   (list, dict, set, bytearray)               — changed in place, watch for aliasing bugs\n# This distinction drives 90% of Python's \"gotchas\". When in doubt, ask: \"does this change in place?\"\n\n# ── 1. int ──────────────────────────────────────────\na = 10; b = -5; c = 1_000_000       # underscores for readability\nd = 0b1010; e = 0o17; f = 0xFF      # binary=10, octal=15, hex=255\ng = int(\"42\"); h = int(\"1010\", 2)   # str->int, binary str->int=10\ni = int(3.9)                         # truncates toward zero => 3\nbig = 10**100                        # arbitrary precision, no overflow\nprint(f\"int: {a}, bin={d}, oct={e}, hex={f}\")  # 10, 10, 15, 255\nprint(f\"int(3.9)={i}, int(-3.9)={int(-3.9)}\") # 3, -3 (truncates, NOT rounds)\n# input: num = int(input(\"Enter integer: \"))\n\n# ── 2. float ────────────────────────────────────────\n# 64-bit IEEE 754 double precision (~15-17 significant digits)\na_f = 3.14; b_f = 3.14e2             # standard, scientific=314.0\nc_f = float(\"inf\"); d_f = float(\"nan\")\nprint(f\"float: {a_f}, sci={b_f}, inf={c_f}, nan={d_f}\")\nprint(f\"0.1 + 0.2 = {0.1 + 0.2}\")                     # 0.30000000000000004\nprint(f\"0.1+0.2 == 0.3 => {0.1 + 0.2 == 0.3}\")        # False  GOTCHA!\nprint(f\"math.isclose => {math.isclose(0.1 + 0.2, 0.3)}\")  # True  FIX\nprint(f\"isnan={math.isnan(d_f)}, isinf={math.isinf(c_f)}\")  # True, True\n# input: price = float(input(\"Enter price: \"))\n\n# ── 3. complex ──────────────────────────────────────\nz = 3 + 4j                           #  same as complex(3, 4)\nprint(f\"complex: {z}, real={z.real}, imag={z.imag}\")  # 3.0, 4.0\nprint(f\"conjugate={z.conjugate()}, abs={abs(z)}\")     # (3-4j), 5.0\n# GOTCHA: complex(\"3+4j\") OK, complex(\"3 + 4j\") ValueError (no spaces!)\n\n# ── 4. bool ─────────────────────────────────────────\n# Subclass of int: True==1, False==0\nprint(f\"True+True={True+True}, True*10={True*10}\")  # 2, 10\nprint(f\"isinstance(True, int)={isinstance(True, int)}\")  # True\n# Falsy: False, None, 0, 0.0, 0j, '', [], (), {}, set(), frozenset()\n# Truthy: everything else\nprint(f\"bool('')={bool('')}, bool('x')={bool('x')}\")       # False, True\nprint(f\"bool([])={bool([])}, bool(None)={bool(None)}\")     # False, False\n# GOTCHA: bool(\"False\") => True (non-empty string!)\n# input: answer = input(\"y/n: \").strip().lower() in (\"yes\",\"y\",\"1\")\n\n# ── 5. str ──────────────────────────────────────────\n# Immutable sequence of Unicode characters\ns1 = 'single'; s2 = \"double\"\ns3 = \"\"\"triple\\nfor multiline\"\"\"\ns4 = str(42)                          # \"42\"\ns5 = r\"raw\\nstring\"                   # no escape processing\n\n# Key methods\nword = \"Hello, World!\"\nprint(f\"len={len(word)}, upper={word.upper()}, lower={word.lower()}\")\nprint(f\"strip='{'  hi  '.strip()}', replace={word.replace('World','Python')}\")\nprint(f\"split={'a,b,c'.split(',')}, join={'-'.join(['a','b','c'])}\")\nprint(f\"find={word.find('World')}, count={'banana'.count('a')}\")\nprint(f\"startswith={word.startswith('Hello')}, isdigit={'123'.isdigit()}\")\n\n# Indexing & slicing\ntext = \"Python\"\nprint(f\"[0]={text[0]}, [-1]={text[-1]}, [0:3]={text[0:3]}, [::-1]={text[::-1]}\")\n\n# Formatting\nname, age = \"Alice\", 30\nprint(f\"f-string: {name} is {age}\")           # f-string: Alice is 30\nprint(f\"{3.14159:.2f}, {1000000:,}, {255:08b}, {255:#x}\")  # 3.14, 1,000,000, 11111111, 0xff\n# IMMUTABLE: text[0] = 'p' => TypeError\n\n# ── 6. NoneType ─────────────────────────────────────\nn = None\nprint(f\"None is None: {n is None}\")            # True (always use 'is', not ==)\nprint(f\"bool(None)={bool(None)}\")              # False\ndef no_return(): pass\nprint(f\"no return => {no_return()}\")           # None\n\n# ╔══════════════════════════════════════════════════╗\n# ║                 INTERMEDIATE                     ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 7. list ─────────────────────────────────────────\n# Mutable, ordered, allows duplicates and mixed types\nl1 = [1, 2, 3]; l2 = list(\"hello\")   # ['h','e','l','l','o']\nl3 = list(range(5))                   # [0,1,2,3,4]\n# Indexing: l1[0]=1, l1[-1]=3, l1[1:3]=[2,3], l1[::-1]=[3,2,1]\n\nlst = [3, 1, 4, 1, 5]\nlst.append(9)                         # [3,1,4,1,5,9]\nlst.insert(0, 0)                      # [0,3,1,4,1,5,9]\nlst.extend([6, 7])                    # adds multiple to end\npopped = lst.pop()                    # remove & return last\nlst.remove(1)                         # remove first occurrence\nprint(f\"count={lst.count(1)}, index={lst.index(4)}\")\n\nlst2 = [3, 1, 4, 1, 5]\nlst2.sort()                           # in-place => [1,1,3,4,5]\nlst2.sort(reverse=True)               # descending\nnew_sorted = sorted([3, 1, 2])        # returns new list, original unchanged\n\n# Comprehension\nsquares = [x**2 for x in range(6)]    # [0,1,4,9,16,25]\nevens = [x for x in range(10) if x % 2 == 0]\n\n# Unpacking\nfirst, *rest = [1, 2, 3, 4]           # first=1, rest=[2,3,4]\n\n# Copying\nshallow = lst2.copy()                 # same as lst2[:]\ndeep = copy.deepcopy([[1,2],[3,4]])   # deep copy for nested\n# input: nums = list(map(int, input(\"numbers: \").split()))\n\n# ── 8. tuple ────────────────────────────────────────\n# Immutable, ordered, hashable (if elements are hashable)\nt1 = (1, 2, 3); t2 = (1,)            # COMMA required for single element!\nt3 = tuple([1, 2, 3])\n# GOTCHA: (1) is int, (1,) is tuple\nprint(f\"single: {t2}, type={type(t2)}\")  # (1,), <class 'tuple'>\nprint(f\"NOT tuple: type((1))={type((1))}\")  # <class 'int'>\n\n# Only 2 methods: count() and index()\na_t, b_t, c_t = t1                   # unpacking\nx, y = 10, 20; x, y = y, x           # swap via tuple unpacking\n\n# Mutable objects INSIDE a tuple CAN change  GOTCHA\ntricky = ([1, 2], [3, 4])\ntricky[0].append(3)                   # ([1,2,3], [3,4]) — no error!\n\n#  list vs tuple: list=mutable,slower | tuple=immutable,hashable,faster\n\n# Named tuple\nPoint = namedtuple(\"Point\", [\"x\", \"y\"])\np = Point(3, 4)\nprint(f\"namedtuple: {p}, x={p.x}\")    # Point(x=3, y=4), x=3\n\n# ── 9. range ────────────────────────────────────────\nr1 = range(5)                         # 0,1,2,3,4\nr2 = range(2, 8)                      # 2,3,4,5,6,7\nr3 = range(0, 10, 2)                  # 0,2,4,6,8\nr4 = range(10, 0, -1)                 # countdown 10..1\nprint(f\"range: {list(r3)}, len={len(r1)}, 5 in range(10)={5 in range(10)}\")\n\n# ── 10. set ─────────────────────────────────────────\n# Mutable, unordered, unique elements, elements must be hashable\ns1 = {1, 2, 3}; s2 = {1, 2, 2, 3}    # duplicates removed => {1,2,3}\ns3 = set(\"hello\")                     # {'h','e','l','o'}\ns4 = set()                            # empty set\n# GOTCHA: {} creates dict, NOT set! Use set() for empty set\n\ns = {1, 2, 3}\ns.add(4)                              # add single\ns.update([5, 6])                      # add multiple\ns.discard(6)                          # remove if present (no error)\ns.remove(5)                           # remove (KeyError if missing!)\n\n# Set operations\na_s, b_s = {1, 2, 3, 4}, {3, 4, 5, 6}\nprint(f\"union: {a_s | b_s}\")          # {1,2,3,4,5,6}\nprint(f\"intersect: {a_s & b_s}\")      # {3,4}\nprint(f\"diff: {a_s - b_s}\")           # {1,2}\nprint(f\"sym_diff: {a_s ^ b_s}\")       # {1,2,5,6}\nprint(f\"subset: {{1,2}} <= a_s = {({1,2}).issubset(a_s)}\")  # True\n\n# Set comprehension\neven_set = {x for x in range(10) if x % 2 == 0}\n\n# ── 11. frozenset ───────────────────────────────────\n# Immutable set — can be dict key or set element\nfs = frozenset([1, 2, 3])\n# fs.add(4)  # AttributeError!\nd_fs = {fs: \"value\"}                  # works because hashable\n#  set vs frozenset: set=mutable | frozenset=immutable,hashable\n\n# ── 12. dict ────────────────────────────────────────\n# Mutable key-value mapping. Keys must be hashable. Insertion-ordered (3.7+)\nd1 = {\"name\": \"Alice\", \"age\": 30}\nd2 = dict(name=\"Alice\", age=30)       # keyword args\nd3 = dict(zip([\"x\",\"y\"], [1,2]))      # from zip\nd4 = {i: i**2 for i in range(5)}      # comprehension\n\n# Access\nprint(f\"d1['name']={d1['name']}\")      # Alice\nprint(f\"get={d1.get('missing','default')}\")  # default (no KeyError)\n# d1['missing']  => KeyError\n\n# Modify\nd1[\"email\"] = \"a@b.com\"               # add/update\nd1.update({\"age\": 31, \"city\": \"NYC\"}) # update multiple\nd1.setdefault(\"country\", \"US\")        # set only if missing\n\n# Remove\npopped_d = d1.pop(\"email\")            # remove & return\nlast = d1.popitem()                   # remove last inserted (3.7+)\n\n# Views & iteration\nprint(f\"keys={list(d1.keys())}, values={list(d1.values())}\")\nprint(f\"items={list(d1.items())}\")\nprint(f\"'name' in d1: {'name' in d1}\")  # checks KEYS, not values\n\n# Merge (3.9+)\nmerged = {\"a\": 1} | {\"a\": 2, \"b\": 3}  # {'a':2,'b':3} — right wins\n\n# ── 13. bytes & bytearray ──────────────────────────\n# bytes: immutable, each element 0-255\nb1 = b\"hello\"                         # ASCII bytes literal\nb2 = bytes([72, 101])                 # from int list\nb3 = \"hello\".encode(\"utf-8\")          # str -> bytes\nb4 = b\"hello\".decode(\"utf-8\")         # bytes -> str\nprint(f\"b1[0]={b1[0]}, hex={b1.hex()}\")  # 104, 68656c6c6f\n\n# bytearray: mutable version of bytes\nba = bytearray(b\"hello\")\nba[0] = 72                            # modify in place => b'Hello'\nba.append(33)                         # append '!'\n\n# memoryview: zero-copy view into bytes/bytearray buffer\ndata = bytearray(b\"Hello World\")\nmv = memoryview(data)\nmv[6:11] = b\"Earth\"                   # modifies data in place\nmv.release()\n\n# ╔══════════════════════════════════════════════════╗\n# ║                   ADVANCED                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 14. Enum ────────────────────────────────────────\nclass Color(Enum):\n    RED = 1; GREEN = 2; BLUE = 3\n\nclass Direction(Enum):\n    NORTH = auto(); SOUTH = auto()     # auto-assigned values\n\nclass Permission(IntEnum):             # comparable with ints\n    READ = 4; WRITE = 2; EXECUTE = 1\n\nclass FileFlag(Flag):\n    READ = auto(); WRITE = auto(); EXECUTE = auto()\n\nprint(f\"Color.RED: name={Color.RED.name}, value={Color.RED.value}\")\nprint(f\"Color(1)={Color(1)}, Color['RED']={Color['RED']}\")\ncombined = FileFlag.READ | FileFlag.WRITE\nprint(f\"flags: {combined}, READ in it: {FileFlag.READ in combined}\")  # True\n\n# ── 15. Type Hints ──────────────────────────────────\n# Not runtime types — static analysis only\nnumbers: list[int] = [1, 2, 3]        # 3.9+ built-in generics\nmapping: dict[str, int] = {\"a\": 1}\nmaybe: Optional[str] = None           # str or None\nflex: Union[int, str] = \"hello\"       # int or str\nanything: Any = [1, \"two\"]\nconstant: Final = 42                  # should not reassign\ndirection: Literal[\"n\", \"s\"] = \"n\"\n\ndef greet(name: str, times: int = 1) -> str:\n    return f\"Hello, {name}! \" * times\n\ndef apply(func: Callable[[int, int], int], a: int, b: int) -> int:\n    return func(a, b)\n\nprint(f\"greet: {greet('Bob', 2)}\")     # Hello, Bob! Hello, Bob!\nprint(f\"apply: {apply(lambda a,b: a+b, 3, 4)}\")  # 7\n\n# ── 16. Collections Module ─────────────────────────\n# defaultdict — auto-creates missing keys with factory\ndd = defaultdict(int)\ndd[\"a\"] += 1; dd[\"b\"] += 5\nprint(f\"defaultdict: {dict(dd)}, missing={dd['x']}\")  # {'a':1,'b':5}, 0\n\ndd_list = defaultdict(list)\ndd_list[\"fruits\"].append(\"apple\")      # no KeyError!\n\n# Counter — count occurrences\ncnt = Counter(\"abracadabra\")\nprint(f\"Counter: {cnt.most_common(2)}\")  # [('a',5),('b',2)]\n\n# deque — double-ended queue, O(1) append/pop both ends\ndq = deque([1, 2, 3])\ndq.appendleft(0); dq.append(4)        # [0,1,2,3,4]\ndq.popleft()                          # remove from left\ndq.rotate(1)                          # rotate right\nbounded = deque(maxlen=3)             # auto-discards oldest when full\nfor i in range(5): bounded.append(i)\nprint(f\"bounded: {bounded}\")           # deque([2,3,4], maxlen=3)\n\n# OrderedDict — remembers insertion order (redundant since dict 3.7+, but has move_to_end)\nod = OrderedDict([(\"b\", 2), (\"a\", 1)])\nod.move_to_end(\"a\")                   # move to end\nod.move_to_end(\"b\", last=False)       # move to beginning\n\n# ChainMap — search multiple dicts as one\ndefaults = {\"color\": \"blue\", \"size\": \"M\"}\nprefs = {\"color\": \"red\"}\ncm = ChainMap(prefs, defaults)\nprint(f\"ChainMap: color={cm['color']}, size={cm['size']}\")  # red, M\n\n# ── 17. dataclass ───────────────────────────────────\n@dataclass\nclass Person:\n    name: str\n    age: int\n    hobbies: list = field(default_factory=list)  # GOTCHA: never use mutable default!\n    def greet(self): return f\"Hi, I'm {self.name}!\"\n\n@dataclass(frozen=True)                # immutable dataclass\nclass Coordinate:\n    x: float; y: float\n\np1 = Person(\"Alice\", 30, [\"reading\"])\np2 = Person(\"Alice\", 30, [\"reading\"])\nprint(f\"dataclass: {p1}, eq={p1 == p2}\")  # auto __eq__\n# coord.x = 3.0 => FrozenInstanceError (frozen=True)\n\n# typing.NamedTuple — typed immutable record\nclass Employee(NamedTuple):\n    name: str; department: str; salary: float = 50000.0\n\nemp = Employee(\"Bob\", \"Eng\", 75000.0)\nprint(f\"NamedTuple: {emp.name}, {emp[1]}\")  # Bob, Eng\n\n# TypedDict — type hints for dict (runtime is still plain dict)\nclass Movie(TypedDict):\n    title: str; year: int; rating: float\n\nmovie: Movie = {\"title\": \"Inception\", \"year\": 2010, \"rating\": 8.8}\nprint(f\"TypedDict type: {type(movie)}\")  # <class 'dict'>\n\n# ── 18. Iterator & Generator ───────────────────────\n# Iterator protocol: __iter__() + __next__()\nit = iter([10, 20, 30])\nprint(f\"next: {next(it)}, {next(it)}, {next(it)}\")  # 10, 20, 30\n# next(it) => StopIteration\n\n# Custom iterator\nclass Countdown:\n    def __init__(self, start): self.start = start\n    def __iter__(self): return self\n    def __next__(self):\n        if self.start <= 0: raise StopIteration\n        self.start -= 1\n        return self.start + 1\n\nprint(f\"Countdown: {list(Countdown(3))}\")  # [3, 2, 1]\n\n# Generator — lazy iterator via yield\ndef fibonacci(n):\n    a, b = 0, 1\n    for _ in range(n):\n        yield a\n        a, b = b, a + b\n\nprint(f\"fib: {list(fibonacci(8))}\")    # [0,1,1,2,3,5,8,13]\n\n# Generator expression (lazy list comprehension)\ngen = (x**2 for x in range(5))\nprint(f\"genexpr: {list(gen)}\")         # [0,1,4,9,16]\n\n# Generator with send()\ndef accumulator():\n    total = 0\n    while True:\n        value = yield total\n        if value is None: break\n        total += value\n\nacc = accumulator()\nnext(acc)                              # prime the generator\nprint(f\"send: {acc.send(10)}, {acc.send(20)}\")  # 10, 30\n\n# ── 19. Callable Types ─────────────────────────────\ndef add(a, b): return a + b           # function\nmultiply = lambda a, b: a * b         # lambda\n\nclass Multiplier:                      # callable object (__call__)\n    def __init__(self, factor): self.factor = factor\n    def __call__(self, value): return value * self.factor\n\ndouble = Multiplier(2)\nprint(f\"callable obj: {double(5)}, callable={callable(double)}\")  # 10, True\n\n# Closure\ndef make_adder(n):\n    def adder(x): return x + n\n    return adder\nadd5 = make_adder(5)\nprint(f\"closure: {add5(10)}\")          # 15\n\n# Partial\nadd10 = partial(add, 10)\nprint(f\"partial: {add10(5)}\")          # 15\n\n# ── 20. Context Manager ────────────────────────────\nclass ManagedResource:\n    def __enter__(self):\n        print(\"  acquired\"); return self\n    def __exit__(self, *args):\n        print(\"  released\"); return False\n\n@contextmanager\ndef managed():\n    print(\"  setup\"); yield \"value\"; print(\"  teardown\")\n\nwith ManagedResource(): pass           # acquired -> released\nwith managed() as v: print(f\"  val={v}\")  # setup -> val=value -> teardown\n\n# ── 21. Regex Match ─────────────────────────────────\nmatch = re.search(r\"(\\d{4})-(\\d{2})-(\\d{2})\", \"Date: 2024-01-15!\")\nif match:\n    print(f\"match: {match.group()}, groups={match.groups()}, span={match.span()}\")\n    # 2024-01-15, ('2024','01','15'), (6,16)\n\n# ── 22. datetime ────────────────────────────────────\nd = date(2024, 1, 15); today = date.today()\nprint(f\"date: {d}, weekday={d.weekday()}\")  # 0=Monday\nprint(f\"strftime: {d.strftime('%B %d, %Y')}\")  # January 15, 2024\n\ndt = datetime(2024, 1, 15, 14, 30, 45)\nnow = datetime.now(); utc = datetime.now(timezone.utc)\nparsed = datetime.strptime(\"2024-01-15\", \"%Y-%m-%d\")\n\ndelta = timedelta(days=7, hours=3)\nprint(f\"delta: {delta}, total_sec={delta.total_seconds()}\")\nprint(f\"date+delta: {d + delta}\")      # 2024-01-22\n\n# ── 23. Decimal & Fraction ──────────────────────────\n# Decimal — exact decimal arithmetic (no float rounding)\nprint(f\"Decimal: {Decimal('0.1') + Decimal('0.2')}\")  # 0.3  (exact!)\nprint(f\"float:   {0.1 + 0.2}\")                        # 0.300...04  (inexact)\ngetcontext().prec = 50                 # set precision\n\n# Fraction — exact rational arithmetic\nf1 = Fraction(1, 3); f2 = Fraction(1, 6)\nprint(f\"Fraction: {f1}+{f2}={f1+f2}\")  # 1/3+1/6=1/2\nprint(f\"from str: {Fraction('7/3')}\")   # 7/3\nprint(f\"pi approx: {Fraction(3.14159).limit_denominator(100)}\")  # 311/99\n\n# ── 24. Path ────────────────────────────────────────\np = Path(\".\")\nprint(f\"cwd={Path.cwd()}, home={Path.home()}, exists={p.exists()}\")\np2 = Path(\"folder\") / \"sub\" / \"file.txt\"  # path joining with /\nprint(f\"parent={p2.parent}, stem={p2.stem}, suffix={p2.suffix}\")\n\n# ── 25. Queue Types (Thread-safe) ───────────────────\nq = Queue(maxsize=3); q.put(\"a\"); q.put(\"b\")\nprint(f\"FIFO: {q.get()}\")             # a\n\nlq = LifoQueue(); lq.put(\"a\"); lq.put(\"b\")\nprint(f\"LIFO: {lq.get()}\")            # b (stack)\n\npq = PriorityQueue()\npq.put((2, \"med\")); pq.put((1, \"high\")); pq.put((3, \"low\"))\nprint(f\"Priority: {pq.get()}\")        # (1, 'high')\n\n# ── 26. Special Types ──────────────────────────────\n# type() — the type of types (metaclass)\nprint(f\"type(42)={type(42)}, type(int)={type(int)}, type(type)={type(type)}\")\nMyClass = type(\"MyClass\", (object,), {\"x\": 10})  # dynamic class creation\n\n# object — base class of everything\nprint(f\"isinstance(42, object)={isinstance(42, object)}\")  # True\n\n# Ellipsis — placeholder in stubs, NumPy slicing\nprint(f\"... is Ellipsis: {... is Ellipsis}\")  # True\n\n# weakref — reference that doesn't prevent GC\nclass MyObj:\n    def __init__(self, name): self.name = name\nobj = MyObj(\"test\"); weak = weakref.ref(obj)\nprint(f\"weakref alive: {weak().name}\")  # test\ndel obj\nprint(f\"weakref dead: {weak()}\")        # None\n\n# ── 27. Type Checking Utilities ─────────────────────\n# type() vs isinstance()\nprint(f\"type(42)==int: {type(42)==int}\")                   # True\nprint(f\"isinstance(True,int): {isinstance(True,int)}\")    # True  GOTCHA: bool IS int\nprint(f\"isinstance(42,(int,float)): {isinstance(42,(int,float))}\")  # tuple of types\n\n# issubclass()\nprint(f\"issubclass(bool,int): {issubclass(bool,int)}\")    # True\n\n# is vs ==\na_id = [1,2]; b_id = a_id; c_id = [1,2]\nprint(f\"a is b: {a_id is b_id}, a is c: {a_id is c_id}, a==c: {a_id==c_id}\")\n# True (same obj), False (diff obj), True (same value)", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n# CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\nprint()\nprint(\"=\" * 70)\nprint(\"PYTHON DATA TYPES CHEAT SHEET\")\nprint(\"=\" * 70)\nprint(f\"\"\"\n{'Type':<15} {'Mutable':<9} {'Ordered':<9} {'Hashable':<10} {'Literal Syntax'}\n{'-'*15} {'-'*9} {'-'*9} {'-'*10} {'-'*25}\n{'int':<15} {'No':<9} {'N/A':<9} {'Yes':<10} 42, 0xFF, 0b1010\n{'float':<15} {'No':<9} {'N/A':<9} {'Yes':<10} 3.14, 1e-3, float(\"inf\")\n{'complex':<15} {'No':<9} {'N/A':<9} {'Yes':<10} 3+4j\n{'bool':<15} {'No':<9} {'N/A':<9} {'Yes':<10} True, False\n{'str':<15} {'No':<9} {'Yes':<9} {'Yes':<10} \"hello\", f\"{{x}}\"\n{'bytes':<15} {'No':<9} {'Yes':<9} {'Yes':<10} b\"hello\"\n{'bytearray':<15} {'Yes':<9} {'Yes':<9} {'No':<10} bytearray(b\"hi\")\n{'list':<15} {'Yes':<9} {'Yes':<9} {'No':<10} [1, 2, 3]\n{'tuple':<15} {'No':<9} {'Yes':<9} {'Yes*':<10} (1, 2, 3)\n{'range':<15} {'No':<9} {'Yes':<9} {'Yes':<10} range(10)\n{'set':<15} {'Yes':<9} {'No':<9} {'No':<10} {{1, 2, 3}}\n{'frozenset':<15} {'No':<9} {'No':<9} {'Yes':<10} frozenset([1,2])\n{'dict':<15} {'Yes':<9} {'Yes**':<9} {'No':<10} {{\"a\": 1}}\n{'NoneType':<15} {'N/A':<9} {'N/A':<9} {'Yes':<10} None\n{'Decimal':<15} {'No':<9} {'N/A':<9} {'Yes':<10} Decimal(\"0.1\")\n{'Fraction':<15} {'No':<9} {'N/A':<9} {'Yes':<10} Fraction(1, 3)\n\n*  tuple hashable only if all elements hashable\n** dict insertion-ordered since Python 3.7\n\nKEY GOTCHAS:\n  {{}} is dict, NOT set        -> use set() for empty set\n  (1) is int, NOT tuple       -> use (1,) for single-element tuple\n  0.1+0.2 != 0.3              -> use math.isclose() or Decimal\n  bool(\"False\") is True       -> non-empty string is truthy\n  isinstance(True, int)=True  -> bool is subclass of int\n  mutable default args shared -> use field(default_factory=list)\n  list.sort() returns None    -> use sorted() for new list\n\"\"\")\n\n# ╔══════════════════════════════════════════════════╗\n# ║          INTERVIEW GOTCHAS                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── Q: Mutable vs Immutable — what changes in place? ──\na = [1, 2, 3]\nb = a              # b points to SAME list\nb.append(4)\nprint(a)           # [1, 2, 3, 4] — a changed too! same object\n\nx = \"hello\"\ny = x\ny = y + \" world\"\nprint(x)           # \"hello\" — unchanged, strings are immutable, y is a NEW string\n\n# ── Q: == vs is ──\na = [1, 2, 3]\nb = [1, 2, 3]\nprint(a == b)    # True  — same VALUE\nprint(a is b)    # False — different OBJECTS in memory\n\n# gotcha with small ints (Python caches -5 to 256)\nx = 256; y = 256\nprint(x is y)    # True  — cached\nx = 257; y = 257\nprint(x is y)    # False (in most cases) — not cached\n\n# ── Q: Shallow vs Deep Copy ──\noriginal = [[1, 2], [3, 4]]\nshallow = original.copy()           # or list(original) or original[:]\ndeep = copy.deepcopy(original)\n\noriginal[0].append(99)\nprint(shallow)   # [[1, 2, 99], [3, 4]] — inner list shared!\nprint(deep)      # [[1, 2], [3, 4]]     — fully independent\n\n# ── Q: Tuple with one element ──\nnot_a_tuple = (42)      # just an int in parentheses\nis_a_tuple = (42,)      # trailing comma makes it a tuple\nprint(type(not_a_tuple))  # <class 'int'>\nprint(type(is_a_tuple))   # <class 'tuple'>\n\n# ── Q: What does `in` check for dicts? ──\nd = {\"name\": \"Alice\", \"age\": 30}\nprint(\"name\" in d)     # True  — checks KEYS, not values\nprint(\"Alice\" in d)    # False — \"Alice\" is a value, not a key\nprint(\"Alice\" in d.values())  # True\n\n# ── Q: String formatting tricks ──\nname = \"Alice\"\nprice = 1234.5678\nprint(f\"{name!r}\")          # 'Alice'    — repr\nprint(f\"{price:.2f}\")       # 1234.57    — 2 decimals\nprint(f\"{price:,.2f}\")      # 1,234.57   — thousands separator\nprint(f\"{42:08b}\")          # 00101010   — binary with padding\nprint(f\"{'hi':>10}\")        #         hi — right align\nprint(f\"{'hi':^10}\")        #     hi     — center\n\n# ── Q: any() and all() ──\nnums = [1, 0, 3, 5]\nprint(any(nums))           # True  — at least one truthy\nprint(all(nums))           # False — 0 is falsy", "reference": ""}, "02-functions.py": {"content": "# ══════════════════════════════════════════════════════════════════\n# PYTHON FUNCTIONS — Essential Guide (Basic → Advanced)\n# ══════════════════════════════════════════════════════════════════\n\n# ╔══════════════════════════════════════════════════╗\n# ║  BEGINNER                                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. Basics — def, return, None ──────────────────\n\ndef greet(name):\n    return f\"Hello, {name}!\"\n\nprint(greet(\"Alice\"))           # Hello, Alice!\n\ndef no_return():\n    x = 5 + 3\n\nprint(no_return())              # None  (no return = returns None)\n\ndef early_exit(x):\n    if x < 0: return \"negative\" # function STOPS here\n    return \"positive\"           # only runs if x >= 0\n\n# Parameter = placeholder in def  |  Argument = actual value when calling\n# def greet(name):   ← PARAMETER  |  greet(\"Alice\")  ← ARGUMENT\n\ndef add(a, b):       # a, b = parameters\n    return a + b\nprint(add(3, 5))     # 3, 5 = arguments  →  8\n\n\n# ── 2. Default values ─────────────────────────────\n\ndef greet(name, greeting=\"Hello\"):\n    return f\"{greeting}, {name}!\"\n\nprint(greet(\"Alice\"))              # Hello, Alice!     (uses default)\nprint(greet(\"Bob\", \"Hi\"))          # Hi, Bob!          (overrides default)\n\n# DANGER: Mutable default is SHARED across calls\n# BAD:  def f(items=[])   → same list every call!\n# GOOD: def f(items=None) → new list each call\n\ndef bad(items=[]):\n    items.append(1); return items\nprint(bad())                 # [1]\nprint(bad())                 # [1, 1]  ← NOT [1]!\n\ndef good(items=None):\n    if items is None: items = []\n    items.append(1); return items\nprint(good())                # [1]\nprint(good())                # [1]  ← correct\n\n\n# ── 3. Positional vs Keyword arguments ─────────────\n# Positional: order matters         → f(\"Alice\", 30)\n# Keyword:   name matters           → f(age=30, name=\"Alice\")\n# Mixed:     positional FIRST       → f(\"Alice\", age=30)  OK\n#            keyword first = ERROR  → f(name=\"Alice\", 30)  ERROR\n\ndef register(name, age, email):\n    return f\"{name}, {age}, {email}\"\n\nprint(register(\"Alice\", 30, \"a@test.com\"))                # positional\nprint(register(email=\"b@test.com\", name=\"Bob\", age=25))   # keyword\nprint(register(\"Charlie\", email=\"c@test.com\", age=35))    # mixed\n\n# Skip middle defaults using keyword\ndef setup(host, port=8000, debug=False, workers=4):\n    return f\"{host}:{port} debug={debug} workers={workers}\"\nprint(setup(\"localhost\", debug=True))     # skip port, set debug\n\n\n# ── 4. Return multiple values ──────────────────────\n\ndef min_max(numbers):\n    return min(numbers), max(numbers)   # returns a tuple\n\nlow, high = min_max([5, 2, 8, 1, 9])   # unpack into 2 vars\nprint(f\"low={low}, high={high}\")        # low=1, high=9\n\ndef analyze(nums):\n    return {\"sum\": sum(nums), \"avg\": sum(nums) / len(nums)}\nprint(analyze([10, 20, 30]))            # {'sum': 60, 'avg': 20.0}\n\n\n# ── 5. Error handling ─────────────────────────────\n\ndef divide(a, b):\n    if b == 0: raise ValueError(\"Cannot divide by zero\")\n    return a / b\n\ntry:\n    print(divide(10, 0))\nexcept ValueError as e:\n    print(f\"Error: {e}\")                # Error: Cannot divide by zero\n\ndef safe_int(val, default=0):\n    try: return int(val)\n    except (ValueError, TypeError): return default\n\nprint(safe_int(\"42\"))       # 42\nprint(safe_int(\"abc\"))      # 0\n\n\n# ╔══════════════════════════════════════════════════╗\n# ║  INTERMEDIATE                                    ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 6. *args vs **kwargs ──────────────────────────\n#  *args    → collects positional → tuple    → f(1, 2, 3)\n#  **kwargs → collects keyword    → dict     → f(a=1, b=2)\n\ndef add_all(*args):\n    return sum(args)           # args is a tuple\nprint(add_all(1, 2, 3))       # 6\n\ndef show(**kwargs):\n    for k, v in kwargs.items():\n        print(f\"  {k}={v}\")\nshow(name=\"Alice\", age=30)    # name=Alice  age=30\n\n# Both together — ORDER: regular, *args, **kwargs\ndef log(level, *tags, **meta):\n    print(f\"  [{level}] tags={tags} meta={meta}\")\nlog(\"INFO\", \"db\", \"slow\", host=\"prod\", latency=200)\n# [INFO] tags=('db', 'slow') meta={'host': 'prod', 'latency': 200}\n\n\n# ── 7. Keyword-only (*) vs Positional-only (/) ────\n#  After *  → MUST use name=       →  def f(*, x):   f(x=5) OK, f(5) ERROR\n#  Before / → CANNOT use name=     →  def f(x, /):   f(5) OK, f(x=5) ERROR\n\ndef connect(host, port, *, timeout=30, ssl=True):\n    return f\"{host}:{port} timeout={timeout}\"\nprint(connect(\"localhost\", 8080, timeout=60))   # OK\n# connect(\"localhost\", 8080, 60)                # TypeError!\n\ndef divide(a, b, /):\n    return a / b\nprint(divide(10, 3))       # OK → 3.333...\n# divide(a=10, b=3)        # TypeError!\n\n# Full combo:  positional-only / normal * keyword-only\ndef hybrid(a, b, /, c, d, *, e):\n    return f\"a={a} b={b} c={c} d={d} e={e}\"\nprint(hybrid(1, 2, 3, d=4, e=5))\n\n\n# ── 8. Unpacking when calling (* vs **) ───────────\n#  *list   → unpacks into positional   f(*[1,2,3])  = f(1,2,3)\n#  **dict  → unpacks into keyword      f(**{\"a\":1}) = f(a=1)\n\ndef add3(a, b, c): return a + b + c\n\nprint(add3(*[10, 20, 30]))                    # 60\nprint(add3(**{\"a\": 1, \"b\": 2, \"c\": 3}))      # 6\n\n# Forwarding — pass everything through\ndef wrapper(*args, **kwargs):\n    return add3(*args, **kwargs)\nprint(wrapper(1, 2, 3))       # 6\n\n\n# ── 9. Lambda vs def ──────────────────────────────\n#  def    → named, multi-line, any logic\n#  lambda → anonymous, ONE expression only, best for sorted/map/filter\n\ndouble = lambda x: x * 2\nclassify = lambda x: \"pos\" if x > 0 else \"neg\" if x < 0 else \"zero\"\nprint(double(5))             # 10\nprint(classify(-3))          # neg\n\nusers = [(\"Bob\", 25), (\"Alice\", 30), (\"Charlie\", 20)]\nprint(sorted(users, key=lambda u: u[1]))      # sort by age\n\nnums = [1, 2, 3, 4, 5, 6, 7, 8]\nprint(list(filter(lambda n: n % 2 == 0, nums)))   # [2, 4, 6, 8]\nprint(list(map(lambda n: n ** 2, nums)))           # [1, 4, 9, 16, ...]\n\n\n# ── 10. map vs filter vs reduce ───────────────────\n#  map()    → transform each item      → list → list\n#  filter() → keep items where True    → list → list\n#  reduce() → combine all into one     → list → value\n\nfrom functools import reduce\nnums = [1, 2, 3, 4, 5]\nprint(list(map(lambda x: x * 2, nums)))       # [2, 4, 6, 8, 10]\nprint(list(filter(lambda x: x > 3, nums)))    # [4, 5]\nprint(reduce(lambda acc, x: acc + x, nums))   # 15\n\n\n# ── 11. First-class functions ─────────────────────\n# Functions ARE objects — assign, pass, store them\n\nyell = str.upper\nprint(yell(\"hello\"))                  # HELLO\n\ndef apply(func, value): return func(value)\nprint(apply(len, \"hello\"))            # 5\n\n# Dispatch pattern — store in dict\nops = {\"+\": lambda a, b: a + b, \"-\": lambda a, b: a - b}\nprint(ops[\"+\"](10, 3))               # 13\n\n\n# ── 12. global vs nonlocal  (Scope: LEGB) ─────────\n#  global   → modify MODULE-level variable\n#  nonlocal → modify ENCLOSING function var\n#  LEGB: Local → Enclosing → Global → Built-in\n\nx = \"global\"\ndef demo_global():\n    global x\n    x = \"modified by function\"\ndemo_global()\nprint(x)            # modified by function\n\ndef outer():\n    msg = \"original\"\n    def inner():\n        nonlocal msg\n        msg = \"changed\"\n    inner()\n    return msg\nprint(outer())      # changed\n\n\n# ── 13. Type hints + Docstrings ────────────────────\n# Hints = for humans & tools (NOT enforced at runtime)\n\nfrom typing import Optional\n\ndef find_user(user_id: int) -> Optional[dict]:\n    \"\"\"Look up a user by ID. Returns None if not found.\"\"\"\n    users = {1: {\"name\": \"Alice\"}}\n    return users.get(user_id)\n\nprint(find_user(1))        # {'name': 'Alice'}\nprint(find_user(99))       # None\n\n\n# ╔══════════════════════════════════════════════════╗\n# ║  ADVANCED                                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 14. Closure — function that remembers outer vars\n#  Regular → no memory between calls\n#  Closure → remembers outer function's vars, even after it exits\n\ndef make_multiplier(factor):\n    def multiply(x): return x * factor  # remembers factor\n    return multiply\n\ndouble = make_multiplier(2)\ntriple = make_multiplier(3)\nprint(f\"double(5)={double(5)}, triple(5)={triple(5)}\")   # 10, 15\n\n# Closure with mutable state\ndef make_counter():\n    count = 0\n    def increment():\n        nonlocal count\n        count += 1\n        return count\n    return increment\n\nc = make_counter()\nprint(f\"{c()}, {c()}, {c()}\")    # 1, 2, 3\n\n\n# ── 15. return vs yield (Generator) ───────────────\n#  return → sends ONE value, function ENDS\n#  yield  → sends ONE value, function PAUSES, resumes on next()\n#  Generators are memory efficient — no full list in RAM\n\ndef get_squares_list(n):         # builds ENTIRE list in memory\n    return [x**2 for x in range(n)]\n\ndef get_squares_gen(n):          # yields ONE at a time (lazy)\n    for x in range(n):\n        yield x**2\n\nprint(list(get_squares_gen(5)))   # [0, 1, 4, 9, 16]\n\ngen = get_squares_gen(3)\nprint(next(gen), next(gen), next(gen))   # 0 1 4\n# next(gen)  → StopIteration\n\n# Infinite generator — impossible with return!\ndef count_forever(start=0):\n    n = start\n    while True:\n        yield n\n        n += 1\n\ncounter = count_forever()\nprint([next(counter) for _ in range(5)])   # [0, 1, 2, 3, 4]\n\n# yield from — delegate to another iterable\ndef combined():\n    yield from range(3)       # 0, 1, 2\n    yield from range(10, 13)  # 10, 11, 12\nprint(list(combined()))       # [0, 1, 2, 10, 11, 12]\n\n# Generator expression vs list comprehension\ngen_exp = (x**2 for x in range(5))    # lazy — uses ()\nlst_cmp = [x**2 for x in range(5)]    # eager — builds full list\n\n\n# ── 16. Decorators ────────────────────────────────\n# @decorator = shorthand for func = decorator(func)\n\nimport functools, time\n\ndef timer(func):\n    @functools.wraps(func)\n    def wrapper(*args, **kwargs):\n        start = time.time()\n        result = func(*args, **kwargs)\n        print(f\"  {func.__name__} took {time.time()-start:.4f}s\")\n        return result\n    return wrapper\n\n@timer\ndef slow(): return sum(range(1_000_000))\nslow()\n\n# Decorator WITH arguments (decorator factory)\ndef repeat(times):\n    def decorator(func):\n        @functools.wraps(func)\n        def wrapper(*args, **kwargs):\n            return [func(*args, **kwargs) for _ in range(times)]\n        return wrapper\n    return decorator\n\n@repeat(3)\ndef say(word): return word\nprint(say(\"hi\"))     # ['hi', 'hi', 'hi']\n\n\n# ── 17. Recursion ─────────────────────────────────\n# Function calls itself — MUST have base case or → crash\n\ndef factorial(n):\n    if n <= 1: return 1              # base case\n    return n * factorial(n - 1)      # recursive case\nprint(f\"5! = {factorial(5)}\")        # 120\n\ndef flatten(lst):\n    result = []\n    for item in lst:\n        if isinstance(item, list): result.extend(flatten(item))\n        else: result.append(item)\n    return result\nprint(flatten([1, [2, [3, [4]]]]))   # [1, 2, 3, 4]\n\n\n# ── 18. Memoization — @lru_cache ──────────────────\n# Caches return values by arguments — makes repeated calls instant\n\n@functools.lru_cache(maxsize=128)\ndef fib(n):\n    if n <= 1: return n\n    return fib(n-1) + fib(n-2)\n\nprint(f\"fib(50) = {fib(50)}\")        # instant! (without cache → years)\nprint(f\"Cache: {fib.cache_info()}\")\nfib.cache_clear()                    # reset cache\n\n\n# ── 19. Partial — pre-fill arguments ──────────────\n\nfrom functools import partial\n\ndef power(base, exp): return base ** exp\nsquare = partial(power, exp=2)\ncube   = partial(power, exp=3)\nprint(f\"square(5)={square(5)}, cube(3)={cube(3)}\")   # 25, 27\n\n\n# ── 20. Common patterns ──────────────────────────\n\n# Callback — pass a function to run later\ndef process(data, on_done):\n    on_done([x * 2 for x in data])\nprocess([1, 2, 3], lambda r: print(f\"Done: {r}\"))   # Done: [2, 4, 6]\n\n# Composition — chain functions left to right\ndef pipe(*fns):\n    def piped(x):\n        for f in fns: x = f(x)\n        return x\n    return piped\nclean = pipe(str.strip, str.lower, str.split)\nprint(clean(\"  Hello World  \"))    # ['hello', 'world']\n\n# Registry — decorator that registers handlers\nregistry = {}\ndef register(name):\n    def dec(fn): registry[name] = fn; return fn\n    return dec\n\n@register(\"greet\")\ndef greet_handler(data): return f\"Hello, {data}!\"\nprint(registry[\"greet\"](\"Alice\"))   # Hello, Alice!\n\n\n# ── 21. Function introspection ────────────────────\n\ndef example(a: int, b: str = \"hi\") -> str:\n    \"\"\"Example function.\"\"\"\n    return f\"{a} {b}\"\n\nprint(f\"__name__:     {example.__name__}\")         # example\nprint(f\"__doc__:      {example.__doc__}\")           # Example function.\nprint(f\"__defaults__: {example.__defaults__}\")      # ('hi',)\nprint(f\"callable:     {callable(example)}\")         # True", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n# CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\n#\n#  DEFINITION                            CALLING\n#  ────────────────────────────────────   ──────────────────────────\n#  def f(a, b):         regular          f(1, 2)        positional\n#  def f(a, b=10):      default          f(a=1, b=2)    keyword\n#  def f(*args):        → tuple          f(*[1,2])      unpack list\n#  def f(**kwargs):     → dict           f(**{\"a\":1})   unpack dict\n#  def f(a, /, b, *, c): pos/kw-only\n#  lambda a, b: a + b   one-liner\n#\n#  RETURN                                SCOPE (LEGB)\n#  ────────────────────────────────────   ──────────────────────────\n#  return x         single value         Local → Enclosing →\n#  return x, y      tuple                  Global → Built-in\n#  no return        → None               global x    module-level\n#  yield x          generator (lazy)     nonlocal x  enclosing func\n#\n#  KEY TOOLS                             BEST PRACTICES\n#  ────────────────────────────────────   ──────────────────────────\n#  map(fn, list)    transform each       Never def f(items=[])\n#  filter(fn, list) keep where True       → use def f(items=None)\n#  reduce(fn, list) combine into one     Guard clauses: validate early\n#  partial(fn, arg) pre-fill args        One function = one job\n#  @lru_cache       cache by args        Type hints: def f(x: int)\n#  @decorator       wrap behavior\n\n# ╔══════════════════════════════════════════════════╗\n# ║          INTERVIEW GOTCHAS                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── Q: Mutable default argument (classic bug) ──\ndef add_item_bad(item, items=[]):   # DEFAULT LIST shared across ALL calls\n    items.append(item)\n    return items\n\nprint(add_item_bad(\"a\"))   # ['a']\nprint(add_item_bad(\"b\"))   # ['a', 'b'] — SURPRISE! same list reused\n\ndef add_item_good(item, items=None):   # FIX: use None\n    if items is None:\n        items = []\n    items.append(item)\n    return items\n\nprint(add_item_good(\"a\"))  # ['a']\nprint(add_item_good(\"b\"))  # ['b'] — fresh list each time\n\n# ── Q: Closure gotcha in loops ──\nfuncs = []\nfor i in range(3):\n    funcs.append(lambda: i)    # all lambdas capture SAME variable i\n\nprint([f() for f in funcs])    # [2, 2, 2] — NOT [0, 1, 2]!\n\n# FIX: capture i as default argument\nfuncs_fixed = []\nfor i in range(3):\n    funcs_fixed.append(lambda i=i: i)\nprint([f() for f in funcs_fixed])       # [0, 1, 2]\n\n# ── Q: Can a function modify an argument? ──\ndef change_list(lst):\n    lst.append(99)       # modifies the SAME list (mutable)\n\ndef change_number(n):\n    n = n + 1            # creates NEW int (immutable) — original unchanged\n\nmy_list = [1, 2]\nchange_list(my_list)\nprint(my_list)           # [1, 2, 99] — changed!\n\nmy_num = 10\nchange_number(my_num)\nprint(my_num)            # 10 — unchanged\n\n# ── Q: Argument unpacking ──\ndef greet_full(first, last):\n    return f\"Hello {first} {last}\"\n\nnames = [\"Alice\", \"Smith\"]\nprint(greet_full(*names))          # Hello Alice Smith  — * unpacks list\n\ninfo = {\"first\": \"Bob\", \"last\": \"Jones\"}\nprint(greet_full(**info))          # Hello Bob Jones  — ** unpacks dict\n\n# ── Q: List comprehension vs generator ──\nlist_comp = [x**2 for x in range(1000)]    # creates entire list in memory\ngenerator = (x**2 for x in range(1000))    # lazy — computes one at a time\nprint(type(list_comp))  # <class 'list'>\nprint(type(generator))  # <class 'generator'>\n\n# ── Q: Walrus operator := (3.8+) ──\ndata = [1, 2, 3, 4, 5, 6, 7, 8]\nresults = [y for x in data if (y := x ** 2) > 10]\nprint(results)  # [16, 25, 36, 49, 64]", "reference": ""}, "03-decorators.py": {"content": "# ══════════════════════════════════════════════════════════════════\n#  PYTHON DECORATORS — Condensed Guide\n#  @decorator is shortcut for: func = decorator(func)\n#  FastAPI's @app.get(\"/path\") is a decorator factory!\n# ══════════════════════════════════════════════════════════════════\nimport time, functools\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  BEGINNER                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. Functions Are Objects ─────────────────────────────\ndef greet(): return \"Hello!\"\nmy_func = greet            # no parens = reference, not call\nprint(my_func())           # Hello!\n\ndef call_twice(func):\n    print(func())\n    print(func())\ncall_twice(greet)          # prints \"Hello!\" twice\n\n# ── 2. Closures — Functions That Return Functions ────────\ndef make_greeter(name):\n    def greeter():\n        return f\"Hello, {name}!\"   # \"remembers\" name from outer scope\n    return greeter\n\nprint(make_greeter(\"Alice\")())  # Hello, Alice!\nprint(make_greeter(\"Bob\")())    # Hello, Bob!\n\n# ── 3. Simplest Decorator ───────────────────────────────\n# @my_decorator is EXACTLY: say_hello = my_decorator(say_hello)\ndef my_decorator(func):\n    def wrapper():\n        print(\"BEFORE\")\n        result = func()\n        print(\"AFTER\")\n        return result\n    return wrapper\n\n@my_decorator\ndef say_hello():\n    print(\"Hello!\")\n    return \"done\"\nsay_hello()  # BEFORE -> Hello! -> AFTER\n\nprint(\"=\" * 50)\n# ╔══════════════════════════════════════════════════╗\n# ║               INTERMEDIATE                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 4. Decorator with *args, **kwargs ────────────────────\ndef log_call(func):\n    def wrapper(*args, **kwargs):\n        print(f\"Calling {func.__name__}({args}, {kwargs})\")\n        return func(*args, **kwargs)\n    return wrapper\n\n@log_call\ndef add(a, b): return a + b\nprint(add(3, 5))  # Calling add((3, 5), {}) -> 8\n\n# ── 5. Decorator Factory (WITH Parameters) ──────────────\n# THREE nesting levels: outer(params) -> decorator(func) -> wrapper(*args)\n# THIS IS HOW @app.get(\"/path\") WORKS!\ndef repeat(times):\n    def decorator(func):\n        def wrapper(*args, **kwargs):\n            for _ in range(times):\n                result = func(*args, **kwargs)\n            return result\n        return wrapper\n    return decorator\n\n@repeat(times=3)\ndef say_hi(name): print(f\"Hi {name}!\")\nsay_hi(\"Alice\")  # prints \"Hi Alice!\" three times\n# Equivalent: say_hi = repeat(3)(say_hi)\n\n# ── 6. functools.wraps — Preserve Metadata ──────────────\ndef bad_dec(func):                           # without wraps:\n    def wrapper(*a, **kw): return func(*a, **kw)\n    return wrapper\ndef good_dec(func):                          # with wraps:\n    @functools.wraps(func)\n    def wrapper(*a, **kw): return func(*a, **kw)\n    return wrapper\n\n@bad_dec\ndef func_bad(): \"\"\"My docstring\"\"\"\n@good_dec\ndef func_good(): \"\"\"My docstring\"\"\"\nprint(f\"Bad:  name={func_bad.__name__}, doc={func_bad.__doc__}\")    # wrapper, None\nprint(f\"Good: name={func_good.__name__}, doc={func_good.__doc__}\")  # func_good, My docstring\n\n# ── 7. Stacking Decorators ──────────────────────────────\n# @A / @B / def f  ≡  f = A(B(f))  — bottom-up wrap, top-down execute\ndef bold(f):\n    def w(*a, **kw): return f\"<b>{f(*a, **kw)}</b>\"\n    return w\ndef italic(f):\n    def w(*a, **kw): return f\"<i>{f(*a, **kw)}</i>\"\n    return w\n\n@bold     # outer\n@italic   # inner\ndef format_text(text): return text\nprint(format_text(\"Hello\"))  # <b><i>Hello</i></b>\n\n# ── 8. Timer Decorator ──────────────────────────────────\ndef timer(func):\n    @functools.wraps(func)\n    def wrapper(*args, **kwargs):\n        start = time.time()\n        result = func(*args, **kwargs)\n        print(f\"{func.__name__} took {time.time() - start:.4f}s\")\n        return result\n    return wrapper\n\n@timer\ndef slow_function():\n    time.sleep(0.5)\n    return \"done\"\nslow_function()  # slow_function took 0.50XXs\n\n# ── 9. Retry Decorator ──────────────────────────────────\ndef retry(max_attempts=3):\n    def decorator(func):\n        @functools.wraps(func)\n        def wrapper(*args, **kwargs):\n            for attempt in range(1, max_attempts + 1):\n                try: return func(*args, **kwargs)\n                except Exception as e:\n                    if attempt == max_attempts: raise\n                    print(f\"  Attempt {attempt} failed: {e}\")\n        return wrapper\n    return decorator\n\n_attempt = 0\n@retry(max_attempts=3)\ndef unreliable_api():\n    global _attempt; _attempt += 1\n    if _attempt < 3: raise ConnectionError(\"Server down\")\n    return \"Success!\"\n_attempt = 0\nprint(unreliable_api())  # fails twice, succeeds on third\n\n# ── 10. Cache / Memoize ─────────────────────────────────\ndef cache(func):\n    stored = {}\n    @functools.wraps(func)\n    def wrapper(*args):\n        if args not in stored: stored[args] = func(*args)\n        return stored[args]\n    return wrapper\n\n@cache\ndef expensive_multiply(a, b): return a * b\nprint(expensive_multiply(3, 4))  # computes -> 12\nprint(expensive_multiply(3, 4))  # cached   -> 12\n\n# ── 11. Auth / Role Check ───────────────────────────────\ncurrent_user = {\"name\": \"Alice\", \"role\": \"admin\"}\ndef require_role(role):\n    def decorator(func):\n        @functools.wraps(func)\n        def wrapper(*args, **kwargs):\n            if current_user[\"role\"] != role:\n                return f\"ACCESS DENIED: need {role}, have {current_user['role']}\"\n            return func(*args, **kwargs)\n        return wrapper\n    return decorator\n\n@require_role(\"admin\")\ndef delete_data(): return \"All data deleted!\"\n@require_role(\"superadmin\")\ndef shutdown(): return \"Shutting down...\"\nprint(delete_data())  # All data deleted!\nprint(shutdown())     # ACCESS DENIED: need superadmin, have admin\nprint(\"=\" * 50)\n# ╔══════════════════════════════════════════════════╗\n# ║                  ADVANCED                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 12. Class-Based Decorator (no params) ────────────────\nclass CountCalls:  # __call__ makes instances callable -> works as decorator\n    def __init__(self, func): self.func, self.count = func, 0\n    def __call__(self, *args, **kwargs):\n        self.count += 1\n        print(f\"{self.func.__name__} called {self.count} time(s)\")\n        return self.func(*args, **kwargs)\n\n@CountCalls  # say_wow = CountCalls(say_wow)\ndef say_wow(): return \"Wow!\"\nsay_wow(); say_wow()  # called 1 time(s) / called 2 time(s)\n\n# ── 13. Class-Based Decorator WITH Parameters ───────────\nclass RateLimit:\n    def __init__(self, max_calls):\n        self.max_calls = max_calls\n    def __call__(self, func):\n        call_count = {\"n\": 0}\n        def wrapper(*args, **kwargs):\n            call_count[\"n\"] += 1\n            if call_count[\"n\"] > self.max_calls:\n                return f\"RATE LIMITED! Max {self.max_calls} calls\"\n            return func(*args, **kwargs)\n        return wrapper\n\n@RateLimit(max_calls=2)\ndef get_secret(): return \"The secret is 42\"\nprint(get_secret())  # The secret is 42\nprint(get_secret())  # The secret is 42\nprint(get_secret())  # RATE LIMITED! Max 2 calls\n\n# ── 14. Validation Decorator ────────────────────────────\ndef validate_positive(func):\n    @functools.wraps(func)\n    def wrapper(*args, **kw):\n        for a in args:\n            if isinstance(a, (int, float)) and a < 0:\n                raise ValueError(f\"Negative not allowed: {a}\")\n        return func(*args, **kw)\n    return wrapper\n\n@validate_positive\ndef calculate_area(w, h): return w * h\nprint(calculate_area(5, 10))  # 50\ntry: calculate_area(-3, 10)\nexcept ValueError as e: print(f\"Error: {e}\")  # Negative not allowed: -3\n\n# ── 15. FastAPI @app.get() Pattern — Full Simulation ────\n# Class stores routes dict; .get()/.post() are decorator factories\nclass SimpleAPI:\n    def __init__(self):\n        self.routes = {\"GET\": {}, \"POST\": {}, \"PUT\": {}, \"DELETE\": {}}\n    def _register(self, method, path):\n        def decorator(func):\n            self.routes[method][path] = func\n            return func\n        return decorator\n    def get(self, path):    return self._register(\"GET\", path)\n    def post(self, path):   return self._register(\"POST\", path)\n    def put(self, path):    return self._register(\"PUT\", path)\n    def delete(self, path): return self._register(\"DELETE\", path)\n    def request(self, method, path, **kwargs):\n        m = method.upper()\n        if m in self.routes and path in self.routes[m]:\n            return self.routes[m][path](**kwargs)\n        return {\"error\": f\"{m} {path} not found\"}\n\napi = SimpleAPI()\n\n@api.get(\"/users\")\ndef list_users(): return [{\"id\": 1, \"name\": \"Alice\"}, {\"id\": 2, \"name\": \"Bob\"}]\n@api.post(\"/users\")\ndef create_user(name=\"Unknown\"): return {\"id\": 3, \"name\": name, \"created\": True}\n@api.delete(\"/users/1\")\ndef delete_user(): return {\"id\": 1, \"deleted\": True}\n\nprint(\"GET /users   ->\", api.request(\"GET\", \"/users\"))\nprint(\"POST /users  ->\", api.request(\"POST\", \"/users\", name=\"Charlie\"))\nprint(\"DELETE       ->\", api.request(\"DELETE\", \"/users/1\"))\nprint(\"GET /unknown ->\", api.request(\"GET\", \"/unknown\"))\n\n# ╔══════════════════════════════════════════════════╗", "cheatSheet": "# ║                 CHEAT SHEET                      ║\n# ╚══════════════════════════════════════════════════╝\n#\n# PATTERN                    STRUCTURE                          USE CASE\n# ─────────────────────────  ─────────────────────────────────  ────────────────\n# Simple decorator           def dec(func):                     logging, timing\n#   @dec / def f               def wrapper(*a,**kw): ...\n#                              return wrapper\n#\n# Decorator factory          def factory(param):                auth, retry\n#   @factory(param)             def dec(func):\n#   def f                         def wrapper(*a,**kw): ...\n#                                 return wrapper\n#                               return dec\n#\n# Class decorator            class Dec:                         counting, state\n#   @Dec / def f               __init__(self, func)\n#                              __call__(self, *a, **kw)\n#\n# Class factory              class Dec:                         rate limiting\n#   @Dec(param)                __init__(self, param)\n#   def f                      __call__(self, func) -> wrapper\n#\n# @app.get(\"/path\")          class App:                         route registration\n#   (FastAPI)                   def get(self, path):\n#                                 def dec(func):\n#                                   routes[path] = func\n#                                 return dec\n#\n# KEY RULES:\n#   @A / @B / def f  ->  f = A(B(f))  ->  bottom-up wrap, top-down execute\n#   Always use @functools.wraps(func) to preserve __name__ and __doc__\n#   @decorator vs @decorator() — parens mean factory (extra nesting level)\n\n# ╔══════════════════════════════════════════════════╗\n# ║          INTERVIEW GOTCHAS                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── Q: What does @decorator actually do? ──\n# @my_decorator         is EXACTLY the same as:\n# def say_hello(): ...  say_hello = my_decorator(say_hello)\n\n# ── Q: Why use functools.wraps? ──\ndef bad_dec(func):\n    def wrapper(*args, **kwargs):\n        return func(*args, **kwargs)\n    return wrapper\n\ndef good_dec(func):\n    @functools.wraps(func)          # preserves original function's metadata\n    def wrapper(*args, **kwargs):\n        return func(*args, **kwargs)\n    return wrapper\n\n@bad_dec\ndef foo2(): \"I am foo\"\n\n@good_dec\ndef bar2(): \"I am bar\"\n\nprint(foo2.__name__)   # \"wrapper\"  — lost original name!\nprint(bar2.__name__)   # \"bar2\"     — preserved by @wraps\n\n# ── Q: Decorator with arguments — 3 levels of nesting ──\ndef repeat(times):                 # decorator FACTORY — returns decorator\n    def decorator(func):\n        @functools.wraps(func)\n        def wrapper(*args, **kwargs):\n            for _ in range(times):\n                result = func(*args, **kwargs)\n            return result\n        return wrapper\n    return decorator\n\n@repeat(3)             # repeat(3) returns the actual decorator\ndef say_hi():\n    print(\"Hi!\")\n\nsay_hi()                # prints \"Hi!\" 3 times", "reference": ""}, "04-annotations.py": {"content": "# ══════════════════════════════════════════════════════════════════\n#  PYTHON ANNOTATIONS & TYPE HINTS — Condensed Guide\n#  Annotations = metadata labels on variables/functions\n#  Python does NOT enforce them — they are HINTS only\n#  But frameworks (FastAPI, Pydantic, dataclasses) READ them at runtime\n# ══════════════════════════════════════════════════════════════════\n\nfrom __future__ import annotations  # makes all annotations lazy strings (3.7+)\nimport typing, functools, operator\nfrom typing import (\n    Optional, Union, Any, Callable, Literal, TypeAlias,\n    TypedDict, Annotated, TypeVar, Protocol, runtime_checkable,\n    Final, final, ClassVar, NamedTuple, NotRequired, Sized, get_type_hints,\n)\nfrom dataclasses import dataclass, field\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  BEGINNER                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. Basic Function Annotations ──────────────────\n# param: Type → annotate parameter  |  -> Type → annotate return\n# Stored in func.__annotations__  |  Python IGNORES them — no enforcement!\ndef greet(name: str) -> str:\n    return f\"Hello, {name}!\"\nprint(greet(\"Alice\"))   # Hello, Alice!\nprint(greet(123))       # Hello, 123!  — no error, annotations aren't enforced\nprint(greet.__annotations__)  # {'name': <class 'str'>, 'return': <class 'str'>}\n\ndef add(a: int, b: int) -> int:\n    return a + b\nprint(add(\"hello\", \" world\"))  # works fine — Python doesn't care\n\n# ── 2. Variable Annotations (3.6+) ─────────────────\n# variable: Type = value — just a label, no validation\nname: str = \"Alice\"\nage: int = 30\nprice: float = 9.99\nactive: bool = True\nwrong: int = \"this is a string\"  # no error! annotation is just a hint\nfuture_value: int  # declares \"will exist\" — but variable doesn't exist yet\n# print(future_value)  # NameError! annotation alone doesn't create it\n\n# ── 3. Collection Type Annotations ─────────────────\n# 3.9+: list[int], dict[str, int], tuple[int, str], set[str]\n# 3.8:  List[int], Dict[str, int] (from typing — avoid in new code)\ndef sum_scores(scores: list[int]) -> int:        return sum(scores)\ndef get_config() -> dict[str, str]:              return {\"host\": \"localhost\", \"port\": \"8000\"}\ndef get_point() -> tuple[int, int]:              return (10, 20)\ndef group_scores() -> dict[str, list[int]]:      return {\"math\": [90, 85]}  # nested\nprint(sum_scores([10, 20, 30]))  # 60\nprint(get_point())               # (10, 20)\n\n# ╔══════════════════════════════════════════════════╗\n# ║               INTERMEDIATE                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 4. Optional — value can be X or None ───────────\n# Optional[str] == str | None (3.10+ pipe syntax)\ndef find_user(user_id: int) -> Optional[dict]:     # old style\n    return {1: {\"name\": \"Alice\"}}.get(user_id)\ndef find_item(item_id: int) -> dict | None:        # 3.10+ style (same thing)\n    return {1: {\"name\": \"Laptop\"}}.get(item_id)\ndef greet_user(name: str, title: Optional[str] = None) -> str:\n    return f\"Hello, {title + ' ' if title else ''}{name}!\"\nprint(find_user(1))    # {'name': 'Alice'}\nprint(find_user(99))   # None\n\n# ── 5. Union — one of several types ────────────────\n# Union[str, int] == str | int (3.10+)\ndef format_id(user_id: Union[str, int]) -> str:    # old style\n    return f\"USER-{user_id}\"\ndef flexible(value: str | int | float) -> str:     # 3.10+ style\n    return str(value)\nprint(format_id(42))     # USER-42\nprint(format_id(\"abc\"))  # USER-abc\n\n# ── 6. Any — accept anything ──────────────────────\n# Use sparingly — defeats purpose of type hints\ndef log_value(value: Any) -> str:\n    return f\"Logged: {value} ({type(value).__name__})\"\nprint(log_value([1, 2]))  # Logged: [1, 2] (list)\n\n# ── 7. Callable — functions as parameters ──────────\n# Callable[[param_types], return_type]\ndef apply(func: Callable[[int, int], int], a: int, b: int) -> int:\n    return func(a, b)\nprint(apply(lambda x, y: x * y, 3, 5))  # 15\n\ndef run_task(task: Callable[[], str]) -> str:      return task()      # no-arg callable\ndef execute(func: Callable[..., Any]) -> Any:      return func()      # any-arg callable\n\n# Callback pattern\ndef fetch_data(url: str, on_success: Callable[[dict], None]) -> None:\n    on_success({\"url\": url, \"status\": 200})\nfetch_data(\"https://api.com\", on_success=lambda d: print(f\"  Got: {d}\"))\n\n# ── 8. Literal — restrict to specific values ──────\n# Like an enum but simpler — type checkers enforce it\ndef set_color(color: Literal[\"red\", \"green\", \"blue\"]) -> str:\n    return f\"Color: {color}\"\ndef set_priority(level: Literal[1, 2, 3]) -> str:\n    return {1: \"High\", 2: \"Medium\", 3: \"Low\"}.get(level, \"Unknown\")\nprint(set_color(\"red\"))       # Color: red\nprint(set_color(\"purple\"))    # runs fine — but mypy flags it\nprint(set_priority(1))        # High\n\n# ── 9. TypeAlias — name complex types ─────────────\nUserRecord: TypeAlias = dict[str, list[tuple[int, str]]]\nJSON: TypeAlias = dict[str, Any]\nHeaders: TypeAlias = dict[str, str]\nCoordinates: TypeAlias = tuple[float, float]\n\ndef make_request(url: str, headers: Headers) -> JSON:\n    return {\"url\": url, \"headers\": headers}\ndef distance(p1: Coordinates, p2: Coordinates) -> float:\n    return ((p2[0]-p1[0])**2 + (p2[1]-p1[1])**2) ** 0.5\nprint(distance((0, 0), (3, 4)))  # 5.0\n\n# ── 10. TypedDict — typed dictionary structure ─────\n# Regular dict[str, Any] doesn't specify which keys exist\nclass UserDict(TypedDict):\n    name: str\n    age: int\n    email: str\n\nclass Config(TypedDict, total=False):   # all keys optional\n    host: str\n    port: int\n\nclass APIResponse(TypedDict):\n    status: int                         # required\n    data: dict                          # required\n    error: NotRequired[str]             # optional\n\ndef create_user() -> UserDict:\n    return {\"name\": \"Alice\", \"age\": 30, \"email\": \"alice@test.com\"}\nprint(create_user())  # {'name': 'Alice', 'age': 30, 'email': 'alice@test.com'}\n\n# ── 11. Annotated — attach metadata to types ──────\n# Annotated[Type, metadata...] — Python ignores metadata, frameworks read it\n# THIS is how FastAPI reads validation rules\ndef create_item(\n    name: Annotated[str, \"Item name, max 100 chars\"],\n    price: Annotated[float, \"Price in USD, > 0\"],\n) -> dict:\n    return {\"name\": name, \"price\": price}\nprint(create_item(\"Laptop\", 999.99))  # {'name': 'Laptop', 'price': 999.99}\n\n# FastAPI usage (not runnable without FastAPI):\n# @app.get(\"/items\")\n# def get_items(\n#     q: Annotated[str, Query(min_length=3, max_length=50)],\n#     skip: Annotated[int, Query(ge=0)] = 0,\n#     limit: Annotated[int, Query(le=100)] = 10,\n# ): ...\n# FastAPI reads Query() from Annotated → enforces validation + generates docs\n\n# Annotated with operator.add — used by LangGraph to MERGE state fields\n# In LangGraph, Annotated[list[str], operator.add] means:\n# \"When updating this field, APPEND new items instead of replacing the list\"\n# Without it: new_state = [\"c\"]           → field becomes [\"c\"]\n# With it:    new_state = [\"c\"]           → field becomes [\"a\", \"b\", \"c\"]\nfrom dataclasses import dataclass as dc\n\n@dc\nclass ChatState:\n    messages: Annotated[list[str], operator.add] = field(default_factory=list)\n    context: Annotated[list[str], operator.add] = field(default_factory=list)\n    final_answer: str = \"\"    # no reducer → plain overwrite\n\nstate = ChatState(messages=[\"Hello\"], context=[\"doc1\"])\n# Simulating what LangGraph does internally when a node returns a partial update:\nupdate = {\"messages\": [\"How are you?\"], \"context\": [\"doc2\", \"doc3\"]}\n# LangGraph sees operator.add in the annotation → calls operator.add(old, new)\nmerged_messages = operator.add(state.messages, update[\"messages\"])\nmerged_context = operator.add(state.context, update[\"context\"])\nprint(f\"Merged messages: {merged_messages}\")  # ['Hello', 'How are you?']\nprint(f\"Merged context: {merged_context}\")    # ['doc1', 'doc2', 'doc3']\n# Without operator.add, update[\"messages\"] would REPLACE state.messages entirely\n\n# operator.add works because list.__add__ concatenates:\nprint(operator.add([1, 2], [3, 4]))  # [1, 2, 3, 4]\n# Other reducers you could use: operator.or_ (sets), custom functions, etc.\n\n# Custom metadata class — access at runtime\nclass Range:\n    def __init__(self, min_val: int, max_val: int):\n        self.min_val, self.max_val = min_val, max_val\n    def __repr__(self): return f\"Range({self.min_val}, {self.max_val})\"\n\ndef set_volume(level: Annotated[int, Range(0, 100)]) -> str:\n    return f\"Volume: {level}\"\nhints = get_type_hints(set_volume, include_extras=True)\nprint(hints)  # {'level': typing.Annotated[int, Range(0, 100)], ...}\n\n# ── 12. Class Annotations ─────────────────────────\nclass User:\n    name: str\n    age: int\n    def __init__(self, name: str, age: int) -> None:\n        self.name, self.age = name, age\n    def greet(self) -> str:\n        return f\"Hi, I'm {self.name}, age {self.age}\"\nprint(User(\"Alice\", 30).greet())   # Hi, I'm Alice, age 30\nprint(User.__annotations__)        # {'name': <class 'str'>, 'age': <class 'int'>}\n\n# ── 13. dataclass — annotations create real attributes ──\n# @dataclass reads annotations → auto-generates __init__, __repr__, __eq__\n@dataclass\nclass Product:\n    name: str                                       # required\n    price: float                                    # required\n    quantity: int = 0                               # optional with default\n    tags: list[str] = field(default_factory=list)   # mutable default\nprint(Product(\"Laptop\", 999.99, 5, [\"tech\"]))  # Product(name='Laptop', ...)\nprint(Product(\"Mouse\", 25.0))                   # Product(name='Mouse', price=25.0, ...)\n\n@dataclass(frozen=True)    # immutable — Point(3,4).x = 5 → FrozenInstanceError\nclass Point:\n    x: float\n    y: float\n\n@dataclass\nclass Rectangle:\n    width: float\n    height: float\n    area: float = field(init=False)   # computed, not in __init__\n    def __post_init__(self) -> None:\n        self.area = self.width * self.height\nprint(Rectangle(5.0, 3.0))  # Rectangle(width=5.0, height=3.0, area=15.0)\n\n# ── 14. NamedTuple with annotations ───────────────\nclass Coordinate(NamedTuple):\n    x: float\n    y: float\n    label: str = \"origin\"\nc = Coordinate(3.0, 4.0, \"A\")\nprint(c.x, c.label)       # 3.0 A\nx, y, label = c           # unpack like a tuple — immutable (c.x = 10 → error)\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  ADVANCED                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 15. TypeVar — generic type placeholders ────────\n# \"T\" = whatever type the caller passes — keeps input/output consistent\nT = TypeVar(\"T\")\ndef first(items: list[T]) -> T:    # type checker knows first([1,2]) returns int\n    return items[0]\nprint(first([1, 2, 3]))     # 1 (int → int)\nprint(first([\"a\", \"b\"]))    # a (str → str)\n\nNumber = TypeVar(\"Number\", int, float)     # constrained — only int or float\ndef double(n: Number) -> Number:\n    return n * 2\n\nS = TypeVar(\"S\", bound=Sized)              # bounded — must have __len__\ndef get_length(item: S) -> int:\n    return len(item)\nprint(double(5))           # 10\nprint(get_length(\"hello\")) # 5\n\n# ── 16. Protocol — structural typing (duck typing) ─\n# \"Any object with these methods works\" — no inheritance needed\n@runtime_checkable\nclass Printable(Protocol):\n    def to_string(self) -> str: ...\n\nclass UserP:\n    def __init__(self, n: str): self.name = n\n    def to_string(self) -> str: return f\"User({self.name})\"\n\nclass ProductP:\n    def __init__(self, n: str, p: float): self.name, self.price = n, p\n    def to_string(self) -> str: return f\"Product({self.name}, ${self.price})\"\n\ndef display(item: Printable) -> None:\n    print(item.to_string())\ndisplay(UserP(\"Alice\"))      # User(Alice) — matches Protocol, no inheritance\ndisplay(ProductP(\"Laptop\", 999))\nprint(isinstance(UserP(\"Bob\"), Printable))  # True (runtime_checkable)\n\n# ── 17. Final — constants & non-overridable ────────\nMAX_RETRIES: Final[int] = 3\nAPI_URL: Final[str] = \"https://api.example.com\"\nPI: Final = 3.14159          # type inferred\n# MAX_RETRIES = 5  → mypy error: Cannot assign to final name\n\nclass Base:\n    @final\n    def critical(self) -> str:  # subclass can't override\n        return \"Don't override me\"\n\n# ── 18. ClassVar — class-level, not in __init__ ────\n@dataclass\nclass Employee:\n    name: str\n    salary: float\n    company: ClassVar[str] = \"Reuters\"     # shared, NOT in __init__\n    count: ClassVar[int] = 0\n    def __post_init__(self) -> None:\n        Employee.count += 1\ne1, e2 = Employee(\"Alice\", 90000), Employee(\"Bob\", 85000)\nprint(f\"Company: {Employee.company}, Count: {Employee.count}\")  # Reuters, 2\n\n# ── 19. get_type_hints() — runtime inspection ─────\n# Better than __annotations__ — resolves forward refs\ndef process(name: str, age: int, scores: list[float]) -> dict[str, Any]:\n    return {\"name\": name, \"age\": age, \"avg\": sum(scores) / len(scores)}\nhints = get_type_hints(process)\nprint(hints)  # {'name': str, 'age': int, 'scores': list[float], 'return': dict[str, Any]}\n\n# Auto-validate using annotations\ndef validate(func: Callable, **kwargs: Any) -> dict[str, bool]:\n    hints = get_type_hints(func)\n    return {k: isinstance(kwargs[k], v) for k, v in hints.items()\n            if k != \"return\" and k in kwargs}\nprint(validate(process, name=\"Alice\", age=30, scores=[90.0]))  # all True\nprint(validate(process, name=\"Alice\", age=\"thirty\"))           # age: False\n\n# ── 20. Forward References ────────────────────────\n# Use \"ClassName\" string when type isn't defined yet\n# Or: from __future__ import annotations (top of file) — makes ALL lazy\nclass TreeNode:\n    def __init__(self, val: int, children: list[TreeNode] | None = None):\n        self.val, self.children = val, children or []\n    def __repr__(self) -> str:\n        return f\"Tree({self.val}{', ' + repr(self.children) if self.children else ''})\"\ntree = TreeNode(1, [TreeNode(2), TreeNode(3, [TreeNode(4)])])\nprint(tree)  # Tree(1, [Tree(2), Tree(3, [Tree(4)])])\n\n# ── 21. Framework Usage Comparison ────────────────\n# Pure Python — annotations IGNORED, no enforcement\n# dataclass — annotations → auto __init__, __repr__, __eq__\n# FastAPI — reads annotations for validation, conversion, docs generation\n# Pydantic — ENFORCES types + auto-converts at runtime\n\n# FastAPI (pseudocode):\n# @app.get(\"/items/{item_id}\")\n# def get_item(\n#     item_id: int,                              # path param, auto-convert\n#     skip: Annotated[int, Query(ge=0)] = 0,     # query param, validated\n# ): ...\n\ntry:\n    from pydantic import BaseModel, ValidationError\n    class UserModel(BaseModel):\n        name: str\n        age: int\n        active: bool = True\n    print(UserModel(name=\"Alice\", age=\"25\"))      # auto-converts \"25\" → 25\n    try:\n        UserModel(name=\"X\", age=\"not a number\")\n    except ValidationError as e:\n        print(f\"  Pydantic caught {e.error_count()} error(s)\")\nexcept ImportError:\n    print(\"  (pydantic not installed)\")\n\n# ── 22. mypy — Static Type Checking ──────────────\n# pip install mypy && mypy file.py — catches bugs without running code\n# pyright is a faster alternative. IDEs (VSCode/PyCharm) check in real-time.\n\n# ── 23. Decorator Preserving Annotations ─────────\ndef logged(func: Callable[..., T]) -> Callable[..., T]:\n    @functools.wraps(func)\n    def wrapper(*args: Any, **kwargs: Any) -> T:\n        return func(*args, **kwargs)\n    return wrapper\n\n@logged\ndef compute(x: int, y: int) -> int:\n    return x + y\nprint(f\"Result: {compute(3, 5)}, name: {compute.__name__}\")  # 8, compute", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n#  CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\n#  SYNTAX:\n#    param: Type              annotate parameter\n#    -> Type                  annotate return value\n#    var: Type = value        annotate variable\n#    func.__annotations__    raw annotation dict\n#    get_type_hints(func)    resolved (handles forward refs)\n#\n#  BASIC TYPES:\n#    str, int, float, bool               primitives\n#    list[int], dict[str, Any]           collections (3.9+)\n#    tuple[int, str], set[str]           fixed tuple, set\n#    List[int], Dict[str, int]           old style (typing, 3.8)\n#\n#  TYPING MODULE:\n#    Optional[X]         X | None             value or None\n#    Union[X, Y]         X | Y  (3.10+)       one of several types\n#    Any                                       no restriction\n#    Literal[\"a\",\"b\"]                          specific values only\n#    Callable[[args], ret]                     function type\n#    TypeAlias            = complex_type       readable name\n#    TypedDict                                 dict with typed keys\n#    Annotated[X, meta]                        type + framework metadata\n#    TypeVar(\"T\")                              generic placeholder\n#    Protocol                                  structural/duck typing\n#    Final[X]                                  constant, don't reassign\n#    ClassVar[X]                               class-level, not instance\n#    NamedTuple                                typed immutable tuple\n#\n#  FORWARD REFS:\n#    \"ClassName\"                        use type before definition\n#    from __future__ import annotations auto-stringify all\n#\n#  WHO READS ANNOTATIONS:\n#    Pure Python  → IGNORED (just labels)\n#    dataclass    → creates __init__, __repr__, __eq__\n#    FastAPI      → validates, converts, generates docs\n#    Pydantic     → enforces types, auto-converts\n#    mypy/pyright → static checking (no runtime)\n# ══════════════════════════════════════════════════════════════════\n\n# ╔══════════════════════════════════════════════════╗\n# ║          INTERVIEW GOTCHAS                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── Q: Do type hints enforce types? ──\ndef add_nums(a: int, b: int) -> int:\n    return a + b\n\nprint(add_nums(\"hello\", \" world\"))   # \"hello world\" — NO ERROR\n# Python IGNORES annotations. Only mypy/pyright catch this.\n\n# ── Q: Optional vs Union vs | — what's the difference? ──\n# Optional[str]    ==  str | None       (3.10+)\n# Union[str, int]  ==  str | int        (3.10+)\n# They are the SAME thing — | is just shorter syntax\n\n# ── Q: When does Python actually READ annotations? ──\n# Pure Python  → IGNORES them\n# dataclass    → reads them to create __init__, __repr__, __eq__\n# FastAPI      → reads them for validation, conversion, docs\n# Pydantic     → reads AND enforces at runtime\n# mypy/pyright → checks at edit/compile time (not runtime)", "reference": ""}, "05-oops.py": {"content": "# ══════════════════════════════════════════════════════════════════\n# PYTHON OOP — Complete Guide (Condensed)\n#\n# Class = blueprint/template  |  Object = instance from a class\n# 4 Pillars: Encapsulation, Inheritance, Polymorphism, Abstraction\n# ══════════════════════════════════════════════════════════════════\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  BEGINNER                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. Basic Class & Object ──────────────────────────────\nclass Car:\n    def __init__(self, brand, color):  # constructor\n        self.brand = brand             # instance variable\n        self.color = color\n    def describe(self):\n        return f\"{self.color} {self.brand}\"\n\ncar1, car2 = Car(\"Toyota\", \"Red\"), Car(\"Honda\", \"Blue\")\nprint(car1.describe())  # Red Toyota\ncar1.color = \"Black\"\nprint(car1.describe())  # Black Toyota  (car2 unchanged — separate objects)\n\n# ── 2. Instance vs Class Variables ──────────────────────────────\nclass Employee:\n    company = \"Reuters\"    # class var — shared by ALL instances\n    count = 0\n    def __init__(self, name, salary):\n        self.name = name   # instance var — unique per object\n        self.salary = salary\n        Employee.count += 1\n\nemp1, emp2 = Employee(\"Alice\", 50000), Employee(\"Bob\", 60000)\nprint(emp1.name, emp2.name)       # Alice Bob  (instance — different)\nprint(emp1.company, emp2.company) # Reuters Reuters  (class — same)\nprint(Employee.count)             # 2\n\n# ── 3. Methods: Instance vs Class vs Static ──────────────────────────────\n#  instance  — def method(self)     works on ONE object\n#  class     — @classmethod         works on the CLASS (cls), alt constructors\n#  static    — @staticmethod        utility, no self/cls\nclass Pizza:\n    base_price = 10\n    def __init__(self, size, toppings):\n        self.size, self.toppings = size, toppings\n    def get_price(self):                          # instance method\n        return Pizza.base_price + len(self.toppings) * 2\n    @classmethod\n    def set_base_price(cls, price):               # class method\n        cls.base_price = price\n    @classmethod\n    def margherita(cls):                           # alt constructor\n        return cls(\"Medium\", [\"cheese\", \"tomato\"])\n    @staticmethod\n    def is_valid_size(size):                       # static\n        return size in [\"Small\", \"Medium\", \"Large\"]\n\np1 = Pizza(\"Large\", [\"cheese\", \"mushroom\", \"olive\"])\nprint(p1.get_price())              # 16  (10 + 3*2)\nPizza.set_base_price(12)\nprint(p1.get_price())              # 18  (12 + 3*2) — changed for ALL\nprint(Pizza.margherita().toppings) # ['cheese', 'tomato']\nprint(Pizza.is_valid_size(\"Huge\")) # False\n\n# ── 4. Encapsulation & Property ──────────────────────────────\n#  public    name    — anyone can access\n#  protected _name   — convention: \"internal use\"\n#  private   __name  — name-mangled to _ClassName__name\n#  @property         — getter/setter/deleter as attribute syntax\nclass BankAccount:\n    def __init__(self, owner, balance):\n        self.owner = owner        # public\n        self._bank = \"Chase\"      # protected (convention)\n        self.__balance = balance   # private (mangled)\n    @property\n    def balance(self):\n        return self.__balance\n    @balance.setter\n    def balance(self, amount):\n        if amount < 0: raise ValueError(\"Balance cannot be negative\")\n        self.__balance = amount\n    def deposit(self, amount):\n        if amount > 0: self.__balance += amount\n        return self.__balance\n\nacc = BankAccount(\"Alice\", 1000)\nprint(acc.owner)                    # Alice  (public)\nprint(acc._bank)                    # Chase  (protected — works but discouraged)\n# print(acc.__balance)              # AttributeError!\nprint(acc._BankAccount__balance)    # 1000  (name mangling — not recommended)\nprint(acc.balance)                  # 1000  (property getter)\nacc.balance = 2000                  # property setter\nprint(acc.deposit(500))             # 2500\ntry:\n    acc.balance = -500\nexcept ValueError as e:\n    print(f\"Error: {e}\")            # Balance cannot be negative\n\n# Computed properties — no stored value\nclass Temperature:\n    def __init__(self, celsius): self._celsius = celsius\n    @property\n    def fahrenheit(self):       return (self._celsius * 9/5) + 32\n    @fahrenheit.setter\n    def fahrenheit(self, v):    self._celsius = (v - 32) * 5/9\n\ntemp = Temperature(100)\nprint(temp.fahrenheit)   # 212.0\ntemp.fahrenheit = 32\nprint(temp._celsius)     # 0.0\n\n# ╔══════════════════════════════════════════════════╗\n# ║                INTERMEDIATE                      ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 5. Inheritance — Single ──────────────────────────────\nclass Animal:\n    def __init__(self, name, sound):\n        self.name, self.sound = name, sound\n    def speak(self):  return f\"{self.name} says {self.sound}!\"\n    def info(self):   return f\"Animal: {self.name}\"\n\nclass Dog(Animal):\n    def __init__(self, name, breed):\n        super().__init__(name, \"Woof\")  # call parent __init__\n        self.breed = breed\n    def info(self):  return f\"Dog: {self.name}, Breed: {self.breed}\"  # override\n\nclass Cat(Animal):\n    def __init__(self, name): super().__init__(name, \"Meow\")\n\ndog, cat = Dog(\"Rex\", \"Labrador\"), Cat(\"Whiskers\")\nprint(dog.speak())  # Rex says Woof!       (inherited)\nprint(dog.info())   # Dog: Rex, Breed: ... (overridden)\nprint(cat.info())   # Animal: Whiskers     (parent's)\nprint(isinstance(dog, Animal), isinstance(cat, Dog))  # True False\n\n# ── 6. Multi-Level & Multiple Inheritance ──────────────────────────────\n# Multi-level: Vehicle -> ElectricVehicle -> Tesla\nclass Vehicle:\n    def __init__(self, brand): self.brand = brand\n    def start(self): return f\"{self.brand} starting...\"\nclass ElectricVehicle(Vehicle):\n    def __init__(self, brand, bat):\n        super().__init__(brand); self.battery = bat\n    def charge(self): return f\"Charging {self.brand} ({self.battery}kWh)\"\nclass Tesla(ElectricVehicle):\n    def __init__(self, model, bat):\n        super().__init__(\"Tesla\", bat); self.model = model\n\nt = Tesla(\"Model 3\", 75)\nprint(t.start())   # Tesla starting...  (grandparent)\nprint(t.charge())  # Charging Tesla...  (parent)\nprint(Tesla.__mro__)  # Tesla -> ElectricVehicle -> Vehicle -> object\n\n# Multiple: two parents — MRO decides conflict winner\nclass Flyable:\n    def move(self): return \"Flying\"\nclass Swimmable:\n    def move(self): return \"Swimming\"\nclass Duck(Flyable, Swimmable): pass  # Flyable listed first\n\nduck = Duck()\nprint(duck.move())   # Flying  (Flyable wins — listed first)\n\n# ── 7. Polymorphism ──────────────────────────────\nclass Circle:\n    def __init__(self, r):    self.r = r\n    def area(self):           return 3.14 * self.r ** 2\nclass Rectangle:\n    def __init__(self, w, h): self.w, self.h = w, h\n    def area(self):           return self.w * self.h\nclass Triangle:\n    def __init__(self, b, h): self.b, self.h = b, h\n    def area(self):           return 0.5 * self.b * self.h\n\nfor s in [Circle(5), Rectangle(4, 6), Triangle(3, 8)]:\n    print(f\"{s.__class__.__name__} -> {s.area()}\")  # 78.5, 24, 12.0\n\n# ── 8. Abstraction — ABC ──────────────────────────────\nfrom abc import ABC, abstractmethod\n\nclass Shape(ABC):\n    @abstractmethod\n    def area(self): pass         # child MUST implement\n    @abstractmethod\n    def perimeter(self): pass\n    def description(self):        # concrete — inherited as-is\n        return f\"I am a {self.__class__.__name__}\"\n\nclass Square(Shape):\n    def __init__(self, side): self.side = side\n    def area(self):           return self.side ** 2\n    def perimeter(self):      return 4 * self.side\n\n# Shape()  # TypeError: Can't instantiate abstract class\nsq = Square(5)\nprint(sq.area(), sq.perimeter(), sq.description())  # 25 20 I am a Square\n\n# ── 9. Magic / Dunder Methods ──────────────────────────────\nclass Product:\n    def __init__(self, name, price):\n        self.name, self.price = name, price\n    def __str__(self):        return f\"{self.name}: ${self.price}\"           # print()\n    def __repr__(self):       return f\"Product('{self.name}', {self.price})\" # debug\n    def __eq__(self, other):  return self.name == other.name and self.price == other.price\n    def __lt__(self, other):  return self.price < other.price               # enables sort\n    def __add__(self, other): return Product(f\"{self.name}+{other.name}\", self.price + other.price)\n    def __len__(self):        return len(self.name)\n    def __bool__(self):       return self.price > 0\n\np1, p2 = Product(\"Laptop\", 999), Product(\"Mouse\", 25)\nprint(p1)                # Laptop: $999          (__str__)\nprint(repr(p2))          # Product('Mouse', 25)  (__repr__)\nprint(p1 == Product(\"Laptop\", 999))  # True      (__eq__)\nprint(p2 < p1)           # True  (25 < 999)      (__lt__)\nprint(p1 + p2)           # Laptop+Mouse: $1024   (__add__)\nprint(len(p1))           # 6                     (__len__)\nprint(bool(Product(\"Free\", 0)))  # False         (__bool__)\n\n# ── 10. Subscriptable Objects ──────────────────────────────\nclass Inventory:\n    def __init__(self):          self._items = {}\n    def __getitem__(self, k):    return self._items.get(k, \"Not found\")\n    def __setitem__(self, k, v): self._items[k] = v\n    def __delitem__(self, k):\n        if k in self._items: del self._items[k]\n    def __contains__(self, k):   return k in self._items\n    def __len__(self):           return len(self._items)\n    def __iter__(self):          return iter(self._items)\n\ninv = Inventory()\ninv[\"laptop\"] = 5; inv[\"mouse\"] = 20  # __setitem__\nprint(inv[\"laptop\"])      # 5     (__getitem__)\nprint(\"mouse\" in inv)     # True  (__contains__)\ndel inv[\"mouse\"]          #       (__delitem__)\nprint(len(inv))           # 1     (__len__)\n\n# ── 11. Composition — \"has a\" vs \"is a\" ──────────────────────────────\nclass Engine:\n    def __init__(self, hp): self.hp, self.running = hp, False\n    def start(self):        self.running = True; return f\"Engine ({self.hp}hp) started\"\nclass GPS:\n    def navigate(self, dest): return f\"Navigating to {dest}...\"\n\nclass MyCar:  # Car HAS an Engine + GPS (composition > inheritance)\n    def __init__(self, brand, hp):\n        self.brand, self.engine, self.gps = brand, Engine(hp), GPS()\n    def start(self):    return f\"{self.brand}: {self.engine.start()}\"\n    def go_to(self, p): return self.gps.navigate(p) if self.engine.running else \"Start first!\"\n\nmy_car = MyCar(\"BMW\", 300)\nprint(my_car.start())           # BMW: Engine (300hp) started\nprint(my_car.go_to(\"Airport\"))  # Navigating to Airport...\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  ADVANCED                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 12. Dataclass ──────────────────────────────\nfrom dataclasses import dataclass, field\n\n@dataclass\nclass User:\n    name: str; email: str; age: int\n    active: bool = True\n    tags: list = field(default_factory=list)  # mutable default\n\nu1 = User(\"Alice\", \"a@test.com\", 30)\nprint(u1)           # User(name='Alice', ...) — auto __repr__\nprint(u1 == User(\"Alice\", \"a@test.com\", 30))  # True — auto __eq__\n\n@dataclass\nclass Point:\n    x: float; y: float\n    def distance(self): return (self.x**2 + self.y**2) ** 0.5\nprint(Point(3, 4).distance())  # 5.0\n\n@dataclass(frozen=True)   # immutable — can't change after creation\nclass Color:\n    r: int; g: int; b: int\n# Color(255,0,0).r = 100  # FrozenInstanceError!\n\n# ---- WITH @dataclass (2 lines) ----\n@dataclass(order=True)    # enables <, >, sorted()\nclass Score:\n    value: int; player: str = \"\"\nprint(sorted([Score(85,\"A\"), Score(92,\"B\"), Score(78,\"C\")]))  # [78, 85, 92]\n\n# ---- WITHOUT @dataclass — same behavior, written by hand (~10 lines) ----\nclass ScoreManual:\n    def __init__(self, value, player=\"\"):\n        self.value, self.player = value, player\n    def __repr__(self):\n        return f\"ScoreManual(value={self.value!r}, player={self.player!r})\"\n    def __eq__(self, other):\n        return NotImplemented if other.__class__ is not self.__class__ \\\n            else (self.value, self.player) == (other.value, other.player)\n    def __lt__(self, other):   # order=True also needs le/gt/ge (same pattern)\n        return NotImplemented if other.__class__ is not self.__class__ \\\n            else (self.value, self.player) < (other.value, other.player)\nprint(sorted([ScoreManual(85,\"A\"), ScoreManual(92,\"B\"), ScoreManual(78,\"C\")]))\n# [ScoreManual(value=78, player='C'), ScoreManual(value=85, player='A'), ScoreManual(value=92, player='B')]\n# same sort result as Score above — @dataclass just writes ScoreManual's\n# methods for you, from the `value: int; player: str = \"\"` field list.\n\n# ── 13. __slots__ — Memory Optimization ──────────────────────────────\nclass WithSlots:\n    __slots__ = (\"x\", \"y\")  # fixed attrs — no __dict__, ~40% less memory\n    def __init__(self, x, y): self.x, self.y = x, y\n\nb = WithSlots(1, 2)\n# b.z = 3    # AttributeError! z not in __slots__\n# b.__dict__ # AttributeError — no __dict__ with slots\n\n# ── 14. Mixins — Reusable Behavior ──────────────────────────────\nimport json\n\nclass JsonMixin:\n    def to_json(self):     return json.dumps(self.__dict__, indent=2)\n    @classmethod\n    def from_json(cls, s): return cls(**json.loads(s))\n\nclass PrintableMixin:\n    def print_info(self):\n        attrs = \", \".join(f\"{k}={v}\" for k, v in self.__dict__.items())\n        print(f\"[{self.__class__.__name__}] {attrs}\")\n\nclass Article(JsonMixin, PrintableMixin):\n    def __init__(self, title, author, words=0):\n        self.title, self.author, self.words = title, author, words\n\nart = Article(\"Breaking News\", \"Alice\", 500)\nart.print_info()  # [Article] title=Breaking News, author=Alice, words=500\nArticle.from_json('{\"title\":\"Update\",\"author\":\"Bob\",\"words\":300}').print_info()\n\n# ── 15. Enum — Named Constants ──────────────────────────────\nfrom enum import Enum, auto\n\nclass Status(Enum):\n    PENDING = \"pending\"; ACTIVE = \"active\"; INACTIVE = \"inactive\"\nclass Priority(Enum):\n    LOW = auto(); MEDIUM = auto(); HIGH = auto()  # auto: 1, 2, 3\n\nprint(Status.ACTIVE.value)   # active\nprint(Priority.HIGH.value)   # 3\n\n# ── 16. Method Chaining — return self ──────────────────────────────\nclass QueryBuilder:\n    def __init__(self, table):\n        self.table, self._conds, self._order, self._limit = table, [], None, None\n    def where(self, c):   self._conds.append(c); return self\n    def order_by(self, c): self._order = c; return self\n    def limit(self, n):   self._limit = n; return self\n    def build(self):\n        q = f\"SELECT * FROM {self.table}\"\n        if self._conds: q += \" WHERE \" + \" AND \".join(self._conds)\n        if self._order: q += f\" ORDER BY {self._order}\"\n        if self._limit: q += f\" LIMIT {self._limit}\"\n        return q\n\nq = QueryBuilder(\"users\").where(\"age > 18\").where(\"active = true\").order_by(\"name\").limit(10).build()\nprint(q)  # SELECT * FROM users WHERE age > 18 AND active = true ORDER BY name LIMIT 10\n\n# ── 17. Context Manager — __enter__ / __exit__ ──────────────────────────────\nclass FileLogger:\n    def __init__(self, fn): self.fn, self.logs = fn, []\n    def __enter__(self):\n        print(f\"Logger started for {self.fn}\"); return self\n    def __exit__(self, exc_type, exc_val, exc_tb):\n        print(f\"Logger finished. {len(self.logs)} logs.\")\n        return False  # don't suppress exceptions\n    def log(self, msg):\n        self.logs.append(msg); print(f\"  LOG: {msg}\")\n\nwith FileLogger(\"app.log\") as logger:\n    logger.log(\"Started\"); logger.log(\"Logged in\")\n\n# ── 18. Singleton — Only ONE Instance ──────────────────────────────\nclass Database:\n    _instance = None\n    def __new__(cls, *args, **kwargs):\n        if cls._instance is None: cls._instance = super().__new__(cls)\n        return cls._instance\n    def __init__(self, host=\"localhost\"): self.host = host\n\ndb1, db2 = Database(\"server1\"), Database(\"server2\")\nprint(db1 is db2)  # True — same object!\nprint(db1.host)    # server2 — last __init__ overwrote\n\n# ── 19. __call__ — Callable Object ──────────────────────────────\nclass Multiplier:\n    def __init__(self, factor):  self.factor = factor\n    def __call__(self, value):   return value * self.factor\n\ndouble = Multiplier(2)\nprint(double(5))          # 10\nprint(callable(double))   # True\n\n# ── 20. Descriptor — Reusable Attribute Logic ──────────────────────────────\nclass PositiveNumber:\n    def __set_name__(self, owner, name): self.name = name\n    def __get__(self, obj, typ=None):    return getattr(obj, f\"_{self.name}\", 0)\n    def __set__(self, obj, value):\n        if value < 0: raise ValueError(f\"{self.name} must be positive, got {value}\")\n        setattr(obj, f\"_{self.name}\", value)\n\nclass Order:\n    quantity = PositiveNumber()\n    price = PositiveNumber()\n    def __init__(self, item, qty, price):\n        self.item, self.quantity, self.price = item, qty, price\n    def total(self): return self.quantity * self.price\n\norder = Order(\"Widget\", 5, 9.99)\nprint(order.total())  # 49.95\ntry:    order.quantity = -3\nexcept ValueError as e: print(f\"Error: {e}\")  # quantity must be positive\n\n# ── 21. isinstance / issubclass ──────────────────────────────\nclass Media: pass\nclass Video(Media): pass\nclass Audio(Media): pass\nclass Podcast(Audio): pass\n\nprint(isinstance(Video(), Media))      # True  — Video IS-A Media\nprint(isinstance(Podcast(), Audio))    # True  — Podcast IS-A Audio\nprint(issubclass(Podcast, Media))      # True  — Podcast -> Audio -> Media\nprint(issubclass(Video, Audio))        # False\n\n# ── 22. __init_subclass__ — Auto-Register Subclasses ──────────────────────────────\nclass Plugin:\n    registry = []\n    def __init_subclass__(cls, **kwargs):\n        super().__init_subclass__(**kwargs)\n        Plugin.registry.append(cls.__name__)\n\nclass PDFExporter(Plugin): pass\nclass CSVExporter(Plugin): pass\nclass XMLExporter(Plugin): pass\nprint(Plugin.registry)  # ['PDFExporter', 'CSVExporter', 'XMLExporter']\n\n# ╔══════════════════════════════════════════════════╗", "cheatSheet": "# ║               CHEAT SHEET                        ║\n# ╚══════════════════════════════════════════════════╝\n# CLASS BASICS:    class Foo | __init__(self) | self.x (instance) | Foo.x (class)\n# METHOD TYPES:    def m(self) instance | @classmethod def(cls) | @staticmethod def()\n# ACCESS CONTROL:  name (public) | _name (protected) | __name (private/mangled)\n# PROPERTY:        @property getter | @x.setter | @x.deleter — attr syntax\n# INHERITANCE:     class B(A) single | class C(B) multi-level | class D(A,B) multiple\n#                  super().__init__() | __mro__ resolution order\n# POLYMORPHISM:    same method name, different behavior per class\n# ABSTRACTION:     ABC + @abstractmethod — must implement in child\n# DUNDERS:         __str__ print | __repr__ debug | __eq__ == | __lt__ < (sort)\n#                  __add__ + | __len__ len() | __bool__ bool() | __call__ obj()\n#                  __getitem__ obj[k] | __setitem__ obj[k]=v | __contains__ in\n#                  __iter__ for | __enter__/__exit__ with | __new__ singleton\n#                  __init_subclass__ hook | __set_name__/__get__/__set__ descriptor\n# DATACLASS:       @dataclass auto init/repr/eq | frozen=True immutable | order=True\n# SLOTS:           __slots__=(...) no __dict__, less memory, faster access\n# PATTERNS:        Mixin (reusable MI) | Enum/auto() | return self (chaining)\n#                  Composition > Inheritance — \"has-a\" beats \"is-a\"\n\n# ╔══════════════════════════════════════════════════╗\n# ║          INTERVIEW GOTCHAS                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── Q: What is self? ──\n# self = reference to the current instance, NOT a keyword — just convention\n# When you call: Dog(\"Rex\").speak()\n# Python actually calls: Dog.speak(dog_instance) — self is auto-passed\n\n# ── Q: Class method vs Static method vs Instance method ──\nclass MyClass:\n    class_var = \"shared\"\n\n    def instance_method(self):          # gets instance (self)\n        return f\"instance: {self}\"\n\n    @classmethod\n    def class_method(cls):              # gets class (cls), NOT instance\n        return f\"class: {cls.class_var}\"\n\n    @staticmethod\n    def static_method():                # gets NOTHING — just a function in a class\n        return \"static: no self, no cls\"\n\nobj = MyClass()\nprint(obj.instance_method())     # instance: <__main__.MyClass object ...>\nprint(MyClass.class_method())    # class: shared\nprint(MyClass.static_method())   # static: no self, no cls\n\n# ── Q: MRO — diamond problem ──\nclass A2:\n    def greet(self): return \"A\"\nclass B2(A2):\n    def greet(self): return \"B\"\nclass C2(A2):\n    def greet(self): return \"C\"\nclass D2(B2, C2):\n    pass\n\nprint(D2().greet())     # \"B\" — MRO is D → B → C → A\nprint(D2.__mro__)       # shows the full order\n\n# ── Q: __str__ vs __repr__ ──\nclass Point2:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n    def __str__(self):           # for print() — human readable\n        return f\"({self.x}, {self.y})\"\n    def __repr__(self):          # for debugging — unambiguous\n        return f\"Point({self.x}, {self.y})\"\n\np = Point2(3, 4)\nprint(p)          # (3, 4)         — calls __str__\nprint(repr(p))    # Point(3, 4)    — calls __repr__\nprint([p])        # [Point(3, 4)]  — lists use __repr__ for items\n\n# ── Q: @property — getter/setter without Java boilerplate ──\nclass Circle2:\n    def __init__(self, radius):\n        self._radius = radius\n\n    @property\n    def radius(self):               # getter — access like attribute\n        return self._radius\n\n    @radius.setter\n    def radius(self, value):        # setter — validate on assignment\n        if value < 0:\n            raise ValueError(\"Radius can't be negative\")\n        self._radius = value\n\n    @property\n    def area(self):                 # computed — read only\n        return 3.14159 * self._radius ** 2\n\nc = Circle2(5)\nprint(c.radius)     # 5      — looks like attribute, calls getter\nprint(c.area)       # 78.5   — computed on access\nc.radius = 10       # calls setter", "reference": ""}, "06-exception-handling.py": {"content": "# ══════════════════════════════════════════════════════════════════\n#  PYTHON EXCEPTION HANDLING — Complete Guide (Condensed)\n#\n#  Exception = runtime error that breaks normal flow\n#  Handling = catch it, deal with it, keep running\n#\n#  try/except vs if/else:\n#    if/else  → check BEFORE doing   (LBYL: Look Before You Leap)\n#    try/except → just DO it, catch failure  (EAFP: Easier to Ask Forgiveness)\n#    Python community prefers EAFP\n# ══════════════════════════════════════════════════════════════════\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  BEGINNER                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. Basic try/except ─────────────────────────────\n# Without handling:  1/0  →  ZeroDivisionError  →  program CRASHES\n# With handling:     catch it, print message, program continues\ntry:\n    result = 10 / 0\nexcept ZeroDivisionError:\n    print(\"Cannot divide by zero\")       # this runs\nprint(\"Program continues\")               # still alive!\n\n# ── 2. Catch specific vs generic ────────────────────\n# ALWAYS catch specific exceptions first — generic last\ntry:\n    x = int(\"abc\")\nexcept ValueError:                        # specific — catches int(\"abc\")\n    print(\"Not a number\")\nexcept Exception:                         # generic — catches everything else\n    print(\"Something else went wrong\")\n\n# ── 3. Access the error message ─────────────────────\ntry:\n    [1, 2, 3][10]\nexcept IndexError as e:                   # \"as e\" captures the error object\n    print(f\"Error: {e}\")                  # \"list index out of range\"\n    print(f\"Type:  {type(e).__name__}\")   # \"IndexError\"\n\n# ── 4. Multiple exceptions in one line ──────────────\ntry:\n    x = int(\"abc\")\nexcept (ValueError, TypeError) as e:     # catch either — same handler\n    print(f\"Bad input: {e}\")\n\n# vs separate handlers (different logic per error):\ntry:\n    data = {\"a\": 1}\n    print(data[\"b\"])\nexcept KeyError:\n    print(\"Key not found\")               # runs for missing dict key\nexcept TypeError:\n    print(\"Wrong type\")                   # runs for wrong type operation\n\n# ── 5. try / except / else / finally ────────────────\n# else = runs ONLY if no exception | finally = runs ALWAYS\ntry:\n    result = 10 / 2\nexcept ZeroDivisionError:\n    print(\"Error!\")                       # skipped (no error)\nelse:\n    print(f\"Result: {result}\")            # runs because no exception → 5.0\nfinally:\n    print(\"Cleanup done\")                # ALWAYS runs — error or not\n\n# COMPARISON:\n# try:     code that MIGHT fail\n# except:  handle the failure\n# else:    runs if try SUCCEEDED (no exception) — put success logic here, not in try\n# finally: runs ALWAYS — cleanup (close files, connections, release locks)\n\n# ── 6. Why use else? ────────────────────────────────\n# Without else — accidental catch:\ntry:\n    value = int(\"5\")\n    result = value / 0       # BUG! — ZeroDivisionError caught by wrong handler\nexcept (ValueError, ZeroDivisionError):\n    print(\"Parse error?\")    # misleading — it's actually a division error\n\n# With else — clean separation:\ntry:\n    value = int(\"5\")         # only THIS can raise ValueError\nexcept ValueError:\n    print(\"Parse error\")\nelse:\n    result = value / 2       # this is NOT inside try — its errors bubble up naturally\n    print(f\"Result: {result}\")\n\n# ╔══════════════════════════════════════════════════╗\n# ║               INTERMEDIATE                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 7. raise — Throw your own exceptions ───────────\ndef withdraw(amount):\n    if amount <= 0:\n        raise ValueError(\"Amount must be positive\")    # throw error\n    if amount > 1000:\n        raise ValueError(\"Cannot withdraw over 1000\")\n    return f\"Withdrew {amount}\"\n\ntry:\n    print(withdraw(-50))\nexcept ValueError as e:\n    print(f\"Failed: {e}\")     # Failed: Amount must be positive\n\n# ── 8. re-raise — Catch, log, then re-throw ────────\n# Catch for logging but let it propagate up\ndef process_data(data):\n    try:\n        return int(data)\n    except ValueError:\n        print(f\"LOG: bad data '{data}'\")  # log it\n        raise                             # re-raise SAME exception (bare raise)\n\ntry:\n    process_data(\"abc\")\nexcept ValueError as e:\n    print(f\"Caller caught: {e}\")          # still reaches caller\n\n# raise vs raise e:\n#   raise     → preserves original traceback (PREFERRED)\n#   raise e   → resets traceback to this line (loses context)\n\n# ── 9. raise from — Chain exceptions ───────────────\n# \"The real cause was X, but I'm reporting Y\"\ndef connect_db():\n    try:\n        raise ConnectionError(\"DB timeout\")\n    except ConnectionError as e:\n        raise RuntimeError(\"Service unavailable\") from e  # chains original cause\n\ntry:\n    connect_db()\nexcept RuntimeError as e:\n    print(f\"Error: {e}\")                  # Service unavailable\n    print(f\"Cause: {e.__cause__}\")        # DB timeout\n\n# raise X from None → suppress chain (hide original cause)\n\n# ── 10. Custom exceptions ──────────────────────────\n# Inherit from Exception (or a subclass). Use for domain-specific errors.\nclass InsufficientFundsError(Exception):\n    def __init__(self, balance, amount):\n        self.balance = balance\n        self.amount = amount\n        super().__init__(f\"Cannot withdraw {amount}, balance is {balance}\")\n\nclass AccountLockedError(Exception):\n    pass                                  # simplest custom exception — just a name\n\nclass BankError(Exception):              # base class for all bank errors\n    pass\nclass OverdraftError(BankError):         # hierarchy — catch BankError catches both\n    pass\nclass FraudError(BankError):\n    pass\n\ntry:\n    raise InsufficientFundsError(100, 500)\nexcept InsufficientFundsError as e:\n    print(f\"{e}\")                         # Cannot withdraw 500, balance is 100\n    print(f\"Short by: {e.amount - e.balance}\")  # 400 — access custom attrs\n\n# ── 11. LBYL vs EAFP ───────────────────────────────\ndata = {\"name\": \"Alice\", \"age\": 30}\n\n# LBYL (Look Before You Leap) — check first, then act\nif \"email\" in data:\n    email = data[\"email\"]\nelse:\n    email = \"N/A\"\n\n# EAFP (Easier to Ask Forgiveness) — just try it\ntry:\n    email = data[\"email\"]\nexcept KeyError:\n    email = \"N/A\"\n\n# COMPARISON:\n# LBYL:  if os.path.exists(f): open(f)   → race condition! file could be deleted between check and open\n# EAFP:  try: open(f) except FileNotFoundError  → atomic, no race condition\n# LBYL:  if x != 0: y = 10/x             → safe for simple checks\n# EAFP:  try: y = 10/x except ZeroDivision  → better when multiple things can fail\n# Python prefers EAFP. Java/C# prefer LBYL.\n\n# ── 12. Common built-in exceptions ──────────────────\nexamples = {\n    \"ValueError\":       lambda: int(\"abc\"),                # wrong value for type\n    \"TypeError\":        lambda: \"2\" + 2,                   # wrong type in operation\n    \"KeyError\":         lambda: {}[\"missing\"],              # dict key not found\n    \"IndexError\":       lambda: [1,2][10],                  # list index out of range\n    \"AttributeError\":   lambda: None.split(),               # object has no attribute\n    \"NameError\":        lambda: eval(\"undefined_var\"),       # variable not defined\n    \"FileNotFoundError\":lambda: open(\"nonexistent.txt\"),    # file not found\n    \"ZeroDivisionError\":lambda: 1/0,                       # division by zero\n    \"ImportError\":      lambda: __import__(\"nonexistent\"),  # module not found\n    \"StopIteration\":    lambda: next(iter([])),             # iterator exhausted\n    \"OverflowError\":    lambda: 10.0 ** 1000,              # number too large\n    \"RecursionError\":   None,                               # max recursion depth\n    \"PermissionError\":  None,                               # OS denies access\n    \"TimeoutError\":     None,                               # operation timed out\n    \"ConnectionError\":  None,                               # network connection failed\n    \"UnicodeDecodeError\": lambda: b'\\x80'.decode('utf-8'),  # invalid unicode\n}\n\nfor name, fn in examples.items():\n    if fn is None: continue\n    try:\n        fn()\n    except Exception as e:\n        print(f\"  {type(e).__name__:25s} → {e}\")\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  ADVANCED                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 13. Exception hierarchy ─────────────────────────\n# BaseException → Exception → ValueError, TypeError, ...\n# BaseException\n# ├── SystemExit            (sys.exit() — don't catch!)\n# ├── KeyboardInterrupt     (Ctrl+C — don't catch!)\n# ├── GeneratorExit         (generator closed — don't catch!)\n# └── Exception             (all \"normal\" exceptions — CATCH THIS)\n#     ├── ValueError, TypeError, KeyError, IndexError, ...\n#     ├── OSError\n#     │   ├── FileNotFoundError, PermissionError, TimeoutError, ConnectionError\n#     │   └── FileExistsError, IsADirectoryError\n#     ├── RuntimeError\n#     │   └── RecursionError\n#     ├── LookupError\n#     │   ├── KeyError, IndexError\n#     ├── ArithmeticError\n#     │   ├── ZeroDivisionError, OverflowError, FloatingPointError\n#     └── StopIteration, StopAsyncIteration\n#\n# RULE: catch Exception, NOT BaseException\n#   except Exception:         → catches all normal errors (GOOD)\n#   except BaseException:     → also catches Ctrl+C and sys.exit() (BAD)\n#   except:                   → same as BaseException (BAD — never use bare except)\n\n# ── 14. Context managers — auto-cleanup with exceptions ──\n# try/finally vs with statement:\n\n# Manual (error-prone):\nf = None\ntry:\n    f = open(\"test_exc.txt\", \"w\")\n    f.write(\"data\")\nfinally:\n    if f: f.close()                       # must remember to close!\n\n# Context manager (automatic):\nwith open(\"test_exc.txt\", \"w\") as f:\n    f.write(\"data\")\n# f.close() called AUTOMATICALLY — even if exception occurs inside with block\n\n# COMPARISON:\n# try/finally:  you handle cleanup  →  easy to forget, verbose\n# with:         auto-cleanup        →  clean, safe, Pythonic\n# Common with:  open(), lock, db connection, http session, tempfile\n\n# ── 15. Nested try blocks ──────────────────────────\ndef fetch_and_parse(url_data):\n    try:                                  # outer: network layer\n        try:                              # inner: parsing layer\n            return int(url_data)\n        except ValueError:\n            print(\"  Parse failed, using default\")\n            return 0\n    except Exception as e:\n        print(f\"  Unexpected: {e}\")\n        return -1\n\nprint(fetch_and_parse(\"123\"))             # 123\nprint(fetch_and_parse(\"abc\"))             # Parse failed → 0\n\n# Better pattern — separate into functions instead of nesting:\ndef parse_safe(data):\n    try: return int(data)\n    except ValueError: return 0\n\ndef fetch_and_parse_v2(data):\n    try: return parse_safe(data)\n    except Exception: return -1\n\n# ── 16. Exception groups (Python 3.11+) ─────────────\n# ExceptionGroup = multiple exceptions at once (from parallel tasks)\n# except* = catch some types, let others propagate\ndef run_tasks():\n    errors = []\n    for i, val in enumerate([\"1\", \"abc\", \"3\", None]):\n        try:\n            int(val)\n        except (ValueError, TypeError) as e:\n            errors.append(e)\n    if errors:\n        raise ExceptionGroup(\"batch failed\", errors)\n\ntry:\n    run_tasks()\nexcept ExceptionGroup as eg:\n    print(f\"ExceptionGroup: {len(eg.exceptions)} errors\")\n    for e in eg.exceptions:\n        print(f\"  {type(e).__name__}: {e}\")\n\n# except* (3.11+) — catch specific types from group:\n# try:\n#     run_tasks()\n# except* ValueError as eg:       → catches only ValueErrors from the group\n#     print(f\"{len(eg.exceptions)} ValueErrors\")\n# except* TypeError as eg:        → catches only TypeErrors\n#     print(f\"{len(eg.exceptions)} TypeErrors\")\n\n# ── 17. Warnings vs Exceptions ─────────────────────\nimport warnings\n\n# Exception:  STOPS execution  |  Warning:  CONTINUES execution\n# raise ValueError(\"bad\")     |  warnings.warn(\"careful\", UserWarning)\n\nwarnings.warn(\"Deprecated function\", DeprecationWarning)   # program continues\n# Control behavior:\n# warnings.filterwarnings(\"ignore\", category=DeprecationWarning)   → suppress\n# warnings.filterwarnings(\"error\", category=DeprecationWarning)    → turn into exception\n\n# ── 18. Logging exceptions ─────────────────────────\nimport logging, traceback\n\nlogging.basicConfig(level=logging.DEBUG)\n\ntry:\n    1 / 0\nexcept ZeroDivisionError:\n    logging.exception(\"Math error\")       # logs full traceback automatically\n    # vs logging.error(\"Math error\")      # logs message only — no traceback\n\n# Manual traceback capture:\ntry:\n    1 / 0\nexcept ZeroDivisionError:\n    tb = traceback.format_exc()           # full traceback as string\n    print(f\"Traceback:\\n{tb}\")\n\n# ── 19. Decorator for exception handling ────────────\nimport functools\n\ndef safe_call(default=None):\n    def decorator(func):\n        @functools.wraps(func)\n        def wrapper(*args, **kwargs):\n            try:\n                return func(*args, **kwargs)\n            except Exception as e:\n                print(f\"  {func.__name__} failed: {e}\")\n                return default\n        return wrapper\n    return decorator\n\n@safe_call(default=0)\ndef risky_divide(a, b): return a / b\n\nprint(risky_divide(10, 2))               # 5.0\nprint(risky_divide(10, 0))               # risky_divide failed → 0\n\n# ── 20. Retry decorator with specific exceptions ───\ndef retry(exceptions=(Exception,), max_tries=3, delay=0):\n    import time\n    def decorator(func):\n        @functools.wraps(func)\n        def wrapper(*args, **kwargs):\n            for attempt in range(1, max_tries + 1):\n                try:\n                    return func(*args, **kwargs)\n                except exceptions as e:\n                    if attempt == max_tries:\n                        raise\n                    print(f\"  Retry {attempt}/{max_tries}: {e}\")\n                    if delay: time.sleep(delay)\n        return wrapper\n    return decorator\n\n_count = 0\n@retry(exceptions=(ConnectionError, TimeoutError), max_tries=3)\ndef call_api():\n    global _count; _count += 1\n    if _count < 3: raise ConnectionError(f\"Attempt {_count} failed\")\n    return \"API response\"\n\n_count = 0\nprint(call_api())                         # retries twice, succeeds third time\n\n# ── 21. Context manager for exception handling ──────\nfrom contextlib import contextmanager, suppress\n\n# suppress — ignore specific exceptions:\nfrom collections import defaultdict\nd = {}\nwith suppress(KeyError):                  # silently ignores KeyError\n    val = d[\"missing\"]\n# equivalent to: try: d[\"missing\"] except KeyError: pass\n\n# Custom context manager:\n@contextmanager\ndef error_boundary(label):\n    try:\n        yield\n    except Exception as e:\n        print(f\"[{label}] Caught: {type(e).__name__}: {e}\")\n\nwith error_boundary(\"data-load\"):\n    int(\"not_a_number\")                   # caught and logged, program continues\n\n# ── 22. Assertions — Debug-time checks ──────────────\n# assert = \"this MUST be true, crash if not\"\n# Removed when running with python -O (optimized) — NEVER use for validation!\ndef divide(a, b):\n    assert b != 0, \"Divisor cannot be zero\"     # dev check — NOT for user input!\n    return a / b\n\ntry:\n    divide(10, 0)\nexcept AssertionError as e:\n    print(f\"Assertion: {e}\")              # Divisor cannot be zero\n\n# COMPARISON:\n# assert x > 0        → debug check, removed with -O, for IMPOSSIBLE states\n# if x <= 0: raise    → validation, always runs, for USER INPUT / API boundaries\n# Rule: if it could happen in production, use raise, not assert\n\n# ── 23. sys.exc_info() — Low-level exception access ─\nimport sys\ntry:\n    1 / 0\nexcept:\n    exc_type, exc_value, exc_tb = sys.exc_info()\n    print(f\"Type:  {exc_type.__name__}\")  # ZeroDivisionError\n    print(f\"Value: {exc_value}\")          # division by zero\n    print(f\"Line:  {exc_tb.tb_lineno}\")   # line number where error occurred\n\n# ── 24. Exception in generators ─────────────────────\ndef safe_generator(items):\n    for item in items:\n        try:\n            yield int(item)               # yields valid, skips invalid\n        except (ValueError, TypeError):\n            print(f\"  Skipping invalid: {item}\")\n\nresults = list(safe_generator([\"1\", \"abc\", \"3\", None, \"5\"]))\nprint(f\"Valid items: {results}\")          # [1, 3, 5]\n\n# generator.throw() — inject exception into generator:\ndef gen():\n    while True:\n        try:\n            value = yield\n            print(f\"  Got: {value}\")\n        except ValueError:\n            print(\"  Received ValueError!\")\n\ng = gen(); next(g)                        # prime generator\ng.send(\"hello\")                           # Got: hello\ng.throw(ValueError, \"bad data\")           # Received ValueError!\n\n# ── 25. Async exception handling ────────────────────\nimport asyncio\n\nasync def async_divide(a, b):\n    await asyncio.sleep(0.01)             # simulate I/O\n    if b == 0: raise ZeroDivisionError(\"async division by zero\")\n    return a / b\n\nasync def main():\n    # Single async try/except — same as sync\n    try:\n        result = await async_divide(10, 0)\n    except ZeroDivisionError as e:\n        print(f\"Async error: {e}\")\n\n    # Gather with return_exceptions — parallel error handling\n    results = await asyncio.gather(\n        async_divide(10, 2), async_divide(10, 0), async_divide(6, 3),\n        return_exceptions=True,\n    )\n    for r in results:\n        if isinstance(r, Exception):\n            print(f\"  Failed: {r}\")       # Failed: async division by zero\n        else:\n            print(f\"  Result: {r}\")       # Result: 5.0, Result: 2.0\n\nasyncio.run(main())\n\n# ── 26. Anti-patterns — What NOT to do ──────────────\n\n# BAD: bare except (catches Ctrl+C, sys.exit!)\n# try: ...\n# except:                           → catches EVERYTHING including KeyboardInterrupt\n#     pass                          → silently swallows — impossible to debug\n\n# GOOD:\n# except Exception:                 → catches all normal errors, not Ctrl+C/sys.exit\n\n# BAD: catch-all with pass (silent failure)\n# try: do_something()\n# except Exception: pass            → error vanishes — no one knows it happened\n\n# GOOD: at minimum, log it\n# except Exception as e:\n#     logging.exception(f\"Failed: {e}\")\n\n# BAD: too broad try block\n# try:\n#     data = read_file()            # could fail\n#     parsed = parse(data)          # could fail\n#     result = calculate(parsed)    # could fail\n# except Exception: ...             # which one failed? can't tell!\n\n# GOOD: narrow try blocks\n# data = read_file()                # let it crash if file missing\n# try:\n#     parsed = parse(data)          # only catch parse errors\n# except ValueError: ...\n\n# BAD: using exceptions for flow control\n# try: d[\"key\"]                     # → just use d.get(\"key\", default)\n# except KeyError: default\n\n# BAD: assert for validation\n# assert user_input > 0             # removed with -O flag!\n\n# ╔══════════════════════════════════════════════════╗", "cheatSheet": "# ║                 CHEAT SHEET                      ║\n# ╚══════════════════════════════════════════════════╝\n#\n# SYNTAX              │ PURPOSE                        │ EXAMPLE\n# ────────────────────┼────────────────────────────────┼──────────────────────────\n# try/except          │ catch and handle error         │ except ValueError as e:\n# try/except/else     │ else = success path            │ else: print(result)\n# try/except/finally  │ finally = always cleanup       │ finally: f.close()\n# except (A, B):      │ catch multiple types           │ except (Key, Index):\n# except Exception:   │ catch all normal errors        │ NOT BaseException!\n# as e                │ capture error object           │ e.args, str(e), type(e)\n# raise               │ throw / re-raise exception     │ raise ValueError(\"msg\")\n# raise X from Y      │ chain exceptions               │ raise New() from original\n# assert cond, msg    │ debug check (removed with -O)  │ assert x > 0, \"positive\"\n#\n# CUSTOM EXCEPTIONS:\n#   class MyError(Exception):              minimal — just a name\n#   class MyError(Exception):              with data:\n#       def __init__(self, detail):            super().__init__(f\"...\")\n#           self.detail = detail               self.detail = detail\n#   class Base(Exception): pass            hierarchy:\n#   class Sub1(Base): pass                   except Base catches Sub1 & Sub2\n#   class Sub2(Base): pass\n#\n# COMPARISON TABLE:\n# ────────────────────┬──────────────────────────────────────────\n# bare except:        │ catches EVERYTHING (Ctrl+C too) — NEVER use\n# except Exception:   │ catches all normal errors — PREFERRED\n# except ValueError:  │ catches specific error — MOST SPECIFIC\n# try/finally:        │ manual cleanup — verbose, error-prone\n# with statement:     │ auto cleanup — clean, safe, Pythonic\n# raise vs raise e:   │ raise keeps traceback, raise e resets it\n# assert vs raise:    │ assert = debug only, raise = production validation\n# LBYL vs EAFP:       │ if/check-first vs try/catch — Python prefers EAFP\n# Exception vs warn:  │ exception STOPS, warning CONTINUES\n# logging.exception:  │ logs message + full traceback automatically\n# logging.error:      │ logs message only — no traceback\n# suppress(Error):    │ context manager — silently ignore specific exceptions\n# ────────────────────┴──────────────────────────────────────────\n#\n# COMMON PATTERNS:\n#   Retry:      for i in range(n): try: return f() except: sleep(delay*i)\n#   Default:    try: val = d[\"key\"] except KeyError: val = default\n#   Parse:      try: x = int(s) except ValueError: x = 0\n#   Cleanup:    try: ... finally: resource.close()  OR  with resource:\n#   Log+raise:  except E: logging.exception(\"...\"); raise\n#   Safe gen:   try: yield val except E: continue\n#\n# ══════════════════════════════════════════════════════════════════\n#", "reference": "# ══════════════════════════════════════════════════════════════════\n#  EXCEPTION HANDLING — DETAILED REFERENCE\n# ══════════════════════════════════════════════════════════════════\n#\n# ── try/except — Basic error catching ────────────────────────────\n#   try:\n#       risky_code()                → code that MIGHT raise an exception\n#   except SomeError as e:          → catches SomeError (and its subclasses)\n#       handle(e)                   → e is the exception object: str(e), type(e), e.args\n#   If no exception: except block is SKIPPED.\n#   If exception matches: except block runs, program continues AFTER the block.\n#   If exception doesn't match: propagates UP the call stack (crash if uncaught).\n#\n# ── else — Success-only code ─────────────────────────────────────\n#   try:\n#       result = parse(data)        → only THIS can trigger the except\n#   except ValueError:\n#       handle_error()\n#   else:\n#       use(result)                 → runs ONLY if try succeeded — keeps try block narrow\n#   Why not put it in try? Because errors in use(result) would be caught too.\n#\n# ── finally — Always runs ───────────────────────────────────────\n#   try: ...\n#   finally: cleanup()              → runs whether exception occurred or not\n#   Even runs if: return in try, break in loop, exception propagates up.\n#   Use for: closing files, releasing locks, DB rollback, network disconnect.\n#\n# ── raise — Throw exceptions ────────────────────────────────────\n#   raise ValueError(\"msg\")         → throw new exception\n#   raise                           → re-raise current exception (in except block)\n#   raise NewError() from original  → chain: NewError.__cause__ = original\n#   raise NewError() from None      → suppress chain (hide original cause)\n#\n# ── Custom exceptions ───────────────────────────────────────────\n#   class MyError(Exception):       → inherit from Exception (or a subclass)\n#   Add __init__ for custom attributes (balance, code, detail, etc.)\n#   Build hierarchies: class Base(Exception) → class Sub(Base)\n#   Catching Base catches all Sub exceptions too.\n#\n# ── ExceptionGroup (3.11+) ──────────────────────────────────────\n#   raise ExceptionGroup(\"msg\", [e1, e2, e3])  → multiple errors at once\n#   except* ValueError as eg:       → catches only ValueErrors from group\n#   eg.exceptions                   → tuple of matched exceptions\n#   Unmatched types propagate as a new ExceptionGroup. Used for parallel tasks.\n#\n# ── Context managers — Exception-safe resource management ───────\n#   with open(f) as fh:             → __enter__ opens, __exit__ closes (even on error)\n#   with suppress(KeyError):        → silently ignores KeyError (contextlib)\n#   @contextmanager + try/yield/except → custom context manager with error handling\n#\n# ── Assertions ──────────────────────────────────────────────────\n#   assert condition, \"message\"     → raises AssertionError if False\n#   REMOVED by python -O flag! Never use for: user input, API validation, security.\n#   Use for: invariants in tests, debug-only sanity checks, \"this should never happen\".\n#\n# ── Async exceptions ────────────────────────────────────────────\n#   try: result = await coro() except E:    → same syntax, just add await\n#   asyncio.gather(return_exceptions=True)  → errors returned as values, not raised\n#   isinstance(r, Exception)                → check which results are errors\n#\n# ══════════════════════════════════════════════════════════════════\n\nimport os\nif os.path.exists(\"test_exc.txt\"):\n    os.remove(\"test_exc.txt\")\n\n# ╔══════════════════════════════════════════════════╗\n# ║          INTERVIEW GOTCHAS                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── Q: When does else run in try/except/else/finally? ──\ntry:\n    x = 10 / 2\nexcept ZeroDivisionError:\n    print(\"error\")       # runs ONLY if exception raised\nelse:\n    print(\"success\")     # runs ONLY if NO exception — prints this\nfinally:\n    print(\"always\")      # runs ALWAYS — even if return/break inside try\n\n# ── Q: What's wrong with bare except? ──\n# try:\n#     something()\n# except:             # catches EVERYTHING — including KeyboardInterrupt, SystemExit\n#     pass            # silently swallows ALL errors — NEVER do this\n# Better: except Exception:   # catches normal errors, lets system exits through\n\n# ── Q: Custom exception — why and how? ──\nclass InsufficientFundsError(Exception):\n    def __init__(self, balance, amount):\n        self.balance = balance\n        self.amount = amount\n        super().__init__(f\"Need {amount}, have {balance}\")\n\ntry:\n    raise InsufficientFundsError(100, 250)\nexcept InsufficientFundsError as e:\n    print(f\"{e}, short by {e.amount - e.balance}\")  # Need 250, have 100, short by 150\n\n# ── Q: raise vs raise from ──\ntry:\n    int(\"abc\")\nexcept ValueError as original:\n    # raise from → chains exceptions (shows \"caused by\" in traceback)\n    # raise RuntimeError(\"parse failed\") from original\n    pass"}, "07-file-handling.py": {"content": "# ══════════════════════════════════════════════════════════════════\n#  PYTHON FILE, JSON & CSV HANDLING — Condensed Guide\n#  Always use \"with open(...)\" — auto-closes even on error\n# ══════════════════════════════════════════════════════════════════\n\nimport os, json, csv, shutil, tempfile\nfrom pathlib import Path\nfrom datetime import datetime, date\n\n# ╔══════════════════════════════════════════════════╗\n# ║              BEGINNER                            ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. File Modes ──────────────────────────────────\n#  \"r\"  = read (default, must exist)    \"rb\" = read binary\n#  \"w\"  = write (creates/OVERWRITES)    \"wb\" = write binary\n#  \"a\"  = append (creates/adds to end)  \"x\"  = exclusive create (error if exists)\n#  \"r+\" = read+write (must exist)       \"w+\" = write+read (creates/overwrites)\n#  Add \"b\" for binary (images, PDFs). Add \"t\" for text (default).\n\n# ── 2. Writing Files ──────────────────────────────\nwith open(\"sample.txt\", \"w\") as f:\n    f.write(\"Line 1: Hello World\\n\")\n    f.write(\"Line 2: Python is great\\n\")\n    f.write(\"Line 3: File handling\\n\")\n    chars = f.write(\"Line 4: Last line\\n\")  # returns char count\nprint(f\"Wrote sample.txt ({chars} chars in last write)\")\n\n# writelines() — write a list (no auto-newline)\nlines = [\"Apple\\n\", \"Banana\\n\", \"Cherry\\n\"]\nwith open(\"fruits.txt\", \"w\") as f:\n    f.writelines(lines)\n\n# ── 3. Reading Files (2 Best Methods) ─────────────\n# Method A: read() — entire file as string (small files)\nwith open(\"sample.txt\", \"r\") as f:\n    content = f.read()\n    print(f\"read(): {repr(content[:40])}...\")\n\n# Method B: for loop — line by line (BEST for large files, memory efficient)\nwith open(\"sample.txt\", \"r\") as f:\n    for i, line in enumerate(f, 1):\n        print(f\"  Line {i}: {line.strip()}\")\n\n# Also: readlines() → list of lines, readline() → single line\n\n# ── 4. Append — \"a\" Mode ─────────────────────────\nwith open(\"sample.txt\", \"a\") as f:\n    f.write(\"Line 5: Appended\\n\")\nwith open(\"sample.txt\", \"r\") as f:\n    print(f\"File now has {len(f.readlines())} lines\")  # 5\n\n# ── 5. Exclusive Create — \"x\" Mode ───────────────\ntry:\n    with open(\"sample.txt\", \"x\") as f:  # already exists → error\n        f.write(\"won't work\")\nexcept FileExistsError:\n    print(\"FileExistsError: sample.txt already exists\")\n\nwith open(\"new_file.txt\", \"x\") as f:\n    f.write(\"Created with x mode\\n\")\n\n# ── 6. Read+Write & File Pointer ─────────────────\nwith open(\"temp_rw.txt\", \"w+\") as f:\n    f.write(\"Hello from w+ mode\\n\")\n    f.seek(0)                 # move pointer back to start\n    print(f\"w+ read: {f.read().strip()}\")\n\n# seek(0) → beginning | seek(0,2) → end | tell() → current position\nwith open(\"sample.txt\", \"r\") as f:\n    f.read(10); print(f\"After read(10): {f.tell()}\")  # 10\n    f.seek(0, 2); print(f\"File size: {f.tell()} bytes\")\n\n# ── 7. Error Handling ─────────────────────────────\ndef safe_read_file(filepath):\n    \"\"\"Handle FileNotFoundError, PermissionError, UnicodeDecodeError, etc.\"\"\"\n    try:\n        with open(filepath, \"r\", encoding=\"utf-8\") as f:\n            return f.read()\n    except FileNotFoundError:\n        print(f\"  ERROR: '{filepath}' not found\")\n    except PermissionError:\n        print(f\"  ERROR: No permission for '{filepath}'\")\n    except IsADirectoryError:\n        print(f\"  ERROR: '{filepath}' is a directory\")\n    except UnicodeDecodeError:\n        print(f\"  ERROR: Cannot decode '{filepath}' as UTF-8\")\n    return None\n\nsafe_read_file(\"sample.txt\")       # works\nsafe_read_file(\"nonexistent.txt\")  # FileNotFoundError\n\n# ╔══════════════════════════════════════════════════╗\n# ║            INTERMEDIATE                          ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 8. Encoding ───────────────────────────────────\n# Always specify encoding=\"utf-8\" for cross-platform consistency\nwith open(\"encoded.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"English: Hello\\nJapanese: こんにちは\\nEmoji: 🐍\\n\")\nwith open(\"encoded.txt\", \"r\", encoding=\"utf-8\") as f:\n    content = f.read()  # works with all unicode\n# errors=\"ignore\" skips bad chars | errors=\"replace\" uses ? for bad chars\ntry:\n    with open(\"encoded.txt\", \"r\", encoding=\"ascii\") as f: f.read()\nexcept UnicodeDecodeError: print(\"Wrong encoding → UnicodeDecodeError\")\n\n# ── 9. Binary Files — \"rb\"/\"wb\" ──────────────────\ndata = bytes([72, 101, 108, 108, 111])  # \"Hello\"\nwith open(\"binary.dat\", \"wb\") as f:\n    f.write(data)\n    f.write(b\"\\x00\\x01\\x02\\x03\")\n\nwith open(\"binary.dat\", \"rb\") as f:\n    content = f.read()\n    print(f\"Bytes: {content}, as text: {content[:5].decode('utf-8')}\")\n\n# Copy any file in binary mode\nwith open(\"binary.dat\", \"rb\") as src, open(\"binary_copy.dat\", \"wb\") as dst:\n    dst.write(src.read())\n\n# ── 10. JSON Basics — dumps/loads/dump/load ───────\n#  json.dumps(obj) → string   |  json.dump(obj, file)  → write to file\n#  json.loads(str) → dict     |  json.load(file)       → read from file\n#  Mnemonic: \"s\" = string\n#\n#  Python→JSON: dict→{}, list→[], str→\"\", int/float→number,\n#               True→true, False→false, None→null\n\nuser = {\"name\": \"Alice\", \"age\": 30, \"active\": True, \"scores\": [95, 87], \"address\": None}\n\njson_str = json.dumps(user)                          # dict → string\nprint(f\"dumps: {json_str}\")\njson_pretty = json.dumps(user, indent=2)             # pretty-print\ncompact = json.dumps(user, separators=(\",\", \":\"))    # no spaces (for APIs)\n\nparsed = json.loads('{\"name\": \"Bob\", \"age\": 25}')   # string → dict\nprint(f\"loads: {parsed['name']}, type={type(parsed)}\")  # Bob, <class 'dict'>\n\n# ── 11. JSON File Read/Write ─────────────────────\nusers = [\n    {\"id\": 1, \"name\": \"Alice\", \"email\": \"alice@test.com\", \"active\": True},\n    {\"id\": 2, \"name\": \"Bob\", \"email\": \"bob@test.com\", \"active\": False},\n    {\"id\": 3, \"name\": \"Charlie\", \"email\": \"charlie@test.com\", \"active\": True},\n]\nwith open(\"users.json\", \"w\", encoding=\"utf-8\") as f:\n    json.dump(users, f, indent=2, ensure_ascii=False)  # dict → file\n\nwith open(\"users.json\", \"r\", encoding=\"utf-8\") as f:\n    loaded = json.load(f)                               # file → dict\nprint(f\"Loaded {len(loaded)} users from users.json\")\n\n# Common pattern: load → modify → save\nwith open(\"users.json\", \"r\", encoding=\"utf-8\") as f:\n    users = json.load(f)\nusers.append({\"id\": 4, \"name\": \"Diana\", \"email\": \"diana@test.com\", \"active\": True})\nusers = [u for u in users if u[\"name\"] != \"Charlie\"]  # remove Charlie\nwith open(\"users.json\", \"w\", encoding=\"utf-8\") as f:\n    json.dump(users, f, indent=2)\nprint(f\"Modified users.json: now {len(users)} users\")\n\n# ── 12. JSON Error Handling ──────────────────────\n# Common invalid JSON: single quotes, trailing commas, unquoted keys\nfor bad in [\"{'name': 'Alice'}\", '{\"name\": \"Alice\",}', 'not json']:\n    try: json.loads(bad)\n    except json.JSONDecodeError as e: print(f\"  Invalid: {repr(bad[:25])} → {e.msg}\")\n\ndef safe_load_json(filepath):\n    try:\n        with open(filepath, \"r\", encoding=\"utf-8\") as f:\n            return json.load(f)\n    except FileNotFoundError:\n        print(f\"  File not found: {filepath}\")\n    except json.JSONDecodeError as e:\n        print(f\"  Invalid JSON in {filepath}: {e.msg} at line {e.lineno}\")\n    return None\n\n# ── 13. Nested JSON Access ───────────────────────\napi = {\"data\": {\"user\": {\"profile\": {\"social\": {\"twitter\": \"@alice\"}},\n       \"orders\": [{\"id\": 1, \"items\": [{\"name\": \"Laptop\", \"price\": 999}]}]}}}\n\n# Direct access (raises KeyError if missing)\nprint(f\"Twitter: {api['data']['user']['profile']['social']['twitter']}\")\n\n# Safe deep access with .get() chains\ntwitter = api.get(\"data\", {}).get(\"user\", {}).get(\"profile\", {}).get(\"social\", {}).get(\"twitter\", \"N/A\")\nlinkedin = api.get(\"data\", {}).get(\"user\", {}).get(\"profile\", {}).get(\"social\", {}).get(\"linkedin\", \"Not found\")\nprint(f\"Safe: twitter={twitter}, linkedin={linkedin}\")\n\n# ── 14. CSV Read/Write ───────────────────────────\n# csv.writer / csv.reader — rows as lists\nwith open(\"employees.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as f:\n    writer = csv.writer(f)\n    writer.writerow([\"Name\", \"Department\", \"Salary\"])  # header\n    writer.writerow([\"Alice\", \"Engineering\", 90000])\n    writer.writerows([[\"Bob\", \"Marketing\", 70000], [\"Charlie\", \"Engineering\", 85000]])\n\nwith open(\"employees.csv\", \"r\", newline=\"\", encoding=\"utf-8\") as f:\n    reader = csv.reader(f)\n    header = next(reader)  # skip header\n    for row in reader:\n        print(f\"  {row[0]}: {row[1]}, ${row[2]}\")\n\n# csv.DictReader / csv.DictWriter — rows as dicts (RECOMMENDED)\nwith open(\"products.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as f:\n    fields = [\"id\", \"name\", \"price\"]\n    writer = csv.DictWriter(f, fieldnames=fields)\n    writer.writeheader()\n    writer.writerow({\"id\": 1, \"name\": \"Laptop\", \"price\": 999.99})\n    writer.writerow({\"id\": 2, \"name\": \"Mouse\", \"price\": 24.99})\n\nwith open(\"products.csv\", \"r\", newline=\"\", encoding=\"utf-8\") as f:\n    for row in csv.DictReader(f):\n        print(f\"  {row['name']}: ${row['price']}\")\n\n# Custom delimiter (TSV)\nwith open(\"data.tsv\", \"w\", newline=\"\", encoding=\"utf-8\") as f:\n    writer = csv.writer(f, delimiter=\"\\t\")\n    writer.writerow([\"Name\", \"Score\"])\n    writer.writerows([[\"Alice\", 95], [\"Bob\", 87]])\n\n# ── 15. pathlib — Modern File Handling ────────────\n# pathlib.Path vs os.path: Path objects use / operator, have cleaner API\np = Path(\"sample.txt\")\nprint(f\"name={p.name}, stem={p.stem}, suffix={p.suffix}\")  # sample.txt, sample, .txt\nprint(f\"exists={p.exists()}, is_file={p.is_file()}, size={p.stat().st_size}\")\n\n# Join paths:  Path(\"data\") / \"2024\" / \"report.csv\"  vs  os.path.join(\"data\",\"2024\",\"report.csv\")\ndata_path = Path(\"data\") / \"2024\" / \"report.csv\"\n\n# Read/write without open()\nPath(\"pathlib_test.txt\").write_text(\"Hello from pathlib!\", encoding=\"utf-8\")\ncontent = Path(\"pathlib_test.txt\").read_text(encoding=\"utf-8\")\nPath(\"pathlib_bin.dat\").write_bytes(b\"binary data\")\ndata = Path(\"pathlib_bin.dat\").read_bytes()\n\n# Glob — find files by pattern\nfor txt_file in Path(\".\").glob(\"*.txt\"):\n    print(f\"  Found: {txt_file}\")\n# Path(\".\").rglob(\"*.py\")  — recursive search into subdirs\n\n# Modify path parts\np3 = Path(\"report.txt\")\nprint(f\"Change ext: {p3.with_suffix('.pdf')}, change name: {p3.with_name('summary.txt')}\")\n\n# JSON with pathlib (one-liner read/write)\nPath(\"fw.json\").write_text(json.dumps({\"name\": \"FastAPI\"}, indent=2), encoding=\"utf-8\")\nloaded = json.loads(Path(\"fw.json\").read_text(encoding=\"utf-8\"))\n\n# ── 16. os Module Essentials ─────────────────────\nos.path.exists(\"sample.txt\")                       # True/False\nos.path.getsize(\"sample.txt\")                      # bytes\nos.path.isfile(\"sample.txt\")                       # True\nname, ext = os.path.splitext(\"report.pdf\")         # ('report', '.pdf')\nfull = os.path.join(\"folder\", \"sub\", \"file.txt\")   # folder/sub/file.txt\nos.path.dirname(\"/home/user/f.txt\")                # /home/user\nos.path.basename(\"/home/user/f.txt\")               # f.txt\ntxt_files = [f for f in os.listdir(\".\") if f.endswith(\".txt\")]\nos.rename(\"new_file.txt\", \"renamed_file.txt\")\nos.makedirs(\"test_dir/sub_dir\", exist_ok=True)\n\n# ╔══════════════════════════════════════════════════╗\n# ║              ADVANCED                            ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 17. tempfile — Auto-Cleanup Temp Files ────────\nwith tempfile.NamedTemporaryFile(mode=\"w\", suffix=\".txt\", delete=False) as tmp:\n    tmp.write(\"Temporary data\\n\")\n    tmp_name = tmp.name                                  # get path before close\nos.unlink(tmp_name)                                      # manual delete (delete=False)\n\nwith tempfile.TemporaryDirectory() as tmpdir:             # auto-deleted on exit\n    Path(tmpdir, \"data.txt\").write_text(\"temp data\")\nprint(f\"Temp dir gone: {not os.path.exists(tmpdir)}\")    # True\n\n# ── 18. shutil — Copy, Move, Delete ──────────────\nshutil.copy(\"sample.txt\", \"sample_backup.txt\")     # copy file\nshutil.copy2(\"sample.txt\", \"sample_backup2.txt\")   # copy + metadata (timestamps)\nshutil.move(\"renamed_file.txt\", \"moved_file.txt\")  # move/rename\nshutil.copytree(\"test_dir\", \"test_dir_copy\")       # copy entire directory tree\nshutil.rmtree(\"test_dir_copy\")                     # delete dir + all contents\n\n# ── 19. JSON Lines (JSONL) ───────────────────────\n# One JSON object per line — ideal for logs, streaming, large datasets\nevents = [\n    {\"ts\": \"2024-01-01T10:00\", \"event\": \"login\", \"user\": \"alice\"},\n    {\"ts\": \"2024-01-01T10:05\", \"event\": \"page_view\", \"user\": \"alice\"},\n]\n# Write: one json.dumps() per line\nwith open(\"events.jsonl\", \"w\", encoding=\"utf-8\") as f:\n    for event in events:\n        f.write(json.dumps(event) + \"\\n\")\n\n# Append (just add a line — no need to rewrite entire file like JSON arrays)\nwith open(\"events.jsonl\", \"a\", encoding=\"utf-8\") as f:\n    f.write(json.dumps({\"ts\": \"2024-01-01T10:15\", \"event\": \"logout\", \"user\": \"alice\"}) + \"\\n\")\n\n# Read: parse each line independently\nwith open(\"events.jsonl\", \"r\", encoding=\"utf-8\") as f:\n    all_events = [json.loads(line) for line in f]\n\n# ── 20. Large File Reading ───────────────────────\nwith open(\"large_demo.txt\", \"w\") as f:\n    for i in range(1000): f.write(f\"Line {i}: test data\\n\")\n\n# Line by line (BEST for text) — never loads entire file into memory\ncount = sum(1 for _ in open(\"large_demo.txt\", \"r\"))\n\n# Chunk-based (for binary or raw processing)\ntotal_bytes = 0\nwith open(\"large_demo.txt\", \"rb\") as f:\n    while chunk := f.read(8192):  # 8KB chunks, walrus operator\n        total_bytes += len(chunk)\n\n# ── 21. JSON ↔ CSV Conversion ────────────────────\n# JSON → CSV\njson_data = [\n    {\"name\": \"Alice\", \"age\": 30, \"city\": \"NYC\"},\n    {\"name\": \"Bob\", \"age\": 25, \"city\": \"LA\"},\n]\nwith open(\"people.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as f:\n    writer = csv.DictWriter(f, fieldnames=json_data[0].keys())\n    writer.writeheader()\n    writer.writerows(json_data)\n\n# CSV → JSON\nwith open(\"people.csv\", \"r\", newline=\"\", encoding=\"utf-8\") as f:\n    csv_as_json = list(csv.DictReader(f))\nwith open(\"people.json\", \"w\", encoding=\"utf-8\") as f:\n    json.dump(csv_as_json, f, indent=2)\n\n# ── 22. Custom JSON Serialization ────────────────\n# JSON can't serialize: datetime, set, bytes → use default= or cls=\ndata_custom = {\n    \"event\": \"Meeting\",\n    \"date\": datetime(2024, 6, 15, 14, 30),\n    \"tags\": {\"python\", \"coding\"},\n    \"raw\": b\"hello\",\n}\n\ndef json_serializer(obj):\n    if isinstance(obj, (datetime, date)): return obj.isoformat()\n    if isinstance(obj, set): return sorted(list(obj))\n    if isinstance(obj, bytes): return obj.decode(\"utf-8\")\n    raise TypeError(f\"Type {type(obj)} not serializable\")\n\nresult = json.dumps(data_custom, default=json_serializer, indent=2)\nprint(f\"Custom serialized:\\n{result}\")\n\n# Reusable: subclass JSONEncoder\nclass CustomEncoder(json.JSONEncoder):\n    def default(self, obj):\n        if isinstance(obj, (datetime, date)): return obj.isoformat()\n        if isinstance(obj, set): return sorted(list(obj))\n        if isinstance(obj, bytes): return obj.decode(\"utf-8\")\n        return super().default(obj)\n\njson.dumps(data_custom, cls=CustomEncoder, indent=2)\n\n# ── 23. JSON Merge & Diff ────────────────────────\ndefaults = {\"theme\": \"light\", \"lang\": \"en\", \"notify\": True, \"font\": 14}\nuser_prefs = {\"theme\": \"dark\", \"font\": 16}\n\nmerged = {**defaults, **user_prefs}   # ** unpacking (3.5+), user_prefs wins\nmerged2 = defaults | user_prefs       # | operator (3.9+)\nprint(f\"Merged: {merged}\")\n\n# Deep merge for nested dicts\ndef deep_merge(base, override):\n    result = base.copy()\n    for key, val in override.items():\n        if key in result and isinstance(result[key], dict) and isinstance(val, dict):\n            result[key] = deep_merge(result[key], val)\n        else:\n            result[key] = val\n    return result\n\ncfg_base = {\"db\": {\"host\": \"localhost\", \"port\": 5432}, \"debug\": False}\ncfg_prod = {\"db\": {\"host\": \"prod-server\"}, \"debug\": False}\nprint(f\"Deep merged: {deep_merge(cfg_base, cfg_prod)}\")\n# {\"db\": {\"host\": \"prod-server\", \"port\": 5432}, \"debug\": False}\n\n# Simple diff\ndef json_diff(old, new):\n    changes = {}\n    for key in set(list(old) + list(new)):\n        if key not in old: changes[key] = {\"added\": new[key]}\n        elif key not in new: changes[key] = {\"removed\": old[key]}\n        elif old[key] != new[key]: changes[key] = {\"old\": old[key], \"new\": new[key]}\n    return changes\n\ndiff = json_diff({\"name\": \"Alice\", \"age\": 30, \"city\": \"NYC\"}, {\"name\": \"Alice\", \"age\": 31, \"country\": \"US\"})\n# {'age': {'old': 30, 'new': 31}, 'city': {'removed': 'NYC'}, 'country': {'added': 'US'}}\n\n# ── CLEANUP ───────────────────────────────────────\nfor f in [\"sample.txt\", \"fruits.txt\", \"encoded.txt\", \"binary.dat\", \"binary_copy.dat\",\n          \"temp_rw.txt\", \"pathlib_test.txt\", \"pathlib_bin.dat\", \"sample_backup.txt\",\n          \"sample_backup2.txt\", \"moved_file.txt\", \"users.json\", \"fw.json\",\n          \"employees.csv\", \"products.csv\", \"data.tsv\", \"people.csv\", \"people.json\",\n          \"large_demo.txt\", \"events.jsonl\"]:\n    if os.path.exists(f):\n        os.remove(f)\nif os.path.exists(\"test_dir\"):\n    shutil.rmtree(\"test_dir\")", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n#                         CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\n#\n#  FILE MODES:\n#    \"r\" read | \"w\" write | \"a\" append | \"x\" exclusive\n#    \"r+\" read+write | \"rb\"/\"wb\" binary | seek(0) reset pointer\n#\n#  TEXT FILES:\n#    with open(path, \"r\", encoding=\"utf-8\") as f:\n#        content = f.read()          # whole file (small files)\n#        for line in f: ...          # line-by-line (large files)\n#    with open(path, \"w\") as f:\n#        f.write(text)               # write string\n#        f.writelines(list_of_str)   # write list (no auto-newline)\n#\n#  JSON:\n#    json.dumps(obj)     → string    |  json.dump(obj, file)  → file\n#    json.loads(string)  → dict      |  json.load(file)       → dict\n#    indent=2            pretty      |  separators=(\",\",\":\")   compact\n#    ensure_ascii=False  keep unicode|  default=func           custom types\n#    sort_keys=True      alphabetical|  cls=CustomEncoder      reusable\n#\n#  CSV:\n#    csv.writer(f)        → writerow([...])         rows as lists\n#    csv.DictWriter(f, fieldnames) → writerow({})   rows as dicts\n#    csv.reader(f)        → iterate lists           newline=\"\" ALWAYS\n#    csv.DictReader(f)    → iterate dicts            delimiter=\"\\t\" for TSV\n#\n#  PATHLIB vs OS:\n#    Path(\"a\")/\"b\"/\"c\"        vs  os.path.join(\"a\",\"b\",\"c\")\n#    p.exists() / p.is_file() vs  os.path.exists() / os.path.isfile()\n#    p.read_text()            vs  open()+read()\n#    p.write_text(s)          vs  open()+write()\n#    p.glob(\"*.txt\")          vs  os.listdir() + filter\n#    p.name/stem/suffix       vs  os.path.basename/splitext\n#\n#  ADVANCED:\n#    tempfile.NamedTemporaryFile/TemporaryDirectory  auto-cleanup\n#    shutil.copy/copy2/move/copytree/rmtree          file ops\n#    JSONL: json.dumps() per line, easy append, stream-friendly\n#    Large: for line in f (text) or while chunk:=f.read(8192)\n#    Merge: {**a,**b} or a|b | Deep: recursive merge function\n#\n#  ERRORS: FileNotFoundError, PermissionError, IsADirectoryError,\n#          UnicodeDecodeError, json.JSONDecodeError, OSError\n# ══════════════════════════════════════════════════════════════════\n\n# ╔══════════════════════════════════════════════════╗\n# ║          INTERVIEW GOTCHAS                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── Q: Why use \"with open()\" instead of open/close? ──\n# with = context manager — auto-closes file even if exception occurs\n# BAD:\n#   f = open(\"file.txt\")\n#   data = f.read()\n#   f.close()           # if error happens before this → file stays open!\n# GOOD:\n#   with open(\"file.txt\") as f:\n#       data = f.read()  # file auto-closed when block exits\n\n# ── Q: read() vs readline() vs readlines() vs for loop ──\n# f.read()        → entire file as ONE string (loads all into memory)\n# f.readline()    → ONE line at a time\n# f.readlines()   → ALL lines as a LIST (loads all into memory)\n# for line in f:  → BEST for large files (one line at a time, memory efficient)\n\n# ── Q: \"w\" vs \"a\" vs \"x\" mode ──\n# \"w\" → write (OVERWRITES existing file — data lost!)\n# \"a\" → append (adds to end — existing data preserved)\n# \"x\" → exclusive create (error if file already exists — safe creation)", "reference": ""}, "08-typeddict.py": {"content": "# ══════════════════════════════════════════════════════════════════\n#  PYTHON TypedDict — Condensed Guide\n#  TypedDict = a dict with KNOWN keys and TYPED values\n#  Regular dict[str, Any] → no idea what keys exist\n#  TypedDict → \"this dict MUST have name(str), age(int), email(str)\"\n#  Python does NOT enforce at runtime — type checkers (mypy/pyright) do\n# ══════════════════════════════════════════════════════════════════\n\nfrom typing import TypedDict, NotRequired, Required, get_type_hints, Any\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  BEGINNER                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. Problem — Why Not Just dict? ───────────────\n# dict[str, Any] = \"some keys, some values\" — no safety\n\ndef process_user_bad(user: dict) -> str:\n    return f\"{user['name']} is {user['age']}\"  # what if \"name\" is missing? KeyError at runtime\n\nuser_bad = {\"name\": \"Alice\", \"age\": 30}\nprint(process_user_bad(user_bad))         # works\n# process_user_bad({\"age\": 30})           # KeyError: 'name' — no warning before running\n\n# TypedDict fixes this — type checker catches missing keys BEFORE you run the code\n\n# ── 2. Basic TypedDict ───────────────────────────\n# class Name(TypedDict): → defines which keys are required and their types\nclass User(TypedDict):\n    name: str\n    age: int\n    email: str\n\n# creating — looks like a normal dict\nalice: User = {\"name\": \"Alice\", \"age\": 30, \"email\": \"alice@test.com\"}  # valid\nprint(alice)           # {'name': 'Alice', 'age': 30, 'email': 'alice@test.com'}\nprint(alice[\"name\"])   # Alice — access like normal dict\nprint(type(alice))     # <class 'dict'> — it IS a dict, TypedDict adds no overhead\n\n# these would be caught by mypy/pyright (but Python itself won't stop you):\n# bad1: User = {\"name\": \"Alice\", \"age\": 30}               # missing \"email\"\n# bad2: User = {\"name\": \"Alice\", \"age\": \"thirty\", \"email\": \"a@b.com\"}  # age should be int\n# bad3: User = {\"name\": \"Alice\", \"age\": 30, \"email\": \"a@b.com\", \"extra\": True}  # extra key\n\n# ── 3. Using in Functions ─────────────────────────\ndef greet_user(user: User) -> str:\n    return f\"Hello {user['name']}, age {user['age']}\"\n\ndef create_user(name: str, age: int, email: str) -> User:\n    return {\"name\": name, \"age\": age, \"email\": email}\n\nprint(greet_user(alice))                           # Hello Alice, age 30\nprint(create_user(\"Bob\", 25, \"bob@test.com\"))     # {'name': 'Bob', 'age': 25, ...}\n\n# ── 4. TypedDict vs dict vs dataclass ────────────\n#\n#  dict[str, Any]         → no key safety, no type safety\n#  TypedDict              → key + type safety (type checker only), still a plain dict\n#  dataclass              → real Python class, attrs via dot notation, __init__ generated\n#  Pydantic BaseModel     → runtime validation + auto-conversion\n#\n#  When to use TypedDict:\n#    - Working with JSON / API responses (already dicts)\n#    - FastAPI request/response bodies\n#    - Config dicts you pass around\n#    - Anywhere you want dict[str, Any] but with structure\n#\n#  When to use dataclass instead:\n#    - You want user.name not user[\"name\"]\n#    - You need methods on the object\n#    - You need immutability (frozen=True)\n\n# ╔══════════════════════════════════════════════════╗\n# ║               INTERMEDIATE                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 5. Optional Keys — total=False ────────────────\n# By default all keys are REQUIRED (total=True)\n# total=False → ALL keys become optional\n\nclass Config(TypedDict, total=False):\n    host: str\n    port: int\n    debug: bool\n\nconfig1: Config = {\"host\": \"localhost\"}                    # valid — all optional\nconfig2: Config = {\"host\": \"0.0.0.0\", \"port\": 8080}      # valid\nconfig3: Config = {}                                       # valid — empty is fine\nprint(config1)  # {'host': 'localhost'}\n\n# ── 6. Mix Required + Optional — NotRequired ─────\n# Best approach: keep total=True (default), mark optional keys with NotRequired\nclass APIResponse(TypedDict):\n    status: int                         # required\n    data: dict                          # required\n    error: NotRequired[str]             # optional — can be missing\n    metadata: NotRequired[dict]         # optional\n\nresp1: APIResponse = {\"status\": 200, \"data\": {\"id\": 1}}                         # valid\nresp2: APIResponse = {\"status\": 500, \"data\": {}, \"error\": \"Server Error\"}       # valid\nprint(resp1)  # {'status': 200, 'data': {'id': 1}}\nprint(resp2)  # {'status': 500, 'data': {}, 'error': 'Server Error'}\n\n# ── 7. Opposite — Required in total=False ─────────\n# If most keys are optional but a few are required:\nclass Filters(TypedDict, total=False):\n    query: Required[str]     # this one is required even though total=False\n    page: int                # optional\n    limit: int               # optional\n    sort_by: str             # optional\n\nf1: Filters = {\"query\": \"python\"}                          # valid — only required key\nf2: Filters = {\"query\": \"python\", \"page\": 1, \"limit\": 10} # valid\n# f3: Filters = {\"page\": 1}  # error — \"query\" is required\n\n# ── 8. Nested TypedDict ──────────────────────────\nclass Address(TypedDict):\n    street: str\n    city: str\n    country: str\n\nclass Company(TypedDict):\n    name: str\n    address: Address        # TypedDict inside TypedDict\n\nclass Employee(TypedDict):\n    name: str\n    age: int\n    company: Company\n    tags: list[str]         # list of strings\n\nemp: Employee = {\n    \"name\": \"Alice\",\n    \"age\": 30,\n    \"company\": {\n        \"name\": \"Reuters\",\n        \"address\": {\"street\": \"123 Main\", \"city\": \"London\", \"country\": \"UK\"},\n    },\n    \"tags\": [\"engineering\", \"senior\"],\n}\nprint(emp[\"company\"][\"address\"][\"city\"])  # London\n\n# ── 9. Inheritance — Extend a TypedDict ───────────\nclass BaseUser(TypedDict):\n    name: str\n    email: str\n\nclass AdminUser(BaseUser):     # inherits name + email, adds role + permissions\n    role: str\n    permissions: list[str]\n\nadmin: AdminUser = {\n    \"name\": \"Alice\",\n    \"email\": \"alice@test.com\",\n    \"role\": \"admin\",\n    \"permissions\": [\"read\", \"write\", \"delete\"],\n}\nprint(admin)  # has all 4 keys\n\n# common pattern — base with required, child adds optional\nclass BaseEvent(TypedDict):\n    event_type: str\n    timestamp: str\n\nclass ClickEvent(BaseEvent):\n    page: str\n    x: NotRequired[int]\n    y: NotRequired[int]\n\nclick: ClickEvent = {\"event_type\": \"click\", \"timestamp\": \"2024-01-15T10:30:00\", \"page\": \"/home\"}\nprint(click)\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  ADVANCED                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 10. Functional Syntax — keys with spaces/hyphens ─\n# class syntax doesn't allow \"content-type\" as a key name\n# functional syntax does:\nHTTPHeaders = TypedDict(\"HTTPHeaders\", {\n    \"content-type\": str,\n    \"x-request-id\": str,\n    \"authorization\": str,\n})\nheaders: HTTPHeaders = {\n    \"content-type\": \"application/json\",\n    \"x-request-id\": \"abc-123\",\n    \"authorization\": \"Bearer token123\",\n}\nprint(headers[\"content-type\"])  # application/json\n\n# ── 11. Runtime Inspection ────────────────────────\n# TypedDict stores type info — you can read it at runtime\nprint(User.__annotations__)          # {'name': <class 'str'>, 'age': <class 'int'>, 'email': <class 'str'>}\nprint(User.__required_keys__)        # frozenset({'name', 'age', 'email'})\nprint(User.__optional_keys__)        # frozenset()\n\nprint(APIResponse.__required_keys__)   # frozenset({'status', 'data'})\nprint(APIResponse.__optional_keys__)   # frozenset({'error', 'metadata'})\n\nhints = get_type_hints(Employee)\nprint(hints)  # {'name': str, 'age': int, 'company': Company, 'tags': list[str]}\n\n# ── 12. TypedDict with JSON / API Responses ──────\n# Most common real-world use — typing API responses\nimport json\n\nclass PaginatedResponse(TypedDict):\n    total: int\n    page: int\n    per_page: int\n    items: list[dict[str, Any]]\n    next_page: NotRequired[str | None]\n\ndef parse_api_response(raw_json: str) -> PaginatedResponse:\n    data: PaginatedResponse = json.loads(raw_json)\n    return data\n\nraw = '{\"total\": 100, \"page\": 1, \"per_page\": 10, \"items\": [{\"id\": 1}]}'\nresponse = parse_api_response(raw)\nprint(f\"Page {response['page']} of {response['total']} items\")  # Page 1 of 100 items\n\n# ── 13. TypedDict Does NOT Validate at Runtime ───\n# THIS IS THE KEY THING TO UNDERSTAND\n# TypedDict is ONLY for type checkers (mypy/pyright) — Python ignores it\n\nwrong_user: User = {\"name\": 123, \"age\": \"thirty\", \"email\": True}  # type: ignore\nprint(wrong_user)  # runs fine! {'name': 123, 'age': 'thirty', 'email': True}\n\n# If you need runtime validation → use Pydantic\n# from pydantic import TypeAdapter\n# adapter = TypeAdapter(User)\n# adapter.validate_python({\"name\": 123, \"age\": \"thirty\"})  # → ValidationError\n\n# ── 14. Pattern — Config / Settings ──────────────\nclass DBConfig(TypedDict):\n    host: str\n    port: int\n    database: str\n    username: str\n    password: str\n    pool_size: NotRequired[int]\n    ssl: NotRequired[bool]\n\nclass AppSettings(TypedDict):\n    app_name: str\n    debug: bool\n    db: DBConfig\n    allowed_origins: list[str]\n\nsettings: AppSettings = {\n    \"app_name\": \"MyAPI\",\n    \"debug\": True,\n    \"db\": {\n        \"host\": \"localhost\",\n        \"port\": 5432,\n        \"database\": \"mydb\",\n        \"username\": \"admin\",\n        \"password\": \"secret\",\n        \"pool_size\": 10,\n    },\n    \"allowed_origins\": [\"http://localhost:3000\"],\n}\nprint(settings[\"db\"][\"host\"])  # localhost\n\n# ── 15. Pattern — FastAPI / LLM Tool Parameters ──\nclass ToolInput(TypedDict):\n    query: str\n    max_results: NotRequired[int]\n    filters: NotRequired[dict[str, str]]\n\nclass ToolOutput(TypedDict):\n    status: str\n    results: list[dict[str, Any]]\n    error: NotRequired[str]\n\ndef search_tool(params: ToolInput) -> ToolOutput:\n    return {\n        \"status\": \"success\",\n        \"results\": [{\"title\": f\"Result for: {params['query']}\"}],\n    }\n\nprint(search_tool({\"query\": \"python typeddict\"}))", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n#  CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\n#\n#  DEFINE:\n#    class Name(TypedDict):              all keys required\n#    class Name(TypedDict, total=False): all keys optional\n#\n#  OPTIONAL KEYS:\n#    key: NotRequired[str]    optional in total=True  (default)\n#    key: Required[str]       required in total=False\n#\n#  INHERIT:\n#    class Child(Parent):     inherits all parent keys, adds new ones\n#\n#  FUNCTIONAL (special key names):\n#    Name = TypedDict(\"Name\", {\"x-key\": str, \"another\": int})\n#\n#  RUNTIME INSPECTION:\n#    MyDict.__annotations__     → {key: type, ...}\n#    MyDict.__required_keys__   → frozenset of required\n#    MyDict.__optional_keys__   → frozenset of optional\n#    get_type_hints(MyDict)     → resolved types\n#\n#  KEY FACTS:\n#    - TypedDict is a PLAIN dict at runtime — zero overhead\n#    - Python does NOT enforce types — only mypy/pyright do\n#    - For runtime validation → use Pydantic\n#    - Best for: JSON, API responses, configs, function params\n#\n#  vs OTHER OPTIONS:\n#    dict[str, Any]     → no safety\n#    TypedDict          → type checker safety, still a dict\n#    dataclass          → real class, dot access, methods\n#    NamedTuple         → immutable, tuple-like\n#    Pydantic BaseModel → runtime validation + conversion\n# ══════════════════════════════════════════════════════════════════\n\n# ╔══════════════════════════════════════════════════╗\n# ║          INTERVIEW GOTCHAS                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── Q: Does TypedDict validate at runtime? ──\nclass StrictUser(TypedDict):\n    name: str\n    age: int\n\nwrong: StrictUser = {\"name\": 123, \"age\": \"thirty\"}  # type: ignore\nprint(wrong)  # runs fine! {'name': 123, 'age': 'thirty'}\n# TypedDict is ONLY for type checkers — Python ignores it completely\n# For runtime validation → use Pydantic\n\n# ── Q: TypedDict vs dataclass — when to use which? ──\n# TypedDict → when data is already a dict (JSON, API responses, configs)\n# dataclass → when you want user.name (dot access), methods, immutability\n\n# ── Q: What's the difference between total=False and NotRequired? ──\n# total=False → makes ALL keys optional\n# NotRequired → makes INDIVIDUAL keys optional (more precise)\n# Use NotRequired when most keys are required but a few are optional", "reference": ""}, "09-pydantic-basics.py": {"content": "# ══════════════════════════════════════════════════════════════════\n#  PYDANTIC — Condensed Guide (Pure Python, no FastAPI)\n#  Pydantic = data validation & parsing using Python type hints\n#  Instead of manually checking types, lengths, formats,\n#  Pydantic does it automatically and gives clear errors\n# ══════════════════════════════════════════════════════════════════\nfrom pydantic import (\n    BaseModel, Field, field_validator, model_validator,\n    ConfigDict, EmailStr, computed_field, ValidationError,\n    field_serializer, model_serializer,\n)\nfrom typing import Optional, Literal\nfrom datetime import datetime, date\nfrom enum import Enum\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  BEGINNER                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. The Problem — Why Pydantic? ────────────────\n# Without Pydantic: manual checks everywhere, easy to miss things\n\ndef create_user_manual(data: dict):\n    if not isinstance(data.get(\"name\"), str):\n        raise ValueError(\"name must be a string\")\n    if not isinstance(data.get(\"age\"), int):\n        raise ValueError(\"age must be an int\")\n    if data[\"age\"] < 0:\n        raise ValueError(\"age must be positive\")\n    # ... 50 more checks for every field ...\n    return data\n\n# With Pydantic: declare the shape, validation is automatic\nfrom pydantic import BaseModel\n\nclass User(BaseModel):\n    name: str\n    age: int\n\nuser = User(name=\"Alice\", age=30)\nprint(user)          # name='Alice' age=30\nprint(user.name)     # Alice\nprint(user.age)      # 30\n\n# ── 2. Automatic Type Coercion ───────────────────\n# Pydantic CONVERTS compatible types (str→int, int→float, etc.)\n\nuser2 = User(name=\"Bob\", age=\"25\")     # \"25\" → 25 (str→int)\nprint(user2.age)                        # 25 (int, not str!)\nprint(type(user2.age))                  # <class 'int'>\n\n# but it won't force impossible conversions:\ntry:\n    User(name=\"Charlie\", age=\"not_a_number\")\nexcept ValidationError as e:\n    print(e)\n    # Input should be a valid integer, unable to parse string as an integer\n\n# ── 3. Validation Errors ────────────────────────\n# Missing fields, wrong types → clear error messages\n\ntry:\n    User(name=\"Dave\")   # missing 'age'\nexcept ValidationError as e:\n    print(e)\n    # age - Field required\n\ntry:\n    User(name=123, age=\"abc\")\nexcept ValidationError as e:\n    print(e.error_count())    # 1 (name coerces 123→\"123\", age fails)\n    for err in e.errors():\n        print(f\"  {err['loc']}: {err['msg']}\")\n\n# ── 4. Optional & Default Values ─────────────────\n\nclass UserWithDefaults(BaseModel):\n    name: str\n    age: int = 0                        # default value\n    email: Optional[str] = None         # optional, defaults to None\n    role: str = \"user\"                  # default\n\nu1 = UserWithDefaults(name=\"Eve\")\nprint(u1)   # name='Eve' age=0 email=None role='user'\n\nu2 = UserWithDefaults(name=\"Frank\", age=28, email=\"frank@example.com\")\nprint(u2)   # name='Frank' age=28 email='frank@example.com' role='user'\n\n# ── 5. Nested Models ────────────────────────────\n# Models inside models — validated recursively\n\nclass Address(BaseModel):\n    street: str\n    city: str\n    zip_code: str\n\nclass Employee(BaseModel):\n    name: str\n    address: Address           # nested model\n\nemp = Employee(\n    name=\"Grace\",\n    address={\"street\": \"123 Main St\", \"city\": \"Springfield\", \"zip_code\": \"62701\"}\n)\nprint(emp.address.city)        # Springfield\n# the dict is automatically parsed into an Address object!\n\n# ── 6. Model Methods — .model_dump() & .model_validate() ─\n\nclass Product(BaseModel):\n    name: str\n    price: float\n    in_stock: bool = True\n\np = Product(name=\"Widget\", price=9.99)\n\n# model → dict\ndata = p.model_dump()\nprint(data)   # {'name': 'Widget', 'price': 9.99, 'in_stock': True}\n\n# dict → model\np2 = Product.model_validate({\"name\": \"Gadget\", \"price\": 19.99})\nprint(p2)     # name='Gadget' price=19.99 in_stock=True\n\n# model → JSON string\njson_str = p.model_dump_json()\nprint(json_str)   # {\"name\":\"Widget\",\"price\":9.99,\"in_stock\":true}\n\n# JSON string → model\np3 = Product.model_validate_json('{\"name\": \"Doohickey\", \"price\": 5.0}')\nprint(p3)         # name='Doohickey' price=5.0 in_stock=True\n\n# ── 7. List & Dict Fields ───────────────────────\n\nclass Team(BaseModel):\n    name: str\n    members: list[str]\n    scores: dict[str, int]\n\nteam = Team(\n    name=\"Alpha\",\n    members=[\"Alice\", \"Bob\", \"Charlie\"],\n    scores={\"Alice\": 95, \"Bob\": 87, \"Charlie\": 92}\n)\nprint(team.members[0])        # Alice\nprint(team.scores[\"Bob\"])     # 87\n\n\n# ╔══════════════════════════════════════════════════╗\n# ║               INTERMEDIATE                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 8. Field() — Constraints & Metadata ──────────\n# Field() adds validation rules: min, max, length, regex, etc.\n\nclass Item(BaseModel):\n    name: str = Field(min_length=1, max_length=100)\n    price: float = Field(gt=0, description=\"Price must be positive\")\n    quantity: int = Field(ge=0, le=10000, default=0)\n    tags: list[str] = Field(default_factory=list, max_length=10)\n\nitem = Item(name=\"Laptop\", price=999.99, quantity=5, tags=[\"electronics\"])\nprint(item)\n\ntry:\n    Item(name=\"\", price=-10, quantity=-1)\nexcept ValidationError as e:\n    for err in e.errors():\n        print(f\"  {err['loc']}: {err['msg']}\")\n    # ('name',): String should have at least 1 character\n    # ('price',): Input should be greater than 0\n    # ('quantity',): Input should be greater than or equal to 0\n\n# ── 9. field_validator — Custom Validation ───────\n# Add your own validation logic per field\n\nclass SignupForm(BaseModel):\n    username: str\n    password: str\n    age: int\n\n    @field_validator(\"username\")\n    @classmethod\n    def username_must_be_alphanumeric(cls, v):\n        if not v.isalnum():\n            raise ValueError(\"username must be alphanumeric\")\n        return v.lower()    # transform: always lowercase\n\n    @field_validator(\"password\")\n    @classmethod\n    def password_strength(cls, v):\n        if len(v) < 8:\n            raise ValueError(\"password must be at least 8 characters\")\n        if not any(c.isupper() for c in v):\n            raise ValueError(\"password must contain an uppercase letter\")\n        return v\n\nsignup = SignupForm(username=\"Alice123\", password=\"SecurePass1\", age=25)\nprint(signup.username)   # alice123 (lowercased by validator)\n\ntry:\n    SignupForm(username=\"bad user!\", password=\"short\", age=25)\nexcept ValidationError as e:\n    for err in e.errors():\n        print(f\"  {err['loc']}: {err['msg']}\")\n\n# ── 10. model_validator — Cross-Field Validation ─\n# Validate fields that depend on EACH OTHER\n\nclass DateRange(BaseModel):\n    start_date: date\n    end_date: date\n\n    @model_validator(mode=\"after\")\n    def end_after_start(self):\n        if self.end_date <= self.start_date:\n            raise ValueError(\"end_date must be after start_date\")\n        return self\n\nvalid = DateRange(start_date=\"2024-01-01\", end_date=\"2024-12-31\")\nprint(valid)\n\ntry:\n    DateRange(start_date=\"2024-12-31\", end_date=\"2024-01-01\")\nexcept ValidationError as e:\n    print(e)   # end_date must be after start_date\n\n# ── 11. Enum Fields & Literal ────────────────────\n\nclass Status(str, Enum):\n    ACTIVE = \"active\"\n    INACTIVE = \"inactive\"\n    SUSPENDED = \"suspended\"\n\nclass Account(BaseModel):\n    name: str\n    status: Status\n    priority: Literal[\"low\", \"medium\", \"high\"]   # only these 3 values\n\nacc = Account(name=\"Acme\", status=\"active\", priority=\"high\")\nprint(acc.status)          # Status.ACTIVE\nprint(acc.status.value)    # active\nprint(acc.priority)        # high\n\ntry:\n    Account(name=\"Bad\", status=\"deleted\", priority=\"urgent\")\nexcept ValidationError as e:\n    for err in e.errors():\n        print(f\"  {err['loc']}: {err['msg']}\")\n\n# ── 12. computed_field — Derived Properties ──────\n# Fields calculated from other fields, included in serialization\n\nclass Rectangle(BaseModel):\n    width: float\n    height: float\n\n    @computed_field\n    @property\n    def area(self) -> float:\n        return self.width * self.height\n\n    @computed_field\n    @property\n    def perimeter(self) -> float:\n        return 2 * (self.width + self.height)\n\nrect = Rectangle(width=5, height=3)\nprint(rect.area)           # 15.0\nprint(rect.perimeter)      # 16.0\nprint(rect.model_dump())   # {'width': 5.0, 'height': 3.0, 'area': 15.0, 'perimeter': 16.0}\n\n# ── 13. Immutable Models (frozen) ────────────────\n# Prevent modification after creation\n\nclass Config(BaseModel):\n    model_config = ConfigDict(frozen=True)\n\n    db_host: str\n    db_port: int = 5432\n\nconfig = Config(db_host=\"localhost\")\nprint(config.db_host)       # localhost\n\ntry:\n    config.db_host = \"remote\"   # can't modify!\nexcept ValidationError as e:\n    print(\"Cannot modify frozen model\")\n\n# ── 14. Model Inheritance ────────────────────────\n\nclass BaseUser(BaseModel):\n    id: int\n    name: str\n    email: str\n\nclass AdminUser(BaseUser):\n    permissions: list[str]\n    department: str\n\nclass GuestUser(BaseUser):\n    expires_at: datetime\n    access_level: Literal[\"read\", \"write\"] = \"read\"\n\nadmin = AdminUser(\n    id=1, name=\"Admin\", email=\"admin@co.com\",\n    permissions=[\"create\", \"delete\"], department=\"IT\"\n)\nguest = GuestUser(\n    id=2, name=\"Guest\", email=\"guest@co.com\",\n    expires_at=\"2025-12-31T23:59:59\"\n)\nprint(admin)\nprint(guest)\nprint(isinstance(admin, BaseUser))   # True\n\n# ── 15. Aliases — Different Names for Input/Output ─\n# API sends \"firstName\" but you want \"first_name\" in Python\n\nclass APIResponse(BaseModel):\n    model_config = ConfigDict(populate_by_name=True)\n\n    first_name: str = Field(alias=\"firstName\")\n    last_name: str = Field(alias=\"lastName\")\n    email_address: str = Field(alias=\"emailAddress\")\n\n# works with alias (from API)\nresp = APIResponse(firstName=\"Jane\", lastName=\"Doe\", emailAddress=\"jane@co.com\")\nprint(resp.first_name)     # Jane\n\n# also works with Python name (populate_by_name=True)\nresp2 = APIResponse(first_name=\"John\", last_name=\"Smith\", email_address=\"john@co.com\")\nprint(resp2.first_name)    # John\n\n# serialize with aliases\nprint(resp.model_dump(by_alias=True))\n# {'firstName': 'Jane', 'lastName': 'Doe', 'emailAddress': 'jane@co.com'}\n\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  ADVANCED                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 16. Discriminated Unions — Polymorphic Models ─\n# Different model types in the same field, chosen by a \"type\" field\n\nfrom typing import Annotated, Union\n\nclass CreditCard(BaseModel):\n    type: Literal[\"credit_card\"]\n    card_number: str\n    cvv: str\n\nclass BankTransfer(BaseModel):\n    type: Literal[\"bank_transfer\"]\n    account_number: str\n    routing_number: str\n\nclass PayPal(BaseModel):\n    type: Literal[\"paypal\"]\n    email: str\n\nPaymentMethod = Annotated[\n    Union[CreditCard, BankTransfer, PayPal],\n    Field(discriminator=\"type\")\n]\n\nclass Order(BaseModel):\n    order_id: int\n    payment: PaymentMethod\n\n# Pydantic picks the right model based on \"type\"\no1 = Order(order_id=1, payment={\"type\": \"credit_card\", \"card_number\": \"4111...\", \"cvv\": \"123\"})\no2 = Order(order_id=2, payment={\"type\": \"paypal\", \"email\": \"user@co.com\"})\n\nprint(type(o1.payment))   # <class 'CreditCard'>\nprint(type(o2.payment))   # <class 'PayPal'>\n\n# ── 17. Custom Serialization ────────────────────\n# Control how fields are exported to dict/JSON\n\nclass Event(BaseModel):\n    name: str\n    timestamp: datetime\n\n    @field_serializer(\"timestamp\")\n    def serialize_timestamp(self, v: datetime, _info):\n        return v.strftime(\"%Y-%m-%d %H:%M\")\n\nevent = Event(name=\"Launch\", timestamp=\"2025-06-15T14:30:00\")\nprint(event.model_dump())\n# {'name': 'Launch', 'timestamp': '2025-06-15 14:30'}\n\n# ── 18. Strict Mode — No Coercion ───────────────\n# By default Pydantic coerces \"25\" → 25\n# Strict mode: \"25\" stays str → validation error\n\nclass StrictUser(BaseModel):\n    model_config = ConfigDict(strict=True)\n\n    name: str\n    age: int\n\nstrict_user = StrictUser(name=\"Alice\", age=30)   # OK\nprint(strict_user)\n\ntry:\n    StrictUser(name=\"Bob\", age=\"25\")   # FAILS in strict mode!\nexcept ValidationError as e:\n    print(\"Strict mode: str not accepted for int field\")\n\n# ── 19. model_validator mode=\"before\" — Raw Data ─\n# Validate/transform data BEFORE Pydantic parses it\n\nclass FlexibleUser(BaseModel):\n    name: str\n    age: int\n\n    @model_validator(mode=\"before\")\n    @classmethod\n    def handle_full_name(cls, data):\n        if isinstance(data, dict) and \"full_name\" in data:\n            data[\"name\"] = data.pop(\"full_name\")\n        return data\n\nu = FlexibleUser(full_name=\"Alice Smith\", age=30)\nprint(u.name)   # Alice Smith\n\n# ── 20. Generic Models ──────────────────────────\n# Reusable model templates with type parameters\n\nfrom typing import Generic, TypeVar\n\nT = TypeVar(\"T\")\n\nclass PaginatedResponse(BaseModel, Generic[T]):\n    items: list[T]\n    total: int\n    page: int\n    per_page: int\n\n    @computed_field\n    @property\n    def total_pages(self) -> int:\n        return (self.total + self.per_page - 1) // self.per_page\n\n# use with any model\nclass UserItem(BaseModel):\n    name: str\n    email: str\n\nresponse = PaginatedResponse[UserItem](\n    items=[\n        {\"name\": \"Alice\", \"email\": \"alice@co.com\"},\n        {\"name\": \"Bob\", \"email\": \"bob@co.com\"},\n    ],\n    total=50,\n    page=1,\n    per_page=10,\n)\nprint(response.total_pages)   # 5\nprint(response.items[0].name) # Alice\n\n# ── 21. JSON Schema Generation ──────────────────\n# Pydantic models can generate JSON schemas (useful for APIs, docs)\n\nclass Task(BaseModel):\n    \"\"\"A task in the todo list.\"\"\"\n    title: str = Field(description=\"Task title\", examples=[\"Buy groceries\"])\n    done: bool = Field(default=False, description=\"Completion status\")\n    priority: Literal[\"low\", \"medium\", \"high\"] = \"medium\"\n\nimport json\nschema = Task.model_json_schema()\nprint(json.dumps(schema, indent=2))\n# generates full JSON Schema with types, descriptions, examples, etc.\n\n# ── 22. Custom Types with Annotated ─────────────\n# Create reusable validation rules\n\nfrom pydantic import AfterValidator\nfrom typing import Annotated\n\ndef must_be_positive(v: int) -> int:\n    if v <= 0:\n        raise ValueError(\"must be positive\")\n    return v\n\nPositiveInt = Annotated[int, AfterValidator(must_be_positive)]\n\nclass Invoice(BaseModel):\n    amount: PositiveInt\n    quantity: PositiveInt\n\ninv = Invoice(amount=100, quantity=5)\nprint(inv)\n\ntry:\n    Invoice(amount=-50, quantity=0)\nexcept ValidationError as e:\n    for err in e.errors():\n        print(f\"  {err['loc']}: {err['msg']}\")", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n#  CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\n#\n#  BASICS:\n#    class MyModel(BaseModel):       define a model\n#    field: type                     required field\n#    field: type = default           field with default\n#    field: Optional[type] = None    optional field\n#\n#  CREATING INSTANCES:\n#    m = MyModel(field=value)        from kwargs\n#    m = MyModel.model_validate(d)   from dict\n#    m = MyModel.model_validate_json(s)  from JSON string\n#\n#  EXPORTING:\n#    m.model_dump()                  → dict\n#    m.model_dump(by_alias=True)     → dict with alias names\n#    m.model_dump(exclude={\"field\"}) → dict without field\n#    m.model_dump_json()             → JSON string\n#\n#  FIELD CONSTRAINTS (Field()):\n#    gt, ge, lt, le                  numeric bounds\n#    min_length, max_length          string/list length\n#    pattern                         regex pattern\n#    default, default_factory        default values\n#    alias                           alternative input name\n#\n#  VALIDATORS:\n#    @field_validator(\"field\")       validate one field\n#    @model_validator(mode=\"after\")  validate across fields (parsed data)\n#    @model_validator(mode=\"before\") validate/transform raw input\n#\n#  SERIALIZATION:\n#    @field_serializer(\"field\")      custom field output\n#    @computed_field + @property     derived field in output\n#\n#  CONFIG (model_config = ConfigDict(...)):\n#    frozen=True                     immutable model\n#    strict=True                     no type coercion\n#    populate_by_name=True           allow both alias & field name\n#    str_strip_whitespace=True       auto-strip strings\n#    extra=\"forbid\"                  error on unknown fields\n#\n#  ADVANCED:\n#    Generic[T]                      reusable model templates\n#    Literal[\"a\",\"b\"]                restrict to specific values\n#    Annotated[type, validator]      reusable custom types\n#    Field(discriminator=\"type\")     polymorphic unions\n#    model_json_schema()             generate JSON Schema\n#\n#  KEY RULES:\n#    Pydantic v2 uses model_dump()   not .dict() (v1)\n#    Pydantic v2 uses model_validate()  not .parse_obj() (v1)\n#    field_validator replaces         @validator (v1)\n#    model_validator replaces         @root_validator (v1)\n#    ConfigDict replaces              class Config (v1)\n# ══════════════════════════════════════════════════════════════════\n\n# ╔══════════════════════════════════════════════════╗\n# ║          INTERVIEW GOTCHAS                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── Q: What's the difference between Pydantic v1 and v2? ──\n# v2: rewritten in Rust (faster), new API names:\n#   .dict() → .model_dump()\n#   .parse_obj() → .model_validate()\n#   @validator → @field_validator\n#   @root_validator → @model_validator\n#   class Config → model_config = ConfigDict(...)\n# v2 is 5-50x faster than v1\n\n# ── Q: Does Pydantic validate at assignment or creation? ──\n# By default: only at creation (MyModel(field=value))\n# After creation: m.field = \"bad\" → NO validation\n# To validate on assignment: model_config = ConfigDict(validate_assignment=True)\n\n# ── Q: BaseModel vs dataclass — when to use which? ──\n# BaseModel → validation, serialization, APIs, external data\n# dataclass → internal data structures, no validation needed\n# Pydantic also has @pydantic.dataclass — dataclass syntax + validation\n\n# ── Q: What does model_validate() do vs __init__? ──\n# Both validate. model_validate() accepts dict/object, __init__() accepts kwargs\n# model_validate() also handles nested parsing and ORM objects\n\n# ── Q: How does Pydantic handle extra fields? ──\n# Default: extra fields are IGNORED (silently dropped)\n# extra=\"forbid\" → raises error on unknown fields\n# extra=\"allow\" → stores extra fields in model.__pydantic_extra__\n\n# ── Q: Can Pydantic validate function arguments? ──\n# Yes — use @pydantic.validate_call:\n#   from pydantic import validate_call\n#   @validate_call\n#   def greet(name: str, age: int) -> str:\n#       return f\"Hi {name}, age {age}\"\n#   greet(\"Alice\", \"30\")  # \"30\" → 30 automatically", "reference": ""}, "10-async-await.py": {"content": "# ══════════════════════════════════════════════════════════════════\n#  PYTHON ASYNC/AWAIT — Condensed Guide (Pure Python, no FastAPI)\n#  async/await = write concurrent code that WAITS efficiently\n#  Instead of blocking (freezing) while waiting for I/O,\n#  Python switches to other tasks and comes back when ready\n# ══════════════════════════════════════════════════════════════════\nimport asyncio\nimport time\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  BEGINNER                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 1. The Problem — Why Async? ───────────────────\n# Sync = one thing at a time, BLOCKS while waiting\n# Async = start waiting tasks, switch to other work, come back when done\n\n# SYNC — total time: 3 seconds (waits for each one)\ndef sync_example():\n    time.sleep(1)    # blocks 1s — program frozen\n    time.sleep(1)    # blocks 1s\n    time.sleep(1)    # blocks 1s\n\n# ASYNC — total time: 1 second (all 3 wait at the same time)\nasync def async_example():\n    await asyncio.gather(\n        asyncio.sleep(1),   # starts waiting\n        asyncio.sleep(1),   # starts waiting at SAME time\n        asyncio.sleep(1),   # starts waiting at SAME time\n    )\n\n# ── 2. Basic async/await ─────────────────────────\n# async def → makes a COROUTINE (not a regular function)\n# await     → pauses here, lets other tasks run, resumes when done\n\nasync def greet(name):\n    print(f\"Hello {name}!\")\n    await asyncio.sleep(1)          # non-blocking wait (other tasks can run)\n    print(f\"Goodbye {name}!\")\n\n# calling a coroutine:\n# greet(\"Alice\")              # WRONG — returns coroutine object, doesn't run!\n# await greet(\"Alice\")        # RIGHT — but only works inside another async func\n# asyncio.run(greet(\"Alice\")) # RIGHT — entry point from sync code\n\nasyncio.run(greet(\"Alice\"))\n# Output: Hello Alice! → (1s pause) → Goodbye Alice!\n\n# ── 3. asyncio.run() — The Entry Point ───────────\n# asyncio.run() = starts the event loop and runs ONE coroutine\n# You call this ONCE from sync code — everything else uses await\n\nasync def main():\n    print(\"start\")\n    await asyncio.sleep(0.5)\n    print(\"done\")\n\nasyncio.run(main())\n# asyncio.run() does: create event loop → run main() → close loop\n\n# ── 4. Coroutine vs Regular Function ─────────────\ndef regular():\n    return \"I run immediately\"\n\nasync def coroutine():\n    return \"I need to be awaited\"\n\nprint(regular())               # \"I run immediately\"\nprint(coroutine())             # <coroutine object ...> — NOT the result!\n# print(await coroutine())     # \"I need to be awaited\" — only inside async\n\n# ── 5. Sequential vs Concurrent ──────────────────\nasync def fetch_data(name, seconds):\n    print(f\"  Fetching {name}...\")\n    await asyncio.sleep(seconds)\n    print(f\"  Got {name}!\")\n    return f\"{name} data\"\n\n# SEQUENTIAL — one after another (slow)\nasync def sequential():\n    start = time.time()\n    a = await fetch_data(\"users\", 1)      # wait 1s\n    b = await fetch_data(\"orders\", 1)     # wait 1s\n    c = await fetch_data(\"products\", 1)   # wait 1s\n    print(f\"  Sequential: {time.time() - start:.1f}s\")  # ~3.0s\n\n# CONCURRENT — all at once (fast)\nasync def concurrent():\n    start = time.time()\n    a, b, c = await asyncio.gather(\n        fetch_data(\"users\", 1),            # starts immediately\n        fetch_data(\"orders\", 1),           # starts immediately\n        fetch_data(\"products\", 1),         # starts immediately\n    )\n    print(f\"  Concurrent: {time.time() - start:.1f}s\")  # ~1.0s\n\nprint(\"\\n--- Sequential ---\")\nasyncio.run(sequential())\nprint(\"\\n--- Concurrent ---\")\nasyncio.run(concurrent())\n\n\n# ╔══════════════════════════════════════════════════╗\n# ║               INTERMEDIATE                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 6. asyncio.gather() — Run Multiple Coroutines ─\n# gather = run all, wait for ALL to finish, return results in order\n\nasync def gather_example():\n    results = await asyncio.gather(\n        fetch_data(\"A\", 2),\n        fetch_data(\"B\", 1),\n        fetch_data(\"C\", 3),\n    )\n    print(f\"  Results: {results}\")   # ['A data', 'B data', 'C data'] — order preserved\n    # Total time: ~3s (slowest), not 6s (sum)\n\nasyncio.run(gather_example())\n\n# ── 7. asyncio.gather() — Error Handling ─────────\nasync def might_fail(name, fail=False):\n    await asyncio.sleep(0.5)\n    if fail:\n        raise ValueError(f\"{name} failed!\")\n    return f\"{name} ok\"\n\n# return_exceptions=True → errors returned as values, not raised\nasync def gather_errors():\n    results = await asyncio.gather(\n        might_fail(\"A\"),\n        might_fail(\"B\", fail=True),\n        might_fail(\"C\"),\n        return_exceptions=True,      # don't crash, collect errors\n    )\n    for r in results:\n        if isinstance(r, Exception):\n            print(f\"  Error: {r}\")\n        else:\n            print(f\"  Success: {r}\")\n\nasyncio.run(gather_errors())\n# Success: A ok\n# Error: B failed!\n# Success: C ok\n\n# ── 8. create_task() — Fire and Continue ──────────\n# create_task = schedule coroutine to run in background\n# You can do other work while it runs\n\nasync def background_job(name, seconds):\n    await asyncio.sleep(seconds)\n    print(f\"  Background {name} done!\")\n    return f\"{name} result\"\n\nasync def create_task_example():\n    # schedule tasks — they start running immediately\n    task1 = asyncio.create_task(background_job(\"download\", 2))\n    task2 = asyncio.create_task(background_job(\"upload\", 1))\n\n    print(\"  Tasks scheduled, doing other work...\")\n    await asyncio.sleep(0.5)\n    print(\"  Still working...\")\n\n    # await when you need the results\n    result1 = await task1\n    result2 = await task2\n    print(f\"  Results: {result1}, {result2}\")\n\nasyncio.run(create_task_example())\n\n# ── 9. gather() vs create_task() ─────────────────\n#\n#  gather():\n#    results = await asyncio.gather(coro1(), coro2())\n#    → runs all, waits for ALL, returns results as list\n#    → best when: you need all results together\n#\n#  create_task():\n#    task = asyncio.create_task(coro())\n#    → schedules task, returns immediately\n#    → await task later when you need the result\n#    → best when: you want to do other work in between\n\n# ── 10. Timeouts — asyncio.wait_for() ────────────\nasync def slow_operation():\n    await asyncio.sleep(10)\n    return \"done\"\n\nasync def timeout_example():\n    try:\n        result = await asyncio.wait_for(slow_operation(), timeout=2.0)\n    except asyncio.TimeoutError:\n        print(\"  Timed out after 2 seconds!\")\n\nasyncio.run(timeout_example())\n\n# ── 11. async for — Async Iteration ──────────────\n# Process items as they arrive (streaming, pagination, etc.)\n\nasync def fetch_pages():\n    for page in range(1, 4):\n        await asyncio.sleep(0.5)    # simulate API call\n        yield {\"page\": page, \"items\": [f\"item_{page}_{i}\" for i in range(3)]}\n\nasync def async_for_example():\n    async for page_data in fetch_pages():\n        print(f\"  Got page {page_data['page']}: {page_data['items']}\")\n\nasyncio.run(async_for_example())\n\n# ── 12. async with — Async Context Manager ───────\n# Like \"with open()\" but for async resources (DB connections, HTTP clients)\n\nclass AsyncDBConnection:\n    async def __aenter__(self):\n        print(\"  Connecting to DB...\")\n        await asyncio.sleep(0.3)\n        print(\"  Connected!\")\n        return self\n\n    async def __aexit__(self, exc_type, exc_val, exc_tb):\n        print(\"  Closing DB connection...\")\n        await asyncio.sleep(0.1)\n        print(\"  Closed!\")\n\n    async def query(self, sql):\n        await asyncio.sleep(0.2)\n        return [{\"id\": 1, \"name\": \"Alice\"}]\n\nasync def async_with_example():\n    async with AsyncDBConnection() as db:\n        results = await db.query(\"SELECT * FROM users\")\n        print(f\"  Results: {results}\")\n    # connection auto-closed here\n\nasyncio.run(async_with_example())\n\n\n# ╔══════════════════════════════════════════════════╗\n# ║                  ADVANCED                        ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── 13. Semaphore — Limit Concurrency ────────────\n# Problem: gather() with 1000 API calls → overwhelms the server\n# Semaphore = \"only N tasks at a time\"\n\nasync def limited_fetch(sem, name):\n    async with sem:              # only enters if < N tasks inside\n        print(f\"  Fetching {name}...\")\n        await asyncio.sleep(1)\n        print(f\"  Done {name}\")\n        return f\"{name} data\"\n\nasync def semaphore_example():\n    sem = asyncio.Semaphore(3)   # max 3 concurrent tasks\n    tasks = [limited_fetch(sem, f\"item-{i}\") for i in range(8)]\n    results = await asyncio.gather(*tasks)\n    print(f\"  Got {len(results)} results\")\n    # runs 3 at a time: [0,1,2] → [3,4,5] → [6,7]\n\nasyncio.run(semaphore_example())\n\n# ── 14. Lock — Prevent Race Conditions ───────────\n# When multiple tasks read/write the same variable\n\ncounter = 0\n\nasync def unsafe_increment(n):\n    global counter\n    for _ in range(n):\n        temp = counter\n        await asyncio.sleep(0)   # yield control — another task can change counter!\n        counter = temp + 1\n\nasync def safe_increment(lock, n):\n    global counter\n    for _ in range(n):\n        async with lock:         # only one task at a time\n            temp = counter\n            await asyncio.sleep(0)\n            counter = temp + 1\n\nasync def lock_example():\n    global counter\n\n    # UNSAFE — race condition\n    counter = 0\n    await asyncio.gather(unsafe_increment(100), unsafe_increment(100))\n    print(f\"  Unsafe counter: {counter}\")   # likely < 200!\n\n    # SAFE — with lock\n    counter = 0\n    lock = asyncio.Lock()\n    await asyncio.gather(safe_increment(lock, 100), safe_increment(lock, 100))\n    print(f\"  Safe counter: {counter}\")     # always 200\n\nasyncio.run(lock_example())\n\n# ── 15. Queue — Producer/Consumer Pattern ────────\n# Producer adds items, consumer processes them — decoupled\n\nasync def producer(queue, name, items):\n    for item in items:\n        await asyncio.sleep(0.2)\n        await queue.put(f\"{name}:{item}\")\n        print(f\"  Produced {name}:{item}\")\n    await queue.put(None)        # signal \"I'm done\"\n\nasync def consumer(queue, name):\n    while True:\n        item = await queue.get()\n        if item is None:\n            break\n        await asyncio.sleep(0.3)\n        print(f\"  {name} consumed {item}\")\n\nasync def queue_example():\n    queue = asyncio.Queue(maxsize=5)   # max 5 items buffered\n    await asyncio.gather(\n        producer(queue, \"P1\", [\"a\", \"b\", \"c\"]),\n        consumer(queue, \"C1\"),\n    )\n\nasyncio.run(queue_example())\n\n# ── 16. Event — Signal Between Tasks ─────────────\n# One task waits for a signal, another task sends it\n\nasync def waiter(event, name):\n    print(f\"  {name} waiting for signal...\")\n    await event.wait()           # blocks until event is set\n    print(f\"  {name} got the signal!\")\n\nasync def trigger(event):\n    print(\"  Preparing data...\")\n    await asyncio.sleep(1)\n    print(\"  Setting event!\")\n    event.set()                  # all waiters wake up\n\nasync def event_example():\n    event = asyncio.Event()\n    await asyncio.gather(\n        waiter(event, \"Task-A\"),\n        waiter(event, \"Task-B\"),\n        trigger(event),\n    )\n\nasyncio.run(event_example())\n\n# ── 17. shield() — Protect from Cancellation ─────\n# Normally, cancelling a parent cancels children too\n# shield() prevents a specific task from being cancelled\n\nasync def critical_operation():\n    print(\"  Critical operation started...\")\n    await asyncio.sleep(2)\n    print(\"  Critical operation done!\")\n    return \"important result\"\n\nasync def shield_example():\n    task = asyncio.create_task(asyncio.shield(critical_operation()))\n    await asyncio.sleep(0.5)\n    task.cancel()                # tries to cancel\n    try:\n        await task\n    except asyncio.CancelledError:\n        print(\"  Task was cancelled, but shielded operation continues\")\n\nasyncio.run(shield_example())\n\n# ── 18. TaskGroup (3.11+) — Structured Concurrency ─\n# Like gather() but cancels all tasks if ANY one fails\n\nasync def task_group_example():\n    try:\n        async with asyncio.TaskGroup() as tg:\n            task1 = tg.create_task(fetch_data(\"A\", 1))\n            task2 = tg.create_task(fetch_data(\"B\", 2))\n            # all tasks must complete before exiting the block\n        print(f\"  Results: {task1.result()}, {task2.result()}\")\n    except* ValueError as eg:       # ExceptionGroup (3.11+)\n        for e in eg.exceptions:\n            print(f\"  Error: {e}\")\n\nasyncio.run(task_group_example())\n\n# ── 19. Running Sync Code in Async ───────────────\n# Problem: you have a blocking function (file I/O, CPU work)\n# Solution: run it in a thread pool so it doesn't block the event loop\n\nimport hashlib\n\ndef blocking_hash(data):\n    \"\"\"CPU-heavy work — would block the event loop\"\"\"\n    return hashlib.sha256(data.encode()).hexdigest()\n\nasync def run_sync_example():\n    loop = asyncio.get_event_loop()\n    # run_in_executor → runs in thread pool, doesn't block event loop\n    result = await loop.run_in_executor(None, blocking_hash, \"hello world\")\n    print(f\"  Hash: {result[:16]}...\")\n\nasyncio.run(run_sync_example())\n\n# ── 20. asyncio.wait() — More Control Than gather ─\n# wait() gives you done/pending sets — you can process as they finish\n\nasync def random_delay(name, seconds):\n    await asyncio.sleep(seconds)\n    return f\"{name} done in {seconds}s\"\n\nasync def wait_example():\n    tasks = [\n        asyncio.create_task(random_delay(\"fast\", 0.5)),\n        asyncio.create_task(random_delay(\"medium\", 1.5)),\n        asyncio.create_task(random_delay(\"slow\", 2.5)),\n    ]\n\n    # FIRST_COMPLETED — returns as soon as ANY one finishes\n    done, pending = await asyncio.wait(tasks, return_when=asyncio.FIRST_COMPLETED)\n    for t in done:\n        print(f\"  First done: {t.result()}\")\n    print(f\"  Still pending: {len(pending)}\")\n\n    # wait for the rest\n    done2, _ = await asyncio.wait(pending)\n    for t in done2:\n        print(f\"  Later done: {t.result()}\")\n\nasyncio.run(wait_example())", "cheatSheet": "# ══════════════════════════════════════════════════════════════════\n#  CHEAT SHEET\n# ══════════════════════════════════════════════════════════════════\n#\n#  BASICS:\n#    async def f():             define a coroutine\n#    await coro()               pause here, run other tasks, resume when done\n#    asyncio.run(main())        entry point from sync code (call ONCE)\n#\n#  RUNNING CONCURRENTLY:\n#    asyncio.gather(a, b, c)    run all, wait ALL, return results list\n#    asyncio.create_task(c)     schedule in background, await later\n#    async with TaskGroup() as tg:  structured concurrency (3.11+)\n#\n#  CONTROL:\n#    asyncio.wait_for(c, timeout=5)   timeout a coroutine\n#    asyncio.wait(tasks)              fine-grained done/pending control\n#    asyncio.shield(c)                protect from cancellation\n#\n#  SYNC PRIMITIVES:\n#    Semaphore(n)     limit to N concurrent tasks\n#    Lock()           one task at a time (prevent race conditions)\n#    Event()          signal between tasks (wait/set)\n#    Queue()          producer/consumer pattern\n#\n#  ASYNC PATTERNS:\n#    async for x in gen:   iterate over async generator\n#    async with ctx:       async context manager (__aenter__/__aexit__)\n#    yield in async def    async generator (stream data)\n#\n#  BLOCKING CODE IN ASYNC:\n#    await loop.run_in_executor(None, sync_func, args)\n#    → runs in thread pool, doesn't freeze event loop\n#\n#  KEY RULES:\n#    Never time.sleep() in async    → use asyncio.sleep()\n#    Never requests.get() in async  → use httpx.AsyncClient\n#    Never blocking I/O in async    → use run_in_executor()\n#    await only inside async def    → asyncio.run() from sync\n#\n#  gather() vs create_task():\n#    gather   → need all results together → await asyncio.gather(a, b)\n#    task     → do work in between       → t = create_task(a); ...; await t\n#\n#  ERRORS:\n#    gather(return_exceptions=True)  → errors in results, no crash\n#    TaskGroup                       → cancels all if one fails (3.11+)\n#    shield()                        → protect task from parent cancel\n# ══════════════════════════════════════════════════════════════════\n\n# ╔══════════════════════════════════════════════════╗\n# ║          INTERVIEW GOTCHAS                       ║\n# ╚══════════════════════════════════════════════════╝\n\n# ── Q: What's the difference between concurrency and parallelism? ──\n# Concurrency = multiple tasks in progress (switching between them) — ONE thread\n# Parallelism = multiple tasks running at the SAME instant — multiple threads/CPUs\n# asyncio = CONCURRENT, not parallel — single thread, switches during await\n\n# ── Q: What happens if you call time.sleep() in async? ──\n# It BLOCKS the entire event loop — no other task can run!\n# Always use asyncio.sleep() in async code\n\n# ── Q: Can you await a regular function? ──\n# No — you can only await a coroutine (async def) or an awaitable object\n# await regular_func()  → TypeError: object int can't be used in 'await'\n\n# ── Q: gather() vs TaskGroup — when to use which? ──\n# gather()    → older, more flexible, return_exceptions=True\n# TaskGroup() → 3.11+, structured, cancels all on first error (safer)\n\n# ── Q: What is the event loop? ──\n# The event loop is the scheduler that runs async tasks\n# It checks: \"any task ready to resume?\" → runs it until next await → checks again\n# asyncio.run() creates the loop, asyncio.get_event_loop() gets the current one\n\n# ── Q: Why can't you use requests library in async code? ──\n# requests.get() is BLOCKING — it freezes the event loop while waiting\n# Use httpx.AsyncClient instead — it's async-native:\n#   async with httpx.AsyncClient() as client:\n#       resp = await client.get(url)", "reference": ""}}};
